CREATE OR REPLACE FUNCTION private.account_closure_document(r private.account_closure_requests)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ select jsonb_build_object('accountId',r.account_id,'requestId',r.id,'state',r.state,'revision',r.revision,
 'requestedAt',r.requested_at,'preparedAt',r.prepared_at,'preparation',r.preparation,
 'restricted',r.state in('READY','EXECUTING','FAILED','CLOSED'),'canExecute',false,'authoritative',true); $function$;


CREATE OR REPLACE FUNCTION private.account_closure_preparation(a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare blockers jsonb:='[]'; reasons jsonb:='[]'; legal jsonb; retention jsonb;
begin
 -- PKG-034: the certified executor owns hard blockers; preparation only
 -- projects them into the five existing receipt codes for installed clients.
 -- Detailed storage blockers remain available in the execution review.
 select coalesce(jsonb_agg(code order by first_seen),'[]'::jsonb) into blockers
 from (
   select case when c in ('ACTIVE_AGREEMENT','OPEN_TASK','ACTIVE_APPLICATION','PENDING_WORKFLOW','RETENTION_HOLD')
     then c else 'PENDING_WORKFLOW' end as code, min(ord) as first_seen
   from unnest(private.closure_erasure_hard_blockers_v5(a)) with ordinality x(c,ord)
   group by 1
 ) projected;
 legal:=public.rpc_get_legal_bundle();
 retention:=public.rpc_get_retention_policy_status();
 if (legal->>'ready')::boolean is distinct from true then reasons:=reasons||'"LEGAL_POLICY_NOT_READY"'::jsonb; end if;
 if (retention->>'ready')::boolean is distinct from true then reasons:=reasons||'"RETENTION_POLICY_NOT_READY"'::jsonb; end if;
 -- The existing P3 adapter covers AI_ABANDONED_UNBOUND only. Neither a legal
 -- document nor a schedule admits account erasure, auth closure or media cleanup.
 -- A future implementation must bind real approved coverage before removing this
 -- source gate. There is intentionally NO operator flag to bypass missing code.
 reasons:=reasons||'"CLOSURE_EXECUTION_NOT_READY"'::jsonb;
 return jsonb_build_object('observedAt',clock_timestamp(),'blockers',blockers,'notReadyReasons',reasons,
  'legalReady',coalesce((legal->>'ready')::boolean,false),'retentionReady',coalesce((retention->>'ready')::boolean,false),
  'executionReady',false,'authClosureReady',false,'mediaCleanupReady',false);
end;
$function$;


CREATE OR REPLACE FUNCTION private.account_is_non_production(p_account_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select private.account_lineage(p_account_id)
    in ('OWNER_PERSONAL','OWNER_BUSINESS','DEV_ACCEPTANCE_QA','SYNTHETIC_ACCEPTANCE_FIXTURE','OPERATOR');
$function$;


CREATE OR REPLACE FUNCTION private.account_lineage(p_account_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select coalesce((select l.lineage from private.account_lineage_v5 l where l.account_id = p_account_id), 'UNCLASSIFIED');
$function$;


CREATE OR REPLACE FUNCTION private.account_lineage_events_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if tg_op = 'UPDATE'
     and private.closure_redaction_allowed_v5(tg_relid, 'UPDATE', to_jsonb(old), to_jsonb(new)) then
    return new;
  end if;
  raise exception 'ACCOUNT_LINEAGE_HISTORY_IMMUTABLE' using errcode = '55000';
end
$function$;


CREATE OR REPLACE FUNCTION private.account_reputation(account_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('accountId',account_id,'reviewCount',count(*),
 'averageRating',case when count(*)=0 then null else round(avg(rating),2) end,
 'state',case when count(*)=0 then 'NO_REVIEWS' else 'RATED' end,'authoritative',true)
 from private.agreement_reviews where target_account_id=account_id;
$function$;


CREATE OR REPLACE FUNCTION private.account_visibility_world(p_account_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select case when coalesce(private.account_lineage(p_account_id), 'UNCLASSIFIED')
                in ('DEV_ACCEPTANCE_QA','SYNTHETIC_ACCEPTANCE_FIXTURE','OPERATOR',
                    -- PKG-029e, owner decision 2026-09-21 ("dok testiramo"): the owner's own accounts share the
                    -- test world while testing. Take these two out again before real users arrive.
                    'OWNER_PERSONAL','OWNER_BUSINESS') then 'TEST' else 'REAL' end;
$function$;


CREATE OR REPLACE FUNCTION private.accounts_same_world(p_a uuid, p_b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select private.account_visibility_world(p_a) = private.account_visibility_world(p_b);
$function$;


CREATE OR REPLACE FUNCTION private.admit_push_opportunity_single_target_v1(p_admission_id uuid, p_authorization_id uuid, p_recipient_user_id uuid, p_event_id uuid, p_delivery_id uuid, p_device_id uuid, p_device_revision bigint, p_bound_session_id uuid, p_expires_at timestamp with time zone, p_receipt_deadline timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
 d public.notification_deliveries%rowtype;
 dev public.notification_push_devices%rowtype;
 a public.notification_push_attempts%rowtype;
 meta jsonb;
 v_now timestamptz:=clock_timestamp();
begin
 if current_user<>'postgres' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_admission_id is null or p_authorization_id is null or p_recipient_user_id is null or p_event_id is null
  or p_delivery_id is null or p_device_id is null or p_device_revision is null or p_device_revision<0
  or p_bound_session_id is null or p_expires_at is null or p_receipt_deadline is null
  or not isfinite(p_expires_at) or not isfinite(p_receipt_deadline)
  or p_expires_at<=v_now or p_expires_at>v_now+interval '24 hours'
  or p_receipt_deadline<=p_expires_at or p_receipt_deadline>p_expires_at+interval '24 hours'
 then raise exception 'INVALID_PUSH_ADMISSION' using errcode='22023'; end if;
 meta:=jsonb_build_object(
  'schema','PUSH_SINGLE_TARGET_V1','authorizationId',p_authorization_id,
  'recipientAccountId',p_recipient_user_id,'recipientRole','WORKER',
  'eventId',p_event_id,'eventType','OPPORTUNITY_AVAILABLE',
  'deviceId',p_device_id,'deviceRevision',p_device_revision,'boundSessionId',p_bound_session_id,
  'expiresAt',p_expires_at,'receiptDeadline',p_receipt_deadline);
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0))
 then return jsonb_build_object('kind','BUSY'); end if;
 select * into d from public.notification_deliveries where id=p_delivery_id for update;
 if not found then raise exception 'PUSH_TARGET_UNAVAILABLE' using errcode='PT409'; end if;
 select * into a from public.notification_push_attempts where id=p_admission_id for update;
 if found then
  if a.delivery_id<>p_delivery_id or a.device_id is distinct from p_device_id
   or a.single_target_admission is distinct from meta
  then raise exception 'PUSH_ADMISSION_CONFLICT' using errcode='PT409'; end if;
  return jsonb_build_object('kind','EXISTING','admissionId',a.id,'state',a.transport_state);
 end if;
 if d.channel<>'PUSH' or d.push_started_at is not null or d.state not in ('CREATED','QUEUED','FAILED_RETRYABLE')
  or d.event_id<>p_event_id or d.recipient_user_id<>p_recipient_user_id or d.recipient_role<>'WORKER'
  or exists(select 1 from public.notification_push_attempts where delivery_id=d.id)
  or not exists(
    select 1 from public.user_activity_events e
    join public.needs n on n.id=e.entity_id
    join public.app_profiles p on p.account_id=p_recipient_user_id and p.kind='WORKER' and p.profile_status='ACTIVE'
    join public.opportunity_deliveries od on od.worker_profile_id=p.id and od.worker_account_id=p_recipient_user_id
      and od.need_id=n.id and od.need_revision=n.revision
    where e.id=p_event_id and e.recipient_user_id=p_recipient_user_id and e.recipient_role='WORKER'
      and e.event_type='OPPORTUNITY_AVAILABLE' and e.entity_type='NEED' and e.entity_version=n.revision
      and e.dedupe_key='opp:'||n.id::text||':'||n.revision::text||':'||p_recipient_user_id::text
      and n.status in('PUBLISHED','SELECTION') and n.requester_account_id is not null
      and n.requester_account_id<>p_recipient_user_id
      and od.status in ('READY','SEEN','RESPONDED')
      and od.expires_at>=p_expires_at
      and private.accounts_same_world(n.requester_account_id,p_recipient_user_id)
      and not private.safety_event_blocked(e)
      and exists(select 1 from public.notification_deliveries inapp
        where inapp.event_id=e.id and inapp.recipient_user_id=p_recipient_user_id
          and inapp.recipient_role='WORKER' and inapp.channel='IN_APP'
          and inapp.dedupe_key=e.dedupe_key||':in_app'
          and inapp.state in ('CREATED','SENT','DELIVERED','READ') and inapp.suppression_reason is null)
   )
 then raise exception 'PUSH_TARGET_UNAVAILABLE' using errcode='PT409'; end if;
 if private.push_suppression(d) is not null
 then raise exception 'PUSH_TARGET_SUPPRESSED' using errcode='PT409'; end if;
 select * into dev from public.notification_push_devices where id=p_device_id;
 if not found or dev.user_id<>p_recipient_user_id or not dev.active or dev.platform not in('ANDROID','IOS')
  or dev.revision<>p_device_revision or dev.bound_revision is distinct from dev.revision
  or dev.bound_session_id is distinct from p_bound_session_id
  or not private.push_session_valid(dev.user_id,dev.bound_session_id)
 then raise exception 'PUSH_DEVICE_CHANGED' using errcode='PT409'; end if;
 insert into public.notification_push_attempts(
 id,delivery_id,device_id,attempt_no,outcome,transport_state,device_revision,next_attempt_at,
 single_target_admission,single_target_authorization_id)
 values(p_admission_id,d.id,dev.id,1,'QUEUED','PENDING',dev.revision,v_now,meta,p_authorization_id);
 return jsonb_build_object('kind','ADMITTED','admissionId',p_admission_id);
end;
$function$;


CREATE OR REPLACE FUNCTION private.admit_push_single_target_v1(p_admission_id uuid, p_authorization_id uuid, p_recipient_user_id uuid, p_recipient_role text, p_event_id uuid, p_delivery_id uuid, p_device_id uuid, p_device_revision bigint, p_bound_session_id uuid, p_expires_at timestamp with time zone, p_receipt_deadline timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare d public.notification_deliveries%rowtype; dev public.notification_push_devices%rowtype;
 a public.notification_push_attempts%rowtype; meta jsonb; why text; v_now timestamptz:=clock_timestamp();
begin
 if current_user<>'postgres' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_admission_id is null or p_authorization_id is null or p_recipient_user_id is null
  or p_recipient_role is null or p_recipient_role not in ('REQUESTER','WORKER')
  or p_event_id is null or p_delivery_id is null or p_device_id is null or p_device_revision is null or p_device_revision<0
  or p_bound_session_id is null or p_expires_at is null or p_receipt_deadline is null
  or not isfinite(p_expires_at) or not isfinite(p_receipt_deadline)
  or p_receipt_deadline<=p_expires_at or p_receipt_deadline>p_expires_at+interval '24 hours'
 then raise exception 'INVALID_PUSH_ADMISSION' using errcode='22023'; end if;
 meta:=jsonb_build_object('schema','PUSH_SINGLE_TARGET_V1','authorizationId',p_authorization_id,
  'recipientAccountId',p_recipient_user_id,'recipientRole',p_recipient_role,'eventId',p_event_id,
  'eventType','MESSAGE_RECEIVED','deviceId',p_device_id,'deviceRevision',p_device_revision,
  'boundSessionId',p_bound_session_id,'expiresAt',p_expires_at,'receiptDeadline',p_receipt_deadline);
 -- Admission and claim share the existing cross-isolate serializer; no provider/token lock is held here.
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0)) then return jsonb_build_object('kind','BUSY'); end if;
 select * into d from public.notification_deliveries where id=p_delivery_id for update;
 if not found then raise exception 'PUSH_TARGET_UNAVAILABLE' using errcode='PT409'; end if;
 select * into a from public.notification_push_attempts where id=p_admission_id for update;
 if found then
  if a.delivery_id<>p_delivery_id or a.device_id is distinct from p_device_id or a.single_target_admission is distinct from meta
  then raise exception 'PUSH_ADMISSION_CONFLICT' using errcode='PT409'; end if;
  return jsonb_build_object('kind','EXISTING','admissionId',a.id,'state',a.transport_state);
 end if;
 if p_expires_at<=clock_timestamp() or d.channel<>'PUSH' or d.push_started_at is not null
  or d.state not in ('CREATED','QUEUED','FAILED_RETRYABLE')
  or d.event_id<>p_event_id or d.recipient_user_id<>p_recipient_user_id or d.recipient_role<>p_recipient_role
  or exists(select 1 from public.notification_push_attempts where delivery_id=d.id)
  or not exists(select 1 from public.user_activity_events e where e.id=p_event_id
   and e.recipient_user_id=p_recipient_user_id and e.recipient_role=p_recipient_role and e.event_type='MESSAGE_RECEIVED')
 then raise exception 'PUSH_TARGET_UNAVAILABLE' using errcode='PT409'; end if;
 why:=private.push_suppression(d);
 if why is not null then raise exception 'PUSH_TARGET_SUPPRESSED' using errcode='PT409'; end if;
 select * into dev from public.notification_push_devices where id=p_device_id;
 if not found or dev.user_id<>p_recipient_user_id or not dev.active or dev.platform not in ('ANDROID','IOS')
  or dev.revision<>p_device_revision or dev.bound_revision is distinct from dev.revision
  or dev.bound_session_id is distinct from p_bound_session_id or not private.push_session_valid(dev.user_id,dev.bound_session_id)
 then raise exception 'PUSH_DEVICE_CHANGED' using errcode='PT409'; end if;
 insert into public.notification_push_attempts(id,delivery_id,device_id,attempt_no,outcome,transport_state,device_revision,next_attempt_at,single_target_admission,single_target_authorization_id)
 values(p_admission_id,d.id,dev.id,1,'QUEUED','PENDING',dev.revision,v_now,meta,p_authorization_id);
 return jsonb_build_object('kind','ADMITTED','admissionId',p_admission_id);
end $function$;


CREATE OR REPLACE FUNCTION private.after_need_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if new.revision>old.revision then
  for r in with affected as (
   update public.marketplace_responses set status='STALE_REVIEW_REQUIRED'
    where need_id=new.id and submitted_against_need_revision=old.revision
     and status in('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
    returning id,worker_account_id,current_version)
   select distinct on(worker_account_id) * from affected order by worker_account_id,id
  loop
   -- Own Application is the safe target even while the revised Need is DRAFT.
   perform private.emit_event(r.worker_account_id,'WORKER','NEED_REVISED','RESPONSE',r.id,new.revision,
    'Zadatak je izmenjen','Pregledajte svoju prijavu pre nastavka.',
    'need-revised:'||new.id::text||':'||new.revision::text||':worker:'||r.worker_account_id::text,
    'NORMAL',jsonb_build_object('needId',new.id,'responseId',r.id,'fromRevision',old.revision,'needRevision',new.revision),null);
  end loop;
  update public.opportunity_deliveries set status='EXPIRED'
   where need_id=new.id and need_revision=old.revision and status in('READY','SEEN');
  update public.dispatch_rounds set status='STOPPED',stop_reason='NEED_REVISED'
   where need_id=new.id and need_revision=old.revision and status in('PLANNED','SENT');
  -- Never dispatch or auto-publish a newly revised DRAFT.
 end if;
 return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.agreement_action_state(p_id uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('agreementId',a.id,'agreementVersion',a.current_version,'accountId',p_actor,'authoritative',true,
   'canProposeChange',a.status='CONFIRMED' and x.state='CONFIRMED' and x.worker_marked_done_at is null and not coalesce(p.has_pending,false),
   'canRespondChange',a.status='CONFIRMED' and x.state='CONFIRMED' and x.worker_marked_done_at is null and coalesce(p.can_respond,false),
   'canWithdrawChange',a.status='CONFIRMED' and x.state='CONFIRMED' and x.worker_marked_done_at is null and coalesce(p.can_withdraw,false),
   'canMarkWorkDone',p_actor=a.worker_account_id and a.status='CONFIRMED' and x.state='CONFIRMED' and x.worker_marked_done_at is null and not coalesce(p.has_pending,false),
   'canConfirmCompletion',p_actor=a.requester_account_id and a.status='CONFIRMED' and x.state in ('CONFIRMED','AWAITING_REQUESTER') and not coalesce(p.has_pending,false),
   'canCancel',a.status='CONFIRMED' and (x.state='CONFIRMED' or (x.state='AWAITING_REQUESTER' and p_actor=a.worker_account_id)),
   'pendingChanges',coalesce(p.items,'[]'::jsonb))
 from public.agreements a join public.agreement_execution x on x.agreement_id=a.id and x.agreement_version=a.current_version
 left join lateral(select bool_or(true) has_pending, bool_or(c.proposed_by_account_id<>p_actor) can_respond,
   bool_or(c.proposed_by_account_id=p_actor) can_withdraw,
   jsonb_agg(jsonb_build_object('id',c.id,'baseVersion',c.base_version,'proposedByAccountId',c.proposed_by_account_id,
     'createdAt',c.created_at,'proposedTerms',c.proposed_terms,'reason',c.reason) order by c.created_at,c.id) items
   from public.agreement_change_proposals c where c.agreement_id=a.id and c.status='PENDING') p on true
 where a.id=p_id and p_actor in (a.requester_account_id,a.worker_account_id);
$function$;


CREATE OR REPLACE FUNCTION private.agreement_calendar_interval(p_terms jsonb)
 RETURNS TABLE(starts_at timestamp with time zone, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  s text := p_terms->>'proposed_start_at';
  e text := p_terms->>'proposed_end_at';
  pattern text := '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$';
begin
  if jsonb_typeof(p_terms) is distinct from 'object' then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  if s is null and e is null then
    return query select null::timestamptz,null::timestamptz;
    return;
  end if;
  if s is null or e is null or jsonb_typeof(p_terms->'proposed_start_at') <> 'string'
     or jsonb_typeof(p_terms->'proposed_end_at') <> 'string'
     or length(s)>32 or length(e)>32 or s !~ pattern or e !~ pattern then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  begin
    starts_at := s::timestamptz;
    ends_at := e::timestamptz;
  exception when datetime_field_overflow or invalid_datetime_format or invalid_parameter_value then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end;
  if not isfinite(starts_at) or not isfinite(ends_at) or starts_at>=ends_at then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  return next;
end;
$function$;


CREATE OR REPLACE FUNCTION private.agreement_cancellation_facts_v1(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  -- CANCEL-INFO (2026-10-07). When, by which side and why ONE cancelled Dogovor was cancelled, read from exactly what the only
  -- writer, public.rpc_cancel_agreement(uuid,text) (body pinned by md5 when this package is applied), leaves behind inside ONE
  -- statement, so all three carry the same statement_timestamp():
  --   1. public.agreements: status 'CANCELLED', updated_at stamped by the trigger private.set_updated_at();
  --   2. the event AGREEMENT_CANCELLED with the dedupe key 'agreement-cancelled:<id>', sent to the OTHER party;
  --   3. unless the pair was blocked or a party was under a closure restriction at that moment: the canceller's own message
  --      'Otkazujem Dogovor. Razlog: <reason>' in the Dogovor's conversation (the reason the app requires, at most 1,973 characters).
  -- No other function sets a Dogovor CANCELLED (catalog scan of canonical DEV, 2026-10-07), so there is no SYSTEM side today: a
  -- future system path must record its side and this helper must learn it. A closure deletes the events of a closing RECIPIENT and
  -- replaces the text of a closing SENDER's messages; the side then comes from what is left and is null when nothing is left
  -- (never guessed). Returns null for a Dogovor that does not exist or is not cancelled.
  select jsonb_build_object(
    'agreementId', a.id,
    'cancelledAt', coalesce(e.created_at, a.updated_at),
    'cancelledBy', case
      when e.recipient_user_id = a.worker_account_id then 'REQUESTER'
      when e.recipient_user_id = a.requester_account_id then 'WORKER'
      when m.sender_account_id = a.requester_account_id then 'REQUESTER'
      when m.sender_account_id = a.worker_account_id then 'WORKER' end,
    'sideSource', case
      when e.recipient_user_id in (a.worker_account_id, a.requester_account_id) then 'EVENT'
      when m.sender_account_id in (a.requester_account_id, a.worker_account_id) then 'MESSAGE' end,
    'cancelledByAccountId', case
      when e.recipient_user_id = a.worker_account_id then a.requester_account_id
      when e.recipient_user_id = a.requester_account_id then a.worker_account_id
      when m.sender_account_id in (a.requester_account_id, a.worker_account_id) then m.sender_account_id end,
    'reason', case when left(m.body, 27) = 'Otkazujem Dogovor. Razlog: ' then nullif(substr(m.body, 28), '') end,
    'reasonState', case
      when m.sender_account_id is null then 'NOT_KEPT'
      when left(m.body, 27) = 'Otkazujem Dogovor. Razlog: ' then 'KEPT'
      else 'REMOVED' end)
  from (select x.id, x.updated_at, x.requester_account_id, x.worker_account_id
          from public.agreements x where x.id = p_agreement_id and x.status = 'CANCELLED') a
  left join lateral (
    select ev.created_at, ev.recipient_user_id from public.user_activity_events ev
     where ev.dedupe_key = 'agreement-cancelled:' || a.id::text and ev.event_type = 'AGREEMENT_CANCELLED'
       and ev.entity_type = 'AGREEMENT' and ev.entity_id = a.id) e on true
  left join lateral (
    select msg.sender_account_id, msg.body from public.agreement_messages msg
     where msg.agreement_id = a.id and msg.created_at = coalesce(e.created_at, a.updated_at)
       and msg.sender_account_id in (a.requester_account_id, a.worker_account_id)
     order by (left(msg.body, 27) = 'Otkazujem Dogovor. Razlog: ') desc, msg.id
     limit 1) m on true;
$function$;


CREATE OR REPLACE FUNCTION private.agreement_invalidation_cleanup_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if new.status not in('CONFIRMED','SUPERSEDED')
    or new.requester_account_id is distinct from old.requester_account_id
    or new.worker_account_id is distinct from old.worker_account_id then
    delete from public.agreement_invalidations_v1 where agreement_id=new.id;
  end if;
  return new;
end
$function$;


CREATE OR REPLACE FUNCTION private.agreement_invalidation_surface_v1()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
select encode(extensions.digest(convert_to(jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'metadata',to_jsonb(p)) order by p.oid::regprocedure::text)
   from pg_proc p where p.oid in(select to_regprocedure(signature) from unnest(array[
     'public.rpc_agreement_invalidation_visible_v1(uuid)',
     'private.agreement_message_invalidate_v1()',
     'private.agreement_invalidation_cleanup_v1()',
     'private.agreement_invalidation_surface_v1()']::text[]) signature)
   having count(*)=4),
 'policies',(select jsonb_agg(to_jsonb(p) order by policyname) from pg_policies p
   where schemaname='public' and tablename='agreement_invalidations_v1'),
 'publications',(select jsonb_agg(to_jsonb(p) order by pubname) from pg_publication_tables p
   where schemaname='public' and tablename in('agreement_invalidations_v1','agreement_messages')),
 'publicationFlags',(select jsonb_build_array(puballtables,pubinsert,pubupdate,pubdelete,pubtruncate)
   from pg_publication where pubname='supabase_realtime')
 )::text,'UTF8'),'sha256'),'hex')
$function$;


CREATE OR REPLACE FUNCTION private.agreement_location_receipt(c private.agreement_location_commands)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('agreementId',c.agreement_id,'agreementVersion',c.agreement_version,
 'clientRequestId',c.client_request_id,'kind',c.kind,'state',c.state,'inputSha256',c.input_hash,'recordedAt',c.created_at,'authoritative',true);
$function$;


CREATE OR REPLACE FUNCTION private.agreement_message_invalidate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare ag public.agreements;
begin
  -- No NEW row field except its Agreement ID enters the projection or any log.
  -- Serialize with lifecycle cleanup: a message cannot recreate the cache from a
  -- pre-terminal snapshot after the closing transaction deleted it.
  select * into ag from public.agreements where id=new.agreement_id for share;
  if not found or ag.status not in('CONFIRMED','SUPERSEDED')
    or private.closure_account_restricted(ag.requester_account_id)
    or private.closure_account_restricted(ag.worker_account_id) then return new; end if;
  insert into public.agreement_invalidations_v1 as cache(agreement_id,revision) values(ag.id,1)
  on conflict(agreement_id) do update set revision=cache.revision+1;
  return new;
end
$function$;


CREATE OR REPLACE FUNCTION private.agreement_messages_v1_view(v jsonb, schema_name text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select (v - 'messages') || jsonb_build_object('schema', schema_name, 'messages', (
    select coalesce(jsonb_agg(case when m->>'kind' = 'VOICE'
        then (m - 'voice') || jsonb_build_object('kind', 'TEXT', 'body', 'Glasovna poruka. Ažuriraj aplikaciju da je poslušaš.')
        else m - 'voice' end order by o), '[]'::jsonb)
    from jsonb_array_elements(v->'messages') with ordinality t(m, o)));$function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_asset_guard_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 perform pg_advisory_xact_lock(private.media_evidence_key_v5(old.account_id));
 if tg_op='DELETE' then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode='55000';end if;
 if(new.id,new.account_id,new.agreement_id,new.agreement_version,new.client_request_id,new.attempt_id,new.input_sha256,new.input_bytes,new.input_type,new.admitted_at,new.created_at)
 is distinct from(old.id,old.account_id,old.agreement_id,old.agreement_version,old.client_request_id,old.attempt_id,old.input_sha256,old.input_bytes,old.input_type,old.admitted_at,old.created_at)
 or(old.storage_path is not null and(new.storage_path,new.sanitized_sha256,new.width,new.height,new.byte_size) is distinct from(old.storage_path,old.sanitized_sha256,old.width,old.height,old.byte_size))
 or(old.attached_message_id is not null and(new.attached_message_id,new.state) is distinct from(old.attached_message_id,old.state))
 or(old.cancelled_at is not null and(new.cancelled_at,new.state) is distinct from(old.cancelled_at,old.state))
 or(old.dispatch_state='SETTLED' and(new.dispatch_state,new.dispatch_outcome) is distinct from(old.dispatch_state,old.dispatch_outcome))
 or(old.dispatch_state='DISPATCHING' and new.dispatch_state='NOT_DISPATCHED')
 or(old.state='FAILED' and new.state not in('FAILED','CANCELLED'))
 or(old.state='READY' and new.state not in('READY','CANCELLED'))
 or(old.state='STAGED' and new.state='PROCESSING')
 then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode='55000';end if;
 if new.attached_message_id is not null and not exists(select 1 from public.agreement_messages m where m.id=new.attached_message_id
  and m.sender_account_id=new.account_id and m.agreement_id=new.agreement_id and m.agreement_version=new.agreement_version and new.id=any(m.photo_asset_ids))
 then raise exception 'MEDIA_MESSAGE_LINK_INCOMPLETE' using errcode='55000';end if;
 return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_context_v5(a uuid, g uuid, v integer, writing boolean)
 RETURNS public.agreements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare ag public.agreements;begin
 select * into ag from public.agreements where id=g;
 if not found or a not in(ag.requester_account_id,ag.worker_account_id) then raise exception 'MEDIA_NOT_FOUND' using errcode='42501';end if;
 if writing then
  perform private.closure_assert_open(ag.requester_account_id,ag.worker_account_id);
  perform pg_advisory_xact_lock(private.agreement_photo_key_v5(a));
  select * into ag from public.agreements where id=g for share;
  perform private.safety_assert_pair(ag.requester_account_id,ag.worker_account_id);
  if ag.status not in('CONFIRMED','SUPERSEDED') then raise exception 'MEDIA_NOT_EDITABLE' using errcode='42501';end if;
  if v is null or v<>ag.current_version then raise exception 'MEDIA_VERSION_CONFLICT' using errcode='PT409';end if;
  if not exists(select 1 from public.agreement_versions where agreement_id=g and version=v and status in('CONFIRMED','SUPERSEDED')) then raise exception 'MEDIA_NOT_EDITABLE' using errcode='42501';end if;
 end if;return ag;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_document_v5(a private.agreement_photo_uploads_v5)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('accountId',a.account_id,'agreementId',a.agreement_id,'agreementVersion',a.agreement_version,'clientRequestId',a.client_request_id,
 'assetId',a.id,'state',a.state,'attachedMessageId',a.attached_message_id,'photo',case when a.state='READY' then jsonb_build_object('assetId',a.id,'width',a.width,'height',a.height,'byteSize',a.byte_size,'contentType','image/jpeg') else null end,'authoritative',true);$function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_key_v5(a uuid)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
 select hashtextextended('uskoci:agreement-photo:'||a::text,144);$function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_link_guard_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if exists(select 1 from unnest(new.photo_asset_ids)x left join private.agreement_photo_uploads_v5 a on a.id=x
  where a.id is null or a.attached_message_id is distinct from new.id or a.account_id<>new.sender_account_id or a.agreement_id<>new.agreement_id
  or a.agreement_version<>new.agreement_version or a.state<>'READY') then raise exception 'MEDIA_MESSAGE_LINK_INCOMPLETE' using errcode='55000';end if;
 return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_message_guard_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare x uuid;a private.agreement_photo_uploads_v5;begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if tg_op='UPDATE' then
  if old.photo_asset_ids is distinct from new.photo_asset_ids or(cardinality(old.photo_asset_ids)>0 and
   (new.id,new.agreement_id,new.agreement_version,new.sender_account_id,new.client_message_id,new.body) is distinct from
   (old.id,old.agreement_id,old.agreement_version,old.sender_account_id,old.client_message_id,old.body)) then raise exception 'MEDIA_MESSAGE_IMMUTABLE' using errcode='55000';end if;
  return new;
 end if;
 if cardinality(new.photo_asset_ids)=0 then return new;end if;
 if cardinality(new.photo_asset_ids)>6 or array_ndims(new.photo_asset_ids)<>1 or array_lower(new.photo_asset_ids,1)<>1
 or array_position(new.photo_asset_ids,null) is not null or(select count(distinct u) from unnest(new.photo_asset_ids)u)<>cardinality(new.photo_asset_ids)
 or auth.uid() is distinct from new.sender_account_id or new.client_message_id is null then raise exception 'MEDIA_INPUT_INVALID' using errcode='22023';end if;
 perform private.agreement_photo_context_v5(new.sender_account_id,new.agreement_id,new.agreement_version,true);
 foreach x in array new.photo_asset_ids loop
  select * into a from private.agreement_photo_uploads_v5 where id=x for update;
  if not found or a.account_id<>new.sender_account_id or a.agreement_id<>new.agreement_id or a.agreement_version<>new.agreement_version
  or a.state<>'READY' or a.attached_message_id is not null then raise exception 'MEDIA_NOT_EDITABLE' using errcode='42501';end if;
 end loop;return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_storage_guard_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.agreement_photo_uploads_v5;e private.closure_executions_v5;begin
 if old.bucket_id<>'profile-media' or split_part(old.name,'/',2)<>'agreement-v5' then return case when tg_op='DELETE' then old else new end;end if;
 select * into a from private.agreement_photo_uploads_v5 where storage_path=old.name;
 if not found then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode='55000';end if;
 if tg_op='UPDATE' then
  if(to_jsonb(new)-array['last_accessed_at']) is distinct from(to_jsonb(old)-array['last_accessed_at']) then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode='55000';end if;
  return new;
 end if;
 -- History is not deleted while the account is open. At closure the existing
 -- reviewed policy/generation and a dispatched exact object action are required.
 perform pg_advisory_xact_lock_shared(private.closure_account_key(a.account_id));
 select x.* into e from private.closure_executions_v5 x join private.closure_actions_v5 c on c.generation=x.generation and c.account_id=x.account_id
 where x.account_id=a.account_id and x.state='EXECUTING' and c.kind='STORAGE_DELETE' and c.state='DISPATCHED' and c.bucket=old.bucket_id and c.object_path=old.name;
 if not found then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode='55000';end if;
 perform private.closure_assert_current_v5(e);
 perform pg_advisory_xact_lock(private.media_evidence_key_v5(a.account_id));
 if (e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1'
  and private.closure_erasure_media_protected_v5(a.account_id,old.name))
  or (e.binding->>'adapterVersion' is distinct from 'OWNER_AF_D22_EVENT_ERASURE_V1'
   and (exists(select 1 from private.media_evidence_refs_v5 where asset_id=a.id)
    or exists(select 1 from private.retention_holds where account_id=a.account_id and active)))
 then raise exception 'MEDIA_EVIDENCE_POLICY_NOT_READY' using errcode='55000';end if;
 return old;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_photo_transfer_v5(a private.agreement_photo_uploads_v5)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('receipt',private.agreement_photo_document_v5(a),'attemptId',a.attempt_id,'path',a.storage_path,'sha256',a.sanitized_sha256,
 'byteSize',a.byte_size,'dispatchState',a.dispatch_state,'dispatchOutcome',a.dispatch_outcome);$function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_asset_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  -- The account-closure erasure certificate (one locked row, one fixed patch, inside the service-owned SQL transaction) is the only way past this guard.
  if auth.role() = 'service_role' then
    if tg_op in ('UPDATE', 'DELETE') and private.closure_redaction_allowed_v5(tg_relid, tg_op, to_jsonb(old), case when tg_op = 'UPDATE' then to_jsonb(new) else null end) then
      if tg_op = 'DELETE' then return old; end if;
      return new;
    end if;
  end if;
  perform pg_advisory_xact_lock(private.media_evidence_key_v5(old.account_id));
  if tg_op = 'DELETE' then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode = '55000'; end if;
  if (new.id, new.account_id, new.agreement_id, new.agreement_version, new.client_request_id, new.attempt_id, new.input_sha256, new.input_bytes, new.input_type, new.admitted_at, new.created_at)
     is distinct from (old.id, old.account_id, old.agreement_id, old.agreement_version, old.client_request_id, old.attempt_id, old.input_sha256, old.input_bytes, old.input_type, old.admitted_at, old.created_at)
     or (old.storage_path is not null and (new.storage_path, new.validated_sha256, new.byte_size, new.duration_ms) is distinct from (old.storage_path, old.validated_sha256, old.byte_size, old.duration_ms))
     or (old.attached_message_id is not null and (new.attached_message_id, new.state) is distinct from (old.attached_message_id, old.state))
     or (old.cancelled_at is not null and (new.cancelled_at, new.state) is distinct from (old.cancelled_at, old.state))
     or (old.dispatch_state = 'SETTLED' and (new.dispatch_state, new.dispatch_outcome) is distinct from (old.dispatch_state, old.dispatch_outcome))
     or (old.dispatch_state = 'DISPATCHING' and new.dispatch_state = 'NOT_DISPATCHED')
     or (old.state = 'FAILED' and new.state not in ('FAILED','CANCELLED'))
     or (old.state = 'READY' and new.state not in ('READY','CANCELLED'))
     or (old.state = 'STAGED' and new.state = 'PROCESSING') then
    raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode = '55000';
  end if;
  if new.attached_message_id is not null and not exists(select 1 from public.agreement_messages m where m.id = new.attached_message_id
      and m.sender_account_id = new.account_id and m.agreement_id = new.agreement_id and m.agreement_version = new.agreement_version and m.voice_asset_id = new.id) then
    raise exception 'MEDIA_MESSAGE_LINK_INCOMPLETE' using errcode = '55000';
  end if;
  return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_context_v1(a uuid, g uuid, v integer, writing boolean)
 RETURNS public.agreements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare ag public.agreements;
begin
  select * into ag from public.agreements where id = g;
  if not found or (a is distinct from ag.requester_account_id and a is distinct from ag.worker_account_id) then
    raise exception 'MEDIA_NOT_FOUND' using errcode = '42501';
  end if;
  if writing then
    perform private.closure_assert_open(ag.requester_account_id, ag.worker_account_id);
    perform pg_advisory_xact_lock(private.agreement_voice_key_v1(a));
    select * into ag from public.agreements where id = g for share;
    perform private.safety_assert_pair(ag.requester_account_id, ag.worker_account_id);
    if ag.status not in ('CONFIRMED','SUPERSEDED') then raise exception 'MEDIA_NOT_EDITABLE' using errcode = '42501'; end if;
    if v is null or v <> ag.current_version then raise exception 'MEDIA_VERSION_CONFLICT' using errcode = 'PT409'; end if;
    if not exists(select 1 from public.agreement_versions where agreement_id = g and version = v and status in ('CONFIRMED','SUPERSEDED')) then
      raise exception 'MEDIA_NOT_EDITABLE' using errcode = '42501';
    end if;
  end if;
  return ag;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_document_v1(a private.agreement_voice_uploads_v1)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
