 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
  select hashtextextended('uskoci:agreement-voice:' || a::text, 1);$function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_link_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if new.voice_asset_id is not null and not exists(select 1 from private.agreement_voice_uploads_v1 a
      where a.id = new.voice_asset_id and a.attached_message_id = new.id and a.account_id = new.sender_account_id
        and a.agreement_id = new.agreement_id and a.agreement_version = new.agreement_version and a.state = 'READY') then
    raise exception 'MEDIA_MESSAGE_LINK_INCOMPLETE' using errcode = '55000';
  end if;
  return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_message_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.agreement_voice_uploads_v1;
begin
  -- The account-closure erasure certificate (one locked row, one fixed patch, inside the service-owned SQL transaction) is the only way past this guard.
  if auth.role() = 'service_role' then
    if tg_op in ('UPDATE', 'DELETE') and private.closure_redaction_allowed_v5(tg_relid, tg_op, to_jsonb(old), case when tg_op = 'UPDATE' then to_jsonb(new) else null end) then
      if tg_op = 'DELETE' then return old; end if;
      return new;
    end if;
  end if;
  if tg_op = 'UPDATE' then
    if old.voice_asset_id is distinct from new.voice_asset_id
       or (old.voice_asset_id is not null and (new.id, new.agreement_id, new.agreement_version, new.sender_account_id, new.client_message_id, new.body, new.photo_asset_ids)
           is distinct from (old.id, old.agreement_id, old.agreement_version, old.sender_account_id, old.client_message_id, old.body, old.photo_asset_ids)) then
      raise exception 'MEDIA_MESSAGE_IMMUTABLE' using errcode = '55000';
    end if;
    return new;
  end if;
  if new.voice_asset_id is null then return new; end if;
  if auth.uid() is distinct from new.sender_account_id or new.client_message_id is null or btrim(new.body) <> '' or cardinality(new.photo_asset_ids) <> 0 then
    raise exception 'MEDIA_INPUT_INVALID' using errcode = '22023';
  end if;
  perform private.agreement_voice_context_v1(new.sender_account_id, new.agreement_id, new.agreement_version, true);
  select * into a from private.agreement_voice_uploads_v1 where id = new.voice_asset_id for update;
  if not found or a.account_id <> new.sender_account_id or a.agreement_id <> new.agreement_id or a.agreement_version <> new.agreement_version
     or a.state <> 'READY' or a.attached_message_id is not null then
    raise exception 'MEDIA_NOT_EDITABLE' using errcode = '42501';
  end if;
  return new;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_storage_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.agreement_voice_uploads_v1; e private.closure_executions_v5;
begin
  if old.bucket_id <> 'agreement-voice' then return case when tg_op = 'DELETE' then old else new end; end if;
  select * into a from private.agreement_voice_uploads_v1 where storage_path = old.name;
  if not found then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode = '55000'; end if;
  if tg_op = 'UPDATE' then
    if (to_jsonb(new) - array['last_accessed_at']) is distinct from (to_jsonb(old) - array['last_accessed_at']) then
      raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode = '55000';
    end if;
    return new;
  end if;
  perform pg_advisory_xact_lock_shared(private.closure_account_key(a.account_id));
  select x.* into e from private.closure_executions_v5 x join private.closure_actions_v5 c on c.generation = x.generation and c.account_id = x.account_id
    where x.account_id = a.account_id and x.state = 'EXECUTING' and c.kind = 'STORAGE_DELETE' and c.state = 'DISPATCHED' and c.bucket = old.bucket_id and c.object_path = old.name;
  if not found then raise exception 'MEDIA_ASSET_IMMUTABLE' using errcode = '55000'; end if;
  perform private.closure_assert_current_v5(e);
  perform pg_advisory_xact_lock(private.media_evidence_key_v5(a.account_id));
  -- Only an account-wide hold refuses (it is also a hard closure blocker); a hold scoped to one AI conversation never protects a voice object.
  if exists(select 1 from private.retention_holds where account_id = a.account_id and active and conversation_id is null) then
    raise exception 'MEDIA_EVIDENCE_POLICY_NOT_READY' using errcode = '55000';
  end if;
  return old;
end $function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_surface_v1()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
select encode(extensions.digest(convert_to(jsonb_build_object(
 'bucket',(select jsonb_build_object('id',b.id,'name',b.name,'public',b.public,'fileSizeLimit',b.file_size_limit,'allowedMimeTypes',b.allowed_mime_types)
   from storage.buckets b where b.id='agreement-voice'),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.policyname,'permissive',p.permissive,'roles',p.roles,'cmd',p.cmd,'qual',p.qual,'withCheck',p.with_check)
   order by p.policyname),'[]'::jsonb) from pg_policies p where p.schemaname='storage' and p.tablename='objects'
   and (p.permissive='RESTRICTIVE' or coalesce(p.qual,'')||coalesce(p.with_check,'') like '%agreement-voice%')),
 'rowSecurity',(select jsonb_build_array(c.relrowsecurity,c.relforcerowsecurity) from pg_class c where c.oid='storage.objects'::regclass)
 )::text,'UTF8'),'sha256'),'hex')
$function$;


CREATE OR REPLACE FUNCTION private.agreement_voice_transfer_v1(a private.agreement_voice_uploads_v1)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select jsonb_build_object('receipt', private.agreement_voice_document_v1(a), 'attemptId', a.attempt_id, 'path', a.storage_path, 'sha256', a.validated_sha256,
    'byteSize', a.byte_size, 'durationMs', a.duration_ms, 'dispatchState', a.dispatch_state, 'dispatchOutcome', a.dispatch_outcome);$function$;


CREATE OR REPLACE FUNCTION private.ai_claim_need_turn_context_v1(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_user_message text, p_location_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;request_hash_value text;ctx jsonb;now_at timestamptz;attempt uuid;turn jsonb;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 if p_user_message is null or char_length(btrim(p_user_message)) not between 1 and 4000 then raise exception 'USER_MESSAGE_INVALID' using errcode='22023';end if;
 if p_location_context is not null and not private.ai_location_context_valid(p_location_context) then raise exception 'LOCATION_CONTEXT_INVALID' using errcode='PT409';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 now_at:=clock_timestamp();
 request_hash_value:=private.ai_location_request_hash(c.id,p_user_message,p_location_context);
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if found and t.conversation_id<>c.id then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
 if t.cancelled_at is not null then
  if t.request_hash<>repeat('0',64) and t.request_hash<>request_hash_value then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
  return jsonb_build_object('turn',private.ai_need_turn_status(p_account_id,c.id,p_client_request_id),'claim',null);
 end if;
 if found and (t.conversation_id<>c.id or t.request_hash<>request_hash_value) then raise exception 'AI_REQUEST_ID_REUSED' using errcode=case when p_location_context is null then '22023' else 'PT409' end;end if;
 turn:=private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
 if not (turn->>'retryAllowed')::boolean then
  if t.turn_id is null then
   insert into private.ai_need_turn_commands(account_id,client_request_id,conversation_id,request_hash,state)
   values(p_account_id,p_client_request_id,c.id,request_hash_value,'FAILED');
   turn:=private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
  end if;
  return jsonb_build_object('turn',turn,'claim',null);
 end if;
 if (select count(*) from private.ai_need_turn_commands x cross join lateral unnest(x.attempt_times) a(started)
  where x.account_id=p_account_id and a.started>now_at-interval '1 minute')>=6
 then raise exception 'AI_RATE_LIMITED' using errcode='P0001';end if;
 if p_location_context is not null and not private.ai_location_review_matches(c.id,p_location_context) then raise exception 'LOCATION_VERSION_CONFLICT' using errcode='PT409';end if;
 ctx:=private.ai_need_turn_context(c.id);attempt:=gen_random_uuid();
 if t.turn_id is null then
  insert into private.ai_need_turn_commands(account_id,client_request_id,conversation_id,request_hash,state,context_hash,attempt_id,lease_expires_at,attempt_times)
  values(p_account_id,p_client_request_id,c.id,request_hash_value,'PROCESSING',ctx->>'sha256',attempt,now_at+interval '90 seconds',array[now_at]);
 else
  update private.ai_need_turn_commands set state='PROCESSING',context_hash=ctx->>'sha256',attempt_id=attempt,
   lease_expires_at=now_at+interval '90 seconds',updated_at=now_at,
   attempt_times=array(select x from unnest(attempt_times) x where x>now_at-interval '1 minute')||array[now_at]
  where account_id=p_account_id and client_request_id=p_client_request_id;
 end if;
 return jsonb_build_object('turn',private.ai_need_turn_status(p_account_id,c.id,p_client_request_id),
  'claim',jsonb_build_object('attemptId',attempt,'leaseExpiresAt',now_at+interval '90 seconds','context',ctx->'context'));
end $function$;


CREATE OR REPLACE FUNCTION private.ai_location_context_valid(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb;a jsonb;
begin
 if v is null or jsonb_typeof(v)<>'object' or octet_length(v::text)>40000
 or (select count(*) from jsonb_object_keys(v))<>9
 or not(v ?& array['version','promptToken','reviewRevision','slot','phase','question','query','proposal','alternatives'])
 or v->'version'<>'1'::jsonb
 or jsonb_typeof(v->'promptToken')<>'string' or v->>'promptToken'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 or jsonb_typeof(v->'reviewRevision')<>'string' or v->>'reviewRevision'!~'^[0-9a-f]{64}$'
 or jsonb_typeof(v->'slot')<>'string' or v->>'slot'!~'^(start|end|serviceArea|waypoints/([0-9]|1[0-9]))$'
 or jsonb_typeof(v->'phase') is distinct from 'string' or coalesce(v->>'phase','') not in('PROPOSAL','AMBIGUOUS','UNRESOLVED')
 or jsonb_typeof(v->'question')<>'string' or char_length(btrim(v->>'question')) not between 1 and 300
 or jsonb_typeof(v->'query')<>'string' or char_length(v->>'query')>1000
 or jsonb_typeof(v->'alternatives')<>'array' or jsonb_array_length(v->'alternatives')>20 then return false;end if;
 p:=v->'proposal';
 if (v->>'phase'='PROPOSAL') is distinct from (p<>'null'::jsonb) then return false;end if;
 if p<>'null'::jsonb and (jsonb_typeof(p)<>'object' or (select count(*) from jsonb_object_keys(p))<>2
 or not(p ?& array['id','label']) or jsonb_typeof(p->'id')<>'string'
 or p->>'id'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 or jsonb_typeof(p->'label')<>'string' or char_length(btrim(p->>'label')) not between 1 and 1000) then return false;end if;
 if v->>'phase'='AMBIGUOUS' and jsonb_array_length(v->'alternatives')<2
 or v->>'phase'='UNRESOLVED' and jsonb_array_length(v->'alternatives')<>0 then return false;end if;
 for a in select value from jsonb_array_elements(v->'alternatives') loop
  if jsonb_typeof(a)<>'object' or (select count(*) from jsonb_object_keys(a))<>2 or not(a ?& array['id','label'])
  or jsonb_typeof(a->'id')<>'string' or char_length(btrim(a->>'id')) not between 1 and 160
  or jsonb_typeof(a->'label')<>'string' or char_length(btrim(a->>'label')) not between 1 and 1000 then return false;end if;
 end loop;
 return (select count(*)=count(distinct value->>'id') from jsonb_array_elements(v->'alternatives'));
exception when others then return false;
end $function$;


CREATE OR REPLACE FUNCTION private.ai_location_request_hash(cid uuid, body text, ctx jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select encode(extensions.digest(convert_to(case when ctx is null
 then jsonb_build_object('conversationId',cid,'text',btrim(body))
 else jsonb_build_object('conversationId',cid,'text',btrim(body),'mode','locationReply','locationContext',ctx) end::text,'UTF8'),'sha256'),'hex');
$function$;


CREATE OR REPLACE FUNCTION private.ai_location_review_matches(cid uuid, ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r jsonb;geo jsonb;s text;
begin
 r:=private.need_location_review_document(cid);geo:=r#>'{value,geography}';s:=ctx->>'slot';
 if r->>'revision' is distinct from ctx->>'reviewRevision' or r->'editable' is distinct from 'true'::jsonb then return false;end if;
 if s like 'waypoints/%' then
  return coalesce(jsonb_typeof(geo->'waypoints')='array' and (split_part(s,'/',2))::integer<jsonb_array_length(geo->'waypoints'),false);
 end if;
 return coalesce(geo ? s and geo->s<>'null'::jsonb,false);
end $function$;


CREATE OR REPLACE FUNCTION private.ai_location_turn_document(aid uuid, cid uuid, rid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare normal jsonb;binding jsonb;
begin
 normal:=private.ai_need_turn_status(aid,cid,rid);
 select receipt->'location' into binding from private.ai_need_turn_commands
 where account_id=aid and conversation_id=cid and client_request_id=rid and state='SUCCEEDED';
 return jsonb_build_object('turn',normal,'location',binding);
end $function$;


CREATE OR REPLACE FUNCTION private.ai_need_turn_context(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;history jsonb;facts jsonb;provider_facts jsonb;binding jsonb;material jsonb;
begin
 select * into c from public.ai_conversations where id=p_conversation_id;
 if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select coalesce(jsonb_agg(to_jsonb(m) order by m.sequence_no),'[]'::jsonb) into history from
  (select id,role,body,safety,sequence_no from public.ai_messages where conversation_id=c.id order by sequence_no desc limit 40) m;
 select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'fact_key',f.fact_key,'fact_value',f.fact_value,
  'value_type',f.value_type,'display_value',f.display_value,'fact_schema_version',f.fact_schema_version,
  'status',f.status,'source',f.source,'created_at',f.created_at) order by f.created_at,f.id),'[]'::jsonb)
 into facts from public.ai_structured_facts f where f.conversation_id=c.id and f.superseded_at is null;
 if jsonb_array_length(facts)>64 then raise exception 'AI_CONTEXT_TOO_LARGE' using errcode='22001';end if;
 binding:=jsonb_build_object('conversationId',c.id,'accountId',c.account_id,'status',c.status,
  'boundNeedId',c.bound_need_id,'schema',c.fact_schema_version,'editBase',c.need_edit_base_fingerprint);
 material:=jsonb_build_object('binding',binding,'history',history,'facts',facts);
 if octet_length(material::text)>524288 then raise exception 'AI_CONTEXT_TOO_LARGE' using errcode='22001';end if;
 -- The full material hash fences manual edits, but the private witness never
 -- leaves SQL. Only the current AI-proposable registry reaches the provider.
 select coalesce(jsonb_agg(f.value-'id' order by f.ordinality),'[]'::jsonb) into provider_facts
 from jsonb_array_elements(facts) with ordinality f(value,ordinality)
 join private.need_fact_registry r on r.fact_key=f.value->>'fact_key'
 where f.value->>'fact_key' not in('need.resolved_location','need.public_photo_paths','need.verified_identity_required');
 return jsonb_build_object('sha256',encode(extensions.digest(convert_to(material::text,'UTF8'),'sha256'),'hex'),
  'context',jsonb_build_object('schemaVersion','NEED_FACT_V2',
  'history',(select coalesce(jsonb_agg(h.value-'id'-'safety' order by h.position),'[]'::jsonb) from jsonb_array_elements(history) with ordinality h(value,position)),
  'activeFacts',provider_facts));
end $function$;


CREATE OR REPLACE FUNCTION private.ai_need_turn_status(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;ready boolean;state_value text;
begin
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for share;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2'
 then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 if p_client_request_id is null then raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id;
 if found and t.conversation_id<>c.id then raise exception 'AI_REQUEST_ID_REUSED' using errcode='22023';end if;
 -- Expiry/abort is not proof that a provider request did not run. Only a known
 -- pre-dispatch failure is retryable, and every unresolved turn blocks successors.
 ready:=c.status='OPEN' and not exists(select 1 from private.ai_need_turn_commands x where x.conversation_id=c.id
  and x.client_request_id<>p_client_request_id and x.state='PROCESSING');
 state_value:=case when t.turn_id is null then 'ABSENT' else t.state end;
 return jsonb_build_object('conversationId',c.id,'clientRequestId',p_client_request_id,'state',state_value,'turnId',t.turn_id,
  'retryAllowed',ready and (state_value='ABSENT' or (state_value='FAILED' and not t.provider_dispatched and t.cancelled_at is null)),
  'receipt',t.receipt-'location');
end $function$;


CREATE OR REPLACE FUNCTION private.ai_task_review_command_document(rid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('reviewId',c.review_id,'clientRequestId',c.client_request_id,'needId',c.need_id,
  'needRevision',c.need_revision,'state',case when c.state='EVALUATING' and c.lease_expires_at<statement_timestamp()
   then 'UNKNOWN_OUTCOME' else c.state end,'evaluation',c.evaluation,'published',c.published,'authoritative',true)
 from private.ai_task_review_commands c where c.review_id=rid;
$function$;


CREATE OR REPLACE FUNCTION private.ai_task_review_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;
 raise exception 'TASK_REVIEW_IMMUTABLE' using errcode='55000'; end $function$;


CREATE OR REPLACE FUNCTION private.ai_task_review_policy(country text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b private.publication_policy_bundles; refs jsonb; policy jsonb; market jsonb;
begin
 select to_jsonb(m) into market from private.location_market_configs m where m.country_code=country;
 select * into b from private.publication_policy_bundles where id=private.current_publication_policy_bundle('RS_PUBLICATION_POLICY_MINIMUM',country,statement_timestamp());
 if b.id is not null then
  policy:=private.publication_policy_document(b.id);
  select coalesce(jsonb_agg(to_jsonb(r) order by r.rule_id),'[]'::jsonb) into refs from private.publication_policy_rule_refs r where bundle_id=b.id;
 end if;
 return jsonb_build_object('country',country,'market',market,'bundleId',b.id,'version',b.version,
  'contentSha256',case when b.id is null or policy is null then null else
    encode(extensions.digest(convert_to(jsonb_build_object('bundle',to_jsonb(b),'ruleRefs',refs,'policy',policy)::text,'UTF8'),'sha256'),'hex') end);
end $function$;


CREATE OR REPLACE FUNCTION private.ai_task_review_source(cid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare d jsonb; aid uuid; refs text[];
begin
 d:=private.ai_task_review_source_before_media(cid); aid:=(d#>>'{conversation,accountId}')::uuid; refs:=private.media_task_refs(cid);
 if not private.media_refs_ready(aid,refs) or exists(select 1 from private.owned_media_assets where conversation_id=cid and selected and state in('PROCESSING','STAGED'))
 then raise exception 'PUBLIC_MEDIA_NOT_READY' using errcode='55000'; end if;
 return d||jsonb_build_object('media',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'ref',a.storage_path,'sha256',a.sanitized_sha256,
  'width',a.width,'height',a.height,'bytes',a.byte_size) order by a.storage_path) from private.owned_media_assets a where a.storage_path=any(refs)),'[]'::jsonb));
end $function$;


CREATE OR REPLACE FUNCTION private.ai_task_review_source_before_media(cid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('conversation',jsonb_build_object('id',c.id,'accountId',c.account_id,
  'purpose',c.purpose,'status',c.status,'boundNeedId',c.bound_need_id,'schemaVersion',c.fact_schema_version,'editBase',c.need_edit_base_fingerprint),
  'need',case when c.bound_need_id is null then null else (select jsonb_build_object('id',n.id,'revision',n.revision,'status',n.status,
    'marker',private.need_edit_base_marker(n.id)) from public.needs n where n.id=c.bound_need_id) end,
  'facts',coalesce((select jsonb_agg(to_jsonb(f) order by f.fact_key,f.id) from public.ai_structured_facts f
   where f.conversation_id=c.id and f.superseded_at is null),'[]'::jsonb),
  'messages',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'sequence',m.sequence_no,'safety',m.safety)
   order by m.sequence_no) from public.ai_messages m where m.conversation_id=c.id),'[]'::jsonb),
  'turns',coalesce((select jsonb_agg(jsonb_build_object('id',t.turn_id,'state',t.state,'attempt',t.attempt_id)
   order by t.turn_id) from private.ai_need_turn_commands t where t.conversation_id=c.id),'[]'::jsonb))
 from public.ai_conversations c where c.id=cid;
$function$;


CREATE OR REPLACE FUNCTION private.ai_test_price_microusd(p_prompt_tokens integer, p_output_tokens integer)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select ceil(coalesce(p_prompt_tokens,0) * 0.75 + coalesce(p_output_tokens,0) * 3.75)::bigint;
$function$;


CREATE OR REPLACE FUNCTION private.ai_test_stt_price_microusd(p_audio_bytes bigint, p_transcript_chars integer)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select ceil(
    -- input: seconds x 25 tokens x 3.50 microUSD per token
    (greatest(p_audio_bytes, 0)::numeric / 32000.0) * 25 * 3.50
    -- output: conservative token bound x 21.00 microUSD per token
    + greatest(ceil((greatest(p_audio_bytes, 0)::numeric / 32000.0) / 60.0 * 175), ceil(greatest(p_transcript_chars, 0)::numeric / 2.0)) * 21.00
  )::bigint;
$function$;


CREATE OR REPLACE FUNCTION private.ai_turn_sweep_v5(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_cutoff timestamptz := coalesce(p_at, statement_timestamp()) - interval '10 minutes';
  v_need integer := 0; v_worker integer := 0; v_qa integer := 0; v_review integer := 0; v_errors jsonb := '[]'::jsonb;
begin
  -- A turn whose lease ended ten minutes ago will never be completed by the worker that claimed it.
  -- Expiry is still not proof that the provider did not run, so the request itself is never retried:
  -- it stays failed, and only a NEW request from the person can continue the conversation. What changes
  -- is that it stops blocking that conversation and the account's closure forever.
  begin
    update private.ai_need_turn_commands set state = 'FAILED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_need = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'NEED_INTAKE', 'sqlstate', sqlstate));
  end;
  begin
    update private.worker_ai_turns set state = 'FAILED'
     where state = 'PROCESSING' and lease_expires_at < v_cutoff;
    get diagnostics v_worker = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'WORKER_PROFILE', 'sqlstate', sqlstate));
  end;
  begin
    -- CANCELLED is the existing "this send will never publish anything" state the app already explains.
    update private.qa_ai_commands set state = 'CANCELLED', updated_at = clock_timestamp()
     where state = 'PROCESSING' and lease_expires_at < v_cutoff
       and not private.closure_account_restricted(account_id);
    get diagnostics v_qa = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns', 'PRESELECTION_QA', 'sqlstate', sqlstate));
  end;
  -- PKG-037: a publication claim cannot complete after its 60-second lease.
  -- End expired attempts without a decision, another paid request or any refund.
  -- Lock only a bounded batch; an in-flight completion wins or is fenced by state.
  begin
    with expired as (
      select c.review_id from private.ai_task_review_commands c
       where c.state = 'EVALUATING'
         and c.lease_expires_at <= least(coalesce(p_at, statement_timestamp()), clock_timestamp())
       order by c.lease_expires_at, c.review_id limit 100 for update skip locked
    )
    update private.ai_task_review_commands c set state = 'EVALUATED',
      evaluation = jsonb_build_object('kind','NOT_READY','needId',c.need_id,
        'needRevision',c.need_revision,'authoritativeDecision',false,'code','EVALUATOR_UNAVAILABLE'),
      evaluation_result_hash = encode(extensions.digest(jsonb_build_object(
        'outcome',null,'rules','[]'::jsonb,'reasons','[]'::jsonb,'provider',null,'model',null,
        'notReady','EVALUATOR_UNAVAILABLE')::text,'sha256'),'hex')
     where c.review_id in (select review_id from expired) and c.state = 'EVALUATING';
    get diagnostics v_review = row_count;
  exception when others then
    v_errors := v_errors || jsonb_build_array(jsonb_build_object('turns','PUBLICATION_REVIEW','sqlstate',sqlstate));
  end;
  return jsonb_build_object('needTurnsFailed', v_need, 'workerTurnsFailed', v_worker,
    'qaCommandsCancelled', v_qa, 'reviewEvaluationsStopped', v_review, 'graceMinutes', 10, 'errors', v_errors);
end
$function$;


CREATE OR REPLACE FUNCTION private.application_calendar_conflict_v1(p_response_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record; s timestamptz; e timestamptz;
begin
 select a.worker_profile_id,a.status,a.submitted_against_need_revision,v.need_revision,v.proposed_start_at,v.proposed_end_at,
 n.revision,n.status as need_status,n.schedule_kind,n.starts_at,n.ends_at,n.response_deadline
 into r from public.marketplace_responses a
 join public.needs n on n.id=a.need_id
 join public.marketplace_response_versions v on v.response_id=a.id and v.version=a.current_version
 where a.id=p_response_id;
 if not found or r.status not in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
 or r.need_status not in ('PUBLISHED','SELECTION')
 or r.submitted_against_need_revision is distinct from r.revision or r.need_revision is distinct from r.revision
 or (r.response_deadline is not null and r.response_deadline<=statement_timestamp()) then return false; end if;
 s:=coalesce(r.proposed_start_at,case when r.schedule_kind='FIXED_WINDOW' then r.starts_at end);
 e:=coalesce(r.proposed_end_at,case when r.schedule_kind='FIXED_WINDOW' then r.ends_at end);
 -- Match the selection writer's point probe for legacy start-only tasks; never invent a duration.
 if r.schedule_kind='FIXED_WINDOW' and r.ends_at is null and r.proposed_start_at is null and r.proposed_end_at is null
 and s is not null and isfinite(s) then e:=s+interval '1 microsecond'; end if;
 if (r.proposed_start_at is null)<>(r.proposed_end_at is null)
 or s is null or e is null or not isfinite(s) or not isfinite(e) or s>=e or e<=statement_timestamp() then return false; end if;
 return private.worker_calendar_conflict(r.worker_profile_id,s,e,null);
end;
$function$;


CREATE OR REPLACE FUNCTION private.assert_application_price_v5(n public.needs, p_covered_slots integer, p_price_rsd integer)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if p_price_rsd is null or p_price_rsd <= 0 then
    raise exception using errcode='22023', message='INVALID_PRICE';
  end if;

  if n.mode = 'MY_PRICE' then
    if n.requester_price_rsd is null or n.requester_price_rsd <= 0 then
      raise exception using errcode='P0001', message='FIXED_PRICE_NOT_READY';
    end if;
    -- pkg025b. A null basis is the rule this product has always had: the application's price is
    -- the task's price, whatever it covers. A basis says what that price is FOR.
    if n.price_basis is null then
      if p_price_rsd <> n.requester_price_rsd then
        raise exception using errcode='22023', message='FIXED_PRICE_MISMATCH';
      end if;
    elsif n.price_basis = 'PER_PERSON' then
      if p_price_rsd <> n.requester_price_rsd::bigint * p_covered_slots then
        raise exception using
          errcode='22023',
          message='FIXED_PRICE_MISMATCH',
          detail=format('basis=PER_PERSON,perPerson=%s,covered=%s,expected=%s,sent=%s',
                        n.requester_price_rsd, p_covered_slots,
                        n.requester_price_rsd::bigint * p_covered_slots, p_price_rsd);
      end if;
    elsif n.price_basis = 'TOTAL' then
      -- Owner 2026-10-09: the task total is shared in proportion to this application's headcount.
      -- Use original required_slots, never remaining slots; preserve existing accepted terms.
      if p_price_rsd::numeric is distinct from
         round(n.requester_price_rsd::numeric * p_covered_slots / n.required_slots) then
        raise exception using errcode='22023', message='FIXED_PRICE_MISMATCH',
          detail=format('basis=TOTAL,total=%s,required=%s,covered=%s,sent=%s',
            n.requester_price_rsd,n.required_slots,p_covered_slots,p_price_rsd);
      end if;
    else
      -- Unreachable while the CHECK holds. A basis nobody has reviewed is refused, never guessed.
      raise exception using errcode='22023', message='UNKNOWN_PRICE_BASIS';
    end if;
  end if;

end;
$function$;


CREATE OR REPLACE FUNCTION private.assert_task_replacement_source(p_source uuid, p_revision integer, p_fingerprint text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare n public.needs;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 select * into n from public.needs where id=p_source for update;
 if not found or n.requester_account_id is distinct from auth.uid() then raise exception 'TASK_REVIEW_NOT_FOUND' using errcode='42501';end if;
 perform private.closure_assert_open(auth.uid());
 if exists(select 1 from public.agreements where need_id=n.id)
 or exists(select 1 from public.need_selections where need_id=n.id)
 or exists(select 1 from public.marketplace_responses where need_id=n.id and status='SELECTED')
 then raise exception 'NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR' using errcode='P0001';end if;
 if n.status not in ('PUBLISHED','SELECTION') or n.revision is distinct from p_revision
 or private.need_edit_base_marker(n.id) is distinct from p_fingerprint
 then raise exception 'REPLACEMENT_SOURCE_STALE' using errcode='PT409';end if;
end $function$;


CREATE OR REPLACE FUNCTION private.audit_marketplace(p_actor uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_entity_version integer DEFAULT NULL::integer, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  insert into private.marketplace_audit_log (
    actor_user_id, event_type, entity_type, entity_id, entity_version, detail
  ) values (
    p_actor, p_event_type, p_entity_type, p_entity_id, p_entity_version,
    coalesce(p_detail, '{}'::jsonb)
  );
$function$;


CREATE OR REPLACE FUNCTION private.availability_is_future(kind text, s timestamp with time zone, e timestamp with time zone, at_now timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select coalesce(isfinite(s) and isfinite(e) and s<e and e>at_now
    and (s>at_now or kind in ('TOMORROW_FLEXIBLE','WEEK_FLEXIBLE')),false);
$function$;


CREATE OR REPLACE FUNCTION private.availability_timezone_valid(value text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  -- ZONE-PERF (2026-10-07). The zone catalog pg_timezone_names reads every zone file of the server (1,196 zones, about 52 ms in CI and
  -- 70-110 ms on canonical DEV per call, warm or cold) and this helper runs for every worker x task pair of the matcher, for every
  -- relative deadline and for every availability save. The two names below are the product's own zones and are known to be in the
  -- catalog (the candidate refuses to apply otherwise); they need no scan. Every other value is judged by exactly the expression
  -- used before, so what is accepted and what is refused is unchanged.
  select case
    when value is null or length(value)>100 then false
    when value in ('Europe/Belgrade','UTC') then true
    else (value='UTC' or position('/' in value)>0)
      and value not like 'posix/%' and value not like 'right/%'
      and exists(select 1 from pg_catalog.pg_timezone_names z where z.name=value)
  end;
$function$;


CREATE OR REPLACE FUNCTION private.cancel_replaced_task(p_need_id uuid, p_need_revision integer, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  n public.needs;
  affected_responses integer := 0;
  w record;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;

  -- Same lock as selection, dispatch and submission. Whichever transaction owns
  -- this row determines the canonical outcome of a race.
  select * into n from public.needs where id = p_need_id for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;
  if n.requester_account_id <> u then
    raise exception using errcode='42501', message='FORBIDDEN';
  end if;

  if n.status = 'CANCELLED' then
    return jsonb_build_object(
      'needId', n.id,
      'status', n.status,
      'revision', n.revision,
      'affectedResponses', 0,
      'idempotentReplay', true,
      'authoritative', true
    );
  end if;

  if n.revision is distinct from p_need_revision then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  -- Once a seat is selected, cancellation belongs to the Agreement lifecycle.
  -- Historical CANCELLED Agreements do not keep the remaining Need hostage.
  if exists (
       select 1 from public.need_selections s
        where s.need_id = n.id and s.status = 'SELECTED'
     )
     or exists (
       select 1 from public.agreements a
        where a.need_id = n.id
          and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
     )
     or exists (
       select 1 from public.marketplace_responses r
        where r.need_id = n.id and r.status = 'SELECTED'
     ) then
    raise exception using errcode='P0001',
      message='NEED_CANCELLATION_REQUIRES_AGREEMENT_FLOW';
  end if;

  if n.status not in ('DRAFT','PUBLISHED','SELECTION') then
    raise exception using errcode='22023', message='NEED_NOT_CANCELLABLE';
  end if;

  -- Stop every pending side effect before emitting the terminal event.
  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE')
     and (
       (e.entity_type = 'NEED' and e.entity_id = n.id)
       or (e.entity_type = 'RESPONSE' and exists (
         select 1 from public.marketplace_responses r
          where r.id = e.entity_id and r.need_id = n.id
       ))
       or (e.entity_type = 'AGREEMENT' and exists (
         select 1 from public.agreements a
          where a.id = e.entity_id and a.need_id = n.id
       ))
     );

  update public.dispatch_rounds
     set status = 'STOPPED', stop_reason = 'NEED_CANCELLED'
   where need_id = n.id and status in ('PLANNED','SENT');

  update public.opportunity_deliveries
     set status = 'EXPIRED'
   where need_id = n.id and status in ('READY','SEEN');

  delete from private.dispatch_schedule where need_id = n.id;

  update public.access_grants g
     set status = 'REVOKED',
         revoked_at = coalesce(g.revoked_at, statement_timestamp())
   where g.status = 'GRANTED'
     and exists (
       select 1 from public.agreements a
        where a.id = g.agreement_id and a.need_id = n.id
     );

  perform set_config('uskoci.need_lifecycle', 'CANCEL_NEED', true);
  update public.needs
     set status = 'CANCELLED', urgent = false
   where id = n.id;

  -- Versions are never deleted or rewritten. Only the live Response outcome
  -- changes, and each affected worker receives an independently deduped event.
  for w in
    update public.marketplace_responses r
       set status = 'EXPIRED', selected_at = null
     where r.need_id = n.id
       and r.status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE')
     returning r.id, r.worker_account_id, r.current_version
  loop
    affected_responses := affected_responses + 1;
    perform private.emit_event(
      w.worker_account_id,
      'WORKER',
      'NEED_CANCELLED',
      'NEED',
      n.id,
      n.revision,
      'Zadatak je izmenjen',
      'Objavljena je nova verzija zadatka. Prethodna prijava je zatvorena i nije preneta na nove uslove.',
      'need-cancelled:' || n.id::text || ':' || n.revision::text || ':worker:' || w.worker_account_id::text,
      'NORMAL',
      jsonb_build_object(
        'reason', 'REQUESTER_CANCELLED',
        'reasonProvided', char_length(btrim(coalesce(p_reason, ''))) > 0
      ),
      null
    );
  end loop;

  perform private.audit_marketplace(
    u,
    'NEED_CANCELLED',
    'NEED',
    n.id,
    n.revision,
    jsonb_build_object('reason', left(btrim(coalesce(p_reason, '')), 500))
  );

  return jsonb_build_object(
    'needId', n.id,
    'status', 'CANCELLED',
    'revision', n.revision,
    'affectedResponses', affected_responses,
    'idempotentReplay', false,
    'authoritative', true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION private.candidate_budget(p_urgent boolean, p_remaining integer, p_cfg jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  b jsonb := p_cfg->'candidateBudget';
  fixed integer := (p_cfg->>'candidateLimit')::integer;
  base integer; hard_max integer; max_routing integer;
  avg_cov numeric; resp_rate numeric; safety numeric;
  needed integer; expected numeric; raw integer;
begin
  if b is null or jsonb_typeof(b) <> 'object' then
    return jsonb_build_object('limit', fixed, 'source', 'FIXED', 'maxRoutingCallsPerWave', 0);
  end if;

  base := (b->>'baseLimit')::integer;
  hard_max := (b->>'hardMaxLimit')::integer;
  max_routing := coalesce((b->>'maxRoutingCallsPerWave')::integer, 0);
  avg_cov := (b->>'avgCoveragePerResponse')::numeric;
  resp_rate := (b->>'responseRate')::numeric;
  safety := (b->>'safetyFactor')::numeric;

  -- Nevazeca konfiguracija nikad ne sme da otvori budzet. Pad na fiksni donorov limit.
  if base is null or base < 1
     or hard_max is null or hard_max < base or hard_max > 10000
     or avg_cov is null or avg_cov <= 0
     or resp_rate is null or resp_rate <= 0 or resp_rate > 1
     or safety is null or safety <= 0 then
    if coalesce((p_cfg->>'fallbackToFixedWaves')::boolean, false) then
      return jsonb_build_object('limit', fixed, 'source', 'FIXED', 'maxRoutingCallsPerWave', 0);
    end if;
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;

  if p_remaining is null or p_remaining <= 0 then
    return jsonb_build_object('limit', base, 'source', 'ADAPTIVE_FLOOR', 'maxRoutingCallsPerWave', max_routing);
  end if;

  needed := ceil(p_remaining::numeric / avg_cov)::integer;
  expected := needed::numeric / resp_rate;
  raw := ceil(expected * safety)::integer;

  if raw <= base then
    return jsonb_build_object('limit', base, 'source', 'ADAPTIVE_FLOOR', 'maxRoutingCallsPerWave', max_routing);
  elsif raw >= hard_max then
    return jsonb_build_object('limit', hard_max, 'source', 'ADAPTIVE_CAPPED', 'maxRoutingCallsPerWave', max_routing);
  end if;
  return jsonb_build_object('limit', raw, 'source', 'ADAPTIVE_COMPUTED', 'maxRoutingCallsPerWave', max_routing);
end;
$function$;


CREATE OR REPLACE FUNCTION private.candidate_profile_ids(nid uuid, p_limit integer)
 RETURNS TABLE(worker_profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs; admitted integer := 0; c record; task_geog extensions.geography;
begin
  select * into n from public.needs where id = nid;
  if not found or p_limit is null or p_limit < 1 then return; end if;

  if n.execution_location_mode in ('STATIONARY','POINT_TO_POINT','MULTI_STOP','AREA_BASED')
     and n.approx_geog is not null then
    task_geog := n.approx_geog;

    for c in
      select pref.worker_profile_id as pid
      from public.worker_match_preferences pref
      where pref.approximate_geog is not null
        and extensions.ST_DWithin(pref.approximate_geog, task_geog, 300000.0)
      order by pref.approximate_geog OPERATOR(extensions.<->) task_geog, pref.worker_profile_id
    loop
      if private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
        worker_profile_id := c.pid; return next;
        admitted := admitted + 1;
        exit when admitted >= p_limit;
      end if;
    end loop;

    if admitted < p_limit then
      for c in
        select p.id as pid
        from public.app_profiles p
        left join public.worker_match_preferences pref on pref.worker_profile_id = p.id
        where p.kind = 'WORKER' and p.profile_status = 'ACTIVE' -- MATCH-V1: a draft or suspended profile is never admitted, never visit it
          and (pref.worker_profile_id is null or pref.approximate_geog is null)
        order by p.id
      loop
        if private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
          worker_profile_id := c.pid; return next;
          admitted := admitted + 1;
          exit when admitted >= p_limit;
        end if;
      end loop;
    end if;
    return;
  end if;

  -- Nefizicka Potreba ili bez koordinata: rotacija zasejana ID-jem Potrebe,
  -- da isti radnici ne budu uvek prvi.
  for c in
    select p.id as pid from public.app_profiles p
    where p.kind = 'WORKER' and p.profile_status = 'ACTIVE' -- MATCH-V1: a draft or suspended profile is never admitted, never visit it
    order by case when p.id >= n.id then 0 else 1 end, p.id
  loop
    if private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
      worker_profile_id := c.pid; return next;
      admitted := admitted + 1;
      exit when admitted >= p_limit;
    end if;
  end loop;
end;
$function$;


CREATE OR REPLACE FUNCTION private.candidate_profile_ids_v1b(nid uuid, p_limit integer, p_cap integer)
 RETURNS TABLE(worker_profile_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs; admitted integer := 0; c record; task_geog extensions.geography;
begin
  -- MATCH-V1B (owner 2026-10-07): the candidates of private.candidate_profile_ids, minus the workers who already got p_cap
  -- proactive new-task notifications in the last 24 hours. Such a worker is skipped here and does NOT use up a place of p_limit
  -- (the ceiling), so the next worker takes it; he still sees the task on the map, the list and in "Za mene", and a later wave
  -- takes him when his count has room again. A null cap (an urgent task, or the ladder) is exactly the MATCH-V1 function.
  if p_cap is null then
    return query select * from private.candidate_profile_ids(nid, p_limit);
    return;
  end if;
  select * into n from public.needs where id = nid;
  if not found or p_limit is null or p_limit < 1 then return; end if;

  if n.execution_location_mode in ('STATIONARY','POINT_TO_POINT','MULTI_STOP','AREA_BASED')
     and n.approx_geog is not null then
    task_geog := n.approx_geog;

    for c in
      select pref.worker_profile_id as pid, pref.worker_account_id as uid
      from public.worker_match_preferences pref
      where pref.approximate_geog is not null
        and extensions.ST_DWithin(pref.approximate_geog, task_geog, 300000.0)
      order by pref.approximate_geog OPERATOR(extensions.<->) task_geog, pref.worker_profile_id
    loop
      if private.worker_notify_room_v1b(c.uid, p_cap) and private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
        worker_profile_id := c.pid; return next;
        admitted := admitted + 1;
        exit when admitted >= p_limit;
      end if;
    end loop;

    if admitted < p_limit then
      for c in
        select p.id as pid, p.account_id as uid
        from public.app_profiles p
        left join public.worker_match_preferences pref on pref.worker_profile_id = p.id
        where p.kind = 'WORKER' and p.profile_status = 'ACTIVE'
          and (pref.worker_profile_id is null or pref.approximate_geog is null)
        order by p.id
      loop
        if private.worker_notify_room_v1b(c.uid, p_cap) and private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
          worker_profile_id := c.pid; return next;
          admitted := admitted + 1;
          exit when admitted >= p_limit;
        end if;
      end loop;
    end if;
    return;
  end if;

  -- a task without a place: the rotation seeded by the id of the task, so that the same workers are not always first
  for c in
    select p.id as pid, p.account_id as uid from public.app_profiles p
    where p.kind = 'WORKER' and p.profile_status = 'ACTIVE'
    order by case when p.id >= n.id then 0 else 1 end, p.id
  loop
    if private.worker_notify_room_v1b(c.uid, p_cap) and private.dispatch_cheap_candidate_admitted(n.id, c.pid) then
      worker_profile_id := c.pid; return next;
      admitted := admitted + 1;
      exit when admitted >= p_limit;
    end if;
  end loop;
end;
$function$;


CREATE OR REPLACE FUNCTION private.capture_agreement_media_trigger_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;
 perform private.capture_agreement_media_v5(new.agreement_id,new.version,true);return new;end $function$;


CREATE OR REPLACE FUNCTION private.capture_agreement_media_v5(aid uuid, ver integer, strict_capture boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.agreements;n public.needs;s public.need_selections;previous private.agreement_media_snapshots_v5;
 paths jsonb;assets jsonb:='[]';resolution jsonb;resolved boolean:=true;doc jsonb;
begin
 if exists(select 1 from private.agreement_media_snapshots_v5 where agreement_id=aid and agreement_version=ver) then return;end if;
 select * into a from public.agreements where id=aid;
 select * into n from public.needs where id=a.need_id;
 select * into s from public.need_selections where id=a.selection_id;
 if a.id is null or n.id is null or s.need_id is distinct from n.id or not exists(select 1 from public.agreement_versions where agreement_id=aid and version=ver)
 then raise exception 'MEDIA_EVIDENCE_CONTEXT_INVALID' using errcode='55000';end if;
 perform pg_advisory_xact_lock(private.media_evidence_key_v5(a.requester_account_id));
 if ver>1 then
  select * into previous from private.agreement_media_snapshots_v5 where agreement_id=aid and agreement_version<ver order by agreement_version desc limit 1;
  resolved:=previous.agreement_id is not null and previous.state='RESOLVED';assets:=coalesce(previous.assets,'[]');
 else
  if n.revision=s.need_revision then paths:=to_jsonb(n.public_photo_paths);
  else
   select previous_material_snapshot->'publicPhotoPaths' into paths from private.need_revision_events where need_id=n.id and from_revision=s.need_revision;
   if paths is null then select new_material_snapshot->'publicPhotoPaths' into paths from private.need_revision_events where need_id=n.id and to_revision=s.need_revision;end if;
  end if;
  resolution:=private.resolve_media_snapshot_v5(a.requester_account_id,paths);resolved:=(resolution->>'resolved')::boolean;assets:=resolution->'assets';
 end if;
 if strict_capture and not resolved then raise exception 'MEDIA_EVIDENCE_SOURCE_NOT_READY' using errcode='55000';end if;
 doc:=jsonb_build_object('agreementId',aid,'version',ver,'needId',n.id,'needRevision',s.need_revision,'state',case when resolved then 'RESOLVED' else 'UNRESOLVED' end,'assets',assets);
 insert into private.agreement_media_snapshots_v5(agreement_id,agreement_version,account_id,need_id,need_revision,state,assets,content_sha256)
 values(aid,ver,a.requester_account_id,n.id,s.need_revision,doc->>'state',assets,encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex'));
 insert into private.media_evidence_refs_v5(asset_id,account_id,source_kind,source_id,source_version)
 select (x->>'assetId')::uuid,a.requester_account_id,'AGREEMENT_VERSION',aid,ver from jsonb_array_elements(assets) x on conflict do nothing;
end $function$;


CREATE OR REPLACE FUNCTION private.capture_case_media_trigger_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 if tg_table_name='safety_reports' then perform private.capture_case_media_v5('SAFETY_REPORT',new.id,1,new.agreement_id,new.need_id,null);
 elsif tg_table_name='agreement_execution' then
  if new.problem_opened_at is not null and (tg_op='INSERT' or old.problem_opened_at is null) then perform private.capture_case_media_v5('AGREEMENT_PROBLEM',new.agreement_id,new.agreement_version,new.agreement_id,null,null);end if;
 elsif tg_table_name='retention_holds' then
  if new.active then perform private.capture_case_media_v5('RETENTION_HOLD',new.id,new.revision,null,null,new.account_id,new.conversation_id);end if;
 end if;return new;
end $function$;


CREATE OR REPLACE FUNCTION private.capture_case_media_v5(kind text, sid uuid, ver bigint, aid uuid, nid uuid, owner_id uuid, conversation uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare own uuid;n public.needs;
begin
 if kind='RETENTION_HOLD' then
  select h.account_id into own from private.retention_holds h where h.id=sid and h.account_id=owner_id and h.revision=ver and h.active and h.conversation_id is not distinct from conversation;
 elsif kind='SAFETY_REPORT' then
  if not exists(select 1 from private.safety_reports r where r.id=sid and r.agreement_id is not distinct from aid and r.need_id is not distinct from nid) then raise exception 'MEDIA_EVIDENCE_CONTEXT_INVALID';end if;
  if aid is not null then select a.requester_account_id,a.need_id into own,nid from public.agreements a where a.id=aid;
  elsif nid is not null then select requester_account_id into own from public.needs where id=nid;end if;
 elsif kind='AGREEMENT_PROBLEM' then
  select a.requester_account_id,a.need_id into own,nid from public.agreements a join public.agreement_execution e on e.agreement_id=a.id
  where a.id=aid and sid=aid and e.agreement_version=ver and e.problem_opened_at is not null;
 else raise exception 'MEDIA_EVIDENCE_CONTEXT_INVALID';end if;
 if own is null then return;end if;
 perform pg_advisory_xact_lock(private.media_evidence_key_v5(own));
 if kind='RETENTION_HOLD' then
  insert into private.media_evidence_refs_v5(asset_id,account_id,source_kind,source_id,source_version)
  select m.id,own,kind,sid,ver from private.owned_media_assets m where m.account_id=own and (conversation is null or m.conversation_id=conversation) on conflict do nothing;
 elsif aid is not null then
  insert into private.media_evidence_refs_v5(asset_id,account_id,source_kind,source_id,source_version)
  select distinct r.asset_id,own,kind,sid,ver from private.media_evidence_refs_v5 r where r.account_id=own and r.source_kind='AGREEMENT_VERSION' and r.source_id=aid on conflict do nothing;
 else
  select * into n from public.needs where id=nid;
  insert into private.media_evidence_refs_v5(asset_id,account_id,source_kind,source_id,source_version)
  select m.id,own,kind,sid,ver from private.owned_media_assets m where m.account_id=own and m.scope='TASK' and m.storage_path=any(n.public_photo_paths) on conflict do nothing;
 end if;
end $function$;


CREATE OR REPLACE FUNCTION private.capture_media_active_hold_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 perform pg_advisory_xact_lock(private.media_evidence_key_v5(new.account_id));
 insert into private.media_evidence_refs_v5(asset_id,account_id,source_kind,source_id,source_version)
 select new.id,new.account_id,'RETENTION_HOLD',h.id,h.revision from private.retention_holds h where h.account_id=new.account_id and h.active and (h.conversation_id is null or h.conversation_id=new.conversation_id) on conflict do nothing;
 return new;
end $function$;


CREATE OR REPLACE FUNCTION private.category_of_event(p_event_type text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select case
    when p_event_type = 'OPPORTUNITY_AVAILABLE' then 'opportunities'
    when p_event_type like 'RESPONSE\_%'
      or p_event_type in ('NEED_REVISED','NEED_CANCELLED','CLARIFICATION_CREATED','CLARIFICATION_ANSWERED') then 'responses'
    when p_event_type like 'AGREEMENT\_%'
      or p_event_type in ('MESSAGE_RECEIVED','PRIVATE_ACCESS_GRANTED','REVIEW_RECEIVED') then 'dogovor'
    when p_event_type in ('EXECUTION_STATE_CHANGED','COMPLETION_REQUIRED') then 'execution'
    when p_event_type = 'RECOVERY_OPENED' then 'recovery'
    else 'account'
  end;
$function$;


CREATE OR REPLACE FUNCTION private.check_need_resolved_location_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare nid uuid; n public.needs; s public.need_sensitive; geo jsonb; point jsonb; anchor jsonb;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if tg_table_name='needs' then nid:=new.id; else nid:=new.need_id; end if;
  select * into n from public.needs where id=nid;
  if not found then return null; end if;
  select * into s from public.need_sensitive where need_id=nid;
  if not found or s.resolved_location is null then return null; end if;
  select public_topology into geo from public.need_geography where need_id=nid;
  if private.resolved_location_record_valid(s.resolved_location,n.task_country_code,geo,s.exact_address,n.requester_account_id) is distinct from true then
    raise exception 'LOCATION_BINDING_CHANGED' using errcode='22023'; end if;
  select p into point from jsonb_array_elements(s.resolved_location#>'{value,points}') p where p->>'slot'='start';
  if s.exact_lat is distinct from (point->>'latitudeE6')::numeric/1000000 or s.exact_lng is distinct from (point->>'longitudeE6')::numeric/1000000 then
    raise exception 'LOCATION_BINDING_CHANGED' using errcode='22023'; end if;
  select p into anchor from jsonb_array_elements(s.resolved_location#>'{value,points}') p
    where p->>'slot'=case when geo->>'mode'='AREA_BASED' and geo ? 'serviceArea' then 'serviceArea' else 'start' end;
  if n.approximate_lat is distinct from round((anchor->>'latitudeE6')::numeric/1000000,2)
    or n.approximate_lng is distinct from round((anchor->>'longitudeE6')::numeric/1000000,2) then
    raise exception 'LOCATION_BINDING_CHANGED' using errcode='22023'; end if;
  return null;
end;
$function$;


CREATE OR REPLACE FUNCTION private.claim_retention_job(p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b jsonb;candidate record;c public.ai_conversations;v jsonb;j private.retention_jobs;now_at timestamptz;due timestamptz;token uuid;
 scan private.retention_scan_cursors;scope uuid:=coalesce(p_account_id,'00000000-0000-0000-0000-000000000000'::uuid);
begin
 lock table private.retention_policy_sets,private.retention_policy_rules,private.retention_data_classes,private.legal_document_versions in share mode;
 b:=private.retention_execution_binding();if b is null then return jsonb_build_object('kind','NOT_READY','code','POLICY_NOT_READY');end if;
 if not coalesce(private.retention_ai_source_ready(),false) then return jsonb_build_object('kind','NOT_READY','code','SOURCE_NOT_READY');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:retention-scan:'||scope::text,0)) then return jsonb_build_object('kind','NONE');end if;
 insert into private.retention_scan_cursors(scope_id) values(scope) on conflict do nothing;
 select * into scan from private.retention_scan_cursors where scope_id=scope for update;
 now_at:=clock_timestamp();
 if scan.abandoned_at is not null and not exists(select 1 from public.ai_conversations c0 where c0.status='ABANDONED' and c0.retention_unbound_origin
  and c0.retention_abandoned_at is not null and (p_account_id is null or c0.account_id=p_account_id)
  and (c0.retention_abandoned_at,c0.id)>(scan.abandoned_at,scan.conversation_id)
  and c0.retention_abandoned_at<=now_at-make_interval(secs=>(b->>'retentionSeconds')::integer)) then
  scan.abandoned_at:=null;scan.conversation_id:=null;
 end if;
 for candidate in select c0.id,c0.account_id,c0.retention_abandoned_at from public.ai_conversations c0 where c0.status='ABANDONED' and c0.retention_unbound_origin and c0.retention_abandoned_at is not null
 and (p_account_id is null or c0.account_id=p_account_id) and c0.retention_abandoned_at<=now_at-make_interval(secs=>(b->>'retentionSeconds')::integer)
 and (scan.abandoned_at is null or (c0.retention_abandoned_at,c0.id)>(scan.abandoned_at,scan.conversation_id))
 order by c0.retention_abandoned_at,c0.id limit 100 loop
   update private.retention_scan_cursors set abandoned_at=candidate.retention_abandoned_at,conversation_id=candidate.id where scope_id=scope;
   -- Closure always precedes retention and parent locks. Busy/restricted accounts
   -- are skipped; no new CLAIMED row can deadlock its closure guard.
   if not pg_try_advisory_xact_lock_shared(private.closure_account_key(candidate.account_id)) then continue;end if;
   if private.closure_account_restricted(candidate.account_id) then continue;end if;
   if not pg_try_advisory_xact_lock(hashtextextended('uskoci:retention:'||candidate.account_id::text,0)) then continue;end if;
   select * into c from public.ai_conversations where id=candidate.id for update skip locked;if not found then continue;end if;
   now_at:=clock_timestamp();v:=private.retention_ai_candidate(c.id);if v is null then continue;end if;
   due:=(v->>'abandonedAt')::timestamptz+make_interval(secs=>(b->>'retentionSeconds')::integer);if due>now_at then continue;end if;
   if exists(select 1 from private.retention_holds where account_id=c.account_id and active and (conversation_id is null or conversation_id=c.id)) then continue;end if;
   select * into j from private.retention_jobs where conversation_id=c.id for update;
   if found and (j.status='SUCCEEDED' or j.attempt_number>=5 or (j.status='CLAIMED' and j.lease_until>now_at) or j.next_attempt_at>now_at) then continue;end if;
   token:=gen_random_uuid();
   insert into private.retention_jobs(account_id,conversation_id,status,attempt_id,attempt_number,lease_until,policy_id,policy_sha256,source_sha256,due_at)
   values(c.account_id,c.id,'CLAIMED',token,1,now_at+interval '120 seconds',(b->>'policyId')::uuid,b->>'sha256',v->>'sha256',due)
   on conflict(conversation_id) do update set status='CLAIMED',attempt_id=excluded.attempt_id,attempt_number=retention_jobs.attempt_number+1,
    lease_until=excluded.lease_until,policy_id=excluded.policy_id,policy_sha256=excluded.policy_sha256,source_sha256=excluded.source_sha256,due_at=excluded.due_at,
    next_attempt_at=null,last_code=null,result=null,updated_at=now_at returning * into j;
   perform private.audit_marketplace(null,'RETENTION_JOB_CLAIMED','SYSTEM',j.id,null,jsonb_build_object('attempt',j.attempt_number,'policyId',j.policy_id,'dataset',j.dataset));
   return jsonb_build_object('kind','CLAIMED','jobId',j.id,'attemptId',j.attempt_id,'leaseExpiresAt',j.lease_until,'dataset',j.dataset,'policyVersion',b->>'policyVersion');
 end loop;
 return jsonb_build_object('kind','NONE');
end $function$;


CREATE OR REPLACE FUNCTION private.classification_conversation_revision_v1(cid uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select case c.purpose
  when 'PROFILE' then (select s.revision::bigint from private.worker_ai_sessions s
    where s.conversation_id=c.id and s.account_id=c.account_id)
  when 'NEED_INTAKE' then (select coalesce(max(m.sequence_no),0)::bigint from public.ai_messages m
    where m.conversation_id=c.id and m.account_id=c.account_id)
  else null end
 from public.ai_conversations c
 where c.id=cid and c.status='OPEN' and c.purpose in('PROFILE','NEED_INTAKE');
$function$;


CREATE OR REPLACE FUNCTION private.closure_account_key(a uuid)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$ select hashtextextended('uskoci:account-closure:'||a::text,10121); $function$;


CREATE OR REPLACE FUNCTION private.closure_account_restricted(a uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ select exists(select 1 from private.account_closure_requests r where r.account_id=a
 and r.state in('READY','EXECUTING','FAILED','CLOSED')); $function$;


CREATE OR REPLACE FUNCTION private.closure_action_document_v5(a private.closure_actions_v5, e private.closure_executions_v5)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('accountId',a.account_id,'requestId',e.request_id,'generation',a.generation,'actionId',a.id,'attemptId',a.attempt_id,'kind',a.kind,'state',a.state,'bucket',a.bucket,'objectPath',a.object_path,'policySha256',e.policy_sha256);
$function$;


CREATE OR REPLACE FUNCTION private.closure_assert_current_v5(e private.closure_executions_v5)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b jsonb;
begin
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then perform private.closure_erasure_assert_current_v5(e);return;end if;
 if e.account_id is null or e.state<>'EXECUTING' then raise exception 'CLOSURE_GENERATION_STALE' using errcode='PT409';end if;
 perform 1 from private.retention_policy_sets where retired_at is null for share;
 perform 1 from private.retention_policy_rules order by id for share;
 perform 1 from private.legal_document_versions where is_active order by id for share;
 b:=private.closure_binding_v5();if b is null or b->>'sha256' is distinct from e.policy_sha256 then raise exception 'CLOSURE_POLICY_CHANGED' using errcode='55000';end if;
 if cardinality(private.closure_blockers_v5(e.account_id))>0 then raise exception 'CLOSURE_BLOCKED' using errcode='55000';end if;
 if exists(select 1 from jsonb_array_elements(e.binding#>'{execution,datasets}') d where e.requested_at+make_interval(secs=>(d->>'retentionSeconds')::integer)<=clock_timestamp()) then raise exception 'CLOSURE_RETAINED_RULE_DUE' using errcode='55000';end if;
end $function$;


CREATE OR REPLACE FUNCTION private.closure_assert_open(a uuid, b uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid;
begin
 if a is null then raise exception 'CLOSURE_CONTEXT_INVALID' using errcode='42501'; end if;
 for u in select distinct x from unnest(array[a,b]) x where x is not null order by x loop
  perform pg_advisory_xact_lock_shared(private.closure_account_key(u));
  if private.closure_account_restricted(u) then raise exception 'ACCOUNT_CLOSING' using errcode='42501'; end if;
 end loop;
end;
$function$;


CREATE OR REPLACE FUNCTION private.closure_auth_dispatched_v5(a uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
 where e.account_id=a and ac.account_id=a and ac.kind='AUTH_IDENTITY_ERASE' and ac.state in('DISPATCHED','VERIFIED'))
 or exists(select 1 from private.account_closure_requests where account_id=a and state='CLOSED');
$function$;


CREATE OR REPLACE FUNCTION private.closure_binding_v5()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets;m jsonb;d jsonb;rules jsonb;privacy private.legal_document_versions;terms private.legal_document_versions; classes text[];seen text[]:='{}';binding jsonb;
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=statement_timestamp();
 if not found or p.account_closure_execution is null then return null;end if;m:=p.account_closure_execution;
 if m-ARRAY['schemaVersion','adapterVersion','sourceSha256','privacyDocumentId','privacyContentSha256','authAction','mediaAction','datasets','contentSha256']<>'{}'
 or not(m?&ARRAY['schemaVersion','adapterVersion','sourceSha256','privacyDocumentId','privacyContentSha256','authAction','mediaAction','datasets','contentSha256'])
 or m->'schemaVersion' is distinct from '1'::jsonb or m->>'adapterVersion' is distinct from 'V5_RETAINED_SUBJECT_CLOSURE_V1'
 or m->>'authAction' is distinct from 'AUTH_IDENTITY_ERASED_SUBJECT_RETAINED' or m->>'mediaAction' is distinct from 'DELETE_OWNED_OBJECTS'
 or m->>'sourceSha256' is distinct from (select sha256 from private.closure_source_v5 where singleton)
 or m->>'sourceSha256' is distinct from private.closure_source_digest_v5()
 or jsonb_typeof(m->'datasets') is distinct from 'array'
 or coalesce(m->>'privacyDocumentId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[a-f0-9]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null;end if;
 select array_agg(code order by code) into classes from private.retention_data_classes where active and required;
 if classes is distinct from (select array_agg(data_class order by data_class) from private.closure_dataset_catalog_v5) then return null;end if;
 if exists(select 1 from private.closure_dataset_catalog_v5 c,unnest(c.relations) r where to_regclass(r) is null) then return null;end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
  if jsonb_typeof(d) is distinct from 'object' or d-ARRAY['dataClass','action','retentionSeconds','trigger','ruleSha256']<>'{}'
  or not(d?&ARRAY['dataClass','action','retentionSeconds','trigger','ruleSha256']) or not(coalesce(d->>'dataClass','')=any(classes))
  or (d->>'dataClass')=any(seen) or d->>'action' is distinct from 'RETAIN_RESTRICTED' or d->>'trigger' is distinct from 'CLOSURE_REQUESTED'
  or jsonb_typeof(d->'retentionSeconds') is distinct from 'number' or coalesce(d->>'retentionSeconds','')!~'^[1-9][0-9]{0,9}$'
  then return null;end if;
  if (d->>'retentionSeconds')::numeric>2147483647 then return null;end if;
  if d->>'ruleSha256' is distinct from (select encode(extensions.digest(convert_to(to_jsonb(r)::text,'UTF8'),'sha256'),'hex') from private.retention_policy_rules r where policy_id=p.id and data_class=d->>'dataClass') then return null;end if;
  seen:=array_append(seen,d->>'dataClass');
 end loop;
 if cardinality(seen)<>cardinality(classes) then return null;end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active
 and published_at<=statement_timestamp() and effective_at<=statement_timestamp() and content_sha256=m->>'privacyContentSha256';
 if not found then return null;end if;
 select * into terms from private.legal_document_versions where document_kind='TERMS' and is_active and published_at<=statement_timestamp() and effective_at<=statement_timestamp();
 if not found then return null;end if;
 select jsonb_agg(to_jsonb(r) order by data_class) into rules from private.retention_policy_rules r where policy_id=p.id;
 binding:=jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'counselReference',p.counsel_reference,'execution',m,'rules',rules,
 'privacy',jsonb_build_object('id',privacy.id,'sha256',privacy.content_sha256),'terms',jsonb_build_object('id',terms.id,'sha256',terms.content_sha256));
 return binding||jsonb_build_object('sha256',encode(extensions.digest(convert_to(binding::text,'UTF8'),'sha256'),'hex'));
end $function$;


CREATE OR REPLACE FUNCTION private.closure_blockers_v5(a uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare codes text[]:='{}';
begin
 if exists(select 1 from private.retention_holds where account_id=a and active) then codes:=array_append(codes,'RETENTION_HOLD');end if;
 if exists(select 1 from public.agreements where (requester_account_id=a or worker_account_id=a) and status not in('COMPLETED','CANCELLED')) then codes:=array_append(codes,'ACTIVE_AGREEMENT');end if;
 if exists(select 1 from public.needs where requester_account_id=a and status in('PUBLISHED','SELECTION','ACTIVE')) then codes:=array_append(codes,'OPEN_TASK');end if;
 if exists(select 1 from public.marketplace_responses where worker_account_id=a and status in('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')) then codes:=array_append(codes,'ACTIVE_APPLICATION');end if;
 if exists(select 1 from private.ai_need_turn_commands where account_id=a and state='PROCESSING')
 or exists(select 1 from private.worker_ai_turns where account_id=a and state='PROCESSING')
 or exists(select 1 from private.qa_ai_commands where account_id=a and state='PROCESSING')
 or exists(select 1 from private.retention_jobs where account_id=a and status='CLAIMED')
 or exists(select 1 from public.data_export_requests where account_id=a and status='PROCESSING') then codes:=array_append(codes,'PENDING_WORKFLOW');end if;
 if exists(select 1 from private.owned_media_assets where account_id=a and dispatch_state='DISPATCHING')
 or exists(select 1 from private.data_export_artifacts where account_id=a and verified_at is null) then codes:=array_append(codes,'STORAGE_PRODUCER_UNSETTLED');end if;
 -- A foreign bucket or a legacy object without an authoritative owner-prefix
 -- cannot become an arbitrary service-role deletion target.
 if exists(select 1 from storage.objects where (owner_id=a::text or split_part(name,'/',1)=a::text)
 and (bucket_id not in('profile-media','data-export-artifacts','agreement-voice') or split_part(name,'/',1)<>a::text or name~'(^|/)[.][.](/|$)' or strpos(name,chr(92))>0)) then codes:=array_append(codes,'STORAGE_INVENTORY_UNSUPPORTED');end if;
 if private.media_owner_protected_v5(a) then codes:=array_append(codes,'MEDIA_EVIDENCE_POLICY_NOT_READY');end if;
 if exists(select 1 from private.support_cases_v5 where account_id=a) then codes:=array_append(codes,'SUPPORT_RETENTION_POLICY_NOT_READY');end if;
 if exists(select 1 from private.agreement_photo_uploads_v5 where account_id=a and dispatch_state='DISPATCHING')
 or exists(select 1 from private.agreement_voice_uploads_v1 where account_id=a and dispatch_state='DISPATCHING') then codes:=array_append(codes,'MEDIA_UPLOAD_PENDING');end if;
 return codes;
end $function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_agreement_protected_v5(g uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select exists(select 1 from public.agreement_execution where agreement_id=g and problem_opened_at is not null)
 or exists(select 1 from private.safety_reports where agreement_id=g)
 or exists(select 1 from private.support_cases_v5 where context->>'kind'='AGREEMENT' and context->>'id'=g::text)
 or exists(select 1 from private.support_evidence_v5 where source_kind='AGREEMENT' and source_id=g);
$function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_assert_current_v5(e private.closure_executions_v5)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b jsonb;begin
 if e.account_id is null or e.state<>'EXECUTING' or e.binding->>'adapterVersion' is distinct from 'OWNER_AF_D22_EVENT_ERASURE_V1' then raise exception 'CLOSURE_GENERATION_STALE' using errcode='PT409';end if;
 b:=private.closure_erasure_binding_v5();
 if b is null or b->>'sha256' is distinct from e.policy_sha256 or b is distinct from e.binding then raise exception 'CLOSURE_POLICY_CHANGED' using errcode='55000';end if;
 if cardinality(private.closure_erasure_hard_blockers_v5(e.account_id))>0 then raise exception 'CLOSURE_BLOCKED' using errcode='55000';end if;
end $function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_binding_v5()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s text;b jsonb;begin
 select sha256 into s from private.closure_erasure_source_v5 where singleton;
 if s is null or s is distinct from private.closure_source_digest_v5() or private.retention_ai_source_ready() is distinct from true then return null;end if;
 b:=jsonb_build_object('adapterVersion','OWNER_AF_D22_EVENT_ERASURE_V1','provenance','OWNER_AF_D22','trigger','CLOSURE_REQUESTED',
  'sourceSha256',s,'authAction','AUTH_IDENTITY_ERASED_SUBJECT_RETAINED','mediaAction','DELETE_UNPROTECTED_OWNED_OBJECTS',
  'relationalAction','ERASE_ORDINARY_PERSONAL_CONTENT','exceptionAction','SCOPED_REVIEW_REQUIRED','legalPolicyAttested',false);
 return b||jsonb_build_object('sha256',encode(extensions.digest(convert_to(b::text,'UTF8'),'sha256'),'hex'));
end $function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_exceptions_v5(a uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare reasons text[]:='{}';
begin
 if exists(select 1 from private.support_cases_v5 where account_id=a)
 or exists(select 1 from private.support_events_v5 where actor_account_id=a and body is not null)
 or exists(select 1 from private.support_decisions_v5 where operator_account_id=a)
 or exists(with refs as (
  select context->>'kind' kind,(context->>'id')::uuid id from private.support_cases_v5 where context?'id'
  union all select source_kind,source_id from private.support_evidence_v5)
  select 1 from refs r where
   (r.kind='TASK' and exists(select 1 from public.needs where id=r.id and requester_account_id=a))
   or(r.kind='AGREEMENT_MESSAGE' and exists(select 1 from public.agreement_messages where id=r.id and sender_account_id=a))
   or(r.kind='GROUP_MESSAGE' and exists(select 1 from private.group_messages_v5 where id=r.id and sender_account_id=a))
   or(r.kind='TASK_REVIEW' and exists(select 1 from private.ai_task_reviews where id=r.id and account_id=a)))
 or exists(select 1 from private.retention_holds where account_id=a and active and conversation_id is not null)
 or exists(select 1 from private.safety_reports where reporter_account_id=a or target_account_id=a)
 or exists(select 1 from public.agreements g where a in(g.requester_account_id,g.worker_account_id)
  and private.closure_erasure_agreement_protected_v5(g.id))
 then reasons:=array_append(reasons,'SCOPED_EVIDENCE_REVIEW_REQUIRED');end if;
 if private.media_owner_protected_v5(a) then reasons:=array_append(reasons,'MEDIA_EVIDENCE_REVIEW_REQUIRED');end if;
 if exists(select 1 from private.closure_scope_sources_v5 ss where account_id=a and scope_author is null and
  (case when source_kind='VERSION' then (select v.terms->>'scope_note' from public.agreement_versions v where v.agreement_id=ss.agreement_id and v.version::text=ss.source_id)
   else (select p.proposed_terms->>'scope_note' from public.agreement_change_proposals p where p.id::text=ss.source_id) end) is distinct from '') then reasons:=array_append(reasons,'HISTORY_ATTRIBUTION_REVIEW_REQUIRED');end if;
 if exists(select 1 from private.qa_ai_commands own join private.qa_ai_commands peer
  on (peer.policy_decision_id=own.policy_decision_id or peer.materiality_decision_id=own.materiality_decision_id)
  where (own.account_id=a or own.need_id in(select id from public.needs where requester_account_id=a)) and peer.account_id<>a
  and not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
   where e.account_id=peer.account_id and ac.kind='RELATIONAL_REDACT' and ac.state='VERIFIED')) then reasons:=array_append(reasons,'SHARED_DECISION_REVIEW_REQUIRED');end if;
 return reasons;
end $function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_hard_blockers_v5(a uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select coalesce(array_agg(c order by ord),'{}') from unnest(private.closure_blockers_v5(a)) with ordinality x(c,ord)
 where c not in('MEDIA_EVIDENCE_POLICY_NOT_READY','SUPPORT_RETENTION_POLICY_NOT_READY')
 and (c<>'RETENTION_HOLD' or exists(select 1 from private.retention_holds where account_id=a and active and conversation_id is null));
$function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_lock_v5(a uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if a is null then raise exception 'CLOSURE_INPUT_INVALID' using errcode='22023';end if;
 -- Support acquires this global private-test barrier before any involved owner,
 -- quota, source row or media lock. Never invert operator and closure locks.
 perform pg_advisory_xact_lock(private.support_operator_key_v5());
 perform pg_advisory_xact_lock(private.closure_account_key(a));
 perform pg_advisory_xact_lock(hashtextextended('uskoci:retention:'||a::text,0));
end $function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_media_protected_v5(a uuid, p text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select exists(select 1 from private.retention_holds h where account_id=a and active and (conversation_id is null or exists(
  select 1 from private.owned_media_assets m where m.account_id=a and m.storage_path=p and m.conversation_id=h.conversation_id)))
 or exists(select 1 from private.media_evidence_gaps_v5 where account_id=a)
 or exists(select 1 from private.agreement_media_snapshots_v5 where account_id=a and state='UNRESOLVED')
 or exists(select 1 from private.media_evidence_refs_v5 r where r.account_id=a and r.asset_id in(
  select id from private.owned_media_assets where account_id=a and storage_path=p
  union all select id from private.agreement_photo_uploads_v5 where account_id=a and storage_path=p));
$function$;


CREATE OR REPLACE FUNCTION private.closure_erasure_program_digest_v5()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
