CREATE OR REPLACE FUNCTION private.closure_support_source_fence_v5(a uuid, k text, i uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare own uuid;peer uuid;n public.needs;m public.agreement_messages;gm private.group_messages_v5;g public.agreements;begin
 perform pg_advisory_xact_lock(private.support_operator_key_v5());
 -- Authenticate visibility before resolving another owner's barrier. The
 -- original reference routine repeats its visibility/revision checks afterward.
 if k='TASK' then
  select * into n from public.needs where id=i;
  if not found or not(n.requester_account_id=a or n.status in('PUBLISHED','SELECTION') or rls_private.need_participant_can_read(n.id)) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  own:=n.requester_account_id;
 elsif k='AGREEMENT' then
  select * into g from public.agreements where id=i;
  if not found or a not in(g.requester_account_id,g.worker_account_id) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  own:=g.requester_account_id;peer:=g.worker_account_id;
 elsif k='AGREEMENT_MESSAGE' then
  select * into m from public.agreement_messages where id=i;select * into g from public.agreements where id=m.agreement_id;
  if g.id is null or a not in(g.requester_account_id,g.worker_account_id) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;own:=m.sender_account_id;
 elsif k='GROUP_MESSAGE' then
  select * into gm from private.group_messages_v5 where id=i;
  if not found or not exists(select 1 from private.group_message_visibility_v5 where message_id=i and account_id=a)
  or not exists(select 1 from private.group_conversations_v5 gr where gr.id=gm.group_id and private.group_member_v5(gr,a)) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;own:=gm.sender_account_id;
 elsif k='TASK_REVIEW' then
  if not exists(select 1 from private.ai_task_reviews where id=i and account_id=a) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;own:=a;
 elsif k<>'SAFETY_REPORT' then raise exception 'SUPPORT_REFERENCE_INVALID' using errcode='22023';end if;
 -- A source already closing cannot be copied anew. Existing stored snapshots,
 -- their owned reads and freeform rights submissions do not call this fence.
 if own is not null then perform private.closure_assert_open(own,peer);end if;
end $function$;


CREATE OR REPLACE FUNCTION private.closure_taxonomy_export_catalog_v1()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT jsonb_agg(jsonb_build_object('key',x->>'key','fields',x->'fields','dataClass',x->>'dataClass',
 'ownershipFilter',private.closure_taxonomy_scope_v1(x->>'relation')) ORDER BY x->>'key')
 FROM jsonb_array_elements(private.closure_taxonomy_inventory_v1()) x;
$function$;


CREATE OR REPLACE FUNCTION private.closure_taxonomy_export_rows_v1(a uuid)
 RETURNS TABLE(key text, value jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;r record;
BEGIN
 IF a IS NULL THEN RAISE EXCEPTION 'F01_EXPORT_OWNER_REQUIRED';END IF;
 FOR c IN SELECT x FROM jsonb_array_elements(private.closure_taxonomy_inventory_v1()) x LOOP
  FOR r IN EXECUTE format('select to_jsonb(t) value from %s t where (%s)',(c->>'relation')::regclass,private.closure_taxonomy_scope_v1(c->>'relation')) USING a LOOP
   key:=c->>'key';value:=private.closure_taxonomy_project_v1(c->>'relation',r.value,a);RETURN NEXT;
  END LOOP;
 END LOOP;
END $function$;


CREATE OR REPLACE FUNCTION private.closure_taxonomy_held_v1(r text, t jsonb, a uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE cid uuid;rid uuid;
BEGIN
 IF r='private.work_taxonomy_gemini_turn_hints_v1' THEN cid:=(t->>'conversation_id')::uuid;
 ELSIF t?'source_review_id' THEN
  rid:=(t->>'source_review_id')::uuid;
  SELECT conversation_id INTO cid FROM (
   SELECT conversation_id FROM private.worker_ai_reviews WHERE id=rid AND account_id=a
   UNION SELECT conversation_id FROM private.ai_task_reviews WHERE id=rid AND account_id=a) s;
 ELSIF r IN('private.work_taxonomy_need_skills','private.work_taxonomy_need_snapshots') THEN
  RETURN EXISTS(SELECT 1 FROM private.work_taxonomy_need_bindings_v1 b
   JOIN private.ai_task_reviews v ON v.id=b.source_review_id AND v.account_id=a
   JOIN private.retention_holds h ON h.account_id=a AND h.conversation_id=v.conversation_id AND h.active
   WHERE b.owner_account_id=a AND b.need_id=(t->>'need_id')::uuid AND b.need_revision=(t->>'need_revision')::integer);
 ELSIF r IN('private.work_taxonomy_worker_capabilities','private.worker_execution_mode_choices') THEN
  RETURN EXISTS(SELECT 1 FROM private.taxonomy_confirmed_worker_modes_v1 m
   JOIN private.worker_ai_reviews v ON v.id=m.source_review_id AND v.account_id=a
   JOIN private.retention_holds h ON h.account_id=a AND h.conversation_id=v.conversation_id AND h.active
   WHERE m.worker_account_id=a AND (r='private.worker_execution_mode_choices' OR m.category_id=(t->>'category_id')::uuid));
 END IF;
 RETURN cid IS NOT NULL AND EXISTS(SELECT 1 FROM private.retention_holds h WHERE h.account_id=a AND h.active AND h.conversation_id=cid);
END $function$;


