"worker_account_id","fields":["id","worker_profile_id","need_id","need_revision","match_score","reason_codes","status","expires_at","seen_at","responded_at","created_at","updated_at"],"mode":"ACCOUNT"},{"relation":"private.dev_phase1_20261014_dispatch_snapshot","dataClass":"NOTIFICATION_DELIVERY","key":"archivedTaskDispatch","ownerColumn":"need_id","fields":["id","need_id","need_revision","round_no","urgency","status","stop_reason","deadline_at","created_at"],"mode":"NEED"},{"relation":"private.dev_test101_owner_worker_profile_backup","dataClass":"PROFILE_DATA","key":"archivedWorkerProfile","ownerColumn":"account_id","fields":["id","kind","display_name","city","headline","bio","avatar_path","account_type","profile_status","years_experience","portfolio","skills","tools","vehicles","licenses","exclusions","radius_km","operating_country_code","available_now","available_now_expires_at","team_capacity","minimum_fee_rsd","rating_requester","rating_worker","created_at","updated_at"],"mode":"ACCOUNT"},{"relation":"private.dev_test101_owner_profile_backup_20261014","dataClass":"PROFILE_DATA","key":"archivedProfiles","ownerColumn":"account_id","fields":["id","kind","display_name","city","headline","bio","avatar_path","account_type","profile_status","years_experience","portfolio","skills","tools","vehicles","licenses","exclusions","radius_km","operating_country_code","available_now","available_now_expires_at","team_capacity","minimum_fee_rsd","rating_requester","rating_worker","created_at","updated_at"],"mode":"ACCOUNT"},{"relation":"private.dev_worker_profile_reset_snapshots_v1","dataClass":"PROFILE_DATA","key":"archivedWorkerReset","ownerColumn":"account_id","fields":["backup_id","profile_id","backed_up_at","payload"],"mode":"ACCOUNT"},{"relation":"private.dev_phase1_20261014_needs_snapshot","dataClass":"NEED_PUBLIC","key":"archivedTasks","ownerColumn":"requester_account_id","fields":["id","title","description","category","category_id","approximate_city","approximate_area","