 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ select jsonb_build_object('displayName',private.data_export_scalar_v5(v->'displayName','string'),'bio',private.data_export_scalar_v5(v->'bio','string'),'skills',private.data_export_array_v5(v->'skills','string'),'tools',private.data_export_array_v5(v->'tools','string'),'licenses',private.data_export_array_v5(v->'licenses','string'),'vehicles',private.data_export_array_v5(v->'vehicles','string'),'teamCapacity',private.data_export_scalar_v5(v->'teamCapacity','number'),'location',jsonb_build_object('operatingCountryCode',private.data_export_scalar_v5(v#>'{location,operatingCountryCode}','string'),'city',private.data_export_scalar_v5(v#>'{location,city}','string'),'radiusKm',private.data_export_scalar_v5(v#>'{location,radiusKm}','number'),'approximatePosition',jsonb_build_object('latitude',private.data_export_scalar_v5(v#>'{location,approximatePosition,latitude}','number'),'longitude',private.data_export_scalar_v5(v#>'{location,approximatePosition,longitude}','number'))),'availability',jsonb_build_object('timezone',private.data_export_scalar_v5(v#>'{availability,timezone}','string'),'availableNow',private.data_export_scalar_v5(v#>'{availability,availableNow}','boolean'),'rules',coalesce((select jsonb_agg(jsonb_build_object('id',private.data_export_scalar_v5(x->'id','string'),'startTime',private.data_export_scalar_v5(x->'startTime','string'),'endTime',private.data_export_scalar_v5(x->'endTime','string'),'startsOn',private.data_export_scalar_v5(x->'startsOn','string'),'endsOn',private.data_export_scalar_v5(x->'endsOn','string'),'label',private.data_export_scalar_v5(x->'label','string'),'active',private.data_export_scalar_v5(x->'active','boolean'),'weekdays',private.data_export_array_v5(x->'weekdays','number')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof(v#>'{availability,rules}')='array' then v#>'{availability,rules}' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb),'windows',coalesce((select jsonb_agg(jsonb_build_object('id',private.data_export_scalar_v5(x->'id','string'),'startsAt',private.data_export_scalar_v5(x->'startsAt','string'),'endsAt',private.data_export_scalar_v5(x->'endsAt','string'),'state',private.data_export_scalar_v5(x->'state','string'),'label',private.data_export_scalar_v5(x->'label','string')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof(v#>'{availability,windows}')='array' then v#>'{availability,windows}' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb))) $function$;


CREATE OR REPLACE FUNCTION private.dispatch_cheap_candidate_admitted(nid uuid, pid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select exists (
    select 1
    from public.needs n
    join public.app_profiles p on p.id = pid
    left join public.worker_match_preferences pref on pref.worker_profile_id = p.id
    where n.id = nid
      and p.kind = 'WORKER'
      and p.profile_status = 'ACTIVE'
      and coalesce(pref.proactive_notifications, true) = true
      -- MATCH-V1 (owner 2026-10-07): the ONE shared "Odgovara mi" rule: kind of work + area + time and the existing
      -- hard exceptions (own task, other world, identity, exclusions). Tools, vehicles, experience and the
      -- minimum fee are no longer conditions; licenses were retired by WPP01. The rule takes the ROW columns, never
      -- the bare parameters: a parameter-only call is a one-time filter that would run before the status filter above,
      -- for every draft or suspended profile the candidate loop visits.
      and private.worker_need_match_v1(n.id, p.id)
      and not exists (
        select 1 from public.opportunity_deliveries od
        where od.worker_account_id = p.account_id
          and od.need_id = n.id
          and od.need_revision = n.revision)
  );
$function$;


CREATE OR REPLACE FUNCTION private.dispatch_config_v1b(sw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  k text; knob record; v jsonb; num numeric; flag boolean := false; cap integer; budget integer;
begin
  -- MATCH-V1B (owner 2026-10-07): checks the knobs of the row private.marketplace_config 'match_v1_dispatch' that this package
  -- adds (mode ALL only). A bad value, a missing cap or budget or a misspelt knob of the two new families is the named configuration
  -- error DISPATCH_CONFIG_INVALID, never a setting that silently stays as it was. Returns the checked switch, the cap that is in force
  -- (workerDailyCap 1000 is "off" and comes back as null: no query is made for it) and the notify budget of one transaction. A wave
  -- larger than that budget could never be sent, so it is an error too.
  for k in select jsonb_object_keys(sw) loop
    if (k like 'remote%' and k not in ('remoteWaves','remoteWaveSize','remoteNextWaveSize','remoteWaveMinutes','remoteStopAfterResponses','remoteCeiling'))
       or (k like 'worker%' and k not in ('workerDailyCap','workerNotifyPerTransaction')) then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
  end loop;

  v := sw->'workerDailyCap';
  if v is null or jsonb_typeof(v) <> 'number' then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;
  num := (v #>> '{}')::numeric;
  if num <> trunc(num) or num < 1 or num > 1000 then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;
  cap := num::integer;

  v := sw->'workerNotifyPerTransaction';
  if v is null or jsonb_typeof(v) <> 'number' then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;
  num := (v #>> '{}')::numeric;
  if num <> trunc(num) or num < 50 or num > 1500 then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;
  budget := num::integer;

  v := sw->'remoteWaves';
  if v is not null then
    if jsonb_typeof(v) <> 'boolean' then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
    flag := (v #>> '{}')::boolean;
  end if;
  if flag then
    for knob in
      select * from (values ('remoteWaveSize', 1, 1500), ('remoteNextWaveSize', 1, 1500), ('remoteWaveMinutes', 1, 1440),
                            ('remoteStopAfterResponses', 1, 1000), ('remoteCeiling', 1, 10000))
        as t(knob_key, lo, hi)
    loop
      v := sw->knob.knob_key;
      if v is null or jsonb_typeof(v) <> 'number' then
        raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
      end if;
      num := (v #>> '{}')::numeric;
      if num <> trunc(num) or num < knob.lo or num > knob.hi then
        raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
      end if;
    end loop;
    if (sw->>'remoteWaveSize')::integer > budget or (sw->>'remoteNextWaveSize')::integer > budget then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
  end if;
  return jsonb_build_object('remoteWaves', flag, 'workerDailyCap', case when cap >= 1000 then null else cap end, 'notifyBudget', budget);
end;
$function$;


CREATE OR REPLACE FUNCTION private.dispatch_next_wave(nid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs;
  cfg jsonb; sizes jsonb; budget jsonb; urgcfg jsonb;
  roundno integer; policy_wave_no integer;
  batch integer; target integer; windowm integer; min_choice integer;
  candidate_limit integer; budget_source text;
  active integer; active_coverage integer; selected integer; remaining integer;
  roundid uuid := gen_random_uuid();
  inserted integer := 0;
  c record; d jsonb; deadline timestamptz; urg text;
  -- MATCH-V1 (owner 2026-10-07): the switch row private.marketplace_config 'match_v1_dispatch' (see below).
  sw jsonb; all_mode boolean := false; sw_ceiling integer; sw_valid integer; delivered integer := 0; valid_until timestamptz;
  -- MATCH-V1B (owner 2026-10-07): the checked knobs of the new layers, whether this task is sent in waves, the per-worker daily cap.
  cfgb jsonb; remote_on boolean := false; daily_cap integer;
  -- MATCH-V1B: the notify budget of one database transaction (the lock table), what the transaction has used, and whether a wave was cut by it.
  tx_budget integer; tx_used integer := 0; chunked boolean := false;
begin
  select * into n from public.needs where id = nid for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;

  if n.status not in ('PUBLISHED','SELECTION') then
    return jsonb_build_object('status','STOPPED','reason','NEED_NOT_OPEN','inserted',0);
  end if;

  if n.remaining_search_closed_at is not null then
    return jsonb_build_object('status','STOPPED','reason','REMAINING_SEARCH_CLOSED','inserted',0);
  end if;

  if not private.need_search_time_admitted_v1(n.id, clock_timestamp()) then
    return jsonb_build_object('status','STOPPED','reason','SEARCH_WINDOW_CLOSED','inserted',0);
  end if;

  select coalesce(sum(covered_slots),0) into selected
    from public.need_selections where need_id = nid and status = 'SELECTED';
  remaining := greatest(0, n.required_slots - selected);
  if remaining = 0 then
    return jsonb_build_object('status','STOPPED','reason','SLOTS_FILLED','inserted',0,
      'selectedSlots',selected,'remainingSlots',0);
  end if;

  select count(*), coalesce(sum(covered_slots),0) into active, active_coverage
    from public.marketplace_responses
   where need_id = nid and submitted_against_need_revision = n.revision
     and status in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED');

  -- Hitnost se cita iz projekcije, ne iz sirove zastavice: istekao prozor je NORMAL.
  urg := case when coalesce(n.urgent,false) and n.urgent_expires_at > statement_timestamp()
              then 'URGENT' else 'NORMAL' end;

  select value into cfg from private.marketplace_config
   where key = case when urg = 'URGENT' then 'dispatch_urgent' else 'dispatch_normal' end;
  if cfg is null then raise exception using errcode='55000', message='DISPATCH_CONFIG_MISSING'; end if;

  sizes := cfg->'waveSizes';
  target := (cfg->>'targetResponses')::integer;
  windowm := (cfg->>'windowMinutes')::integer;
  if jsonb_typeof(sizes) <> 'array' or jsonb_array_length(sizes) = 0
     or target is null or target < 1 or windowm is null or windowm < 1 then
    raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
  end if;

  -- MATCH-V1 (owner 2026-10-07): HOW does this server dispatch? One switch row decides; turning the ladder on needs no code change.
  --   mode ALL (the default of this package): ONE wave to EVERY worker the shared rule admits, nearest first, in this tick. No group of
  --     5 / 5 / 10 / 20, no waiting window between groups, no stop after N responses (a stop would starve later workers of their
  --     notification). A worker who becomes eligible later (a new or a changed profile) is reached by the next wave of the same task
  --     (the profile re-queue); a worker already notified for this revision is never notified twice. Safety ceiling: at most 'ceiling'
  --     notified workers per task REVISION (default 500). Above it nobody more is notified for that revision: the task stays on the
  --     map and the list for everyone and applying stays open; the wave answers DELIVERY_CEILING_REACHED (the tick records it in
  --     dispatch_schedule.last_reason and keeps its normal back-off check); raising the ceiling continues with the workers not yet
  --     notified, nearest first. Deliveries and their notifications stay valid for 'validMinutes' (default 24 h): the push transport
  --     needs time to reach hundreds of workers and an expired notification would be a worker who never heard of the task.
  --   mode LADDER (or no row): today's waves, unchanged (dispatch_normal / dispatch_urgent: waveSizes, windowMinutes, targetResponses,
  --     candidate budget). "Mogu odmah" first (timeTier) orders the workers inside a wave in both modes.
  select value into sw from private.marketplace_config where key = 'match_v1_dispatch';
  if sw is not null then
    if jsonb_typeof(sw) <> 'object' or coalesce(sw->>'mode','') not in ('ALL','LADDER') then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
    all_mode := sw->>'mode' = 'ALL';
  end if;
  if all_mode then
    begin
      sw_ceiling := (sw->>'ceiling')::integer;
      sw_valid := (sw->>'validMinutes')::integer;
    exception when others then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end;
    if sw_ceiling is null or sw_ceiling < 1 or sw_ceiling > 10000 or sw_valid is null or sw_valid < 1 or sw_valid > 10080 then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
    -- MATCH-V1B (owner 2026-10-07): three layers on top of mode ALL (the knobs are checked here; a bad one is the named error):
    --   1. a task WITHOUT a place (remote, or without coordinates) is sent in WAVES (private.dispatch_remote_wave_v1b) with its own
    --      ceiling, instead of one wave to everybody;
    --   2. a worker who already got workerDailyCap proactive new-task notifications in the last 24 hours is skipped for this task,
    --      without using up a place of any ceiling; an urgent task ignores the cap;
    --   3. a task WITH a place keeps the one wave and the ceiling of MATCH-V1, but one database transaction (one tick) notifies at most
    --      workerNotifyPerTransaction workers in all (every notified recipient holds two locks of the shared lock table until the end
    --      of the transaction, about 4,800 entries on the whole server): a larger wave is sent in chunks, one per tick.
    -- The ladder (mode LADDER) never reaches this block.
    cfgb := private.dispatch_config_v1b(sw);
    remote_on := (cfgb->>'remoteWaves')::boolean
                 and not coalesce((n.execution_location_mode in ('STATIONARY','POINT_TO_POINT','MULTI_STOP','AREA_BASED'))
                                  and n.approx_geog is not null, false);
    daily_cap := case when urg = 'URGENT' then null else (cfgb->>'workerDailyCap')::integer end;
    tx_budget := (cfgb->>'notifyBudget')::integer;
    tx_used := coalesce(nullif(current_setting('v1b.notified', true), '')::integer, 0);
    select count(*) into delivered from public.opportunity_deliveries where need_id = nid and need_revision = n.revision;
    if delivered >= sw_ceiling and not remote_on then
      return jsonb_build_object('status','STOPPED','reason','DELIVERY_CEILING_REACHED','inserted',0,'mode','ALL','ceiling',sw_ceiling,
        'deliveredBefore',delivered,'activeResponses',active,'activeCoverage',active_coverage,
        'selectedSlots',selected,'remainingSlots',remaining);
    end if;
  end if;

  -- MATCH-V1B: a task without a place goes to the waves of the remote function (its own ceiling, pace and stop).
  if remote_on then
    return private.dispatch_remote_wave_v1b(nid, sw, cfgb, urg, windowm, target, remaining, selected, active, active_coverage, delivered, tx_budget - tx_used);
  end if;

  if not all_mode and active >= target and active_coverage >= remaining then
    return jsonb_build_object('status','STOPPED','reason','RESPONSE_TARGET_AND_COVERAGE_REACHED',
      'inserted',0,'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining);
  end if;

  if all_mode then
    -- MATCH-V1: every admitted worker, up to what is left of the ceiling of this task revision ('FIXED' is the allowed budget source).
    candidate_limit := sw_ceiling - delivered;
    budget_source := 'FIXED';
    -- MATCH-V1B: the notify budget of this transaction (the lock table). Nothing left: the wave waits for the next tick, due at once.
    -- More workers than what is left: this wave is a chunk of at most that many; a chunk that comes back full is followed by the next one at the next tick.
    if tx_budget - tx_used < 1 then
      return jsonb_build_object('status','SENT','inserted',0,'waiting',true,'deferred','TRANSACTION_NOTIFY_BUDGET','mode','ALL','ceiling',sw_ceiling,
        'deliveredBefore',delivered,'deadlineAt',statement_timestamp(),'txNotifyBudget',tx_budget,'activeResponses',active,'activeCoverage',active_coverage,
        'selectedSlots',selected,'remainingSlots',remaining);
    end if;
    if candidate_limit > tx_budget - tx_used then
      candidate_limit := tx_budget - tx_used;
      chunked := true;
    end if;
  else
    budget := private.candidate_budget(urg = 'URGENT', greatest(0, remaining - active_coverage), cfg);
    candidate_limit := (budget->>'limit')::integer;
    budget_source := budget->>'source';
    if candidate_limit is null or candidate_limit < 1 or candidate_limit > 10000 then
      raise exception using errcode='55000', message='DISPATCH_CONFIG_INVALID';
    end if;
  end if;

  select coalesce(max(round_no),0)+1 into roundno
    from public.dispatch_rounds where need_id = nid and need_revision = n.revision;
  select count(*)+1 into policy_wave_no
    from public.dispatch_rounds
   where need_id = nid and need_revision = n.revision and urgency = urg
     -- PKG-027a: a check that found nobody reached nobody, so it does not use up a wave.
     and not (status = 'STOPPED' and stop_reason = 'NO_ELIGIBLE_CANDIDATES');

  if not all_mode and policy_wave_no > jsonb_array_length(sizes) then
    return jsonb_build_object('status','STOPPED','reason','WAVES_EXHAUSTED','inserted',0,
      'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining,'candidateLimit',candidate_limit);
  end if;

  batch := case when all_mode then candidate_limit else (sizes->>(policy_wave_no-1))::integer end;

  -- O-3: pod izbora za HITNO.
  if urg = 'URGENT' and not all_mode then
    select value into urgcfg from private.marketplace_config where key = 'urgent_activation_policy';
    min_choice := coalesce(nullif(urgcfg->>'minChoice','')::integer, 2);
    if min_choice < 2 or min_choice > 10 then min_choice := 2; end if;
    batch := greatest(batch, min_choice);
  end if;

  deadline := statement_timestamp() + make_interval(mins => windowm);
  -- MATCH-V1: 'deadline' is when this wave's window ends (the tick checks the task again then). In mode ALL the deliveries and their
  -- notifications outlive it: they stay valid for 'validMinutes', for an urgent task not beyond the end of its urgency.
  valid_until := deadline;
  if all_mode then
    valid_until := statement_timestamp() + make_interval(mins => sw_valid);
    if urg = 'URGENT' then valid_until := least(valid_until, n.urgent_expires_at); end if;
  end if;

  insert into public.dispatch_rounds(id,need_id,need_revision,round_no,urgency,batch_size,
      target_responses,candidate_limit_used,budget_source,status,deadline_at)
    values (roundid,n.id,n.revision,roundno,urg,batch,target,candidate_limit,budget_source,'SENT',deadline);

  for c in
    with candidate_base as materialized (
      select p.id as pid, p.account_id as uid, pc.candidate_rank
      from private.candidate_profile_ids_v1b(n.id, candidate_limit, daily_cap)
           with ordinality as pc(worker_profile_id, candidate_rank)
      join public.app_profiles p on p.id = pc.worker_profile_id
      order by pc.candidate_rank
    ), scored as materialized (
      select b.pid, b.uid, private.match_detail(n.id, b.pid) as detail from candidate_base b
    )
    select s.pid, s.uid, s.detail from scored s
    where coalesce((s.detail->>'dispatchEligible')::boolean, false)
    -- MATCH-V1: "Mogu odmah" first for a task danas/odmah (timeTier 1), then the schedule (2); score within a tier.
    order by coalesce((s.detail->>'timeTier')::integer, 9), (s.detail->>'score')::numeric desc, s.pid
  loop
    exit when inserted >= batch;
    d := c.detail;
    insert into public.opportunity_deliveries(worker_account_id,worker_profile_id,need_id,
        need_revision,dispatch_round_id,match_score,score_components,reason_codes,status,expires_at)
      values (c.uid,c.pid,n.id,n.revision,roundid,(d->>'score')::numeric,
        coalesce(d->'scoreComponents','{}'::jsonb) || jsonb_build_object(
          'distanceToStartKm', d->'distanceToStartKm',
          'effectiveRadiusKm', d->'effectiveRadiusKm',
          'distanceSource', d->'distanceSource',
          'taskLocationMode', d->'taskLocationMode'),
        array(select jsonb_array_elements_text(d->'reasonCodes')), 'READY', valid_until)
      on conflict do nothing;

    if found then
      inserted := inserted + 1;
      perform private.emit_event(
        p_recipient => c.uid, p_role => 'WORKER',
        p_event_type => 'OPPORTUNITY_AVAILABLE',
        p_entity_type => 'NEED', p_entity_id => n.id, p_entity_version => n.revision,
        p_title => 'Nova prilika koja može da Vam odgovara',
        p_body => left(n.title,140),
        p_dedupe_key => 'opp:'||n.id::text||':'||n.revision::text||':'||c.uid::text,
        p_urgency => case when urg = 'URGENT' then 'HITNO' else 'NORMAL' end,
        p_payload => jsonb_build_object('needRevision',n.revision,
                       'reasonCodes',d->'reasonCodes','remainingSlots',remaining),
        p_expires_at => valid_until);
    end if;
  end loop;

  if inserted = 0 then
    update public.dispatch_rounds
       set status = 'STOPPED', stop_reason = 'NO_ELIGIBLE_CANDIDATES'
     where id = roundid;
  end if;

  -- MATCH-V1B: what this transaction has notified so far (read by the next task of the same tick; a rolled-back task takes its share back with it).
  if all_mode then
    perform set_config('v1b.notified', (tx_used + inserted)::text, true);
    if chunked and inserted >= batch then deadline := statement_timestamp(); end if;
  end if;

  return jsonb_build_object(
    'status', case when inserted > 0 then 'SENT' else 'STOPPED' end,
    'round', roundno, 'policyWaveNo', policy_wave_no, 'urgency', urg,
    'inserted', inserted, 'batchSize', batch, 'minChoice', min_choice,
    'deadlineAt', deadline,
    'activeResponses', active, 'activeCoverage', active_coverage,
    'selectedSlots', selected, 'remainingSlots', remaining,
    'candidateLimit', candidate_limit, 'budgetSource', budget_source,
    'routingCallsUsed', 0, 'routingProvider', null,
    'candidateRetrieval', 'CLEAN_STREAMING_BOUNDED_GEO_KNN',
    'authoritative', true)
    || case when all_mode then jsonb_build_object('mode','ALL','ceiling',sw_ceiling,'deliveredBefore',delivered,'validUntil',valid_until)
            else '{}'::jsonb end
    || case when chunked and inserted >= batch then jsonb_build_object('chunk',true,'txNotifyBudget',tx_budget) else '{}'::jsonb end;
end;
$function$;


CREATE OR REPLACE FUNCTION private.dispatch_remote_wave_v1b(nid uuid, sw jsonb, cfgb jsonb, urg text, windowm integer, target integer, remaining integer, selected integer, active integer, active_coverage integer, delivered integer, tx_left integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  n public.needs;
  wave_size integer := (sw->>'remoteWaveSize')::integer;
  next_size integer := (sw->>'remoteNextWaveSize')::integer;
  wave_minutes integer := (sw->>'remoteWaveMinutes')::integer;
  stop_after integer := (sw->>'remoteStopAfterResponses')::integer;
  rem_ceiling integer := (sw->>'remoteCeiling')::integer;
  sw_valid integer := (sw->>'validMinutes')::integer;
  daily_cap integer := case when urg = 'URGENT' then null else (cfgb->>'workerDailyCap')::integer end;
  pace_minutes integer; batch integer; roundno integer; roundid uuid := gen_random_uuid();
  lr_no integer; lr_at timestamptz; lr_empty boolean; streak integer := 0; permitted timestamptz;
  deadline timestamptz; valid_until timestamptz; inserted integer := 0; c record; d jsonb;
begin
  -- MATCH-V1B (owner 2026-10-07): one WAVE of a task without a place (remote, or without coordinates).
  -- Called by private.dispatch_next_wave in mode ALL when remoteWaves is on; the task is locked, open and has room, the knobs are checked.
  --   * the first wave notifies at most remoteWaveSize workers, every later wave at most remoteNextWaveSize: always the NEXT workers of the
  --     rotation seeded by the id of the task (the same order as private.candidate_profile_ids), never a worker twice for one revision of
  --     the task (a new revision starts the rotation again);
  --   * the next wave comes remoteWaveMinutes after the previous one (an urgent task: its own, shorter window), no matter who wakes the
  --     task up (a changed profile re-queues it at once): an early call answers "waiting" with the time it is due;
  --   * waves stop while the task has remoteStopAfterResponses active applications (they go on when applications are withdrawn), and
  --     for good when the task is closed or agreed (the checks of private.dispatch_next_wave before this call);
  --   * at most remoteCeiling workers are notified for one revision of one task: the brake;
  --   * a check that finds nobody new is paced like the tick paces every task that found nobody (5 minutes, growing to 6 hours);
  --   * one transaction (one tick) notifies at most workerNotifyPerTransaction workers in all (every notified recipient holds two locks of
  --     the shared lock table until the transaction ends): a wave that does not fit in what is left of that budget is not started, the
  --     answer is "waiting" and due at once, so the next tick sends it.
  select * into n from public.needs where id = nid;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;

  if delivered >= rem_ceiling then
    return jsonb_build_object('status','STOPPED','reason','DELIVERY_CEILING_REACHED','inserted',0,'mode','ALL','remote',true,
      'ceiling',rem_ceiling,'deliveredBefore',delivered,'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining);
  end if;

  if active >= stop_after and active_coverage >= remaining then
    return jsonb_build_object('status','STOPPED','reason','REMOTE_RESPONSE_TARGET_REACHED','inserted',0,'mode','ALL','remote',true,
      'stopAfterResponses',stop_after,'deliveredBefore',delivered,'activeResponses',active,'activeCoverage',active_coverage,
      'selectedSlots',selected,'remainingSlots',remaining);
  end if;

  pace_minutes := case when urg = 'URGENT' then least(wave_minutes, windowm) else wave_minutes end;

  select r.round_no, r.created_at, (r.status = 'STOPPED' and r.stop_reason = 'NO_ELIGIBLE_CANDIDATES')
    into lr_no, lr_at, lr_empty
    from public.dispatch_rounds r
   where r.need_id = nid and r.need_revision = n.revision
   order by r.round_no desc
   limit 1;
  roundno := coalesce(lr_no, 0) + 1;

  if lr_no is not null then
    if coalesce(lr_empty, false) then
      select count(*) into streak from public.dispatch_rounds r
       where r.need_id = nid and r.need_revision = n.revision
         and r.status = 'STOPPED' and r.stop_reason = 'NO_ELIGIBLE_CANDIDATES'
         and r.round_no > coalesce((select max(x.round_no) from public.dispatch_rounds x
                                     where x.need_id = nid and x.need_revision = n.revision
                                       and not (x.status = 'STOPPED' and x.stop_reason = 'NO_ELIGIBLE_CANDIDATES')), 0);
      permitted := lr_at + make_interval(mins => least(360, greatest(5, (2 ^ least(streak - 1, 9))::integer)));
    else
      permitted := lr_at + make_interval(mins => pace_minutes);
    end if;
    if statement_timestamp() < permitted then
      return jsonb_build_object('status','SENT','inserted',0,'waiting',true,'mode','ALL','remote',true,
        'deadlineAt',permitted,'deliveredBefore',delivered,'activeResponses',active,'activeCoverage',active_coverage,
        'selectedSlots',selected,'remainingSlots',remaining);
    end if;
  end if;

  batch := least(case when delivered = 0 then wave_size else next_size end, rem_ceiling - delivered);

  -- the lock table: this transaction has already notified its share, so the wave waits for the next tick (nothing is written)
  if tx_left < batch then
    return jsonb_build_object('status','SENT','inserted',0,'waiting',true,'deferred','TRANSACTION_NOTIFY_BUDGET','mode','ALL','remote',true,
      'deadlineAt',statement_timestamp(),'txNotifyBudget',(cfgb->>'notifyBudget')::integer,'txNotifyLeft',tx_left,'deliveredBefore',delivered,
      'activeResponses',active,'activeCoverage',active_coverage,'selectedSlots',selected,'remainingSlots',remaining);
  end if;

  deadline := statement_timestamp() + make_interval(mins => pace_minutes);
  valid_until := statement_timestamp() + make_interval(mins => sw_valid);
  if urg = 'URGENT' then valid_until := least(valid_until, n.urgent_expires_at); end if;

  insert into public.dispatch_rounds(id,need_id,need_revision,round_no,urgency,batch_size,
      target_responses,candidate_limit_used,budget_source,status,deadline_at)
    values (roundid,n.id,n.revision,roundno,urg,batch,target,batch,'FIXED','SENT',deadline);

  for c in
    select s.pid, s.uid, s.detail from private.remote_wave_candidates_v1b(n.id, batch, daily_cap) s
    -- "Mogu odmah" first for a task danas/odmah (timeTier 1), then the schedule (2); score within a tier.
    order by coalesce((s.detail->>'timeTier')::integer, 9), (s.detail->>'score')::numeric desc, s.pid
  loop
    d := c.detail;
    insert into public.opportunity_deliveries(worker_account_id,worker_profile_id,need_id,
        need_revision,dispatch_round_id,match_score,score_components,reason_codes,status,expires_at)
      values (c.uid,c.pid,n.id,n.revision,roundid,(d->>'score')::numeric,
        coalesce(d->'scoreComponents','{}'::jsonb) || jsonb_build_object(
          'distanceToStartKm', d->'distanceToStartKm',
          'effectiveRadiusKm', d->'effectiveRadiusKm',
          'distanceSource', d->'distanceSource',
          'taskLocationMode', d->'taskLocationMode'),
        array(select jsonb_array_elements_text(d->'reasonCodes')), 'READY', valid_until)
      on conflict do nothing;

    if found then
      inserted := inserted + 1;
      perform private.emit_event(
        p_recipient => c.uid, p_role => 'WORKER',
        p_event_type => 'OPPORTUNITY_AVAILABLE',
        p_entity_type => 'NEED', p_entity_id => n.id, p_entity_version => n.revision,
        p_title => 'Nova prilika koja može da Vam odgovara',
        p_body => left(n.title,140),
        p_dedupe_key => 'opp:'||n.id::text||':'||n.revision::text||':'||c.uid::text,
        p_urgency => case when urg = 'URGENT' then 'HITNO' else 'NORMAL' end,
        p_payload => jsonb_build_object('needRevision',n.revision,
                       'reasonCodes',d->'reasonCodes','remainingSlots',remaining),
        p_expires_at => valid_until);
    end if;
  end loop;

  -- what this transaction has notified so far (read by the next task of the same tick); a rolled-back task takes its share back with it
  perform set_config('v1b.notified', (coalesce(nullif(current_setting('v1b.notified', true), '')::integer, 0) + inserted)::text, true);

  -- nobody new: the same record as every other check that found nobody (it does not use up a wave), paced by the back-off below
  if inserted = 0 then
    update public.dispatch_rounds
       set status = 'STOPPED', stop_reason = 'NO_ELIGIBLE_CANDIDATES',
           deadline_at = statement_timestamp() + make_interval(mins => least(360, greatest(5, (2 ^ least(streak, 9))::integer)))
     where id = roundid;
  end if;

  return jsonb_build_object(
    'status', case when inserted > 0 then 'SENT' else 'STOPPED' end,
    'round', roundno, 'urgency', urg,
    'inserted', inserted, 'batchSize', batch,
    'deadlineAt', deadline,
    'activeResponses', active, 'activeCoverage', active_coverage,
    'selectedSlots', selected, 'remainingSlots', remaining,
    'candidateLimit', batch, 'budgetSource', 'FIXED',
    'candidateRetrieval', 'REMOTE_ROTATION_WAVES',
    'authoritative', true,
    'mode', 'ALL', 'remote', true, 'waveSize', case when delivered = 0 then wave_size else next_size end, 'ceiling', rem_ceiling,
    'deliveredBefore', delivered, 'deliveredTotal', delivered + inserted,
    'exhausted', inserted < batch, 'validUntil', valid_until, 'workerDailyCap', daily_cap)
    || case when inserted = 0 then jsonb_build_object('reason', 'NO_ELIGIBLE_CANDIDATES') else '{}'::jsonb end;
end;
$function$;


CREATE OR REPLACE FUNCTION private.dispatch_tick(p_batch integer DEFAULT 25, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  claimed uuid[]; r record; candidate record; res jsonb; profile_requeue jsonb;
  tick_started timestamptz := clock_timestamp(); tick_budget numeric := 40; deferred integer := 0;
  processed integer := 0; sent integer := 0; stopped integer := 0; failed integer := 0;
  reason text; next_at timestamptz;
begin
  if p_batch is null or p_batch < 1 or p_batch > 200 then p_batch := 25; end if;

  -- MATCH-V1 (owner 2026-10-07): a direct profile write (the manual profile editor) brings the open tasks back
  -- to the queue as the RPC saves do: once per change, before this tick claims anything. A failure here is
  -- reported in the result and never stops the dispatch.
  begin
    profile_requeue := private.requeue_changed_worker_profiles_v1(p_at);
  exception when others then
    profile_requeue := jsonb_build_object('status','ERROR','reason',left(sqlerrm,200));
  end;

  -- MATCH-V1: the time budget of this tick (private.marketplace_config 'match_v1_dispatch', tickBudgetSeconds, default 40 s). One wave
  -- to hundreds of workers takes seconds. After the budget this tick starts no further task: the claimed tasks it did not start are
  -- released and come first on the next tick, so one heavy minute can never run into the statement timeout, roll back and repeat
  -- forever. At least one task is always handled. A bad setting never stops the dispatch (default 40 s).
  begin
    select coalesce((value->>'tickBudgetSeconds')::numeric, 40) into tick_budget
      from private.marketplace_config where key = 'match_v1_dispatch';
  exception when others then
    tick_budget := 40;
  end;
  tick_budget := least(greatest(coalesce(tick_budget, 40), 0.001), 100);

  -- Claim each free Need and queue in a bounded successful-claim batch.
  -- locked_until je zastita od procesa koji padne usred obrade.
  -- Each attempt locks its Need before its queue. A skipped queue rolls back
  -- this small subtransaction, releasing that unsuccessful Need lock. Thus a
  -- queue-only holder cannot starve the next free item or accumulate held Needs.
  claimed := '{}'::uuid[];
  for candidate in
    select s.need_id from private.dispatch_schedule s
    where s.next_run_at <= p_at
      and (s.locked_until is null or s.locked_until < p_at)
    order by s.next_run_at, s.need_id
  loop
    begin
      perform 1 from public.needs n where n.id = candidate.need_id
        for update of n skip locked;
      if not found then continue; end if;
      perform 1 from private.dispatch_schedule s
        where s.need_id = candidate.need_id and s.next_run_at <= p_at
          and (s.locked_until is null or s.locked_until < p_at)
        for update of s skip locked;
      if not found then
        raise exception using errcode = 'UD108', message = 'DISPATCH_QUEUE_SKIPPED';
      end if;
      update private.dispatch_schedule s
        set locked_until = p_at + interval '2 minutes', updated_at = statement_timestamp()
        where s.need_id = candidate.need_id;
      claimed := array_append(claimed, candidate.need_id);
    exception when sqlstate 'UD108' then
      null;
    end;
    exit when cardinality(claimed) >= p_batch;
  end loop;

  for r in select unnest(claimed) as need_id loop
    if processed > 0 and clock_timestamp() - tick_started > make_interval(secs => tick_budget) then
      update private.dispatch_schedule set locked_until = null where need_id = r.need_id;
      deferred := deferred + 1;
      continue;
    end if;
    processed := processed + 1;
    begin
      res := private.dispatch_next_wave(r.need_id);
      reason := coalesce(res->>'reason', res->>'status');

      if (res->>'status') = 'SENT' then
        sent := sent + 1;
        -- Sledeci talas tek kad se prozor ovog zatvori.
        next_at := coalesce((res->>'deadlineAt')::timestamptz, p_at + interval '15 minutes');
        update private.dispatch_schedule
           set next_run_at = next_at, locked_until = null, attempts = 0,
               last_status = 'SENT', last_reason = null, updated_at = statement_timestamp()
         where need_id = r.need_id;

      elsif reason in ('SLOTS_FILLED','NEED_NOT_OPEN','WAVES_EXHAUSTED',
                       'RESPONSE_TARGET_AND_COVERAGE_REACHED','REMAINING_SEARCH_CLOSED',
                       'SEARCH_WINDOW_CLOSED') then
        stopped := stopped + 1;
        delete from private.dispatch_schedule where need_id = r.need_id;

      else
        -- NO_ELIGIBLE_CANDIDATES i slicno: eksponencijalno odlaganje do sest sati, bez odustajanja
        -- (PKG-027a). Promena kod radnika vraca zadatak u red odmah (requeue_open_needs_for_worker_v5).
        stopped := stopped + 1;
        update private.dispatch_schedule
           set attempts = attempts + 1,
               locked_until = null,
               next_run_at = p_at + make_interval(
                 mins => least(360, greatest(5, (2 ^ least(attempts, 9))::integer))),
               last_status = 'STOPPED', last_reason = reason,
               updated_at = statement_timestamp()
         where need_id = r.need_id;
      end if;

    exception when others then
      failed := failed + 1;
      update private.dispatch_schedule
         set attempts = attempts + 1, locked_until = null,
             next_run_at = p_at + interval '10 minutes',
             last_status = 'ERROR', last_reason = left(sqlerrm, 200),
             updated_at = statement_timestamp()
       where need_id = r.need_id;
    end;
  end loop;

  return jsonb_build_object('processed',processed,'sent',sent,'stopped',stopped,
                            'failed',failed,'batch',p_batch,'claimed',cardinality(claimed),
                            'deferred',deferred,'profileRequeue',profile_requeue);
end;
$function$;


CREATE OR REPLACE FUNCTION private.edge_worker_tick_v5(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_base text;
  v_key text;
  v_workers jsonb := '{}'::jsonb;
  w record;
begin
  -- Close provider tickets older than the 24h receipt window even when
  -- Expo transport is disabled. The previous expiration lived only inside
  -- rpc_claim_push_transport, which an inactive transport never reaches.
  -- No new sends, claims, provider calls or ticket replays are created here.
  UPDATE public.notification_push_attempts a
     SET transport_state='UNKNOWN', outcome='FATAL',
         error_code='RECEIPT_UNAVAILABLE', lease_id=NULL, lease_until=NULL
   WHERE a.transport_state='TICKET_PENDING'
     AND a.ticket_received_at IS NOT NULL
     AND a.ticket_received_at <= p_at - interval '24 hours'
     AND (a.lease_until IS NULL OR a.lease_until <= p_at);
  select s.decrypted_secret into v_base from vault.decrypted_secrets s where s.name = 'uskoci_edge_base_url';
  select s.decrypted_secret into v_key from vault.decrypted_secrets s where s.name = 'uskoci_edge_worker_key';
  -- Only a Supabase project address over HTTPS, or the disposable local stack's own gateway.
  if v_base is null or v_base !~ '^(https://[a-z0-9]{20}\.supabase\.co|http://supabase_kong_[a-z0-9_-]+:8000)$' then
    return jsonb_build_object('kind', 'NOT_CONFIGURED', 'missing', 'BASE_URL');
  end if;
  -- The shape of a server key, a legacy JWT or a secret key (the length is checked apart: a regular expression
  -- repetition count cannot exceed 255). The key itself is never returned or logged.
  if v_key is null or length(v_key) not between 16 and 4096 or v_key !~ '^[A-Za-z0-9._~-]+$' then
    return jsonb_build_object('kind', 'NOT_CONFIGURED', 'missing', 'WORKER_KEY');
  end if;
  -- One call a minute per worker, and only when it has work. Every worker finishes or gives up inside
  -- 55 seconds, so two calls to the same worker never overlap. "Has work" may be wider than what a worker
  -- would take, never narrower: a wasted call is harmless, a skipped one leaves the work where it is.
  for w in
    select * from (values
      ('PUSH', 'uskoci-push-transport', '{"action":"tick"}'::jsonb,
        exists (select 1 from public.notification_deliveries d
                 where d.channel = 'PUSH' and d.push_started_at is null
                   and d.state in ('CREATED', 'QUEUED', 'FAILED_RETRYABLE'))
        or exists (select 1 from public.notification_push_attempts a
                    where a.transport_state in ('PENDING', 'RETRYABLE', 'SEND_LEASED', 'SEND_STARTED',
                                                'TICKET_PENDING', 'RECEIPT_LEASED'))),
      ('DATA_EXPORT', 'uskoci-data-export-worker', '{"action":"tick"}'::jsonb,
        (private.data_export_policy_binding() is not null
          and exists (select 1 from public.data_export_requests r
                       where r.export_revoked_at is null and r.status in ('REQUESTED', 'PROCESSING')))
        or exists (select 1 from private.data_export_artifacts x where x.cleanup_not_before <= p_at)),
      ('ACCOUNT_CLOSURE', 'uskoci-account-closure-worker', '{"action":"maintenance","maxSteps":8}'::jsonb,
        private.closure_erasure_binding_v5() is not null
        and exists (select 1 from private.closure_executions_v5 e where e.state = 'EXECUTING'))
    ) x(worker, slug, body, has_work)
  loop
    if w.has_work then
      v_workers := v_workers || jsonb_build_object(w.worker, jsonb_build_object('requestId',
        net.http_post(
          url := v_base || '/functions/v1/' || w.slug,
          body := w.body,
          -- PKG-030a: on apikey. A secret key (sb_secret_) is not a JWT, so as a Bearer it never passes the gateway.
          headers := jsonb_build_object('Content-Type', 'application/json', 'apikey', v_key),
          timeout_milliseconds := 60000)));
    else
      v_workers := v_workers || jsonb_build_object(w.worker, 'IDLE');
    end if;
  end loop;
  return jsonb_build_object('kind', 'TICKED', 'workers', v_workers);
end
$function$;


CREATE OR REPLACE FUNCTION private.effective_radius_km(base_radius integer)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$ select greatest(1, least(1000, coalesce(base_radius, 15)))::numeric; $function$;


CREATE OR REPLACE FUNCTION private.emit_event(p_recipient uuid, p_role text, p_event_type text, p_entity_type text, p_entity_id uuid, p_entity_version integer, p_title text, p_body text, p_dedupe_key text, p_urgency text DEFAULT 'NORMAL'::text, p_payload jsonb DEFAULT '{}'::jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_event_id uuid;
  v_prefs public.notification_preferences%rowtype;
  v_cat text := private.category_of_event(p_event_type);
  v_cat_on boolean;
  v_quiet boolean;
  v_prio text := case when p_urgency = 'HITNO' then 'HIGH' else 'NORMAL' end;
  v_suppress text;
begin
  -- PKG-027c: every stored text addresses the person as "ti" and uses the product's words. Two emitting
  -- functions are trigger functions inside the certified closure source, so the texts are mapped here.
  p_title := private.notification_copy_v5(p_title);
  p_body := private.notification_copy_v5(p_body);
  -- 1) durable event, idempotentno
  insert into public.user_activity_events
    (recipient_user_id, recipient_role, event_type, entity_type, entity_id,
     entity_version, urgency, payload, dedupe_key)
  values (p_recipient, p_role, p_event_type, p_entity_type, p_entity_id,
     p_entity_version, p_urgency, p_payload, p_dedupe_key)
  on conflict (dedupe_key) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    return null;  -- vec emitovano; nista se ne duplira
  end if;

  -- 2) preference; ako red ne postoji, vaze podrazumevane vrednosti
  select * into v_prefs from public.notification_preferences
   where user_id = p_recipient and role_context = p_role;
  if not found then
    v_prefs.in_app_enabled := true;
    -- PKG-029a (deep read 4.1): a role without its own row takes the push choice of the account's other role.
    -- A person who switched push on once expects it on; it was off for every event of the other role.
    v_prefs.push_enabled := coalesce((select np.push_enabled from public.notification_preferences np
                                       where np.user_id = p_recipient order by np.role_context limit 1), false);
    v_prefs.quiet_hours_enabled := false;
    v_prefs.urgent_overrides_quiet_hours := false;
    v_prefs.opportunities_enabled := true; v_prefs.responses_enabled := true;
    v_prefs.dogovor_enabled := true; v_prefs.execution_enabled := true;
    v_prefs.recovery_enabled := true; v_prefs.account_enabled := true;
  end if;

  v_cat_on := case v_cat
    when 'opportunities' then v_prefs.opportunities_enabled
    when 'responses'     then v_prefs.responses_enabled
    when 'dogovor'       then v_prefs.dogovor_enabled
    when 'execution'     then v_prefs.execution_enabled
    when 'recovery'      then v_prefs.recovery_enabled
    else v_prefs.account_enabled end;

  -- 3) IN_APP
  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'IN_APP', v_prio,
     case when v_prefs.in_app_enabled and v_cat_on then 'CREATED' else 'SUPPRESSED' end,
     case when v_prefs.in_app_enabled and v_cat_on then null
          when not v_cat_on then 'CATEGORY_OFF' else 'IN_APP_OFF' end,
     p_title, p_body, p_dedupe_key || ':in_app', p_expires_at)
  on conflict (dedupe_key) do nothing;

  -- 4) PUSH — tihi sati se postuju osim uz izricit opt-in za HITNO
  v_quiet := private.in_quiet_hours(v_prefs);
  v_suppress := case
    when not v_prefs.push_enabled then 'PUSH_OFF'
    when not v_cat_on then 'CATEGORY_OFF'
    when v_quiet and not (p_urgency = 'HITNO' and v_prefs.urgent_overrides_quiet_hours)
      then 'QUIET_HOURS'
    else null end;

  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'PUSH', v_prio,
     case when v_suppress is null then 'CREATED' else 'SUPPRESSED' end,
     v_suppress, p_title, p_body, p_dedupe_key || ':push', p_expires_at)
  on conflict (dedupe_key) do nothing;

  return v_event_id;
end;
$function$;


CREATE OR REPLACE FUNCTION private.enqueue_dispatch(p_need_id uuid, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  insert into private.dispatch_schedule (need_id, next_run_at)
  values (p_need_id, p_at)
  on conflict (need_id) do update
    set next_run_at = least(private.dispatch_schedule.next_run_at, excluded.next_run_at),
        updated_at = statement_timestamp();
$function$;


CREATE OR REPLACE FUNCTION private.enqueue_on_need_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status in ('PUBLISHED','SELECTION') then
    if tg_op = 'INSERT'
       or old.status is distinct from new.status
       or old.revision is distinct from new.revision then
      perform private.enqueue_dispatch(new.id, statement_timestamp());
    end if;
  elsif tg_op = 'UPDATE' and old.status is distinct from new.status then
    delete from private.dispatch_schedule where need_id = new.id;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.execute_retention_job(p_job_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare j private.retention_jobs;b jsonb;v jsonb;now_at timestamptz;code text;v_result jsonb;message_count integer:=0;account uuid;
begin
 lock table private.retention_policy_sets,private.retention_policy_rules,private.retention_data_classes,private.legal_document_versions in share mode;
 select account_id into account from private.retention_jobs where id=p_job_id;if not found then raise exception 'RETENTION_JOB_NOT_FOUND';end if;
 -- Preserve immutable result replay; acquire the shared closure fence first.
 perform pg_advisory_xact_lock_shared(private.closure_account_key(account));
 perform pg_advisory_xact_lock(hashtextextended('uskoci:retention:'||account::text,0));
 select * into j from private.retention_jobs where id=p_job_id for update;
 if p_attempt_id is null or j.attempt_id<>p_attempt_id then raise exception 'RETENTION_ATTEMPT_STALE' using errcode='PT409';end if;
 if j.result is not null then return j.result||jsonb_build_object('idempotentReplay',true);end if;
 perform 1 from public.ai_conversations where id=j.conversation_id for update;
 now_at:=clock_timestamp();b:=private.retention_execution_binding();v:=private.retention_ai_candidate(j.conversation_id);
 code:=case when j.lease_until<=now_at then 'LEASE_EXPIRED'
   when exists(select 1 from private.retention_holds where account_id=j.account_id and active and (conversation_id is null or conversation_id=j.conversation_id)) then 'HELD'
   when b is null or b->>'sha256'<>j.policy_sha256 then 'POLICY_CHANGED'
   when not coalesce(private.retention_ai_source_ready(),false) or v is null or v->>'sha256'<>j.source_sha256 or j.due_at>now_at then 'SOURCE_CHANGED' else null end;
 if code is null then
   begin
     -- No network or Storage work: final hold check and complete deletion commit
     -- atomically under the account+parent locks. The candidate has no facts,
     -- proposals, draft receipts or links to Need/edit evidence.
     message_count:=(v->>'messageCount')::integer;
     delete from public.ai_conversations where id=j.conversation_id;
     if not found then raise exception 'RETENTION_SOURCE_DISAPPEARED';end if;
     v_result:=jsonb_build_object('jobId',j.id,'status','SUCCEEDED','deletedConversation',true,'deletedMessages',message_count,'idempotentReplay',false);
     update private.retention_jobs set status='SUCCEEDED',result=v_result,last_code=null,next_attempt_at=null,updated_at=clock_timestamp() where id=j.id;
     perform private.audit_marketplace(null,'RETENTION_DELETE_COMPLETED','SYSTEM',j.id,null,jsonb_build_object('dataset',j.dataset,'policyId',j.policy_id,'deletedMessages',message_count));
     return v_result;
   exception when others then
     -- Subtransaction rollback restores every deleted row before recording a
     -- bounded technical retry. Never expose exception text or private content.
     code:='EXECUTION_FAILED';
   end;
 end if;
 v_result:=jsonb_build_object('jobId',j.id,'status',case when code='EXECUTION_FAILED' then 'FAILED' else 'BLOCKED' end,
 'code',code,'deletedConversation',false,'deletedMessages',0,'idempotentReplay',false);
 update private.retention_jobs set status=case when code='EXECUTION_FAILED' then 'FAILED' else 'BLOCKED' end,last_code=code,result=v_result,
  next_attempt_at=case when attempt_number<5 then clock_timestamp()+interval '60 seconds' else null end,updated_at=clock_timestamp() where id=j.id;
 perform private.audit_marketplace(null,'RETENTION_DELETE_DEFERRED','SYSTEM',j.id,null,jsonb_build_object('code',code,'attempt',j.attempt_number));
 return v_result;
end $function$;


CREATE OR REPLACE FUNCTION private.expire_lifecycle(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  d integer := 0;
  rr integer := 0;
  av integer := 0;
  ur integer := 0;
  ne integer := 0;
  re integer := 0;
  nd integer := 0;
  dq integer := 0;
  changed integer := 0;
  locked_needs uuid[];
begin
  perform set_config('uskoci.need_lifecycle', 'EXPIRE', true);

  -- Parent fencing also covers expired waves/deliveries on still-open Needs.
  -- Skip busy parents; their unchanged due rows remain eligible for a later tick.
  select coalesce(array_agg(locked.id), '{}'::uuid[]) into locked_needs
  from (
    select n.id from public.needs n
    where (
      n.status in ('PUBLISHED','SELECTION')
      and (
        (n.response_deadline is not null and n.response_deadline <= p_at)
        -- PKG-028b: a fixed-time task is over once its time has passed, with or without a deadline.
        or (n.schedule_kind = 'FIXED_WINDOW' and coalesce(n.ends_at, n.starts_at) <= p_at)
        -- PKG-029b: "danas", "sutra" and "ove nedelje" end with their day, counted from publication.
        or (n.schedule_kind in ('TODAY_FLEXIBLE', 'TOMORROW_FLEXIBLE', 'WEEK_FLEXIBLE')
            and private.relative_schedule_end_v5(n.schedule_kind, n.published_at, n.task_timezone) <= p_at)
      )
      and not exists (select 1 from public.need_selections s
        where s.need_id = n.id and s.status = 'SELECTED')
    ) or exists (
      select 1 from public.opportunity_deliveries o where o.need_id = n.id
        and o.status in ('READY','SEEN')
        and o.expires_at is not null and o.expires_at <= p_at
    ) or exists (
      select 1 from public.dispatch_rounds r where r.need_id = n.id
        and r.status = 'SENT'
        and r.deadline_at is not null and r.deadline_at <= p_at
    )
    order by n.id
    for update of n skip locked
  ) locked;

  with expired_needs as (
    update public.needs x
       set status = 'EXPIRED', urgent = false
     where x.id = any(locked_needs)
       and x.status in ('PUBLISHED','SELECTION')
       and (
         (x.response_deadline is not null and x.response_deadline <= p_at)
         or (x.schedule_kind = 'FIXED_WINDOW' and coalesce(x.ends_at, x.starts_at) <= p_at)
         or (x.schedule_kind in ('TODAY_FLEXIBLE', 'TOMORROW_FLEXIBLE', 'WEEK_FLEXIBLE')
             and private.relative_schedule_end_v5(x.schedule_kind, x.published_at, x.task_timezone) <= p_at)
       )
       and not exists (
         select 1 from public.need_selections s
          where s.need_id = x.id and s.status = 'SELECTED'
    )
    returning x.id, x.revision
  ), expired_responses as (
    update public.marketplace_responses r
       set status = 'EXPIRED', selected_at = null
      from expired_needs i
     where r.need_id = i.id
       and r.status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE')
    returning r.id
  ), expired_notifications as (
    update public.notification_deliveries d
       set state = 'EXPIRED'
      from public.user_activity_events e
     where d.event_id = e.id
       and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE')
       and (
         (e.entity_type = 'NEED' and exists (
           select 1 from expired_needs i where i.id = e.entity_id
         ))
         or (e.entity_type = 'RESPONSE' and exists (
           select 1
             from public.marketplace_responses r
             join expired_needs i on i.id = r.need_id
            where r.id = e.entity_id
         ))
       )
    returning d.id
  ), stopped_rounds as (
    update public.dispatch_rounds r
       set status = 'STOPPED', stop_reason = 'NEED_EXPIRED'
      from expired_needs i
     where r.need_id = i.id and r.status in ('PLANNED','SENT')
    returning r.need_id
  ), expired_opportunities as (
    update public.opportunity_deliveries o set status = 'EXPIRED'
      from expired_needs i
     where o.need_id = i.id and o.status in ('READY','SEEN')
    returning o.need_id
  ), dequeued as (
    delete from private.dispatch_schedule s
     using expired_needs i where s.need_id = i.id
    returning s.need_id
  )
  select
    (select count(*)::integer from expired_needs),
    (select count(*)::integer from expired_responses),
    (select count(*)::integer from expired_notifications),
    (select count(*)::integer from stopped_rounds),
    (select count(*)::integer from expired_opportunities),
    (select count(*)::integer from dequeued)
  into ne, re, nd, rr, d, dq;

  update public.opportunity_deliveries
     set status = 'EXPIRED'
   where need_id = any(locked_needs)
     and status in ('READY','SEEN')
     and expires_at is not null and expires_at <= p_at;
  get diagnostics changed = row_count;
  d := d + changed;

  update public.dispatch_rounds
     set status = 'EXPIRED'
   where need_id = any(locked_needs)
     and status = 'SENT'
     and deadline_at is not null and deadline_at <= p_at;
  get diagnostics changed = row_count;
  rr := rr + changed;

  av := 0; -- Persistent owner intent has no automatic expiration.

  ur := private.expire_urgent(p_at);

  return jsonb_build_object(
    'needsExpired', ne,
    'responsesExpired', re,
    'notificationsExpired', nd,
    'schedulesDequeued', dq,
    'deliveriesExpired', d,
    'roundsExpired', rr,
    'availabilityExpired', av,
    'urgencyExpired', ur
  );
end;
$function$;


CREATE OR REPLACE FUNCTION private.expire_urgent(at_time timestamp with time zone DEFAULT statement_timestamp())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r record; expired_count integer := 0;
begin
  for r in
    select id, revision from public.needs
     where urgent = true and urgent_expires_at is not null and urgent_expires_at <= at_time
     for update skip locked
  loop
    update public.needs set urgent = false where id = r.id;
    update public.dispatch_rounds set status='STOPPED', stop_reason='URGENT_EXPIRED'
     where need_id = r.id and need_revision = r.revision
       and urgency = 'URGENT' and status in ('PLANNED','SENT');
    expired_count := expired_count + 1;
  end loop;
  return expired_count;
end;
$function$;


CREATE OR REPLACE FUNCTION private.finalize_task_replacement(p_candidate uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r jsonb; n public.needs;
begin
 r:=private.task_replacement_origin(p_candidate);
 if r is null then return;end if;
 select * into n from public.needs where id=p_candidate for update;
 if n.requester_account_id is distinct from auth.uid() or n.status<>'DRAFT' then
  raise exception 'TASK_REVIEW_COMMAND_MISMATCH' using errcode='42501';end if;
 perform private.assert_task_replacement_source((r->>'sourceNeedId')::uuid,(r->>'sourceRevision')::integer,r->>'sourceFingerprint');

 if private.task_replacement_material(p_candidate) = private.task_replacement_material((r->>'sourceNeedId')::uuid) then
  raise exception 'NO_MATERIAL_CHANGE' using errcode='P0001';end if;
 perform private.cancel_replaced_task((r->>'sourceNeedId')::uuid,(r->>'sourceRevision')::integer,'Objava zamenjena novom verzijom');
 -- Applicant consent is never transferred. Existing cancellation delivery/read
 -- routing stays valid and points to the original closed task.
end $function$;


CREATE OR REPLACE FUNCTION private.grant_counterparty_ok(p_agreement_id uuid, p_granter uuid, p_grantee uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select exists (
    select 1 from public.agreements a
    where a.id = p_agreement_id
      and p_granter <> p_grantee
      and ((a.requester_account_id = p_granter and a.worker_account_id = p_grantee)
        or (a.worker_account_id = p_granter and a.requester_account_id = p_grantee))
  );
$function$;


CREATE OR REPLACE FUNCTION private.grant_is_ownable(p_agreement_id uuid, p_channel text, p_granter uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select exists (
    select 1 from public.agreements a
    where a.id = p_agreement_id
      and case p_channel
        when 'EXACT_LOCATION' then a.requester_account_id = p_granter
        when 'PHONE' then p_granter in (a.requester_account_id, a.worker_account_id)
        else false
      end
  );
$function$;


CREATE OR REPLACE FUNCTION private.group_agreement_changed_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin perform private.group_sync_agreement_v5(new);return new;end $function$;


CREATE OR REPLACE FUNCTION private.group_can_send_v5(g private.group_conversations_v5, u uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select private.group_member_v5(g,u) and not private.closure_account_restricted(g.requester_account_id)
 and exists(select 1 from public.needs n where n.id=g.need_id and n.status not in('COMPLETED','CANCELLED','EXPIRED','ARCHIVED'))
 and (g.requester_account_id=u or (exists(select 1 from private.group_memberships_v5 m where m.group_id=g.id and m.account_id=u and m.ended_sequence is null)
 and not private.safety_pair_blocked(u,g.requester_account_id)));
$function$;


CREATE OR REPLACE FUNCTION private.group_member_v5(g private.group_conversations_v5, u uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select u is not null and not private.closure_account_restricted(u)
 and (g.requester_account_id=u or exists(select 1 from private.group_memberships_v5 m where m.group_id=g.id and m.account_id=u));
$function$;


CREATE OR REPLACE FUNCTION private.group_message_receipt_v5(m private.group_messages_v5, replayed boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 select jsonb_build_object('accountId',m.sender_account_id,'groupId',m.group_id,'clientRequestId',m.client_request_id,
 'messageId',m.id,'sequence',m.sequence::text,'bodySha256',m.body_sha256,'createdAt',m.created_at,'idempotentReplay',replayed,'authoritative',true);
$function$;


CREATE OR REPLACE FUNCTION private.group_need_changed_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 -- Serialize terminal visibility with sends without adding a second Need writer.
 perform 1 from private.group_conversations_v5 where need_id=new.id for update;return new;
end $function$;


CREATE OR REPLACE FUNCTION private.group_sync_agreement_v5(a public.agreements)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare g private.group_conversations_v5;n public.needs;first_account_admission boolean;admitted uuid;r uuid;
begin
 select * into g from private.group_conversations_v5 where need_id=a.need_id for update;
 if not found then
  -- A single worker bringing several people still has the existing private
  -- Agreement. The shared conversation starts with two independently selected
  -- accounts. There is no earlier group history to grant retroactively.
  select * into n from public.needs where id=a.need_id;
  if (select count(distinct worker_account_id) from public.agreements where need_id=a.need_id and status<>'CANCELLED')<2 then return;end if;
  insert into private.group_conversations_v5(need_id,requester_account_id) values(n.id,n.requester_account_id)
   on conflict(need_id) do nothing;
  select * into g from private.group_conversations_v5 where need_id=a.need_id for update;
  insert into private.group_memberships_v5(group_id,agreement_id,account_id,profile_id,joined_sequence)
   select g.id,x.id,x.worker_account_id,x.worker_profile_id,g.sequence+1 from public.agreements x
   where x.need_id=a.need_id and x.status<>'CANCELLED' on conflict(agreement_id) do nothing;
 end if;
 if a.status='CANCELLED' then
  update private.group_memberships_v5 set ended_sequence=g.sequence,ended_at=clock_timestamp()
   where agreement_id=a.id and ended_sequence is null;
 else
  -- The group row serializes first admission with sends and all later admissions.
  -- A prior membership for ANY agreement consumes the one-time history grant.
  first_account_admission:=not exists(select 1 from private.group_memberships_v5
   where group_id=g.id and account_id=a.worker_account_id);
  insert into private.group_memberships_v5(group_id,agreement_id,account_id,profile_id,joined_sequence)
   values(g.id,a.id,a.worker_account_id,a.worker_profile_id,g.sequence+1)
   on conflict(agreement_id) do nothing returning agreement_id into admitted;
  if first_account_admission and admitted is not null then
   -- Same shared closure/safety barriers as group send; the exclusive barrier
   -- owners never take group/domain row locks. Recheck eligibility AFTER locks.
   -- Grant omissions are final even if the person is subsequently unblocked.
   for r in select a.worker_account_id
    union select g.requester_account_id
    union select sender_account_id from private.group_messages_v5 where group_id=g.id
    order by 1 loop
    perform pg_advisory_xact_lock_shared(private.closure_account_key(r));
    if r<>a.worker_account_id then
     perform pg_advisory_xact_lock_shared(private.safety_pair_key(a.worker_account_id,r));
    end if;
   end loop;
   if not private.closure_account_restricted(a.worker_account_id)
    and not private.closure_account_restricted(g.requester_account_id)
    and not private.safety_pair_blocked(a.worker_account_id,g.requester_account_id) then
    insert into private.group_message_visibility_v5(message_id,account_id,read_at)
    select m.id,a.worker_account_id,null from private.group_messages_v5 m
     where m.group_id=g.id and m.sequence<=g.sequence
      and not private.closure_account_restricted(m.sender_account_id)
      and (m.sender_account_id=a.worker_account_id
       or not private.safety_pair_blocked(a.worker_account_id,m.sender_account_id))
    on conflict(message_id,account_id) do nothing;
   end if;
  end if;
 end if;
end $function$;


CREATE OR REPLACE FUNCTION private.guard_ai_fact_schema()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_conversation_schema text;
  v_registry_type text;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  select fact_schema_version
    into v_conversation_schema
    from public.ai_conversations
   where id=new.conversation_id;

  if not found then
    raise exception 'AI_CONVERSATION_NOT_FOUND' using errcode='23503';
  end if;

  if v_conversation_schema is distinct from new.fact_schema_version then
    raise exception 'AI_FACT_SCHEMA_MISMATCH' using errcode='22023';
  end if;

  if new.fact_schema_version='NEED_FACT_V2' then
    select value_type into v_registry_type
      from private.need_fact_registry
     where fact_key=new.fact_key;
    if not found or v_registry_type is distinct from new.value_type then
      raise exception 'V2_FACT_REGISTRY_MISMATCH' using errcode='22023',detail=new.fact_key;
    end if;
    if coalesce(char_length(btrim(new.display_value)),0)<1 then
      raise exception 'V2_FACT_DISPLAY_REQUIRED' using errcode='22023',detail=new.fact_key;
    end if;
    perform private.validate_need_v2_fact(new.fact_key,new.fact_value);
    if new.fact_key='need.verified_identity_required' and new.fact_value='true'::jsonb
     and (tg_op='INSERT' or new.fact_key is distinct from old.fact_key or new.fact_value is distinct from old.fact_value
      or new.conversation_id is distinct from old.conversation_id or new.fact_schema_version is distinct from old.fact_schema_version)
     and (tg_op='INSERT' and new.source='SYSTEM_DERIVED' and new.status='CONFIRMED'
      and new.confirmed_by_user_id=new.account_id and new.confirmed_at is not null
      and exists(select 1 from public.ai_conversations c join public.needs n on n.id=c.bound_need_id
       where c.id=new.conversation_id and c.account_id=new.account_id and n.requester_account_id=c.account_id
        and n.id=new.subject_need_id and n.verified_identity_required and c.purpose='NEED_INTAKE'
        and c.fact_schema_version='NEED_FACT_V2' and c.status='OPEN')) is not true
    then raise exception 'IDENTITY_VERIFICATION_UNAVAILABLE' using errcode='22023';end if;
  end if;

  return new;
end
$function$;


CREATE OR REPLACE FUNCTION private.guard_ai_fact_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_role text:=auth.role();
  v_only_subject_binding boolean;
  v_only_supersede_start boolean;
  v_only_supersede_link boolean;
  v_need_owner uuid;
  v_need_status text;
  v_conv_account uuid;
  v_conv_schema text;
  v_conv_status text;
  v_conv_bound_need uuid;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  -- This trigger guards UPDATE only.
  if tg_op<>'UPDATE' then return new; end if;

  -- ------------------------------------------------------------
  -- 1) RU-2 canonical DRAFT binding.
  -- Exactly one field may change: subject_need_id NULL -> one newly selected
  -- DRAFT Need owned by the same account. The V2 conversation must still be
  -- OPEN and unbound; rpc_save_need_draft_from_review binds the conversation
  -- only after every fact has passed this guard.
  -- ------------------------------------------------------------
  v_only_subject_binding:=
       old.fact_schema_version='NEED_FACT_V2'
   and new.fact_schema_version='NEED_FACT_V2'
   and old.subject_need_id is null
   and new.subject_need_id is not null
   and (to_jsonb(new)-'subject_need_id') is not distinct from (to_jsonb(old)-'subject_need_id');

  if v_only_subject_binding then
    if v_uid is null or new.account_id is distinct from v_uid then
      raise exception 'FACT_SUBJECT_BIND_REQUIRES_OWNER_COMMAND' using errcode='42501';
    end if;

    select n.requester_account_id,n.status
      into v_need_owner,v_need_status
      from public.needs n
     where n.id=new.subject_need_id;
    if not found
       or v_need_owner is distinct from new.account_id
       or v_need_status<>'DRAFT' then
      raise exception 'FACT_SUBJECT_BIND_TARGET_INVALID' using errcode='42501';
    end if;

    select c.account_id,c.fact_schema_version,c.status,c.bound_need_id
      into v_conv_account,v_conv_schema,v_conv_status,v_conv_bound_need
      from public.ai_conversations c
     where c.id=new.conversation_id;
    if not found
       or v_conv_account is distinct from new.account_id
       or v_conv_schema<>'NEED_FACT_V2'
       or v_conv_status<>'OPEN'
       or v_conv_bound_need is not null then
      raise exception 'FACT_SUBJECT_BIND_CONVERSATION_INVALID' using errcode='42501';
    end if;

    return new;
  end if;

  -- ------------------------------------------------------------
  -- 2) Supersession start.
  -- Old live fact becomes superseded. No content/provenance field may change.
  -- This is used both by owner typed correction and the service-only V2 writer.
  -- ------------------------------------------------------------
  v_only_supersede_start:=
       old.superseded_at is null
   and new.superseded_at is not null
   and new.superseded_by is not distinct from old.superseded_by
   and (to_jsonb(new)-'superseded_at'-'superseded_by')
       is not distinct from
       (to_jsonb(old)-'superseded_at'-'superseded_by');

  if v_only_supersede_start then
    if not (
      (v_uid is not null and new.account_id=v_uid)
      or v_role='service_role'
    ) then
      raise exception 'FACT_SUPERSEDE_REQUIRES_OWNER_OR_SERVICE' using errcode='42501';
    end if;
    return new;
  end if;

  -- ------------------------------------------------------------
  -- 3) Supersession link.
  -- After the replacement fact exists, the already-superseded row may receive
  -- only superseded_by, and that target must be the live replacement for the
  -- same account/conversation/key/schema.
  -- ------------------------------------------------------------
  v_only_supersede_link:=
       old.superseded_at is not null
   and new.superseded_at is not distinct from old.superseded_at
   and old.superseded_by is null
   and new.superseded_by is not null
   and (to_jsonb(new)-'superseded_by') is not distinct from (to_jsonb(old)-'superseded_by');

  if v_only_supersede_link then
    if not (
      (v_uid is not null and new.account_id=v_uid)
      or v_role='service_role'
    ) then
      raise exception 'FACT_SUPERSEDE_LINK_REQUIRES_OWNER_OR_SERVICE' using errcode='42501';
    end if;
    if not exists (
      select 1
        from public.ai_structured_facts r
       where r.id=new.superseded_by
         and r.account_id=new.account_id
         and r.conversation_id=new.conversation_id
         and r.fact_key=new.fact_key
         and r.fact_schema_version=new.fact_schema_version
         and r.superseded_at is null
    ) then
      raise exception 'FACT_SUPERSEDE_LINK_TARGET_INVALID' using errcode='42501';
    end if;
    return new;
  end if;

  -- ------------------------------------------------------------
  -- 4) Human confirmation. Existing semantics preserved: owner only, immutable
  -- fact content, one allowed status transition, confirmation metadata derived.
  -- ------------------------------------------------------------
  if new.account_id is distinct from v_uid then
    raise exception 'FACT_NOT_OWNED_BY_CALLER' using errcode='42501';
  end if;

  if new.fact_key is distinct from old.fact_key then raise exception 'FACT_KEY_IMMUTABLE' using errcode='42501'; end if;
  if new.fact_value is distinct from old.fact_value then raise exception 'FACT_VALUE_IMMUTABLE' using errcode='42501'; end if;
  if new.source is distinct from old.source then raise exception 'FACT_SOURCE_IMMUTABLE' using errcode='42501'; end if;
  if new.evidence_excerpt is distinct from old.evidence_excerpt then raise exception 'FACT_EVIDENCE_IMMUTABLE' using errcode='42501'; end if;
  if new.scope is distinct from old.scope then raise exception 'FACT_SCOPE_IMMUTABLE' using errcode='42501'; end if;
  if new.confidence is distinct from old.confidence then raise exception 'FACT_CONFIDENCE_IMMUTABLE' using errcode='42501'; end if;
  if new.conversation_id is distinct from old.conversation_id then raise exception 'FACT_CONVERSATION_IMMUTABLE' using errcode='42501'; end if;
  if new.subject_need_id is distinct from old.subject_need_id then raise exception 'FACT_SUBJECT_IMMUTABLE' using errcode='42501'; end if;
  if new.fact_schema_version is distinct from old.fact_schema_version then raise exception 'FACT_SCHEMA_IMMUTABLE' using errcode='42501'; end if;
  if new.value_type is distinct from old.value_type then raise exception 'FACT_VALUE_TYPE_IMMUTABLE' using errcode='42501'; end if;
  if new.display_value is distinct from old.display_value then raise exception 'FACT_DISPLAY_IMMUTABLE' using errcode='42501'; end if;
  if new.superseded_at is distinct from old.superseded_at
     or new.superseded_by is distinct from old.superseded_by then
    raise exception 'FACT_SUPERSESSION_REQUIRES_CANONICAL_PATH' using errcode='42501';
  end if;

  if new.status is distinct from old.status then
    if not (old.status in ('NEEDS_CONFIRMATION','INFERRED','UNKNOWN') and new.status='CONFIRMED') then
      raise exception 'INVALID_FACT_STATUS_TRANSITION'
        using errcode='22023',detail=old.status||' -> '||new.status;
    end if;
    new.confirmed_by_user_id:=v_uid;
    new.confirmed_at:=statement_timestamp();
  elsif new.confirmed_at is distinct from old.confirmed_at
     or new.confirmed_by_user_id is distinct from old.confirmed_by_user_id then
    raise exception 'CONFIRMED_METADATA_REQUIRES_STATUS_TRANSITION' using errcode='42501';
  end if;

  return new;
end
$function$;


CREATE OR REPLACE FUNCTION private.guard_ai_proposal_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid := auth.uid();
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  -- Internal RPCs bypass all checks
  if current_setting('uskoci.ai_mutation', true) is not null then
    return new;
  end if;

  -- Ownership check
  if new.account_id is distinct from uid then
    raise exception using errcode='42501', message='PROPOSAL_NOT_OWNED_BY_CALLER';
  end if;

  -- Immutable content fields
  if new.action_kind is distinct from old.action_kind then
    raise exception using errcode='42501', message='PROPOSAL_ACTION_KIND_IMMUTABLE';
  end if;
  if new.payload is distinct from old.payload then
    raise exception using errcode='42501', message='PROPOSAL_PAYLOAD_IMMUTABLE';
  end if;
  if new.conversation_id is distinct from old.conversation_id then
    raise exception using errcode='42501', message='PROPOSAL_CONVERSATION_IMMUTABLE';
  end if;

  -- Status transition enforcement
  if new.status is distinct from old.status then
    if not (
      (old.status = 'PROPOSED' and new.status in ('CONFIRMED','REJECTED'))
    ) then
      raise exception using errcode='22023',
        message='INVALID_PROPOSAL_STATUS_TRANSITION',
        detail = old.status || ' -> ' || new.status;
    end if;

    -- Server-derive decision timestamp
    new.decided_at := statement_timestamp();
  end if;

  -- Reject fabrication: cannot set decided_at without transitioning status
  if new.status = old.status then
    if new.decided_at is distinct from old.decided_at then
      raise exception using errcode='42501',
        message='DECIDED_AT_REQUIRES_STATUS_TRANSITION';
    end if;
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_availability_timezone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  select * into p from public.app_profiles where id=new.worker_profile_id for update;
  if not found or p.kind<>'WORKER' or p.account_id<>new.worker_account_id then
    raise exception 'WORKER_PROFILE_REQUIRED' using errcode='42501';
  end if;
  if not private.availability_timezone_valid(new.timezone) then
    raise exception 'AVAILABILITY_TIMEZONE_INVALID' using errcode='22023';
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_closed_remaining_search_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status in ('READY','SEEN')
     and exists (
       select 1 from public.needs n
        where n.id = new.need_id
          and n.remaining_search_closed_at is not null
     ) then
    raise exception 'NEED_REMAINING_SEARCH_CLOSED' using errcode='P0001';
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_closed_remaining_search_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_closed timestamptz;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.status not in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','SELECTED') then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and new.status is not distinct from old.status
     and new.submitted_against_need_revision is not distinct from old.submitted_against_need_revision
     and new.current_version is not distinct from old.current_version then
    return new;
  end if;

  select n.remaining_search_closed_at into v_closed
    from public.needs n
   where n.id = new.need_id;

  if v_closed is not null then
    raise exception 'NEED_REMAINING_SEARCH_CLOSED' using errcode='P0001';
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_media_evidence_asset_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

 perform pg_advisory_xact_lock(private.media_evidence_key_v5(old.account_id));
 if (exists(select 1 from private.media_evidence_refs_v5 where asset_id=old.id)
 or exists(select 1 from private.media_evidence_gaps_v5 where account_id=old.account_id)
 or exists(select 1 from private.agreement_media_snapshots_v5 where account_id=old.account_id and state='UNRESOLVED')) and
 (tg_op='DELETE' or (new.id,new.account_id,new.scope,new.conversation_id,new.profile_id) is distinct from (old.id,old.account_id,old.scope,old.conversation_id,old.profile_id)
 or (old.storage_path is not null and (new.storage_path,new.sanitized_sha256,new.width,new.height,new.byte_size) is distinct from (old.storage_path,old.sanitized_sha256,old.width,old.height,old.byte_size))
 or (old.state='READY' and new.state is distinct from old.state))
 then raise exception 'MEDIA_EVIDENCE_IMMUTABLE' using errcode='55000';end if;
 return case when tg_op='DELETE' then old else new end;
end $function$;


CREATE OR REPLACE FUNCTION private.guard_media_evidence_storage_v5()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ declare own uuid;protected boolean;begin
 if old.bucket_id<>'profile-media' then return case when tg_op='DELETE' then old else new end;end if;
 if split_part(old.name,'/',1)~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then own:=split_part(old.name,'/',1)::uuid;end if;
 if own is null then return case when tg_op='DELETE' then old else new end;end if;
 perform pg_advisory_xact_lock(private.media_evidence_key_v5(own));
 select exists(select 1 from private.owned_media_assets m join private.media_evidence_refs_v5 r on r.asset_id=m.id and r.account_id=m.account_id where m.account_id=own and m.storage_path=old.name)
 or exists(select 1 from private.agreement_media_snapshots_v5 where account_id=own and state='UNRESOLVED')
 or exists(select 1 from private.media_evidence_gaps_v5 where account_id=own)
 or exists(select 1 from private.retention_holds h where h.account_id=own and h.active and (h.conversation_id is null or exists(select 1 from private.owned_media_assets m where m.account_id=own and m.storage_path=old.name and m.conversation_id=h.conversation_id))) into protected;
 if protected and (tg_op='DELETE' or (to_jsonb(new)-array['last_accessed_at']) is distinct from (to_jsonb(old)-array['last_accessed_at']))
 then raise exception 'MEDIA_EVIDENCE_POLICY_NOT_READY' using errcode='55000';end if;
 return case when tg_op='DELETE' then old else new end;
end $function$;


CREATE OR REPLACE FUNCTION private.guard_need_edit_base_marker()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare n public.needs;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if tg_op='UPDATE' then
    if new.need_edit_base_fingerprint is distinct from old.need_edit_base_fingerprint
       or (old.need_edit_base_fingerprint is not null and (
         new.bound_need_id is distinct from old.bound_need_id or new.account_id is distinct from old.account_id
         or new.purpose is distinct from old.purpose or new.fact_schema_version is distinct from old.fact_schema_version)) then
      raise exception 'EDIT_BASE_CONTEXT_SERVER_OWNED' using errcode='42501';
    end if;
    return new;
  end if;
  if new.need_edit_base_fingerprint is not null then raise exception 'EDIT_BASE_CONTEXT_SERVER_OWNED' using errcode='42501'; end if;
  if new.bound_need_id is not null and new.purpose='NEED_INTAKE' and new.fact_schema_version='NEED_FACT_V2' then
    select * into n from public.needs where id=new.bound_need_id for update;
    if found and n.status in('DRAFT','PUBLISHED','SELECTION') then
      if auth.uid() is null or n.requester_account_id is distinct from auth.uid() or new.account_id is distinct from auth.uid()
         or new.status<>'OPEN' then raise exception 'EDIT_BASE_CONTEXT_SERVER_OWNED' using errcode='42501'; end if;
      perform 1 from public.need_geography where need_id=n.id for share;
      perform 1 from public.need_sensitive where need_id=n.id for share;
      perform 1 from public.need_requirement_details where need_id=n.id for share;
      new.need_edit_base_fingerprint:=private.need_edit_base_marker(n.id);
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_need_resolved_location_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare n public.needs;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and new.resolved_location is not null) or (tg_op='UPDATE' and new.resolved_location is distinct from old.resolved_location) then
    select * into n from public.needs where id=new.need_id;
    if auth.uid() is null or n.requester_account_id is distinct from auth.uid() or n.status is distinct from 'DRAFT'
      or exists(select 1 from public.agreements where need_id=new.need_id) or exists(select 1 from public.need_selections where need_id=new.need_id) then
      raise exception 'LOCATION_REVIEW_NOT_EDITABLE' using errcode='42501'; end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_need_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  token text := current_setting('uskoci.need_lifecycle', true);
  material boolean;
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and (new.task_country_code is not null or new.task_timezone is not null))
    or (tg_op='UPDATE' and (new.task_country_code is distinct from old.task_country_code or new.task_timezone is distinct from old.task_timezone)) then
    if current_setting('uskoci.need_region',true) is distinct from 'CONFIRMED_REVIEW' then
      raise exception 'NEED_COUNTRY_REQUIRES_CONFIRMED_REVIEW' using errcode='42501';
    end if;
    perform private.require_location_country(to_jsonb(new.task_country_code));
    if new.task_timezone is distinct from (select default_timezone from private.location_market_configs where country_code=new.task_country_code) then
      raise exception 'NEED_COUNTRY_TIMEZONE_MISMATCH' using errcode='22023';
    end if;
  end if;
  if not exists (
    select 1 from public.app_profiles p
     where p.id = new.requester_profile_id
       and p.account_id = new.requester_account_id
       and p.kind = 'REQUESTER'
  ) then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'DRAFT'
       and not (new.status = 'PUBLISHED' and token = 'PUBLISH') then
      raise exception using errcode='22023', message='NEED_MUST_START_AS_DRAFT';
    end if;
    if token is null then
      new.urgent := false;
      new.urgent_activated_at := null;
      new.urgent_expires_at := null;
      new.urgent_policy_version := null;
      new.published_at := null;
      new.response_deadline := null;
    end if;
    return new;
  end if;

  if old.status in ('COMPLETED','CANCELLED','EXPIRED','ARCHIVED')
     and (
       (to_jsonb(new) - array['urgent','updated_at'])
         is distinct from
       (to_jsonb(old) - array['urgent','updated_at'])
       or (not coalesce(old.urgent, false) and coalesce(new.urgent, false))
     ) then
    raise exception using errcode='22023', message='NEED_TERMINAL_IMMUTABLE';
  end if;

  if new.requester_account_id <> old.requester_account_id then
    raise exception using errcode='42501', message='NEED_OWNER_IMMUTABLE';
  end if;

  material :=
       new.task_country_code is distinct from old.task_country_code
    or new.task_timezone is distinct from old.task_timezone
    or
       new.title is distinct from old.title
    or new.description is distinct from old.description
    or new.category is distinct from old.category
    or new.required_slots is distinct from old.required_slots
    or new.mode is distinct from old.mode
    or new.requester_price_rsd is distinct from old.requester_price_rsd
    or new.required_skills is distinct from old.required_skills
    or new.required_tools is distinct from old.required_tools
    or new.required_vehicles is distinct from old.required_vehicles
    or new.required_licenses is distinct from old.required_licenses
    or new.minimum_experience_years is distinct from old.minimum_experience_years
    or new.verified_identity_required is distinct from old.verified_identity_required
    or new.schedule_kind is distinct from old.schedule_kind
    or new.starts_at is distinct from old.starts_at
    or new.ends_at is distinct from old.ends_at
    or new.execution_location_mode is distinct from old.execution_location_mode
    or new.approximate_lat is distinct from old.approximate_lat
    or new.approximate_lng is distinct from old.approximate_lng
    or new.approximate_city is distinct from old.approximate_city
    or new.approximate_area is distinct from old.approximate_area
    or new.public_photo_paths is distinct from old.public_photo_paths
    or new.response_deadline is distinct from old.response_deadline;

  if token = 'CONFIRM_EDIT' then
    if old.status not in ('DRAFT','PUBLISHED','SELECTION') or new.status <> 'DRAFT' then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_STATUS_INVALID';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_REVISION_INVALID';
    end if;
    if exists (select 1 from public.agreements a where a.need_id = old.id)
       or exists (select 1 from public.need_selections s where s.need_id = old.id)
       or exists (select 1 from public.marketplace_responses r where r.need_id = old.id and r.status = 'SELECTED') then
      raise exception using errcode='P0001', message='NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR';
    end if;
    if new.published_at is not null or new.response_deadline is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_PUBLICATION_METADATA_NOT_CLEARED';
    end if;
    if coalesce(new.urgent, false)
       or new.urgent_activated_at is not null
       or new.urgent_expires_at is not null
       or new.urgent_policy_version is not null then
      raise exception using errcode='22023', message='CONFIRMED_EDIT_URGENT_METADATA_NOT_CLEARED';
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    if not (
         (token = 'PUBLISH' and old.status = 'DRAFT' and new.status = 'PUBLISHED')
      or (token = 'SELECT' and old.status in ('PUBLISHED','SELECTION') and new.status in ('SELECTION','ACTIVE'))
      or (token = 'CANCEL_NEED' and old.status in ('DRAFT','PUBLISHED','SELECTION') and new.status = 'CANCELLED')
      or (token = 'CANCEL_AGREEMENT' and old.status in ('ACTIVE','SELECTION') and new.status = 'SELECTION')
      or (token = 'EXPIRE' and old.status in ('PUBLISHED','SELECTION') and new.status = 'EXPIRED')
      or (token = 'COMPLETE' and old.status in ('ACTIVE','SELECTION') and new.status = 'COMPLETED')
    ) then
      raise exception using errcode='22023', message='NEED_STATUS_TRANSITION_REQUIRES_RPC';
    end if;
  end if;

  if token is null then
    if new.revision is distinct from old.revision then
      raise exception using errcode='42501', message='NEED_REVISION_IS_SERVER_OWNED';
    end if;
    if new.urgent is distinct from old.urgent then raise exception using errcode='42501', message='URGENT_IS_SERVER_OWNED'; end if;
    if new.urgent_activated_at is distinct from old.urgent_activated_at then raise exception using errcode='42501', message='URGENT_ACTIVATED_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_expires_at is distinct from old.urgent_expires_at then raise exception using errcode='42501', message='URGENT_EXPIRES_AT_IS_SERVER_OWNED'; end if;
    if new.urgent_policy_version is distinct from old.urgent_policy_version then raise exception using errcode='42501', message='URGENT_POLICY_VERSION_IS_SERVER_OWNED'; end if;
    if new.published_at is distinct from old.published_at then raise exception using errcode='42501', message='PUBLISHED_AT_IS_SERVER_OWNED'; end if;
    if new.response_deadline is distinct from old.response_deadline then raise exception using errcode='42501', message='RESPONSE_DEADLINE_IS_SERVER_OWNED'; end if;
  end if;

  if material then
    if old.status in ('PUBLISHED','SELECTION') then
      raise exception using errcode='22023', message='PUBLIC_NEED_EDIT_REQUIRES_CONFIRM_COMMAND';
    elsif old.status <> 'DRAFT' then
      raise exception using errcode='P0001', message='NEED_NOT_EDITABLE';
    end if;
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_persistent_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  new.available_now_expires_at:=null;
  if new.kind='WORKER' and new.profile_status not in ('DRAFT','ACTIVE') then new.available_now:=false; end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_profile_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  after_fields jsonb;
  before_fields jsonb := '{}'::jsonb;
  field text;
  validate_all boolean;
  token text := nullif(
    current_setting('uskoci.profile_mutation', true),
    ''
  );
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if (tg_op='INSERT' and new.operating_country_code is not null)
    or (tg_op='UPDATE' and new.operating_country_code is distinct from old.operating_country_code) then
    if token is distinct from 'LOCATION_REVIEW' or new.kind is distinct from 'WORKER' then
      raise exception 'PROFILE_COUNTRY_REQUIRES_LOCATION_REVIEW' using errcode='42501';
    end if;
    perform private.require_location_country(to_jsonb(new.operating_country_code));
  end if;
  -- Reuse the same V2 value validator and comparison vocabulary as a Need.
  -- Do not rewrite historical profiles or reject unrelated edits to old data.
  if new.kind = 'WORKER' then
    after_fields := to_jsonb(new);
    validate_all := tg_op = 'INSERT';
    if tg_op = 'UPDATE' then
      before_fields := to_jsonb(old);
      validate_all := old.profile_status = 'DRAFT' and new.profile_status = 'ACTIVE';
    end if;
    foreach field in array array['skills','tools','vehicles','licenses'] loop
      if validate_all or (after_fields->field) is distinct from (before_fields->field) then
        perform private.validate_need_v2_fact('need.required_' || field, after_fields->field);
      end if;
    end loop;
  end if;

  if tg_op = 'INSERT' then
    new.profile_status := case
      when new.kind = 'REQUESTER' then 'ACTIVE'
      when new.kind = 'WORKER' then 'DRAFT'
      else 'DRAFT'
    end;
    new.account_type := 'INDIVIDUAL';
    new.rating_requester := null;
    new.rating_worker := null;
    return new;
  end if;

  if new.account_id is distinct from old.account_id
     or new.kind is distinct from old.kind then
    raise exception 'PROFILE_IDENTITY_IMMUTABLE'
      using errcode = '42501';
  end if;

  if new.profile_status is distinct from old.profile_status then
    if token is distinct from 'COMPLETE_WORKER_PROFILE'
       or old.kind is distinct from 'WORKER'
       or old.profile_status is distinct from 'DRAFT'
       or new.profile_status is distinct from 'ACTIVE' then
      raise exception 'PROFILE_STATUS_IS_SERVER_DERIVED'
        using errcode = '42501';
    end if;
  end if;

  if new.account_type is distinct from old.account_type then
    raise exception 'ACCOUNT_TYPE_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  if new.rating_requester is distinct from old.rating_requester then
    raise exception 'RATING_REQUESTER_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  if new.rating_worker is distinct from old.rating_worker then
    raise exception 'RATING_WORKER_IS_SERVER_DERIVED'
      using errcode = '42501';
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_remaining_search_close_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if new.remaining_search_closed_at is distinct from old.remaining_search_closed_at
     or new.remaining_search_closed_by_account_id is distinct from old.remaining_search_closed_by_account_id
     or new.remaining_search_close_reason is distinct from old.remaining_search_close_reason then
    if current_setting('uskoci.need_lifecycle', true) is distinct from 'CLOSE_REMAINING_SEARCH' then
      raise exception 'REMAINING_SEARCH_STATE_IS_SERVER_OWNED' using errcode='42501';
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION private.guard_requester_identity_writer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
