$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_complete_need_location_turn_v1_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid, p_user_message text, p_assistant_message text, p_safety text, p_proposals jsonb, p_location_context jsonb, p_location_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;raw jsonb;receipt_value jsonb;hash_value text;now_at timestamptz;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 if p_location_context is null or not private.ai_location_context_valid(p_location_context) or p_location_action is null or p_location_action not in('CONFIRM_DISPLAYED','CORRECT','CLARIFY','CONTINUE') then raise exception 'LOCATION_CONTEXT_INVALID' using errcode='PT409';end if;
 if p_location_action='CONFIRM_DISPLAYED' and (p_location_context->>'phase'<>'PROPOSAL' or p_location_context->'proposal'='null'::jsonb or p_proposals is distinct from '[]'::jsonb or p_safety is distinct from 'ALLOW') then raise exception 'LOCATION_CONFIRMATION_INVALID' using errcode='PT409';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 hash_value:=private.ai_location_request_hash(c.id,p_user_message,p_location_context);
 if not found or t.conversation_id<>c.id or t.request_hash<>hash_value then raise exception 'AI_REQUEST_ID_REUSED' using errcode='PT409';end if;
 if t.state='SUCCEEDED' then return private.ai_location_turn_document(p_account_id,c.id,p_client_request_id);end if;
 if t.state<>'PROCESSING' or t.attempt_id<>p_attempt_id or not t.provider_dispatched or t.cancelled_at is not null then return private.ai_location_turn_document(p_account_id,c.id,p_client_request_id);end if;
 now_at:=clock_timestamp();
 if c.status<>'OPEN' or t.lease_expires_at<=now_at or not private.ai_location_review_matches(c.id,p_location_context) or t.context_hash is distinct from (private.ai_need_turn_context(c.id)->>'sha256') then
  update private.ai_need_turn_commands set state='FAILED',updated_at=now_at where account_id=p_account_id and client_request_id=p_client_request_id;
  return private.ai_location_turn_document(p_account_id,c.id,p_client_request_id);
 end if;
 -- Existing V2 writer owns proposal validation, supersession, provenance and messages.
 raw:=public.rpc_ai_apply_interview_turn_v2_service(p_account_id,c.id,p_user_message,p_assistant_message,p_safety,p_proposals);
 receipt_value:=jsonb_build_object('userMessageId',raw->'userMessageId','assistantMessageId',raw->'assistantMessageId',
  'proposedCount',raw->'proposedCount','safety',raw->'safety','schemaVersion',raw->'schemaVersion','authoritative',raw->'authoritative');
 if raw->>'conversationId' is distinct from c.id::text or raw->>'schemaVersion' is distinct from 'NEED_FACT_V2'
  or raw->'authoritative' is distinct from 'true'::jsonb or raw->>'userMessageId' is null or raw->>'assistantMessageId' is null
  or (raw->>'proposedCount')::integer not between 0 and 12
 then raise exception 'AI_TURN_RECEIPT_INVALID' using errcode='P0001';end if;
 receipt_value:=receipt_value||jsonb_build_object('location',jsonb_build_object('version',1,
  'promptToken',p_location_context->'promptToken','reviewRevision',p_location_context->'reviewRevision','slot',p_location_context->'slot',
  'proposalId',p_location_context#>'{proposal,id}','action',p_location_action));
 update private.ai_need_turn_commands set state='SUCCEEDED',receipt=receipt_value,updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id;
 return private.ai_location_turn_document(p_account_id,c.id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_complete_need_turn_v2_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid, p_user_message text, p_assistant_message text, p_safety text, p_proposals jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;raw jsonb;receipt_value jsonb;hash_value text;now_at timestamptz;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 hash_value:=encode(extensions.digest(convert_to(jsonb_build_object('conversationId',c.id,'text',btrim(p_user_message))::text,'UTF8'),'sha256'),'hex');
 if not found or t.conversation_id<>c.id or t.request_hash<>hash_value then raise exception 'AI_REQUEST_ID_REUSED' using errcode='22023';end if;
 if t.state='SUCCEEDED' then return private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);end if;
 if t.state<>'PROCESSING' or t.attempt_id<>p_attempt_id or not t.provider_dispatched or t.cancelled_at is not null then return private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);end if;
 now_at:=clock_timestamp();
 if c.status<>'OPEN' or t.lease_expires_at<=now_at or t.context_hash is distinct from (private.ai_need_turn_context(c.id)->>'sha256') then
  update private.ai_need_turn_commands set state='FAILED',updated_at=now_at where account_id=p_account_id and client_request_id=p_client_request_id;
  return private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
 end if;
 -- Existing V2 writer owns proposal validation, supersession, provenance and messages.
 raw:=public.rpc_ai_apply_interview_turn_v2_service(p_account_id,c.id,p_user_message,p_assistant_message,p_safety,p_proposals);
 receipt_value:=jsonb_build_object('userMessageId',raw->'userMessageId','assistantMessageId',raw->'assistantMessageId',
  'proposedCount',raw->'proposedCount','safety',raw->'safety','schemaVersion',raw->'schemaVersion','authoritative',raw->'authoritative');
 if raw->>'conversationId' is distinct from c.id::text or raw->>'schemaVersion' is distinct from 'NEED_FACT_V2'
  or raw->'authoritative' is distinct from 'true'::jsonb or raw->>'userMessageId' is null or raw->>'assistantMessageId' is null
  or (raw->>'proposedCount')::integer not between 0 and 12
 then raise exception 'AI_TURN_RECEIPT_INVALID' using errcode='P0001';end if;
 update private.ai_need_turn_commands set state='SUCCEEDED',receipt=receipt_value,updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id;
 return private.ai_need_turn_status(p_account_id,c.id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_confirm_fact(p_fact_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); v_fact public.ai_structured_facts%rowtype; v_conv public.ai_conversations%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select * into v_fact from public.ai_structured_facts where id=p_fact_id;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_fact.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  select * into v_conv from public.ai_conversations where id=v_fact.conversation_id for update;
  if not found or v_conv.account_id<>v_uid then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_fact from public.ai_structured_facts where id=p_fact_id and conversation_id=v_conv.id for update;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_fact.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_fact.fact_key='need.resolved_location' then raise exception 'LOCATION_EDITOR_REQUIRED' using errcode='42501'; end if;
  if v_fact.superseded_at is not null then raise exception 'SUPERSEDED' using errcode='P0001'; end if;

  if v_conv.status<>'OPEN' then raise exception 'CONVERSATION_CLOSED' using errcode='P0001'; end if;
  if v_fact.status='CONFIRMED' then
    if v_fact.confirmed_at is null or v_fact.confirmed_by_user_id is null then raise exception 'CONFIRMED_PROVENANCE_INVALID' using errcode='P0001'; end if;
    return p_fact_id;
  end if;
  update public.ai_structured_facts set status='CONFIRMED',confirmed_at=statement_timestamp(),confirmed_by_user_id=v_uid where id=p_fact_id;
  return p_fact_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_correct_fact(p_fact_id uuid, p_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_old public.ai_structured_facts%rowtype; v_conv public.ai_conversations%rowtype;
  v_value text:=nullif(btrim(p_value),''); v_new_id uuid:=extensions.gen_random_uuid(); v_previous_ids uuid[];
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if v_value is null or char_length(v_value)>2000 then raise exception 'FACT_VALUE_INVALID' using errcode='22023'; end if;
  select * into v_old from public.ai_structured_facts where id=p_fact_id;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  select * into v_conv from public.ai_conversations where id=v_old.conversation_id for update;
  if not found or v_conv.account_id<>v_uid then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_old from public.ai_structured_facts where id=p_fact_id and conversation_id=v_conv.id for update;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_old.superseded_at is not null then raise exception 'SUPERSEDED' using errcode='P0001'; end if;
  if v_old.scope<>'NEED_DRAFT' then raise exception 'FACT_SCOPE_NOT_EDITABLE' using errcode='P0001'; end if;

  if v_conv.purpose<>'NEED_INTAKE' or v_conv.status<>'OPEN' then raise exception 'CONVERSATION_NOT_EDITABLE' using errcode='P0001'; end if;

  with superseded as (
    update public.ai_structured_facts set superseded_at=statement_timestamp(),superseded_by=null
     where conversation_id=v_old.conversation_id and fact_key=v_old.fact_key and superseded_at is null
     returning id
  ) select coalesce(array_agg(id),'{}'::uuid[]) into v_previous_ids from superseded;

  insert into public.ai_structured_facts(
    id,account_id,conversation_id,subject_need_id,fact_key,fact_value,status,source,scope,confidence,evidence_excerpt,confirmed_by_user_id,confirmed_at
  ) values (
    v_new_id,v_uid,v_old.conversation_id,v_old.subject_need_id,v_old.fact_key,to_jsonb(v_value),'CONFIRMED','EXPLICIT_USER_ANSWER','NEED_DRAFT',1,null,v_uid,statement_timestamp()
  );
  if cardinality(v_previous_ids)>0 then update public.ai_structured_facts set superseded_by=v_new_id where id=any(v_previous_ids); end if;
  return v_new_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_correct_fact_v2(p_fact_id uuid, p_value jsonb, p_display_value text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_old public.ai_structured_facts%rowtype;
  v_conv public.ai_conversations%rowtype;
  v_display text:=nullif(btrim(p_display_value),'');
  v_new_id uuid:=extensions.gen_random_uuid();
  v_previous_ids uuid[];
  v_value_type text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if v_display is null or char_length(v_display)>1000 then raise exception 'V2_FACT_DISPLAY_INVALID' using errcode='22023'; end if;

  select * into v_old from public.ai_structured_facts where id=p_fact_id;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  select * into v_conv from public.ai_conversations where id=v_old.conversation_id for update;
  if not found or v_conv.account_id<>v_uid then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  select * into v_old from public.ai_structured_facts where id=p_fact_id and conversation_id=v_conv.id for update;
  if not found then raise exception 'FACT_NOT_FOUND' using errcode='P0002'; end if;
  if v_old.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_old.fact_key in('need.resolved_location','need.public_photo_paths') then raise exception 'LOCATION_EDITOR_REQUIRED' using errcode='42501'; end if;
  if v_old.superseded_at is not null then raise exception 'SUPERSEDED' using errcode='P0001'; end if;
  if v_old.fact_schema_version<>'NEED_FACT_V2' then raise exception 'V2_FACT_REQUIRED' using errcode='P0001'; end if;
  if v_old.scope<>'NEED_DRAFT' then raise exception 'FACT_SCOPE_NOT_EDITABLE' using errcode='P0001'; end if;


  if v_conv.purpose<>'NEED_INTAKE' or v_conv.status<>'OPEN' or v_conv.fact_schema_version<>'NEED_FACT_V2' then
    raise exception 'CONVERSATION_NOT_EDITABLE' using errcode='P0001';
  end if;

  select value_type into v_value_type from private.need_fact_registry where fact_key=v_old.fact_key;
  if not found then raise exception 'V2_FACT_KEY_INVALID' using errcode='22023'; end if;
  perform private.validate_need_v2_fact(v_old.fact_key,p_value);

  with superseded as (
    update public.ai_structured_facts
       set superseded_at=statement_timestamp(),superseded_by=null
     where conversation_id=v_old.conversation_id
       and fact_key=v_old.fact_key
       and superseded_at is null
     returning id
  )
  select coalesce(array_agg(id),'{}'::uuid[]) into v_previous_ids from superseded;

  insert into public.ai_structured_facts(
    id,account_id,conversation_id,subject_need_id,fact_key,fact_value,status,source,scope,
    confidence,evidence_excerpt,confirmed_by_user_id,confirmed_at,
    fact_schema_version,value_type,display_value
  ) values (
    v_new_id,v_uid,v_old.conversation_id,v_old.subject_need_id,v_old.fact_key,p_value,
    'CONFIRMED','EXPLICIT_USER_ANSWER','NEED_DRAFT',1,null,v_uid,statement_timestamp(),
    'NEED_FACT_V2',v_value_type,v_display
  );

  if cardinality(v_previous_ids)>0 then
    update public.ai_structured_facts set superseded_by=v_new_id where id=any(v_previous_ids);
  end if;

  return v_new_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_dispatch_need_turn_v2_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations;t private.ai_need_turn_commands;
begin
 if p_account_id is null or p_conversation_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 select * into t from private.ai_need_turn_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or t.conversation_id<>c.id or t.attempt_id is distinct from p_attempt_id
 or t.state<>'PROCESSING' or t.cancelled_at is not null or t.provider_dispatched or c.status<>'OPEN'
 or t.lease_expires_at<=clock_timestamp() or t.context_hash is distinct from (private.ai_need_turn_context(c.id)->>'sha256') then return false;end if;
 update private.ai_need_turn_commands set provider_dispatched=true,updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id;
 return true;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_fail_need_turn_v2_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if p_account_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'TURN_IDENTITY_REQUIRED' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||p_account_id::text,0));
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id for update;
 if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 update private.ai_need_turn_commands set state='FAILED',updated_at=clock_timestamp()
 where account_id=p_account_id and client_request_id=p_client_request_id and conversation_id=p_conversation_id
 and state='PROCESSING' and attempt_id=p_attempt_id and cancelled_at is null;
 return private.ai_need_turn_status(p_account_id,p_conversation_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_need_review_v2(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_conv public.ai_conversations%rowtype;
  v_facts jsonb;
  v_missing jsonb;
  v_safety text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  select * into v_conv
    from public.ai_conversations
   where id=p_conversation_id
   for share;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  if v_conv.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_conv.purpose<>'NEED_INTAKE' then raise exception 'CONVERSATION_PURPOSE_MISMATCH' using errcode='P0001'; end if;

  -- Ignore null/unsupported rows so they cannot clear an earlier BLOCK.
  -- No supported decision retains the existing conservative REVIEW fallback.
  select coalesce((
    select m.safety from public.ai_messages m
     where m.conversation_id=p_conversation_id
       and m.role='ASSISTANT'
       and m.safety in ('ALLOW','CLARIFY','REVIEW','BLOCK')
     order by m.sequence_no desc
     limit 1
  ),'REVIEW') into v_safety;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id',f.id,
      'key',f.fact_key,
      'value',f.fact_value,
      'displayValue',coalesce(f.display_value,
        case when jsonb_typeof(f.fact_value)='string' then f.fact_value#>>'{}' else f.fact_value::text end),
      'status',f.status,
      'source',f.source,
      'evidence',f.evidence_excerpt,
      'schemaVersion',f.fact_schema_version,
      'valueType',f.value_type,
      'privacyClass',coalesce(r.privacy_class,'PRIVATE'),
      'requiredForDraft',coalesce(r.required_for_draft,false),
      'material',coalesce(r.material,true)
    ) order by f.created_at,f.fact_key
  ),'[]'::jsonb)
    into v_facts
    from public.ai_structured_facts f
    left join private.need_fact_registry r
      on r.fact_key=f.fact_key and f.fact_schema_version='NEED_FACT_V2'
   where f.conversation_id=p_conversation_id
     and f.superseded_at is null;

  if v_conv.fact_schema_version='NEED_FACT_V2' then
    select coalesce(jsonb_agg(r.fact_key order by r.fact_key),'[]'::jsonb)
      into v_missing
      from private.need_fact_registry r
     where r.required_for_draft
       and not exists (
         select 1 from public.ai_structured_facts f
          where f.conversation_id=p_conversation_id
            and f.fact_key=r.fact_key
            and f.fact_schema_version='NEED_FACT_V2'
            and f.status='CONFIRMED'
            and f.superseded_at is null
       );
  else
    v_missing:='[]'::jsonb;
  end if;

  return jsonb_build_object(
    'conversationId',v_conv.id,
    'schemaVersion',v_conv.fact_schema_version,
    'status',v_conv.status,
    'boundNeedId',v_conv.bound_need_id,
    'facts',v_facts,
    'missingRequired',v_missing,
    'safety',v_safety,
    'canSaveDraft',
      v_conv.fact_schema_version='NEED_FACT_V2'
      and v_conv.status='OPEN'
      and jsonb_array_length(v_missing)=0
      and v_safety<>'BLOCK'
  );
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_open_conversation(p_purpose text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare uid uuid := auth.uid(); v_id uuid;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if p_purpose not in ('NEED_INTAKE','APPLICATION','PROFILE') then
    raise exception 'BAD_PURPOSE' using errcode = 'P0001'; end if;
  insert into public.ai_conversations (account_id, purpose) values (uid, p_purpose) returning id into v_id;
  return v_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_open_need_conversation_owned_v2(p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid();cid uuid;replayed boolean:=false;
begin
 if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 if p_client_request_id is null then raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('w03-account:'||actor::text,0));
 select conversation_id into cid from private.ai_need_open_commands where account_id=actor and client_request_id=p_client_request_id;
 if found then
  replayed:=true;
  if not exists(select 1 from public.ai_conversations where id=cid and account_id=actor and purpose='NEED_INTAKE' and fact_schema_version='NEED_FACT_V2')
  then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002';end if;
 else
  if (select count(*) from private.ai_need_open_commands where account_id=actor and created_at>clock_timestamp()-interval '1 minute')>=6
  then raise exception 'AI_RATE_LIMITED' using errcode='P0001';end if;
  cid:=public.rpc_ai_open_need_conversation_v2();
  insert into private.ai_need_open_commands(account_id,client_request_id,conversation_id) values(actor,p_client_request_id,cid);
 end if;
 return jsonb_build_object('conversationId',cid,'clientRequestId',p_client_request_id,'authoritative',true,'idempotentReplay',replayed);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_open_need_conversation_v2()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  insert into public.ai_conversations(account_id,purpose,fact_schema_version)
  values(v_uid,'NEED_INTAKE','NEED_FACT_V2')
  returning id into v_id;

  return v_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_open_need_edit_conversation_v2(p_need_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_need public.needs%rowtype;
  v_sensitive public.need_sensitive%rowtype;
  v_geo jsonb;
  v_conditions text[]:='{}'::text[];
  v_conversation_id uuid;
  v_key text;
  v_type text;
  v_value jsonb;
  v_display text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null then raise exception 'NEED_ID_REQUIRED' using errcode='22004'; end if;

  select * into v_need from public.needs where id=p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id<>v_uid then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.status not in ('DRAFT','PUBLISHED','SELECTION') then raise exception 'NEED_NOT_EDITABLE_PUBLIC_STATE' using errcode='P0001'; end if;

  if exists(select 1 from public.agreements a where a.need_id=v_need.id)
     or exists(select 1 from public.need_selections s where s.need_id=v_need.id)
     or exists(select 1 from public.marketplace_responses r where r.need_id=v_need.id and r.status='SELECTED') then
    raise exception 'NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR' using errcode='P0001';
  end if;

  perform 1 from public.need_geography where need_id=v_need.id for share;
  perform 1 from public.need_requirement_details where need_id=v_need.id for share;
  select * into v_sensitive from public.need_sensitive where need_id=v_need.id for share;
  select g.public_topology into v_geo from public.need_geography g where g.need_id=v_need.id;
  select coalesce(d.critical_conditions,'{}'::text[]) into v_conditions
    from public.need_requirement_details d where d.need_id=v_need.id;
  if not found then v_conditions:='{}'::text[]; end if;

  if v_geo is null then
    if v_need.execution_location_mode='REMOTE' then
      v_geo:=jsonb_build_object('mode','REMOTE','start',null,'end',null,'waypoints','[]'::jsonb,'serviceArea',null);
    else
      raise exception 'NEED_EDIT_GEOGRAPHY_NOT_READY' using errcode='P0001';
    end if;
  end if;
  perform private.validate_need_v2_fact('need.task_geography',v_geo);

  insert into public.ai_conversations(account_id,purpose,status,bound_need_id,fact_schema_version)
  values(v_uid,'NEED_INTAKE','OPEN',v_need.id,'NEED_FACT_V2')
  returning id into v_conversation_id;

  for v_key,v_type in
    select fact_key,value_type from private.need_fact_registry
     where schema_version='NEED_FACT_V2'
     order by fact_key
  loop
    v_value:=null;
    v_display:=null;

    case v_key
      when 'need.title' then v_value:=to_jsonb(v_need.title); v_display:=v_need.title;
      when 'need.description' then v_value:=to_jsonb(v_need.description); v_display:=v_need.description;
      when 'need.category' then v_value:=to_jsonb(v_need.category); v_display:=v_need.category;
      when 'need.price_mode' then v_value:=to_jsonb(v_need.mode); v_display:=v_need.mode;
      when 'need.price_rsd' then
        if v_need.requester_price_rsd is not null then v_value:=to_jsonb(v_need.requester_price_rsd); v_display:=v_need.requester_price_rsd::text||' RSD'; end if;
      when 'need.schedule_kind' then v_value:=to_jsonb(v_need.schedule_kind); v_display:=v_need.schedule_kind;
      when 'need.starts_at' then
        if v_need.starts_at is not null then v_value:=to_jsonb(v_need.starts_at); v_display:=to_jsonb(v_need.starts_at)#>>'{}'; end if;
      when 'need.ends_at' then
        if v_need.ends_at is not null then v_value:=to_jsonb(v_need.ends_at); v_display:=to_jsonb(v_need.ends_at)#>>'{}'; end if;
      when 'need.price_basis' then
        -- PKG-027e: an edit keeps what the price is for; without this the edit writer clears it.
        if v_need.mode='MY_PRICE' and v_need.price_basis is not null then
          v_value:=to_jsonb(v_need.price_basis);
          v_display:=case v_need.price_basis when 'PER_PERSON' then 'Po osobi' else 'Ukupno' end;
        end if;
      when 'need.people_needed' then v_value:=to_jsonb(v_need.required_slots); v_display:=v_need.required_slots::text;
      when 'need.required_skills' then v_value:=to_jsonb(coalesce(v_need.required_skills,'{}'::text[])); v_display:=array_to_string(coalesce(v_need.required_skills,'{}'::text[]),', ');
      when 'need.required_tools' then v_value:=to_jsonb(coalesce(v_need.required_tools,'{}'::text[])); v_display:=array_to_string(coalesce(v_need.required_tools,'{}'::text[]),', ');
      when 'need.required_vehicles' then v_value:=to_jsonb(coalesce(v_need.required_vehicles,'{}'::text[])); v_display:=array_to_string(coalesce(v_need.required_vehicles,'{}'::text[]),', ');
      when 'need.required_licenses' then v_value:=to_jsonb(coalesce(v_need.required_licenses,'{}'::text[])); v_display:=array_to_string(coalesce(v_need.required_licenses,'{}'::text[]),', ');
      when 'need.minimum_experience_years' then
        if v_need.minimum_experience_years is not null then v_value:=to_jsonb(v_need.minimum_experience_years); v_display:=v_need.minimum_experience_years::text; end if;
      when 'need.verified_identity_required' then v_value:=to_jsonb(coalesce(v_need.verified_identity_required,false)); v_display:=case when coalesce(v_need.verified_identity_required,false) then 'Da' else 'Ne' end;
      when 'need.task_country_code' then
        if v_need.task_country_code is not null then v_value:=to_jsonb(v_need.task_country_code); v_display:=v_need.task_country_code; end if;
      when 'need.task_geography' then v_value:=v_geo; v_display:=coalesce(v_geo->'start'->>'label',v_geo->'serviceArea'->>'label',v_geo->>'mode');
      when 'need.handoff' then
        if v_need.execution_location_mode='REMOTE' then
          select d.handoff into v_value from public.need_requirement_details d where d.need_id=v_need.id;
          v_display:=private.taxonomy_handoff_display_v1(v_value);
        end if;
      when 'need.critical_conditions' then
        select array_remove(v_conditions,'Predaja: '||private.taxonomy_handoff_display_v1(d.handoff))
          into v_conditions from public.need_requirement_details d where d.need_id=v_need.id;
        v_value:=to_jsonb(coalesce(v_conditions,'{}'::text[])); v_display:=array_to_string(v_conditions,', ');
      when 'need.public_photo_paths' then v_value:=to_jsonb(coalesce(v_need.public_photo_paths,'{}'::text[])); v_display:=case when cardinality(coalesce(v_need.public_photo_paths,'{}'::text[]))=0 then 'Bez fotografija' else cardinality(v_need.public_photo_paths)::text||' fotografija' end;
      when 'need.exact_address' then
        if v_sensitive.need_id is not null and nullif(btrim(v_sensitive.exact_address),'') is not null then v_value:=to_jsonb(v_sensitive.exact_address); v_display:=v_sensitive.exact_address; end if;
      when 'need.access_notes' then
        if v_sensitive.need_id is not null and nullif(btrim(v_sensitive.access_notes),'') is not null then v_value:=to_jsonb(v_sensitive.access_notes); v_display:=v_sensitive.access_notes; end if;
      else null;
    end case;

    if v_value is not null and v_value<>'null'::jsonb then
      perform private.validate_need_v2_fact(v_key,v_value);
      insert into public.ai_structured_facts(
        account_id,conversation_id,subject_need_id,fact_key,fact_value,status,source,scope,
        confidence,evidence_excerpt,confirmed_by_user_id,confirmed_at,
        fact_schema_version,value_type,display_value
      ) values (
        v_uid,v_conversation_id,v_need.id,v_key,v_value,'CONFIRMED','SYSTEM_DERIVED','NEED_DRAFT',
        1,null,v_uid,statement_timestamp(),'NEED_FACT_V2',v_type,
        coalesce(nullif(left(v_display,1000),''),'—')
      );
    end if;
  end loop;

  -- Clone the already-confirmed private value last, after its public binding facts.
  -- Preserve the original human's provenance; do not manufacture a new confirmation.
  if v_sensitive.resolved_location is not null then
    if private.resolved_location_record_valid(v_sensitive.resolved_location,v_need.task_country_code,v_geo,
      v_sensitive.exact_address,v_uid) is distinct from true then
      raise exception 'LOCATION_BINDING_CHANGED' using errcode='22023'; end if;
    insert into public.ai_structured_facts(account_id,conversation_id,subject_need_id,fact_key,fact_value,status,source,scope,
      confidence,evidence_excerpt,confirmed_by_user_id,confirmed_at,fact_schema_version,value_type,display_value)
    values(v_uid,v_conversation_id,v_need.id,'need.resolved_location',v_sensitive.resolved_location->'value','CONFIRMED','EXPLICIT_USER_ANSWER','NEED_DRAFT',
      1,null,(v_sensitive.resolved_location->>'confirmedByAccountId')::uuid,(v_sensitive.resolved_location->>'confirmedAt')::timestamptz,
      'NEED_FACT_V2','OBJECT','Potvrđene tačke: '||jsonb_array_length(v_sensitive.resolved_location#>'{value,points}')::text);
  end if;

  return jsonb_build_object(
    'conversationId',v_conversation_id,
    'needId',v_need.id,
    'revision',v_need.revision,
    'status',v_need.status,
    'authoritative',true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_propose_fact(p_conversation_id uuid, p_fact_key text, p_fact_value jsonb, p_source text, p_scope text, p_confidence numeric DEFAULT NULL::numeric, p_evidence text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  raise exception using
    errcode = '42501',
    message = 'LEGACY_RPC_RETIRED',
    hint = 'AI proposals are written only by the service-owned interview turn command.';
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_publish_need(p_conversation_id uuid, p_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_account_id uuid := auth.uid();
begin
  if v_account_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  raise exception 'PACKAGE_4_NOT_READY'
    using
      errcode = 'P0001',
      detail = 'AI publish is fail-closed during PRE-P4 integrity repair.',
      hint = 'Use the canonical non-AI Need flow until human review and safety validation are implemented.';
end;
$function$;


