 SET search_path TO 'pg_catalog'
AS $function$
declare aid uuid:=auth.uid();
begin
 if aid is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 return private.ai_location_turn_document(aid,p_conversation_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_read_need_location_turn_v1_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
