CREATE OR REPLACE FUNCTION public.rpc_ai_read_need_turn_v2(p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 return private.ai_need_turn_status(auth.uid(),p_conversation_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_recover_need_turn_v2(p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a uuid:=auth.uid();c public.ai_conversations;t private.ai_need_turn_commands;turn_value jsonb;
begin
 if a is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 turn_value:=private.ai_need_turn_status(a,p_conversation_id,p_client_request_id);
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=a;
 select * into t from private.ai_need_turn_commands where account_id=a and client_request_id=p_client_request_id;
 return jsonb_build_object('accountId',a,'conversationId',c.id,'clientRequestId',p_client_request_id,'conversationStatus',c.status,
  'turn',turn_value,'providerDispatched',coalesce(t.provider_dispatched,false),'cancelled',t.cancelled_at is not null,
  'canCancel',c.status='OPEN' and not private.closure_account_restricted(a) and t.cancelled_at is null
  and (t.turn_id is null or t.state='PROCESSING' or (not t.provider_dispatched and t.state='FAILED')),
  'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_test_budget_report_service()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_budget private.ai_test_budget_v5;
  v_calls integer; v_with_usage integer; v_prompt bigint; v_output bigint;
  v_measured_calls integer; v_measured_microusd bigint;
  v_estimated_calls integer; v_estimated_microusd bigint;
  v_audio_calls integer; v_audio_microusd bigint; v_audio_bytes bigint;
  v_failed_calls integer; v_unsettled integer;
begin
  select * into v_budget from private.ai_test_budget_v5 where singleton;
  select count(*) into v_calls from private.ai_test_reservations_v5;
  select count(*), coalesce(sum(prompt_tokens),0), coalesce(sum(output_tokens),0)
    into v_with_usage, v_prompt, v_output from private.ai_test_usage_v5;
  select count(*) filter (where settlement_basis='MEASURED'),
         coalesce(sum(settled_microusd) filter (where settlement_basis='MEASURED'),0),
         count(*) filter (where settlement_basis='CONSERVATIVE_ESTIMATE_UNMEASURED'),
         coalesce(sum(settled_microusd) filter (where settlement_basis='CONSERVATIVE_ESTIMATE_UNMEASURED'),0),
         count(*) filter (where settlement_basis='AUDIO_DURATION_AT_PUBLISHED_RATE'),
         coalesce(sum(settled_microusd) filter (where settlement_basis='AUDIO_DURATION_AT_PUBLISHED_RATE'),0),
         coalesce(sum(measured_audio_bytes) filter (where settlement_basis='AUDIO_DURATION_AT_PUBLISHED_RATE'),0),
         count(*) filter (where settlement_basis='FAILED_NO_USAGE'),
         count(*) filter (where settled_microusd is null)
    into v_measured_calls, v_measured_microusd, v_estimated_calls, v_estimated_microusd,
         v_audio_calls, v_audio_microusd, v_audio_bytes, v_failed_calls, v_unsettled
    from private.ai_test_reservations_v5;

  return jsonb_build_object(
    'providerCalls', v_calls,
    'callsWithReportedUsage', v_with_usage,
    'callsWithoutReportedUsage', v_calls - v_with_usage,
    'inputTokens', case when v_with_usage = 0 then null else v_prompt end,
    'outputTokens', case when v_with_usage = 0 then null else v_output end,
    'measuredCalls', v_measured_calls,
    'measuredSpendUsd', case when v_measured_calls = 0 then null else round(v_measured_microusd / 1000000.0, 6) end,
    'audioDurationCalls', v_audio_calls,
    'audioDurationSeconds', case when v_audio_calls = 0 then null else round(v_audio_bytes / 32000.0, 2) end,
    'audioDurationSpendUsd', case when v_audio_calls = 0 then null else round(v_audio_microusd / 1000000.0, 6) end,
    'audioDurationBasis', case when v_audio_calls = 0 then null else
      'AUDIO_DURATION_AT_PUBLISHED_RATE: measured PCM bytes sent to the provider, priced at the published gemini-3.5-transcribe-live rates with output tokens bounded conservatively. Not provider-reported usage.' end,
    'unmeasuredCalls', v_estimated_calls,
    'unmeasuredProvisionUsd', case when v_estimated_calls = 0 then null else round(v_estimated_microusd / 1000000.0, 6) end,
    'unmeasuredBasis', case when v_estimated_calls = 0 then null else
      'CONSERVATIVE_ESTIMATE_UNMEASURED: these calls predate provider usage capture. The figure exists only to settle their reservation and must never be read as measured provider spend.' end,
    'failedNoUsageCalls', v_failed_calls,
    'unsettledReservations', v_unsettled,
    'realSpendUsd', null,
    'realSpendBasis', 'UNKNOWN in total: ' || v_measured_calls || ' MEASURED from provider usage metadata, '
      || v_audio_calls || ' priced from measured audio duration at published rates, '
      || v_estimated_calls || ' UNMEASURED estimates, ' || v_unsettled || ' still unsettled. The provider billing console remains authoritative.',
    'reservationCapEnforced', v_budget.reservation_cap_enforced,
    'internalTestBudgetCapUsd', case when v_budget.reservation_cap_enforced then round(v_budget.ceiling_microusd / 1000000.0, 2) else null end,
    'internalTestBudgetReservedUsd', round(v_budget.reserved_microusd / 1000000.0, 2),
    'remainingAllowedCalls', case when v_budget.reservation_cap_enforced then greatest(0, (v_budget.ceiling_microusd - v_budget.reserved_microusd) / 250000) else null end,
    'capIsACallCounter', v_budget.reservation_cap_enforced,
    'priceValidUntil', v_budget.price_valid_until,
    'authoritative', true);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_test_budget_reserve_service(p_account_id uuid, p_operation_id uuid, p_kind text, p_max_cost_microusd bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_budget private.ai_test_budget_v5%rowtype;
  v_existing private.ai_test_reservations_v5%rowtype;
  v_id uuid;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_account_id is null or p_operation_id is null or p_kind not in ('LLM','STT') or p_kind is null
    or p_max_cost_microusd is distinct from (case p_kind when 'LLM' then 250000::bigint when 'STT' then 200000::bigint end) then
    raise exception 'AI_TEST_RESERVATION_INVALID';
  end if;

  -- Match existing closure ordering before the global budget row. A closing
  -- account cannot acquire a fresh provider operation.
  perform pg_advisory_xact_lock_shared(private.closure_account_key(p_account_id));
  -- Every reservation shares this row, so different accounts cannot each spend $5.
  select * into strict v_budget from private.ai_test_budget_v5 where singleton for update;
  select * into v_existing from private.ai_test_reservations_v5 where operation_id = p_operation_id;
  if found then
    if v_existing.account_id <> p_account_id or v_existing.kind <> p_kind
      or v_existing.max_cost_microusd <> p_max_cost_microusd then
      raise exception 'AI_TEST_OPERATION_CONFLICT';
    end if;
    -- Admission is deliberately false: a retry may read its existing receipt but cannot call a provider again.
    return jsonb_build_object('admitted',false,'reservationId',v_existing.id,'replay',true,'code','AI_TEST_OPERATION_REPLAY');
  end if;

  if not v_budget.enabled or statement_timestamp() >= v_budget.price_valid_until then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_BUDGET_NOT_READY');
  end if;
  if not exists(select 1 from private.ai_test_accounts_v5 where account_id=p_account_id and retired_at is null)
    or not exists(select 1 from auth.users where id=p_account_id and deleted_at is null)
    or private.closure_account_restricted(p_account_id) then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_ACCOUNT_NOT_ADMITTED');
  end if;
  if v_budget.reservation_cap_enforced and v_budget.reserved_microusd + p_max_cost_microusd > v_budget.ceiling_microusd then
    return jsonb_build_object('admitted',false,'reservationId',null,'replay',false,'code','AI_TEST_BUDGET_EXHAUSTED');
  end if;

  insert into private.ai_test_reservations_v5(operation_id,account_id,kind,max_cost_microusd)
    values(p_operation_id,p_account_id,p_kind,p_max_cost_microusd) returning id into v_id;
  update private.ai_test_budget_v5 set reserved_microusd=reserved_microusd+p_max_cost_microusd where singleton;
  return jsonb_build_object('admitted',true,'reservationId',v_id,'replay',false,'code','AI_TEST_RESERVED');
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_test_record_usage_service(p_operation_id uuid, p_model text, p_prompt_tokens integer, p_output_tokens integer, p_total_tokens integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_reservation private.ai_test_reservations_v5;
  v_existing private.ai_test_usage_v5;
  v_cost bigint;
  v_released bigint := 0;
  v_settled boolean := false;
begin
  if p_operation_id is null or p_model is null
     or p_prompt_tokens is null or p_output_tokens is null or p_total_tokens is null
     or p_prompt_tokens < 0 or p_output_tokens < 0 or p_total_tokens < 0 then
    raise exception 'AI_USAGE_INPUT_INVALID' using errcode = '22023';
  end if;

  select * into v_reservation from private.ai_test_reservations_v5 where operation_id = p_operation_id;
  if not found then
    raise exception 'AI_USAGE_NO_RESERVATION' using errcode = '42501';
  end if;

  select * into v_existing from private.ai_test_usage_v5 where operation_id = p_operation_id;
  if found then
    if v_existing.prompt_tokens = p_prompt_tokens and v_existing.output_tokens = p_output_tokens
       and v_existing.total_tokens = p_total_tokens and v_existing.model = btrim(p_model) then
      -- Replay. Nothing is recorded and nothing is released a second time.
      return jsonb_build_object('operationId', p_operation_id, 'recorded', false,
        'promptTokens', v_existing.prompt_tokens, 'outputTokens', v_existing.output_tokens,
        'totalTokens', v_existing.total_tokens, 'authoritative', true,
        'settledMicrousd', v_reservation.settled_microusd, 'releasedMicrousd', 0);
    end if;
    raise exception 'AI_USAGE_ALREADY_RECORDED' using errcode = '55000';
  end if;

  insert into private.ai_test_usage_v5(operation_id, account_id, model, prompt_tokens, output_tokens, total_tokens)
    values (p_operation_id, v_reservation.account_id, btrim(p_model), p_prompt_tokens, p_output_tokens, p_total_tokens);

  -- Settle the worst-case hold down to what the provider actually charged. Same
  -- singleton lock the reservation writer takes, so the two cannot interleave.
  v_cost := least(private.ai_test_price_microusd(p_prompt_tokens, p_output_tokens), v_reservation.max_cost_microusd);
  perform 1 from private.ai_test_budget_v5 where singleton for update;
  update private.ai_test_reservations_v5
     set settled_microusd = v_cost, settlement_basis = 'MEASURED', settled_at = statement_timestamp()
   where operation_id = p_operation_id and settled_microusd is null;
  get diagnostics v_settled = row_count;
  if v_settled then
    v_released := v_reservation.max_cost_microusd - v_cost;
    update private.ai_test_budget_v5
       set reserved_microusd = greatest(0, reserved_microusd - v_released) where singleton;
  else
    v_cost := v_reservation.settled_microusd;
  end if;

  return jsonb_build_object('operationId', p_operation_id, 'recorded', true,
    'promptTokens', p_prompt_tokens, 'outputTokens', p_output_tokens,
    'totalTokens', p_total_tokens, 'authoritative', true,
    'settledMicrousd', v_cost, 'releasedMicrousd', v_released);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_test_release_unused_reservation_service(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_reservation private.ai_test_reservations_v5;
  v_rows integer;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_operation_id is null then raise exception 'AI_RELEASE_INPUT_INVALID' using errcode = '22023'; end if;

  select * into v_reservation from private.ai_test_reservations_v5 where operation_id = p_operation_id;
  if not found then raise exception 'AI_RELEASE_NO_RESERVATION' using errcode = '42501'; end if;

  -- A failed operation that nevertheless produced usage is a real call. It settles through
  -- the measured path and must never be recorded as FAILED_NO_USAGE.
  if exists (select 1 from private.ai_test_usage_v5 where operation_id = p_operation_id) then
    return jsonb_build_object('operationId', p_operation_id, 'released', false,
      'code', 'AI_RELEASE_REFUSED_USAGE_EXISTS', 'releasedMicrousd', 0,
      'settlementBasis', v_reservation.settlement_basis, 'settledMicrousd', v_reservation.settled_microusd);
  end if;

  if v_reservation.settled_microusd is not null then
    return jsonb_build_object('operationId', p_operation_id, 'released', false,
      'code', 'AI_RELEASE_ALREADY_SETTLED', 'releasedMicrousd', 0,
      'settlementBasis', v_reservation.settlement_basis, 'settledMicrousd', v_reservation.settled_microusd);
  end if;

  -- The same singleton lock the reservation writer and the measured settlement take.
  perform 1 from private.ai_test_budget_v5 where singleton for update;
  update private.ai_test_reservations_v5
     set settled_microusd = 0, settlement_basis = 'FAILED_NO_USAGE', settled_at = statement_timestamp()
   where operation_id = p_operation_id and settled_microusd is null;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    return jsonb_build_object('operationId', p_operation_id, 'released', false,
      'code', 'AI_RELEASE_ALREADY_SETTLED', 'releasedMicrousd', 0);
  end if;

  update private.ai_test_budget_v5
     set reserved_microusd = greatest(0, reserved_microusd - v_reservation.max_cost_microusd) where singleton;

  return jsonb_build_object('operationId', p_operation_id, 'released', true,
    'code', 'AI_RELEASE_DONE', 'releasedMicrousd', v_reservation.max_cost_microusd,
    'settlementBasis', 'FAILED_NO_USAGE', 'settledMicrousd', 0);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ai_test_settle_audio_service(p_operation_id uuid, p_audio_bytes bigint, p_transcript_chars integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_reservation private.ai_test_reservations_v5;
  v_cost bigint;
  v_rows integer;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if;
  if p_operation_id is null or p_audio_bytes is null or p_transcript_chars is null
     or p_audio_bytes <= 0 or p_transcript_chars < 0 then
    raise exception 'AI_AUDIO_SETTLE_INPUT_INVALID' using errcode = '22023';
  end if;

  select * into v_reservation from private.ai_test_reservations_v5 where operation_id = p_operation_id;
  if not found then raise exception 'AI_AUDIO_SETTLE_NO_RESERVATION' using errcode = '42501'; end if;
  if v_reservation.kind <> 'STT' then
    return jsonb_build_object('operationId', p_operation_id, 'settled', false, 'code', 'AI_AUDIO_SETTLE_NOT_STT', 'releasedMicrousd', 0);
  end if;
  -- Provider-reported usage always wins over a duration-based settlement.
  if exists (select 1 from private.ai_test_usage_v5 where operation_id = p_operation_id) then
    return jsonb_build_object('operationId', p_operation_id, 'settled', false, 'code', 'AI_AUDIO_SETTLE_USAGE_EXISTS', 'releasedMicrousd', 0);
  end if;
  if v_reservation.settled_microusd is not null then
    return jsonb_build_object('operationId', p_operation_id, 'settled', false, 'code', 'AI_AUDIO_SETTLE_ALREADY_SETTLED',
      'releasedMicrousd', 0, 'settlementBasis', v_reservation.settlement_basis, 'settledMicrousd', v_reservation.settled_microusd);
  end if;

  v_cost := least(private.ai_test_stt_price_microusd(p_audio_bytes, p_transcript_chars), v_reservation.max_cost_microusd);

  perform 1 from private.ai_test_budget_v5 where singleton for update;
  update private.ai_test_reservations_v5
     set settled_microusd = v_cost, settlement_basis = 'AUDIO_DURATION_AT_PUBLISHED_RATE', settled_at = statement_timestamp(),
         measured_audio_bytes = p_audio_bytes, measured_transcript_chars = p_transcript_chars
   where operation_id = p_operation_id and settled_microusd is null;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    return jsonb_build_object('operationId', p_operation_id, 'settled', false, 'code', 'AI_AUDIO_SETTLE_ALREADY_SETTLED', 'releasedMicrousd', 0);
  end if;

  update private.ai_test_budget_v5
     set reserved_microusd = greatest(0, reserved_microusd - (v_reservation.max_cost_microusd - v_cost)) where singleton;

  return jsonb_build_object('operationId', p_operation_id, 'settled', true, 'code', 'AI_AUDIO_SETTLED',
    'settledMicrousd', v_cost, 'releasedMicrousd', v_reservation.max_cost_microusd - v_cost,
    'audioSeconds', round(p_audio_bytes::numeric / 32000.0, 2), 'settlementBasis', 'AUDIO_DURATION_AT_PUBLISHED_RATE');
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_apply_profile_avatar(p_asset_id uuid, p_expected_avatar_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets; p public.app_profiles; receipt jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 perform private.closure_assert_open(auth.uid());
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=auth.uid() and scope='AVATAR' and state='READY';
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 select * into p from public.app_profiles where id=a.profile_id and account_id=auth.uid() and profile_status in('DRAFT','ACTIVE') for update;
 if not found then raise exception 'MEDIA_NOT_EDITABLE' using errcode='42501'; end if;
 select * into a from private.owned_media_assets where id=a.id for update;
 if a.avatar_apply_receipt is not null then return a.avatar_apply_receipt; end if;
 if not a.selected then raise exception 'MEDIA_NOT_EDITABLE' using errcode='55000'; end if;
 if p.avatar_path is distinct from p_expected_avatar_path or a.avatar_source_marker is distinct from encode(extensions.digest(to_jsonb(p)::text,'sha256'),'hex')
 then raise exception 'MEDIA_VERSION_CONFLICT' using errcode='PT409'; end if;
 update public.app_profiles set avatar_path=a.storage_path where id=p.id;
 receipt:=jsonb_build_object('profileId',p.id,'accountId',auth.uid(),'assetId',a.id,'avatarPath',a.storage_path,'saved',true,'authoritative',true);
 update private.owned_media_assets set avatar_apply_receipt=receipt where id=a.id;
 return receipt;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_authorize_data_export_download(p_receipt_id uuid, p_artifact_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; expires timestamptz; grant_id uuid:=gen_random_uuid();
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 r:=private.data_export_lock(p_receipt_id,auth.uid());
 if p_artifact_generation is null or r.active_export_attempt_id is distinct from p_artifact_generation then raise exception 'EXPORT_GENERATION_STALE' using errcode='PT409'; end if;
 if private.data_export_descriptor(r.id,r.account_id) is null then raise exception 'EXPORT_NOT_READY' using errcode='55000'; end if;
 select * into a from private.data_export_artifacts where id=r.active_export_attempt_id for update;
 expires:=least(clock_timestamp()+make_interval(secs=>(a.policy_binding#>>'{delivery,downloadLifetimeSeconds}')::integer),a.artifact_expires_at);
 if expires<=clock_timestamp() then raise exception 'EXPORT_GRANT_EXPIRED' using errcode='55000'; end if;
 update private.data_export_artifacts set download_grant_id=grant_id,download_grant_expires_at=expires where id=a.id;
 perform private.audit_marketplace(r.account_id,'DATA_EXPORT_DOWNLOAD_AUTHORIZED','SYSTEM',r.id,null,'{}'::jsonb);
 return jsonb_build_object('receiptId',r.id,'downloadGrantId',grant_id,'artifactGeneration',a.id,'expiresAt',expires);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_begin_push_send(p_attempt_id uuid, p_lease_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  a public.notification_push_attempts%rowtype;
  d public.notification_deliveries%rowtype;
  dev public.notification_push_devices%rowtype;
  why text;
  v_event_type text;
  v_event_id uuid;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'FORBIDDEN' using errcode='42501';
  end if;
  select x.* into dev
  from public.notification_push_devices x
  join public.notification_push_attempts y on y.device_id=x.id
  where y.id=p_attempt_id;
  if not found then return jsonb_build_object('kind','SUPPRESSED'); end if;

  -- Preserve the proven token-first lock ordering.
  perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||dev.expo_push_token,0));
  select x.* into d
  from public.notification_deliveries x
  join public.notification_push_attempts y on y.delivery_id=x.id
  where y.id=p_attempt_id
  for update of x;
  select * into a from public.notification_push_attempts where id=p_attempt_id for update;
  if not found or a.transport_state<>'SEND_LEASED'
     or a.lease_id is distinct from p_lease_id
     or a.lease_until<=clock_timestamp() then
    raise exception 'PUSH_LEASE_STALE' using errcode='PT409';
  end if;

  select * into dev from public.notification_push_devices where id=a.device_id;
  if a.single_target_admission is not null then
    if a.single_target_claimed_at is null or a.send_count<>0
       or ((a.single_target_admission->>'expiresAt')::timestamptz>clock_timestamp()) is not true
       or a.device_id::text is distinct from a.single_target_admission->>'deviceId'
       or a.device_revision::text is distinct from a.single_target_admission->>'deviceRevision'
       or dev.bound_session_id::text is distinct from a.single_target_admission->>'boundSessionId'
       or d.event_id::text is distinct from a.single_target_admission->>'eventId'
       or d.recipient_user_id::text is distinct from a.single_target_admission->>'recipientAccountId'
       or d.recipient_role is distinct from a.single_target_admission->>'recipientRole'
       or not exists(select 1 from public.user_activity_events e
         where e.id=d.event_id and e.recipient_user_id=d.recipient_user_id
           and e.recipient_role=d.recipient_role
           and e.event_type=a.single_target_admission->>'eventType'
           and e.event_type in ('MESSAGE_RECEIVED','OPPORTUNITY_AVAILABLE'))
       -- A Need can change between manual admission and the actual send. Recheck
       -- current recipient, public task revision, world, consent and expiry.
       or (a.single_target_admission->>'eventType'='OPPORTUNITY_AVAILABLE' and not exists(
         select 1 from public.user_activity_events e
         join public.needs n on n.id=e.entity_id
         join public.app_profiles p on p.account_id=d.recipient_user_id
           and p.kind='WORKER' and p.profile_status='ACTIVE'
         join public.opportunity_deliveries od on od.worker_profile_id=p.id
           and od.worker_account_id=d.recipient_user_id and od.need_id=n.id
           and od.need_revision=n.revision
         where e.id=d.event_id and e.recipient_user_id=d.recipient_user_id
           and e.recipient_role='WORKER' and e.event_type='OPPORTUNITY_AVAILABLE'
           and e.entity_type='NEED' and e.entity_version=n.revision
           and e.dedupe_key='opp:'||n.id::text||':'||n.revision::text||':'||d.recipient_user_id::text
           and n.status in ('PUBLISHED','SELECTION') and n.requester_account_id is not null
           and n.requester_account_id<>d.recipient_user_id
           and od.status in ('READY','SEEN','RESPONDED') and od.expires_at>clock_timestamp()
           and private.accounts_same_world(n.requester_account_id,d.recipient_user_id)
           and not private.closure_account_restricted(n.requester_account_id)
           and not private.safety_event_blocked(e)
           and exists(select 1 from public.notification_deliveries x where x.event_id=e.id
             and x.recipient_user_id=d.recipient_user_id and x.recipient_role='WORKER'
             and x.channel='IN_APP' and x.dedupe_key=e.dedupe_key||':in_app'
             and x.suppression_reason is null and x.state in ('CREATED','SENT','DELIVERED','READ'))
       ))
    then why:='SINGLE_TARGET_EXPIRED_OR_CHANGED'; end if;
  end if;
  why:=coalesce(why,private.push_suppression(d));
  if why is null and
    (dev.id is null or dev.user_id<>d.recipient_user_id or not dev.active
     or dev.revision<>a.device_revision or dev.bound_revision is distinct from dev.revision
     or not private.push_session_valid(dev.user_id,dev.bound_session_id)) then
    why:='DEVICE_CHANGED';
  end if;
  if why is not null then
    update public.notification_push_attempts
    set transport_state='SUPPRESSED',outcome='FATAL',error_code=why,lease_id=null,lease_until=null
    where id=a.id;
    return jsonb_build_object('kind','SUPPRESSED');
  end if;

  select e.event_type,e.id into v_event_type,v_event_id
  from public.user_activity_events e
  where e.id=d.event_id
    and e.recipient_user_id=d.recipient_user_id
    and e.recipient_role=d.recipient_role;
  if v_event_type is null then
    update public.notification_push_attempts
    set transport_state='SUPPRESSED',outcome='FATAL',error_code='EVENT_UNAVAILABLE',lease_id=null,lease_until=null
    where id=a.id;
    return jsonb_build_object('kind','SUPPRESSED');
  end if;

  update public.notification_push_attempts
  set transport_state='SEND_STARTED',send_count=send_count+1
  where id=a.id;

  -- The event UUID is a recipient-bound hint, never navigation authority. The
  -- authenticated P4 resolver rechecks it after tap and returns the exact target.
  return jsonb_build_object(
    'kind','SEND',
    'attemptId',a.id,
    'leaseId',a.lease_id,
    'leaseExpiresAt',a.lease_until,
    'expoPushToken',dev.expo_push_token,
    'priority',d.priority,
    'eventType',v_event_type
  ) || case when v_event_type in ('MESSAGE_RECEIVED','OPPORTUNITY_AVAILABLE','RESPONSE_RECEIVED','RESPONSE_UPDATED')
    then jsonb_build_object('eventId',v_event_id) else '{}'::jsonb end;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_agreement(p_agreement_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid := auth.uid();
  v_need_id uuid;
  v_agr public.agreements%rowtype;
  v_covered integer;
  v_need public.needs%rowtype;
  v_reason_kept boolean := false;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'REASON_REQUIRED' using errcode = 'P0001';
  end if;

  -- Discover without locking, authorize, then use the canonical lock order
  -- Need -> Agreement -> Response shared with selection/cancel/withdraw.
  select a.need_id into v_need_id
    from public.agreements a
   where a.id = p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;

  select * into v_need
    from public.needs n
   where n.id = v_need_id
   for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode = 'P0002'; end if;

  select * into v_agr from public.agreements
   where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_agr.need_id is distinct from v_need.id then
    raise exception 'AGREEMENT_NEED_MISMATCH' using errcode = 'P0001';
  end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;
  if v_agr.status = 'CANCELLED' then return; end if;
  if v_agr.status = 'COMPLETED' then
    raise exception 'ALREADY_COMPLETED' using errcode = 'P0001';
  end if;
  -- PKG-031a (deep read 7.16): once the worker has said the work is done, the requester confirms completion or
  -- reports a problem. Cancelling would take the finished job, and its rating, from the worker.
  if uid = v_agr.requester_account_id and exists (select 1 from public.agreement_execution x
       where x.agreement_id = v_agr.id and x.state = 'AWAITING_REQUESTER') then
    raise exception 'AGREEMENT_WORK_REPORTED_DONE' using errcode = 'P0001';
  end if;

  -- PKG-032a (deep read 7.15): the reason the app requires is kept where the other party and support read it, as
  -- the canceller's own message in the Agreement's conversation, the way rpc_report_problem keeps a problem.
  if not private.safety_pair_blocked(v_agr.requester_account_id, v_agr.worker_account_id)
     and not private.closure_account_restricted(v_agr.requester_account_id)
     and not private.closure_account_restricted(v_agr.worker_account_id) then
    insert into public.agreement_messages(agreement_id, agreement_version, sender_account_id, body)
    values (v_agr.id, v_agr.current_version, uid, left('Otkazujem Dogovor. Razlog: ' || btrim(p_reason), 2000));
    v_reason_kept := true;
  end if;

  update public.agreements set status = 'CANCELLED' where id = p_agreement_id;
  update public.agreement_execution set state = 'CANCELLED'
   where agreement_id = p_agreement_id;
  update public.need_selections set status = 'CANCELLED'
   where id = v_agr.selection_id;
  update public.marketplace_responses
     set status = 'NOT_SELECTED', selected_at = null
   where id = v_agr.selected_response_id;
  update public.access_grants
     set status = 'REVOKED',
         revoked_at = coalesce(revoked_at, statement_timestamp())
   where agreement_id = p_agreement_id and status = 'GRANTED';
  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and e.entity_type = 'AGREEMENT'
     and e.entity_id = p_agreement_id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');

  v_covered := public.fn_need_covered_slots(v_agr.need_id);

  if v_covered < v_need.required_slots
     and v_need.status in ('ACTIVE','SELECTION')
     and not private.closure_account_restricted(v_need.requester_account_id) then
    -- Coverage truth changes even when search authority says do not search.
    perform set_config('uskoci.need_lifecycle', 'CANCEL_AGREEMENT', true);
    update public.needs set status = 'SELECTION' where id = v_need.id;

    -- Human search authority is independent from coverage. Cancellation never clears it.
    -- Time authority is also independent: no matching is reanimated after the admitted window.
    if v_need.remaining_search_closed_at is null
       and private.need_search_time_admitted_v1(v_need.id, clock_timestamp()) then
      perform private.enqueue_dispatch(v_need.id, clock_timestamp());
    else
      -- The existing Need status trigger blindly enqueues ACTIVE -> SELECTION.
      -- Remove that stale queue row when search/time authority says matching is closed.
      delete from private.dispatch_schedule where need_id = v_need.id;
    end if;
  end if;
  perform private.emit_event(
    case when uid=v_agr.requester_account_id then v_agr.worker_account_id else v_agr.requester_account_id end,
    case when uid=v_agr.requester_account_id then 'WORKER' else 'REQUESTER' end,
    'AGREEMENT_CANCELLED','AGREEMENT',v_agr.id,v_agr.current_version,
    'Dogovor je otkazan',
    case when v_reason_kept then 'Druga strana je otkazala Dogovor. Razlog je u Porukama.'
         else 'Druga strana je otkazala Dogovor.' end,
    'agreement-cancelled:'||v_agr.id::text,'NORMAL',
    jsonb_build_object('agreementId',v_agr.id,'state','CANCELLED'),null);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_data_export(p_receipt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  r public.data_export_requests%rowtype;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_receipt_id is null then raise exception 'INVALID_RECEIPT_ID' using errcode='22023'; end if;

  perform pg_advisory_xact_lock(hashtextextended('uskoci:data-export:'||u::text,0));

  select * into r from public.data_export_requests d
  where d.id=p_receipt_id and d.account_id=u
  for update;
  if not found then raise exception 'DATA_EXPORT_REQUEST_NOT_FOUND' using errcode='P0002'; end if;

  if r.status='CANCELLED' then
    return jsonb_build_object('receiptId',r.id,'status',r.status,'cancelledAt',r.cancelled_at,'idempotentReplay',true);
  end if;
  if r.status<>'REQUESTED' then
    raise exception 'DATA_EXPORT_REQUEST_NOT_CANCELLABLE' using errcode='55000';
  end if;

  update public.data_export_requests
  set status='CANCELLED',cancelled_at=statement_timestamp(),updated_at=statement_timestamp()
  where id=r.id
  returning * into r;

  perform private.audit_marketplace(u,'DATA_EXPORT_CANCELLED','SYSTEM',r.id,null,'{}'::jsonb);

  return jsonb_build_object('receiptId',r.id,'status',r.status,'cancelledAt',r.cancelled_at,'idempotentReplay',false);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_media_upload(p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid := auth.uid(); c public.ai_conversations; a private.owned_media_assets; v_previous text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 if p_conversation_id is null or p_client_request_id is null then raise exception 'MEDIA_INPUT_INVALID' using errcode='22023'; end if;
 perform private.closure_assert_open(v_uid);
 -- Only the owner's own intake conversation may host the command. This is not an editability check: a draft
 -- that can no longer be edited may still retire an unconfirmed command identity.
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=v_uid;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 -- Same lock as the service claim: a delayed first send with this key waits here and then meets the tombstone.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:media-upload:'||v_uid::text||':'||p_client_request_id::text,130));
 -- RC02: preserve claim's advisory-first order, then lock conversation before asset.
 -- Re-read ownership under the lock; cancellation still does not require an editable draft.
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=v_uid for update;
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 select * into a from private.owned_media_assets where account_id=v_uid and client_request_id=p_client_request_id for update;
 if not found then
  insert into private.owned_media_assets(account_id,scope,conversation_id,client_request_id,state,selected,dispatch_state)
  values(v_uid,'TASK',c.id,p_client_request_id,'CANCELLED',false,'NOT_DISPATCHED');
  return jsonb_build_object('accountId',v_uid,'conversationId',c.id,'clientRequestId',p_client_request_id,
   'previousState',null,'assetId',null,'selected',false,'cancelled',true,'authoritative',true);
 end if;
 if a.scope<>'TASK' or a.conversation_id is distinct from c.id then raise exception 'MEDIA_COMMAND_CONFLICT' using errcode='PT409'; end if;
 if a.state='CANCELLED' then
  return jsonb_build_object('accountId',v_uid,'conversationId',c.id,'clientRequestId',p_client_request_id,
   'previousState',null,'assetId',null,'selected',false,'cancelled',true,'authoritative',true);
 end if;
 v_previous := a.state;
 if a.state='READY' then
  -- An admitted photograph leaves the draft through the existing removal writer (refs plus selected=false);
  -- no Storage object is deleted here.
  perform public.rpc_remove_task_photo(a.conversation_id,a.id);
 elsif a.selected then
  -- PROCESSING/STAGED: the dispatch may still settle, but it can never select this photograph into the draft.
  -- FAILED is already retired.
  update private.owned_media_assets set selected=false where id=a.id;
 end if;
 select * into a from private.owned_media_assets where id=a.id;
 return jsonb_build_object('accountId',v_uid,'conversationId',a.conversation_id,'clientRequestId',a.client_request_id,
  'previousState',v_previous,'assetId',a.id,'selected',a.selected,'cancelled',true,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_need(p_need_id uuid, p_need_revision integer, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  n public.needs;
  affected_responses integer := 0;
  w record;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;

  -- Same lock as selection, dispatch and submission. Whichever transaction owns
  -- this row determines the canonical outcome of a race.
  select * into n from public.needs where id = p_need_id for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;
  if n.requester_account_id <> u then
    raise exception using errcode='42501', message='FORBIDDEN';
  end if;

  if n.status = 'CANCELLED' then
    return jsonb_build_object(
      'needId', n.id,
      'status', n.status,
      'revision', n.revision,
      'affectedResponses', 0,
      'idempotentReplay', true,
      'authoritative', true
    );
  end if;

  if n.revision is distinct from p_need_revision then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  -- Once a seat is selected, cancellation belongs to the Agreement lifecycle.
  -- Historical CANCELLED Agreements do not keep the remaining Need hostage.
  if exists (
       select 1 from public.need_selections s
        where s.need_id = n.id and s.status = 'SELECTED'
     )
     or exists (
       select 1 from public.agreements a
        where a.need_id = n.id
          and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
     )
     or exists (
       select 1 from public.marketplace_responses r
        where r.need_id = n.id and r.status = 'SELECTED'
     ) then
    raise exception using errcode='P0001',
      message='NEED_CANCELLATION_REQUIRES_AGREEMENT_FLOW';
  end if;

  if n.status not in ('DRAFT','PUBLISHED','SELECTION') then
    raise exception using errcode='22023', message='NEED_NOT_CANCELLABLE';
  end if;

  -- Stop every pending side effect before emitting the terminal event.
  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE')
     and (
       (e.entity_type = 'NEED' and e.entity_id = n.id)
       or (e.entity_type = 'RESPONSE' and exists (
         select 1 from public.marketplace_responses r
          where r.id = e.entity_id and r.need_id = n.id
       ))
       or (e.entity_type = 'AGREEMENT' and exists (
         select 1 from public.agreements a
          where a.id = e.entity_id and a.need_id = n.id
       ))
     );

  update public.dispatch_rounds
     set status = 'STOPPED', stop_reason = 'NEED_CANCELLED'
   where need_id = n.id and status in ('PLANNED','SENT');

  update public.opportunity_deliveries
     set status = 'EXPIRED'
   where need_id = n.id and status in ('READY','SEEN');

  delete from private.dispatch_schedule where need_id = n.id;

  update public.access_grants g
     set status = 'REVOKED',
         revoked_at = coalesce(g.revoked_at, statement_timestamp())
   where g.status = 'GRANTED'
     and exists (
       select 1 from public.agreements a
        where a.id = g.agreement_id and a.need_id = n.id
     );

  perform set_config('uskoci.need_lifecycle', 'CANCEL_NEED', true);
  update public.needs
     set status = 'CANCELLED', urgent = false
   where id = n.id;

  -- Versions are never deleted or rewritten. Only the live Response outcome
  -- changes, and each affected worker receives an independently deduped event.
  for w in
    update public.marketplace_responses r
       set status = 'EXPIRED', selected_at = null
     where r.need_id = n.id
       and r.status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE')
     returning r.id, r.worker_account_id, r.current_version
  loop
    affected_responses := affected_responses + 1;
    perform private.emit_event(
      w.worker_account_id,
      'WORKER',
      'NEED_CANCELLED',
      'NEED',
      n.id,
      n.revision,
      'Potreba je otkazana',
      'Narucilac je otkazao Potrebu za koju ste poslali prijavu.',
      'need-cancelled:' || n.id::text || ':' || n.revision::text || ':worker:' || w.worker_account_id::text,
      'NORMAL',
      jsonb_build_object(
        'reason', 'REQUESTER_CANCELLED',
        'reasonProvided', char_length(btrim(coalesce(p_reason, ''))) > 0
      ),
      null
    );
  end loop;

  perform private.audit_marketplace(
    u,
    'NEED_CANCELLED',
    'NEED',
    n.id,
    n.revision,
    jsonb_build_object('reason', left(btrim(coalesce(p_reason, '')), 500))
  );

  return jsonb_build_object(
    'needId', n.id,
    'status', 'CANCELLED',
    'revision', n.revision,
    'affectedResponses', affected_responses,
    'idempotentReplay', false,
    'authoritative', true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_qa_classification(p_expected_user_id uuid, p_type text, p_need_id uuid, p_need_revision integer, p_question_id uuid, p_text_sha256 text, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a uuid:=auth.uid();c private.qa_ai_commands;input_hash text;context_value jsonb;prior jsonb;prior_receipt jsonb;
begin
 if a is null or a is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000';end if;
 if p_need_id is null or p_client_request_id is null or p_need_revision is null or p_need_revision<1 or p_type is null or p_type not in('ASK','ANSWER')
 or (p_type='ASK')<>(p_question_id is null) or p_text_sha256 is null or p_text_sha256 !~ '^[a-f0-9]{64}$' then raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_assert_open(a);perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||a::text||':'||p_client_request_id::text,0));
 input_hash:=private.qa_ai_input_hash(p_type,p_need_id,p_need_revision,p_question_id,p_text_sha256);
 -- Match the retained canonical command lock as well. If a direct RU4B writer
 -- already won, return its immutable receipt instead of claiming cancellation.
 perform pg_advisory_xact_lock(hashtextextended(a::text||E'\n'||p_client_request_id::text,case when p_type='ASK' then 4412 else 4413 end));
 prior:=public.rpc_read_preselection_qa_command(a,p_need_id,p_client_request_id);
 if prior->'found'='true'::jsonb then
  if prior#>>'{command,type}'<>p_type or prior#>>'{command,textSha256}'<>p_text_sha256
   or(prior#>>'{command,needRevision}')::integer<>p_need_revision
   or(p_type='ANSWER' and prior#>>'{command,receipt,questionId}'<>p_question_id::text) then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';end if;
  prior_receipt:=prior#>'{command,receipt}';
 end if;
 select * into c from private.qa_ai_commands where account_id=a and client_request_id=p_client_request_id for update;
 if found then
  if c.request_hash<>input_hash then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';end if;
  if c.state='COMMITTED' then return private.qa_ai_status(a,p_need_id,p_client_request_id);
  elsif prior_receipt is not null then update private.qa_ai_commands set state='COMMITTED',receipt=prior_receipt,updated_at=clock_timestamp() where id=c.id;
  elsif c.state in('PROCESSING','READY') then update private.qa_ai_commands set state='CANCELLED',updated_at=clock_timestamp() where id=c.id;end if;
 else
  if prior_receipt is null then
  context_value:=public.rpc_read_preselection_qa_context(a,p_need_id);
  if p_type='ASK' and(context_value->>'mode'<>'PUBLIC' or context_value->'activeWorker'<>'true'::jsonb)
   or p_type='ANSWER' and(context_value->>'mode'<>'OWNER' or not exists(select 1 from private.preselection_qa_questions where id=p_question_id and need_id=p_need_id))
   then raise exception 'QA_INPUT_INVALID' using errcode='42501';end if;end if;
  insert into private.qa_ai_commands(account_id,client_request_id,command_type,need_id,need_revision,question_id,text_sha256,request_hash,state)
  values(a,p_client_request_id,p_type,p_need_id,p_need_revision,p_question_id,p_text_sha256,input_hash,'CANCELLED');
  if prior_receipt is not null then update private.qa_ai_commands set state='COMMITTED',receipt=prior_receipt where account_id=a and client_request_id=p_client_request_id;end if;
 end if;
 return private.qa_ai_status(a,p_need_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_cancel_worker_ai_turn(p_expected_user_id uuid, p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); s private.worker_ai_sessions; t private.worker_ai_turns;
begin
 if u is null or p_expected_user_id is distinct from u then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 if p_conversation_id is null or p_client_request_id is null then raise exception 'WORKER_AI_ID_REQUIRED' using errcode='22023';end if;
 perform private.closure_assert_open(u);
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||u::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where account_id=u and conversation_id=p_conversation_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=u and purpose='PROFILE' and status='OPEN' for update;
 if not found then return private.worker_ai_turn_recovery_v5(u,p_conversation_id,p_client_request_id);end if;
 select * into t from private.worker_ai_turns where account_id=u and client_request_id=p_client_request_id for update;
 if found then
  if t.conversation_id is distinct from p_conversation_id then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409';end if;
  if t.state='PROCESSING' and t.cancelled_at is null then
   update private.worker_ai_turns set state='FAILED',cancelled_at=clock_timestamp() where turn_id=t.turn_id;
  end if;
 else
  -- Absent is only a read observation. The tombstone fences an HTTP claim still
  -- in flight and stores no message; the same opaque key can never be reused.
  insert into private.worker_ai_turns(account_id,conversation_id,client_request_id,body_hash,source_revision,state,lease_expires_at,cancelled_at)
  values(u,p_conversation_id,p_client_request_id,repeat('0',64),s.revision,'FAILED',clock_timestamp(),clock_timestamp());
 end if;
 return private.worker_ai_turn_recovery_v5(u,p_conversation_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_check_preselection_qa_limits_service(p_actor_account_id uuid, p_subject_kind text, p_need_id uuid, p_need_revision integer, p_question_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare n public.needs;question private.preselection_qa_questions;reason text;
begin
 select * into n from public.needs where id=p_need_id for share;
 if not found then raise exception 'NEED_NOT_FOUND' using errcode='42501';end if;
 if n.revision is distinct from p_need_revision then raise exception 'STALE_NEED_REVISION' using errcode='P0001';end if;
 if n.status not in('PUBLISHED','SELECTION') then raise exception 'NEED_NOT_PUBLIC' using errcode='P0001';end if;
 if p_subject_kind='QUESTION' then
  if n.requester_account_id=p_actor_account_id then raise exception 'REQUESTER_CANNOT_ASK_OWN_TASK' using errcode='42501';end if;
  if not exists(select 1 from public.app_profiles where account_id=p_actor_account_id and kind='WORKER' and profile_status='ACTIVE') then raise exception 'ACTIVE_WORKER_REQUIRED' using errcode='42501';end if;
  perform private.ru4b_assert_block_authority_ready(p_actor_account_id,n.requester_account_id);
 elsif p_subject_kind='ANSWER' then
  if n.requester_account_id is distinct from p_actor_account_id then raise exception 'NOT_NEED_OWNER' using errcode='42501';end if;
  select * into question from private.preselection_qa_questions where id=p_question_id and need_id=n.id and need_revision=n.revision;
  if not found then raise exception 'QUESTION_NOT_FOUND' using errcode='42501';end if;
  if question.status in('IGNORED','REPORTED') then raise exception 'QUESTION_NOT_ANSWERABLE' using errcode='P0001';end if;
  perform private.ru4b_assert_block_authority_ready(question.asker_account_id,p_actor_account_id);
 else raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 perform private.ru4b_assert_numeric_policy_v5(p_actor_account_id,p_subject_kind,p_need_id,p_need_revision,p_question_id,p_text);
 reason:=private.ru4b_public_floor_reason(btrim(coalesce(p_text,'')));
 if reason is not null then raise exception '%',reason using errcode='P0001';end if;
 return jsonb_build_object('accountId',p_actor_account_id,'needId',p_need_id,'needRevision',p_need_revision,'subjectKind',p_subject_kind,'questionId',p_question_id,
  'textSha256',encode(extensions.digest(convert_to(btrim(p_text),'UTF8'),'sha256'),'hex'),'ready',true,'policyVersion','V5_QA_LIMITS_1','authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_account_closure_action_service(p_account_id uuid, p_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e private.closure_executions_v5;a private.closure_actions_v5;begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 if p_account_id is null or p_generation is null then raise exception 'CLOSURE_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_erasure_lock_v5(p_account_id);
 select * into e from private.closure_executions_v5 where account_id=p_account_id and generation=p_generation;
 if not found then raise exception 'CLOSURE_GENERATION_STALE' using errcode='PT409';end if;
 if e.state='CLOSED' then return jsonb_build_object('kind','CLOSED','receipt',e.receipt);end if;
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then perform private.closure_erasure_assert_current_v5(e);else perform private.closure_assert_current_v5(e);end if;
 update private.closure_executions_v5 set last_checked_at=clock_timestamp() where account_id=e.account_id;
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' and not exists(select 1 from private.closure_actions_v5 where generation=e.generation and kind='STORAGE_DELETE' and state<>'VERIFIED')
 and not private.closure_auth_dispatched_v5(e.account_id) then perform private.closure_erasure_refresh_steps_v5(e);end if;
 select * into a from private.closure_actions_v5 where generation=e.generation and state<>'VERIFIED' order by case kind when 'STORAGE_DELETE' then 0 when 'RELATIONAL_REDACT' then 1 else 2 end,id limit 1;
 if not found then return jsonb_build_object('kind','FINALIZE','accountId',e.account_id,'generation',e.generation);end if;
 if a.kind='AUTH_IDENTITY_ERASE' and e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' and cardinality(private.closure_erasure_exceptions_v5(e.account_id))>0 then
  return jsonb_build_object('kind','EXCEPTIONS_PENDING','progress',private.closure_erasure_progress_v5(e));end if;
 return private.closure_action_document_v5(a,e);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_ai_task_review_evaluation_service(p_account_id uuid, p_review_id uuid, p_need_id uuid, p_need_revision integer, p_binding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r private.ai_task_reviews; c private.ai_task_review_commands; ctx jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 lock table private.publication_policy_bundles,private.publication_policy_rule_refs,private.location_market_configs in share mode;
 select * into r from private.ai_task_reviews where id=p_review_id and account_id=p_account_id;
 if not found then raise exception 'TASK_REVIEW_NOT_FOUND' using errcode='42501'; end if;
 select * into c from private.ai_task_review_commands where review_id=r.id and account_id=p_account_id for update;
 if not found or c.need_id is distinct from p_need_id or c.need_revision is distinct from p_need_revision
 then raise exception 'TASK_REVIEW_COMMAND_MISMATCH' using errcode='42501'; end if;
 if c.state<>'ACCEPTED' then return jsonb_build_object('acquired',false,'attemptId',null,'command',private.ai_task_review_command_document(r.id)); end if;
 if exists(select 1 from jsonb_array_elements(r.envelope->'publicProjection') identity_fact
  where identity_fact->>'key'='need.verified_identity_required' and identity_fact->'value'='true'::jsonb)
 then raise exception 'IDENTITY_VERIFICATION_UNAVAILABLE' using errcode='22023';end if;
 if r.policy_binding is distinct from private.ai_task_review_policy(r.envelope#>>'{location,taskCountryCode}')
 then raise exception 'TASK_REVIEW_POLICY_STALE' using errcode='PT409'; end if;
 ctx:=private.need_publication_context(c.need_id,c.need_revision,p_account_id);
 if ctx->>'kind'<>'READY' or ctx->'binding' is distinct from p_binding then raise exception 'TASK_REVIEW_STALE' using errcode='PT409'; end if;
 update private.ai_task_review_commands set state='EVALUATING',attempt_id=extensions.gen_random_uuid(),
  lease_expires_at=clock_timestamp()+interval '60 seconds',evaluation_binding=p_binding where review_id=r.id returning * into c;
 return jsonb_build_object('acquired',true,'attemptId',c.attempt_id,'command',private.ai_task_review_command_document(r.id));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_data_export(p_receipt_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; b jsonb; target uuid; snap text; v_now timestamptz; aid uuid:=gen_random_uuid(); global_claim boolean:=p_receipt_id is null and p_account_id is null;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 for target in select d.id from public.data_export_requests d left join private.data_export_artifacts x on x.id=d.active_export_attempt_id
 where (p_receipt_id is null or d.id=p_receipt_id) and (p_account_id is null or d.account_id=p_account_id) and d.export_revoked_at is null
 and (d.status='REQUESTED' or (d.status='PROCESSING' and x.lease_until<=clock_timestamp())) and (d.export_next_attempt_at is null or d.export_next_attempt_at<=clock_timestamp())
 order by d.requested_at,d.id limit 32 loop
 r:=private.data_export_lock(target,p_account_id,global_claim);v_now:=clock_timestamp();
 if r.id is null then continue; end if;
 if global_claim then
   select * into a from private.data_export_artifacts where id=r.active_export_attempt_id for update skip locked;
   if r.active_export_attempt_id is not null and not found then continue; end if;
 else select * into a from private.data_export_artifacts where id=r.active_export_attempt_id for update; end if;
 if r.export_revoked_at is not null or r.status not in ('REQUESTED','PROCESSING') or (r.status='PROCESSING' and (a.id is null or a.lease_until>v_now)) or r.export_next_attempt_at>v_now then continue; end if;
 if r.export_attempt_count>=5 then
   update public.data_export_requests set status='FAILED',completed_at=v_now,failure_code='EXPORT_WORKER_FAILED',updated_at=v_now,export_next_attempt_at=null where id=r.id;
   continue;
 end if;
 b:=private.data_export_policy_binding();if b is null then return jsonb_build_object('kind','NOT_READY','code','EXPORT_POLICY_NOT_READY'); end if;
 snap:=private.data_export_snapshot(r.account_id,r.id,b,v_now);
 if snap is null then
   if global_claim then continue; end if;
   return jsonb_build_object('kind','NOT_READY','code','EXPORT_ACCOUNT_UNAVAILABLE');
 end if;
 if octet_length(snap)>8388608 then
   if global_claim then continue; end if;
   return jsonb_build_object('kind','NOT_READY','code','EXPORT_SNAPSHOT_TOO_LARGE');
 end if;
 v_now:=clock_timestamp();
 if a.id is not null then update private.data_export_artifacts set cleanup_not_before=greatest(lease_until,v_now),download_grant_id=null,download_grant_expires_at=null where id=a.id; end if;
 insert into private.data_export_artifacts(id,receipt_id,account_id,attempt_number,policy_id,policy_sha256,policy_binding,snapshot_text,byte_length,sha256,md5,object_path,created_at,lease_until,artifact_expires_at,snapshot_expires_at,cleanup_not_before)
 values(aid,r.id,r.account_id,r.export_attempt_count+1,(b->>'policyId')::uuid,b->>'sha256',b,snap,octet_length(snap),encode(extensions.digest(convert_to(snap,'UTF8'),'sha256'),'hex'),md5(snap),r.account_id::text||'/'||r.id::text||'/'||aid::text||'.json',v_now,
 least(v_now+interval '120 seconds',v_now+make_interval(secs=>(b#>>'{delivery,artifactLifetimeSeconds}')::integer)),v_now+make_interval(secs=>(b#>>'{delivery,artifactLifetimeSeconds}')::integer),v_now+make_interval(secs=>(b#>>'{delivery,snapshotLifetimeSeconds}')::integer),v_now+make_interval(secs=>(b#>>'{delivery,artifactLifetimeSeconds}')::integer)) returning * into a;
 update public.data_export_requests set status='PROCESSING',completed_at=null,cancelled_at=null,failure_code=null,updated_at=v_now,active_export_attempt_id=a.id,export_attempt_count=a.attempt_number,export_next_attempt_at=null where id=r.id;
 perform private.audit_marketplace(r.account_id,'DATA_EXPORT_PROCESSING','SYSTEM',r.id,null,jsonb_build_object('attempt',a.attempt_number));
 return jsonb_build_object('kind','CLAIMED','receiptId',r.id,'accountId',r.account_id,'attemptId',a.id,'leaseExpiresAt',a.lease_until,'snapshotText',a.snapshot_text,'byteLength',a.byte_length,'sha256',a.sha256,'md5',a.md5,'bucket','data-export-artifacts','objectPath',a.object_path,'artifactExpiresAt',a.artifact_expires_at);
 end loop;
 return jsonb_build_object('kind','NONE');
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_data_export_cleanup(p_receipt_id uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; candidate record; token uuid:=gen_random_uuid(); v_now timestamptz; global_claim boolean:=p_receipt_id is null and p_account_id is null;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 for candidate in select x.id,x.receipt_id from private.data_export_artifacts x where (p_receipt_id is null or x.receipt_id=p_receipt_id) and (p_account_id is null or x.account_id=p_account_id)
 and x.cleanup_not_before<=clock_timestamp() and x.lease_until<=clock_timestamp()
 and (x.cleanup_lease_until is null or x.cleanup_lease_until<=clock_timestamp()) and (x.cleanup_next_at is null or x.cleanup_next_at<=clock_timestamp())
 order by coalesce(x.cleanup_next_at,x.cleanup_not_before),x.id limit 32 loop
 r:=private.data_export_lock(candidate.receipt_id,p_account_id,global_claim);v_now:=clock_timestamp();
 if r.id is null then continue; end if;
 if global_claim then select * into a from private.data_export_artifacts where id=candidate.id for update skip locked;
 else select * into a from private.data_export_artifacts where id=candidate.id for update; end if;
 if not found then continue; end if;
 if a.cleanup_not_before>v_now or a.lease_until>v_now or a.cleanup_lease_until>v_now or a.cleanup_next_at>v_now then continue; end if;
 if r.active_export_attempt_id=a.id and r.status='READY' and r.export_revoked_at is null and a.artifact_expires_at>v_now then continue; end if;
 update private.data_export_artifacts set cleanup_attempt_id=token,cleanup_deleted=null,cleanup_lease_until=v_now+interval '120 seconds',download_grant_id=null,download_grant_expires_at=null where id=a.id;
 if r.active_export_attempt_id=a.id and r.status='READY' then update public.data_export_requests set status='EXPIRED',updated_at=v_now where id=r.id; end if;
 return jsonb_build_object('kind','CLAIMED','receiptId',r.id,'accountId',r.account_id,'artifactGeneration',a.id,'cleanupAttemptId',token,'leaseExpiresAt',v_now+interval '120 seconds','bucket','data-export-artifacts','objectPath',a.object_path);
 end loop;
 return jsonb_build_object('kind','NONE');
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_media_upload_service(p_account_id uuid, p_scope text, p_target_id uuid, p_client_request_id uuid, p_input_sha256 text, p_input_bytes integer, p_input_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets; c public.ai_conversations; refs text[]; avatar_marker text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_account_id is null or p_target_id is null or p_client_request_id is null or p_scope is null or p_scope not in('TASK','AVATAR')
  or p_input_sha256 is null or p_input_sha256!~'^[a-f0-9]{64}$' or p_input_bytes is null or p_input_bytes not between 1 and 10485760
  or p_input_type is null or p_input_type not in('image/jpeg','image/png','image/webp') then raise exception 'MEDIA_INPUT_INVALID' using errcode='22023'; end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('uskoci:media-upload:'||p_account_id::text||':'||p_client_request_id::text,130));
 if exists(select 1 from private.owned_media_assets x where x.account_id=p_account_id and x.client_request_id=p_client_request_id and x.state='CANCELLED') then raise exception 'MEDIA_COMMAND_CANCELLED' using errcode='55000'; end if;
 select * into a from private.owned_media_assets where account_id=p_account_id and client_request_id=p_client_request_id;
 if found then
  if a.scope is distinct from p_scope or coalesce(a.conversation_id,a.profile_id) is distinct from p_target_id or a.input_sha256 is distinct from p_input_sha256
   or a.input_bytes is distinct from p_input_bytes or a.input_type is distinct from p_input_type then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023'; end if;
  return jsonb_build_object('acquired',false,'attemptId',null,'asset',private.media_asset_document(a),'staged',case when a.state='STAGED' then
   jsonb_build_object('path',a.storage_path,'sha256',a.sanitized_sha256,'byteSize',a.byte_size,'dispatchState',a.dispatch_state,'dispatchOutcome',a.dispatch_outcome) else null end);
 end if;
 if p_scope='TASK' then
  c:=private.media_assert_task_edit(p_account_id,p_target_id); refs:=private.media_task_refs(c.id);
  if cardinality(refs)+(select count(*) from private.owned_media_assets where conversation_id=c.id and selected and state in('PROCESSING','STAGED'))>=6
   then raise exception 'MEDIA_LIMIT_REACHED' using errcode='22023'; end if;
 else
  perform 1 from public.app_profiles where id=p_target_id and account_id=p_account_id and profile_status in('DRAFT','ACTIVE') for update;
  if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
  if exists(select 1 from private.owned_media_assets where profile_id=p_target_id and selected and state in('PROCESSING','STAGED'))
   then raise exception 'MEDIA_UPLOAD_PENDING' using errcode='55000'; end if;
  select encode(extensions.digest(to_jsonb(p)::text,'sha256'),'hex') into avatar_marker from public.app_profiles p where p.id=p_target_id;
 end if;
 insert into private.owned_media_assets(account_id,scope,conversation_id,profile_id,client_request_id,input_sha256,input_bytes,input_type,avatar_source_marker)
 values(p_account_id,p_scope,case when p_scope='TASK' then p_target_id end,case when p_scope='AVATAR' then p_target_id end,p_client_request_id,p_input_sha256,p_input_bytes,p_input_type,avatar_marker) returning * into a;
 return jsonb_build_object('acquired',true,'attemptId',a.attempt_id,'asset',private.media_asset_document(a),'staged',null);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_push_single_target(p_admission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.notification_push_attempts%rowtype; d public.notification_deliveries%rowtype;
 dev public.notification_push_devices%rowtype; why text; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_admission_id is null then raise exception 'INVALID_PUSH_ADMISSION' using errcode='22023'; end if;
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0)) then return jsonb_build_object('kind','NONE'); end if;
 v_now:=clock_timestamp();
 if (select count(*) from public.notification_push_attempts where lease_until>v_now)>=6
  or (select count(*) from public.notification_push_attempts where last_claimed_at>v_now-interval '1 second')>=60
 then return jsonb_build_object('kind','NONE'); end if;
 select x.* into d from public.notification_deliveries x join public.notification_push_attempts y on y.delivery_id=x.id
  where y.id=p_admission_id and y.single_target_admission is not null for update of x;
 if not found then return jsonb_build_object('kind','NONE'); end if;
 select * into a from public.notification_push_attempts where id=p_admission_id for update;
 -- Never return a previously granted lease, even if no begin/provider call occurred.
 if not found or a.single_target_admission is null or a.single_target_claimed_at is not null
  or a.transport_state<>'PENDING' or a.send_count<>0 or a.lease_id is not null
 then return jsonb_build_object('kind','NONE'); end if;
 v_now:=clock_timestamp();
 why:=private.push_suppression(d);
 if why is null and ((a.single_target_admission->>'expiresAt')::timestamptz<=v_now
  or d.push_started_at is not null or d.event_id::text<>a.single_target_admission->>'eventId'
  or d.recipient_user_id::text<>a.single_target_admission->>'recipientAccountId'
  or d.recipient_role<>a.single_target_admission->>'recipientRole') then why:='SINGLE_TARGET_EXPIRED_OR_CHANGED'; end if;
 select * into dev from public.notification_push_devices where id=a.device_id;
 if why is null and (dev.id is null or not dev.active or dev.user_id<>d.recipient_user_id
  or dev.revision<>a.device_revision or dev.bound_revision is distinct from dev.revision
  or dev.bound_session_id::text is distinct from a.single_target_admission->>'boundSessionId'
  or not private.push_session_valid(dev.user_id,dev.bound_session_id)) then why:='DEVICE_CHANGED'; end if;
 if why is not null then
  update public.notification_push_attempts set single_target_claimed_at=v_now,transport_state='SUPPRESSED',outcome='FATAL',error_code=why,next_attempt_at=null where id=a.id;
  return jsonb_build_object('kind','NONE');
 end if;
 update public.notification_deliveries set push_started_at=v_now,queued_at=v_now,state='QUEUED' where id=d.id;
 update public.notification_push_attempts set single_target_claimed_at=v_now,transport_state='SEND_LEASED',
  lease_id=extensions.gen_random_uuid(),lease_until=least(v_now+interval '90 seconds',(single_target_admission->>'expiresAt')::timestamptz),
  next_attempt_at=null,last_claimed_at=v_now where id=a.id returning * into a;
 return jsonb_build_object('kind','SEND','attemptId',a.id,'leaseId',a.lease_id,'leaseExpiresAt',a.lease_until,'ticketId',null);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_push_single_target_receipt(p_admission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.notification_push_attempts%rowtype; d public.notification_deliveries%rowtype; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_admission_id is null then raise exception 'INVALID_PUSH_ADMISSION' using errcode='22023'; end if;
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0)) then return jsonb_build_object('kind','NONE'); end if;
 v_now:=clock_timestamp();
 if (select count(*) from public.notification_push_attempts where lease_until>v_now)>=6
  or (select count(*) from public.notification_push_attempts where last_claimed_at>v_now-interval '1 second')>=60
 then return jsonb_build_object('kind','NONE'); end if;
 select x.* into d from public.notification_deliveries x join public.notification_push_attempts y on y.delivery_id=x.id
  where y.id=p_admission_id and y.single_target_admission is not null for update of x;
 if not found then return jsonb_build_object('kind','NONE'); end if;
 select * into a from public.notification_push_attempts where id=p_admission_id for update;
 if not found or a.single_target_admission is null or a.single_target_claimed_at is null then return jsonb_build_object('kind','NONE'); end if;
 v_now:=clock_timestamp();
 -- Expired sends never return to PENDING. This is target-only retirement, not a scan of backlog.
 if a.transport_state in ('SEND_LEASED','SEND_STARTED') and a.lease_until<=v_now then
  update public.notification_push_attempts set transport_state=case when a.transport_state='SEND_STARTED' then 'UNKNOWN' else 'FINAL' end,
   outcome='FATAL',error_code=case when a.transport_state='SEND_STARTED' then 'SEND_OUTCOME_UNKNOWN' else 'ADMISSION_LEASE_EXPIRED' end,
   lease_id=null,lease_until=null,next_attempt_at=null where id=a.id;
  return jsonb_build_object('kind','NONE');
 end if;
 if a.transport_state not in ('TICKET_PENDING','RECEIPT_LEASED') then return jsonb_build_object('kind','NONE'); end if;
 if (a.single_target_admission->>'receiptDeadline')::timestamptz<=v_now or a.ticket_received_at<=v_now-interval '24 hours' then
  update public.notification_push_attempts set transport_state='UNKNOWN',outcome='FATAL',error_code='RECEIPT_UNAVAILABLE',lease_id=null,lease_until=null,next_attempt_at=null where id=a.id;
  return jsonb_build_object('kind','NONE');
 end if;
 if a.transport_state='RECEIPT_LEASED' and a.lease_until>v_now then return jsonb_build_object('kind','NONE'); end if;
 if a.send_count<>1 or a.provider_ticket_id is null or (a.transport_state='TICKET_PENDING' and a.next_attempt_at>v_now)
 then return jsonb_build_object('kind','NONE'); end if;
 update public.notification_push_attempts set transport_state='RECEIPT_LEASED',lease_id=extensions.gen_random_uuid(),
  lease_until=least(v_now+interval '90 seconds',(single_target_admission->>'receiptDeadline')::timestamptz),last_claimed_at=v_now
  where id=a.id returning * into a;
 return jsonb_build_object('kind','RECEIPT','attemptId',a.id,'leaseId',a.lease_id,'leaseExpiresAt',a.lease_until,'ticketId',a.provider_ticket_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_push_transport(p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare d public.notification_deliveries%rowtype; a public.notification_push_attempts%rowtype; v_now timestamptz:=clock_timestamp(); why text; dev record; num integer;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_kind is null or p_kind not in ('SEND','RECEIPT') then raise exception 'INVALID_PUSH_ACTION' using errcode='22023'; end if;
 -- Cross-isolate dispatch throttle and SKIP LOCKED delivery ownership. No
 -- in-memory limit is mistaken for a project-wide limiter.
 if not pg_try_advisory_xact_lock(hashtextextended('uskoci:push-claim',0)) then return jsonb_build_object('kind','NONE'); end if;
 if (select count(*) from public.notification_push_attempts where lease_until>v_now)>=6 then return jsonb_build_object('kind','NONE'); end if;
 if (select count(*) from public.notification_push_attempts where last_claimed_at>v_now-interval '1 second')>=60 then return jsonb_build_object('kind','NONE'); end if;
 for d in select * from public.notification_deliveries x where x.channel='PUSH' and not exists(select 1 from public.notification_push_attempts admitted where admitted.delivery_id=x.id and admitted.single_target_admission is not null) and
  ((p_kind='SEND' and x.push_started_at is null and x.state in ('CREATED','QUEUED','FAILED_RETRYABLE') and not exists(select 1 from public.notification_push_attempts z where z.delivery_id=x.id))
   or exists(select 1 from public.notification_push_attempts z where z.delivery_id=x.id and
    ((p_kind='SEND' and z.transport_state in ('PENDING','RETRYABLE','SEND_LEASED','SEND_STARTED')) or (p_kind='RECEIPT' and z.transport_state in ('TICKET_PENDING','RECEIPT_LEASED')))
    and (z.next_attempt_at<=v_now or z.lease_until<=v_now)))
  order by case x.priority when 'HIGH' then 0 else 1 end,x.created_at,x.id limit 64 for update skip locked loop
  if d.push_started_at is null and p_kind='SEND' then
   why:=private.push_suppression(d);
   if why is not null then update public.notification_deliveries set state='SUPPRESSED',suppression_reason=why,push_started_at=v_now where id=d.id; continue; end if;
   -- Historical attempts are not reinterpreted or resent by the new transport.
   if exists(select 1 from public.notification_push_attempts where delivery_id=d.id) then continue; end if;
   num:=0;
   for dev in select * from public.notification_push_devices x where x.user_id=d.recipient_user_id and x.active and x.bound_revision=x.revision and private.push_session_valid(x.user_id,x.bound_session_id) and x.platform in ('IOS','ANDROID') order by x.id loop
    num:=num+1;
    insert into public.notification_push_attempts(delivery_id,device_id,attempt_no,outcome,transport_state,device_revision,next_attempt_at)
    values(d.id,dev.id,num,'QUEUED','PENDING',dev.revision,v_now);
   end loop;
   update public.notification_deliveries set push_started_at=v_now,queued_at=v_now,state=case when num=0 then 'SUPPRESSED' else 'QUEUED' end,suppression_reason=case when num=0 then 'NO_ACTIVE_DEVICE' else null end where id=d.id;
  end if;
  -- Losing a worker after begin may have produced a real push. Never resend it.
  update public.notification_push_attempts set transport_state='UNKNOWN',outcome='FATAL',error_code='SEND_OUTCOME_UNKNOWN',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='SEND_STARTED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='PENDING',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='SEND_LEASED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='TICKET_PENDING',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='RECEIPT_LEASED' and lease_until<=v_now;
  update public.notification_push_attempts set transport_state='UNKNOWN',outcome='FATAL',error_code='RECEIPT_UNAVAILABLE',lease_id=null,lease_until=null where delivery_id=d.id and transport_state='TICKET_PENDING' and ticket_received_at<=v_now-interval '24 hours';
  select * into a from public.notification_push_attempts where delivery_id=d.id and next_attempt_at<=v_now and
   ((p_kind='SEND' and transport_state in ('PENDING','RETRYABLE') and send_count<3) or (p_kind='RECEIPT' and transport_state='TICKET_PENDING')) order by attempt_no limit 1 for update;
  if not found then continue; end if;
  if p_kind='SEND' then
   why:=private.push_suppression(d);
   if why is not null then update public.notification_push_attempts set transport_state='SUPPRESSED',outcome='FATAL',error_code=why where id=a.id; continue; end if;
   select * into dev from public.notification_push_devices x where x.id=a.device_id and x.user_id=d.recipient_user_id and x.active and x.revision=a.device_revision and x.bound_revision=x.revision and private.push_session_valid(x.user_id,x.bound_session_id);
   if not found then update public.notification_push_attempts set transport_state='SUPPRESSED',outcome='FATAL',error_code='DEVICE_CHANGED' where id=a.id; continue; end if;
  end if;
  update public.notification_push_attempts set transport_state=case when p_kind='SEND' then 'SEND_LEASED' else 'RECEIPT_LEASED' end,lease_id=extensions.gen_random_uuid(),lease_until=v_now+interval '90 seconds',next_attempt_at=v_now,last_claimed_at=v_now where id=a.id returning * into a;
  return jsonb_build_object('kind',p_kind,'attemptId',a.id,'leaseId',a.lease_id,'leaseExpiresAt',a.lease_until,'ticketId',a.provider_ticket_id);
 end loop;
 return jsonb_build_object('kind','NONE');
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_qa_classification_service(p_account_id uuid, p_type text, p_need_id uuid, p_need_revision integer, p_question_id uuid, p_text text, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.qa_ai_commands;src jsonb;h text;input_hash text;subject text;checked jsonb;
begin
 if p_account_id is null or p_need_id is null or p_client_request_id is null or p_need_revision is null or p_need_revision<1
 or p_type not in('ASK','ANSWER') or p_type is null or (p_type='ASK')<>(p_question_id is null) then raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 h:=encode(extensions.digest(convert_to(btrim(coalesce(p_text,'')),'UTF8'),'sha256'),'hex');input_hash:=private.qa_ai_input_hash(p_type,p_need_id,p_need_revision,p_question_id,h);
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||p_account_id::text||':'||p_client_request_id::text,0));
 select * into c from private.qa_ai_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if found then
  if c.request_hash<>input_hash then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';end if;
  return jsonb_build_object('status',private.qa_ai_status(p_account_id,p_need_id,p_client_request_id),'claim',null);
 end if;
 perform private.qa_ai_assert_actor(p_account_id,p_need_id,p_need_revision,p_question_id,p_type);
 subject:=case when p_type='ASK' then 'QUESTION' else 'ANSWER' end;
 checked:=public.rpc_check_preselection_qa_limits_service(p_account_id,subject,p_need_id,p_need_revision,p_question_id,p_text);
 src:=private.qa_ai_source(p_need_id,p_need_revision,p_question_id);
 if src is null then raise exception 'PRESELECTION_QA_POLICY_NOT_READY' using errcode='55000';end if;
 insert into private.qa_ai_commands(account_id,client_request_id,command_type,need_id,need_revision,question_id,text_sha256,request_hash,content_fingerprint,
  source_hash,policy_bundle_id,policy_hash,state,attempt_id,lease_expires_at)
 values(p_account_id,p_client_request_id,p_type,p_need_id,p_need_revision,p_question_id,h,input_hash,
  private.ru4b_content_fingerprint(subject,p_need_id,p_need_revision,p_question_id,p_text),src->>'sourceHash',(src->>'policyBundleId')::uuid,src->>'policyHash','PROCESSING',gen_random_uuid(),clock_timestamp()+interval '60 seconds') returning * into c;
 return jsonb_build_object('status',private.qa_ai_status(p_account_id,p_need_id,p_client_request_id),'claim',jsonb_build_object('attemptId',c.attempt_id,'leaseExpiresAt',c.lease_expires_at,
  'context',jsonb_build_object('schemaVersion','PRESELECTION_QA_CLASSIFIER_V1','type',p_type,'sourceHash',c.source_hash,'policyHash',c.policy_hash,
   'policy',src->'policy','taskSafetyPolicy',src->'taskSafetyPolicy','publicTask',src->'publicTask','question',src->'question')));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_retention_job(p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'TRUSTED_SERVER_REQUIRED' using errcode='42501';end if;
 return private.claim_retention_job(p_account_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_claim_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; t private.worker_ai_turns; hash text; message_id uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 if p_client_request_id is null or p_text is null or length(btrim(p_text)) not between 1 and 4000
 then raise exception 'WORKER_AI_INPUT_INVALID' using errcode='22023'; end if;
 hash:=encode(extensions.digest(p_text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||p_account_id::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=p_account_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 select * into t from private.worker_ai_turns where account_id=p_account_id and client_request_id=p_client_request_id;
 if found then
  if t.conversation_id<>p_conversation_id then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
  if t.cancelled_at is not null then return jsonb_build_object('acquired',false,'turn',private.worker_ai_turn_document(t.turn_id));end if;
  if t.body_hash<>hash then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
  return jsonb_build_object('acquired',false,'turn',private.worker_ai_turn_document(t.turn_id));
 end if;
 perform public.rpc_read_worker_ai_context_service(p_account_id,p_conversation_id);
 perform 1 from public.ai_conversations where id=p_conversation_id for update;
 if exists(select 1 from private.worker_ai_turns where conversation_id=p_conversation_id and state='PROCESSING')
 then raise exception 'WORKER_AI_TURN_PENDING' using errcode='55000'; end if;
 if (select count(*) from private.worker_ai_turns where account_id=p_account_id and created_at>clock_timestamp()-interval '1 minute')>=6
 then raise exception 'WORKER_AI_RATE_LIMITED' using errcode='55000'; end if;
 insert into private.worker_ai_turns(account_id,conversation_id,client_request_id,body_hash,source_revision,state,lease_expires_at)
 values(p_account_id,p_conversation_id,p_client_request_id,hash,s.revision,'PROCESSING',clock_timestamp()+interval '60 seconds') returning * into t;
 insert into public.ai_messages(account_id,conversation_id,role,body) values(p_account_id,p_conversation_id,'USER',p_text) returning id into message_id;
 update private.worker_ai_turns set user_message_id=message_id where turn_id=t.turn_id;
 return jsonb_build_object('acquired',true,'turn',private.worker_ai_turn_document(t.turn_id));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_clear_profile_avatar(p_profile_id uuid, p_expected_avatar_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 perform private.closure_assert_open(auth.uid());
 select * into p from public.app_profiles where id=p_profile_id and account_id=auth.uid() and profile_status in('DRAFT','ACTIVE') for update;
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 if p.avatar_path is not null then
  if p.avatar_path is distinct from p_expected_avatar_path then raise exception 'MEDIA_VERSION_CONFLICT' using errcode='PT409'; end if;
  update public.app_profiles set avatar_path=null where id=p.id;
 end if;
 return public.rpc_read_profile_avatar(p.id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_close_remaining_search(p_need_id uuid, p_expected_revision integer, p_client_request_id text, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_request_id text := btrim(coalesce(p_client_request_id,''));
  v_reason text := left(btrim(coalesce(p_reason,'')),500);
  v_request_hash text;
  v_existing private.remaining_search_close_commands%rowtype;
  v_need public.needs%rowtype;
  v_selected_slots integer := 0;
  v_remaining integer := 0;
  v_affected integer := 0;
  v_result jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'NEED_ID_REVISION_REQUIRED' using errcode='22023';
  end if;
  if char_length(v_request_id) not between 8 and 200 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(jsonb_build_object(
        'needId',p_need_id,
        'expectedRevision',p_expected_revision,
        'reason',v_reason
      )::text,'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || E'\n' || v_request_id, 4410));

  select * into v_existing
    from private.remaining_search_close_commands c
   where c.requester_account_id = v_actor
     and c.client_request_id = v_request_id
   for update;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';
    end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;

  select * into v_need
    from public.needs n
   where n.id = p_need_id
   for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id <> v_actor then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.revision <> p_expected_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;

  if v_need.remaining_search_closed_at is not null then
    return jsonb_build_object(
      'needId',v_need.id,
      'revision',v_need.revision,
      'requiredSlots',v_need.required_slots,
      'remainingSearchClosed',true,
      'closedAt',v_need.remaining_search_closed_at,
      'idempotentReplay',true,
      'authoritative',true
    );
  end if;

  if not exists (select 1 from public.agreements a where a.need_id = v_need.id) then
    raise exception 'REMAINING_SEARCH_CLOSE_REQUIRES_DOGOVOR' using errcode='P0001';
  end if;

  if v_need.status not in ('PUBLISHED','SELECTION','ACTIVE') then
    raise exception 'NEED_REMAINING_SEARCH_NOT_OPEN' using errcode='P0001';
  end if;

  select coalesce(sum(s.covered_slots),0)::integer
    into v_selected_slots
    from public.need_selections s
   where s.need_id = v_need.id
     and s.status = 'SELECTED';

  v_remaining := greatest(v_need.required_slots - v_selected_slots,0);
  if v_selected_slots < 1 then
    raise exception 'REMAINING_SEARCH_CLOSE_REQUIRES_SELECTED_CAPACITY' using errcode='P0001';
  end if;
  if v_remaining < 1 then
    raise exception 'NO_REMAINING_SEARCH' using errcode='P0001';
  end if;

  perform set_config('uskoci.need_lifecycle','CLOSE_REMAINING_SEARCH',true);
  update public.needs
     set remaining_search_closed_at = statement_timestamp(),
         remaining_search_closed_by_account_id = v_actor,
         remaining_search_close_reason = nullif(v_reason,''),
         updated_at = statement_timestamp()
   where id = v_need.id;
  perform set_config('uskoci.need_lifecycle','',true);

  update public.dispatch_rounds
     set status = 'STOPPED', stop_reason = 'REMAINING_SEARCH_CLOSED'
   where need_id = v_need.id
     and status in ('PLANNED','SENT');

  update public.opportunity_deliveries
     set status = 'EXPIRED'
   where need_id = v_need.id
     and status in ('READY','SEEN');

  delete from private.dispatch_schedule where need_id = v_need.id;

  -- PKG-029a (deep read 12.9): every applicant whose application closes here is told, as rpc_cancel_need does.
  with closed as (
    update public.marketplace_responses
       set status = 'EXPIRED'
     where need_id = v_need.id
       and status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE','STALE_REVIEW_REQUIRED')
     returning worker_account_id
  )
  select count(*)::integer into v_affected
    from closed c
    cross join lateral (select private.emit_event(c.worker_account_id, 'WORKER', 'NEED_CANCELLED', 'NEED', v_need.id,
      v_need.revision, 'Potraga je zatvorena',
      'Onaj ko je objavio zadatak zatvorio je potragu. Tvoja prijava više nije aktivna.',
      'search-closed:' || v_need.id::text || ':' || v_need.revision::text || ':worker:' || c.worker_account_id::text,
      'NORMAL', jsonb_build_object('reason', 'REMAINING_SEARCH_CLOSED'), null)) e;

  perform private.audit_marketplace(
    v_actor,
    'REMAINING_SEARCH_CLOSED',
    'NEED',
    v_need.id,
    v_need.revision,
    jsonb_build_object(
      'requiredSlots',v_need.required_slots,
      'selectedSlots',v_selected_slots,
      'closedRemainingSlots',v_remaining,
      'affectedResponses',v_affected,
      'reasonProvided',v_reason<>''
    )
  );

  select * into v_need from public.needs where id = v_need.id;

  v_result := jsonb_build_object(
    'needId',v_need.id,
    'revision',v_need.revision,
    'status',v_need.status,
    'requiredSlots',v_need.required_slots,
    'selectedSlots',v_selected_slots,
    'closedRemainingSlots',v_remaining,
    'affectedResponses',v_affected,
    'remainingSearchClosed',true,
    'closedAt',v_need.remaining_search_closed_at,
    'idempotentReplay',false,
    'authoritative',true
  );

  insert into private.remaining_search_close_commands(
    requester_account_id,client_request_id,request_hash,need_id,need_revision,result
  ) values (
    v_actor,v_request_id,v_request_hash,v_need.id,v_need.revision,v_result
  );

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_closure_api_guard()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid();path text:=coalesce(current_setting('request.path',true),'');begin
 if auth.role()='authenticated' and private.closure_account_restricted(u) then
  if path in('/rpc/rpc_read_account_closure_execution','/rpc/rpc_start_account_closure_execution') then return;end if;
  if path in('/rpc/rpc_support_capabilities_v5','/rpc/rpc_support_inbox_v5','/rpc/rpc_support_detail_v5',
   '/rpc/rpc_support_find_context_v5','/rpc/rpc_support_mark_read_v5','/rpc/rpc_support_read_command_v5',
   '/rpc/rpc_support_cancel_command_v5','/rpc/rpc_support_submit_v5') then
   perform private.support_auth_v5(u);return;
  end if;
  raise exception 'ACCOUNT_CLOSING' using errcode='42501';
 end if;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_account_closure_action_service(p_account_id uuid, p_generation uuid, p_action_id uuid, p_attempt_id uuid, p_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e private.closure_executions_v5;a private.closure_actions_v5;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform pg_advisory_xact_lock(private.closure_account_key(p_account_id));
 select * into e from private.closure_executions_v5 where account_id=p_account_id and generation=p_generation;
 select * into a from private.closure_actions_v5 where id=p_action_id and generation=p_generation and account_id=p_account_id;
 if e.account_id is null or a.id is null or p_attempt_id is null or a.attempt_id is distinct from p_attempt_id or a.state='PENDING' then raise exception 'CLOSURE_ATTEMPT_STALE' using errcode='PT409';end if;
 if a.kind='RELATIONAL_REDACT' then raise exception 'CLOSURE_EVIDENCE_INVALID' using errcode='22023';end if;
 if p_evidence is distinct from (case a.kind when 'STORAGE_DELETE' then 'STORAGE_OBJECT_ABSENT' else 'AUTH_IDENTITY_ERASED_SUBJECT_RETAINED' end) then raise exception 'CLOSURE_EVIDENCE_INVALID' using errcode='22023';end if;
 if a.kind='STORAGE_DELETE' and exists(select 1 from storage.objects where bucket_id=a.bucket and name=a.object_path) then raise exception 'CLOSURE_STORAGE_NOT_CLEAN' using errcode='55000';end if;
 if a.kind='AUTH_IDENTITY_ERASE' and (not exists(select 1 from auth.users where id=p_account_id and deleted_at is not null and coalesce(encrypted_password,'')='' and coalesce(raw_user_meta_data,'{}')='{}' and coalesce(raw_app_meta_data,'{}')='{}') or exists(select 1 from auth.sessions where user_id=p_account_id)) then raise exception 'CLOSURE_AUTH_NOT_CLOSED' using errcode='55000';end if;
 if a.state<>'VERIFIED' then update private.closure_actions_v5 set state='VERIFIED',verified_at=clock_timestamp(),evidence=p_evidence where id=a.id returning * into a;end if;
 return private.closure_action_document_v5(a,e)||jsonb_build_object('evidence',a.evidence);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_ai_task_review_evaluation_service(p_account_id uuid, p_review_id uuid, p_attempt_id uuid, p_outcome text, p_rule_ids text[], p_safe_reason_codes text[], p_provider_ref text, p_model_ref text, p_not_ready_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r private.ai_task_reviews; c private.ai_task_review_commands; decision jsonb; result_hash text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 lock table private.publication_policy_bundles,private.publication_policy_rule_refs,private.location_market_configs in share mode;
 select * into r from private.ai_task_reviews where id=p_review_id and account_id=p_account_id;
 if not found then raise exception 'TASK_REVIEW_NOT_FOUND' using errcode='42501'; end if;
 select * into c from private.ai_task_review_commands where review_id=r.id and account_id=p_account_id for update;
 if not found or c.attempt_id is distinct from p_attempt_id then raise exception 'TASK_REVIEW_ATTEMPT_STALE' using errcode='PT409'; end if;
 result_hash:=encode(extensions.digest(jsonb_build_object('outcome',p_outcome,'rules',p_rule_ids,'reasons',p_safe_reason_codes,
  'provider',p_provider_ref,'model',p_model_ref,'notReady',p_not_ready_code)::text,'sha256'),'hex');
 if c.state in('EVALUATED','PUBLISHED') then
  if c.evaluation_result_hash is distinct from result_hash then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023'; end if;
  return c.evaluation;
 end if;
 if c.state<>'EVALUATING' or c.lease_expires_at<=clock_timestamp() then raise exception 'TASK_REVIEW_ATTEMPT_STALE' using errcode='PT409'; end if;
 if r.policy_binding is distinct from private.ai_task_review_policy(r.envelope#>>'{location,taskCountryCode}')
 then raise exception 'TASK_REVIEW_POLICY_STALE' using errcode='PT409'; end if;
 if p_not_ready_code is not null then
  if p_not_ready_code not in('EVALUATOR_UNAVAILABLE','EVALUATOR_INVALID_RESPONSE','RATE_LIMITED')
   or p_outcome is not null then raise exception 'TASK_REVIEW_INPUT_INVALID' using errcode='22023'; end if;
  decision:=jsonb_build_object('kind','NOT_READY','needId',c.need_id,'needRevision',c.need_revision,'authoritativeDecision',false,'code',p_not_ready_code);
 else
  decision:=jsonb_build_object('kind','DECISION','decision',public.rpc_record_need_publication_decision_service(c.need_id,c.need_revision,
   c.evaluation_binding->>'policyId',c.evaluation_binding->>'jurisdiction',p_outcome,p_rule_ids,'PUBLICATION_EVALUATOR_V1',p_safe_reason_codes,
   p_provider_ref,p_model_ref,'{}'::jsonb,jsonb_build_object('evaluationContext',c.evaluation_binding)));
 end if;
 update private.ai_task_review_commands set state='EVALUATED',evaluation=decision,evaluation_result_hash=result_hash where review_id=r.id;
 return decision;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_data_export(p_receipt_id uuid, p_attempt_id uuid, p_byte_length bigint, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; b jsonb; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 r:=private.data_export_lock(p_receipt_id,null);v_now:=clock_timestamp();
 select * into a from private.data_export_artifacts where id=p_attempt_id and receipt_id=r.id for update;
 if not found or r.active_export_attempt_id is distinct from a.id or r.export_revoked_at is not null or a.deleted_at is not null or a.artifact_expires_at<=v_now then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 if p_byte_length is distinct from a.byte_length or p_sha256 is distinct from a.sha256 then raise exception 'EXPORT_ARTIFACT_MISMATCH' using errcode='22023'; end if;
 b:=private.data_export_policy_binding();if b is null or b->>'sha256'<>a.policy_sha256 then raise exception 'EXPORT_POLICY_CHANGED' using errcode='PT409'; end if;
 if r.status='READY' and a.verified_at is not null then return jsonb_build_object('receiptId',r.id,'status','READY','artifactGeneration',a.id,'idempotentReplay',true); end if;
 if r.status<>'PROCESSING' or a.lease_until<=v_now then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 update private.data_export_artifacts set verified_at=v_now where id=a.id;
 update public.data_export_requests set status='READY',completed_at=v_now,failure_code=null,updated_at=v_now where id=r.id;
 perform private.audit_marketplace(r.account_id,'DATA_EXPORT_READY','SYSTEM',r.id,null,jsonb_build_object('attempt',a.attempt_number,'byteLength',a.byte_length));
 return jsonb_build_object('receiptId',r.id,'status','READY','artifactGeneration',a.id,'idempotentReplay',false);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_data_export_cleanup(p_receipt_id uuid, p_artifact_generation uuid, p_cleanup_attempt_id uuid, p_deleted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_deleted is null then raise exception 'EXPORT_CLEANUP_RESULT_INVALID' using errcode='22023'; end if;
 r:=private.data_export_lock(p_receipt_id,null);v_now:=clock_timestamp();
 select * into a from private.data_export_artifacts where id=p_artifact_generation and receipt_id=r.id for update;
 if not found or a.cleanup_attempt_id is distinct from p_cleanup_attempt_id or p_cleanup_attempt_id is null then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 if a.cleanup_lease_until is null and a.cleanup_deleted is not distinct from p_deleted then return jsonb_build_object('receiptId',r.id,'artifactGeneration',a.id,'deleted',p_deleted); end if;
 if a.cleanup_lease_until is null or a.cleanup_lease_until<=v_now then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 -- Sixty seconds is technical reconciliation cadence, not approved metadata retention.
 -- Keep each exact retired path eligible after an absence observation for late commits.
 update private.data_export_artifacts set deleted_at=case when p_deleted then v_now else deleted_at end,cleanup_lease_until=null,cleanup_deleted=p_deleted,
 cleanup_next_at=v_now+interval '60 seconds',
 snapshot_text=case when snapshot_expires_at<=v_now then null else snapshot_text end where id=a.id;
 perform private.audit_marketplace(r.account_id,case when p_deleted then 'DATA_EXPORT_ARTIFACT_DELETED' else 'DATA_EXPORT_CLEANUP_RETRY' end,'SYSTEM',r.id,null,'{}'::jsonb);
 return jsonb_build_object('receiptId',r.id,'artifactGeneration',a.id,'deleted',p_deleted);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_media_upload_service(p_account_id uuid, p_asset_id uuid, p_storage_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets; c public.ai_conversations; refs text[];
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=p_account_id;
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 -- Match conversation -> asset ordering with removal and final review.
 if a.scope='TASK' then select * into c from public.ai_conversations where id=a.conversation_id and account_id=p_account_id for update;
 else perform 1 from public.app_profiles where id=a.profile_id and account_id=p_account_id for update; end if;
 select * into a from private.owned_media_assets where id=p_asset_id for update;
 if a.state not in('STAGED','READY') or a.sanitized_sha256 is distinct from p_storage_sha256 or a.dispatch_state<>'SETTLED' or a.dispatch_outcome<>'STORED'
 then raise exception 'MEDIA_STORAGE_UNCONFIRMED' using errcode='PT409'; end if;
 if a.state='READY' then return private.media_asset_document(a); end if;
 update private.owned_media_assets set state='READY',selected=case when scope='TASK' and (c.id is null or c.status<>'OPEN') then false else selected end where id=a.id returning * into a;
 if a.scope='TASK' and a.selected then
  refs:=private.media_task_refs(c.id);
  if not(a.storage_path=any(refs)) then refs:=array_append(refs,a.storage_path); end if;
  perform private.media_write_task_refs(c,refs);
 end if;
 return private.media_asset_document(a);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_push_transport(p_attempt_id uuid, p_lease_id uuid, p_result text, p_ticket_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a public.notification_push_attempts%rowtype; d public.notification_deliveries%rowtype; token text; receipt boolean; v_now timestamptz:=clock_timestamp(); next_state text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_result is null or p_result not in ('TICKET','PROVIDER_ACCEPTED','DEVICE_NOT_REGISTERED','RETRYABLE','RECEIPT_RATE_EXCEEDED','FATAL','UNKNOWN','RECEIPT_PENDING') or
  (p_result='TICKET' and (p_ticket_id is null or p_ticket_id!~'^[A-Za-z0-9_-]{1,200}$')) or (p_result<>'TICKET' and p_ticket_id is not null) then raise exception 'INVALID_PUSH_RESULT' using errcode='22023'; end if;
 select x.expo_push_token into token from public.notification_push_devices x join public.notification_push_attempts y on y.device_id=x.id where y.id=p_attempt_id;
 if token is not null then perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||token,0)); end if;
 select x.* into d from public.notification_deliveries x join public.notification_push_attempts y on y.delivery_id=x.id where y.id=p_attempt_id for update of x;
 select * into a from public.notification_push_attempts where id=p_attempt_id for update;
 if not found or a.lease_id is distinct from p_lease_id or a.lease_until<=clock_timestamp() or a.transport_state not in ('SEND_STARTED','RECEIPT_LEASED') then raise exception 'PUSH_LEASE_STALE' using errcode='PT409'; end if;
 receipt:=a.transport_state='RECEIPT_LEASED';
 if (receipt and (p_result='TICKET' or a.provider_ticket_id is null)) or (not receipt and p_result in ('PROVIDER_ACCEPTED','RECEIPT_PENDING','RECEIPT_RATE_EXCEEDED'))
 or (p_result='TICKET' and p_ticket_id=any(a.rejected_ticket_ids)) then raise exception 'INVALID_PUSH_RESULT' using errcode='22023'; end if;
 -- A documented receipt MessageRateExceeded is a known rejection of this
 -- message, unlike HTTP429 while merely looking up a receipt. Only the former
 -- permits a new send, with current-device/consent revalidation and max3 sends.
 next_state:=case p_result when 'TICKET' then 'TICKET_PENDING' when 'PROVIDER_ACCEPTED' then 'PROVIDER_ACCEPTED' when 'DEVICE_NOT_REGISTERED' then 'FINAL' when 'UNKNOWN' then 'UNKNOWN' when 'RECEIPT_PENDING' then 'TICKET_PENDING' when 'RECEIPT_RATE_EXCEEDED' then case when a.send_count<3 then 'RETRYABLE' else 'FINAL' end when 'RETRYABLE' then case when receipt then 'TICKET_PENDING' when a.send_count<3 then 'RETRYABLE' else 'FINAL' end else 'FINAL' end;
 -- A one-shot admission never regains send permission, including known provider throttles.
 if a.single_target_admission is not null and next_state='RETRYABLE' then next_state:='FINAL'; end if;
 update public.notification_push_attempts set transport_state=next_state,
  outcome=case when next_state='PROVIDER_ACCEPTED' then 'OK' when next_state='RETRYABLE' then 'RETRYABLE' when next_state in ('TICKET_PENDING') then 'QUEUED' else 'FATAL' end,
  error_code=case when p_result in ('TICKET','PROVIDER_ACCEPTED') then null else p_result end,
  rejected_ticket_ids=case when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then array_append(rejected_ticket_ids,provider_ticket_id) else rejected_ticket_ids end,
  provider_ticket_id=case when p_result='TICKET' then p_ticket_id when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then null else provider_ticket_id end,
  ticket_received_at=case when p_result='TICKET' then v_now when p_result='RECEIPT_RATE_EXCEEDED' and next_state='RETRYABLE' then null else ticket_received_at end,
  receipt_checked_at=case when receipt then v_now else receipt_checked_at end,
  next_attempt_at=case when next_state='TICKET_PENDING' then v_now+interval '15 minutes' when next_state='RETRYABLE' then v_now+make_interval(secs=>power(2,a.send_count)::integer*30) else null end,
  lease_id=null,lease_until=null where id=a.id;
 if p_result='DEVICE_NOT_REGISTERED' then
  -- Token rebind / revoke / re-registration changes revision. An old provider
  -- result must never disable a different user's or a newer registration.
  update public.notification_push_devices set active=false,revision=revision+1,bound_session_id=null,bound_revision=null
  where id=a.device_id and user_id=d.recipient_user_id and revision=a.device_revision and active;
 end if;
 if p_result='TICKET' and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE') then update public.notification_deliveries set state='SENT',sent_at=coalesce(sent_at,v_now) where id=d.id; end if;
 -- DELIVERED and delivered_at are deliberately never written by this adapter.
 return jsonb_build_object('attemptId',a.id,'state',next_state);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_qa_classification_service(p_account_id uuid, p_need_id uuid, p_client_request_id uuid, p_attempt_id uuid, p_output jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.qa_ai_commands;src jsonb;doc jsonb;rule jsonb;item jsonb;rules text[];reasons text[];outcome_value text;materiality_value text;
 policy_id uuid;materiality_id uuid;output_digest text;source_provenance jsonb;
begin
 if p_account_id is null or p_need_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_assert_open(p_account_id);perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||p_account_id::text||':'||p_client_request_id::text,0));
 select * into c from private.qa_ai_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or c.need_id<>p_need_id or c.attempt_id is distinct from p_attempt_id then raise exception 'QA_CLASSIFICATION_NOT_FOUND' using errcode='42501';end if;
 if jsonb_typeof(p_output) is distinct from 'object' or p_output-ARRAY['outcome','materiality','ruleIds','safeReasonCodes']<>'{}'::jsonb
 or not(p_output ?& ARRAY['outcome','materiality','ruleIds','safeReasonCodes']) then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 output_digest:=encode(extensions.digest(convert_to(p_output::text,'UTF8'),'sha256'),'hex');
 if c.state<>'PROCESSING' then
  if c.output_hash is not null and c.output_hash<>output_digest then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';end if;
  return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);end if;
 if not c.provider_dispatched then raise exception 'QA_CLASSIFICATION_NOT_DISPATCHED' using errcode='42501';end if;
 perform private.qa_ai_assert_actor(c.account_id,c.need_id,c.need_revision,c.question_id,c.command_type);
 src:=private.qa_ai_source(c.need_id,c.need_revision,c.question_id);
 if c.lease_expires_at<=clock_timestamp() or src->>'sourceHash' is distinct from c.source_hash then
  update private.qa_ai_commands set state='STALE',output_hash=output_digest,updated_at=clock_timestamp() where id=c.id;
  return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);end if;
 doc:=src->'policy';outcome_value:=p_output->>'outcome';materiality_value:=p_output->>'materiality';
 if outcome_value is null or outcome_value not in('ALLOW','CLARIFY','REVIEW','BLOCK')
 or(c.command_type='ASK' and p_output->'materiality'<>'null'::jsonb)
 or(c.command_type='ANSWER' and(materiality_value is null and outcome_value<>'REVIEW' or materiality_value is not null and materiality_value not in('NON_MATERIAL','MATERIAL')))
 or jsonb_typeof(p_output->'ruleIds') is distinct from 'array' or jsonb_array_length(p_output->'ruleIds') not between 1 and 64
 or jsonb_typeof(p_output->'safeReasonCodes') is distinct from 'array' or jsonb_array_length(p_output->'safeReasonCodes')>64
 then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 select array_agg(value order by value) into rules from jsonb_array_elements_text(p_output->'ruleIds');
 select coalesce(array_agg(value order by value),'{}'::text[]) into reasons from jsonb_array_elements_text(p_output->'safeReasonCodes');
 if cardinality(rules)<>(select count(distinct x) from unnest(rules)x) or cardinality(reasons)<>(select count(distinct x) from unnest(reasons)x)
 then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_output->'ruleIds') loop
  if jsonb_typeof(item)<>'string' then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
  select value into rule from jsonb_array_elements(doc->'rules') where value->>'ruleId'=item#>>'{}';
  if rule is null or not(rule->'outcomes' ? outcome_value) then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 end loop;
 for item in select value from jsonb_array_elements(p_output->'safeReasonCodes') loop
  if jsonb_typeof(item)<>'string' or not exists(select 1 from jsonb_array_elements(doc->'rules') r where r->>'ruleId'=any(rules) and r->'safeReasonCodes' ? (item#>>'{}'))
  then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 end loop;
 if materiality_value='MATERIAL' and outcome_value='ALLOW' then raise exception 'QA_CLASSIFICATION_INVALID' using errcode='22023';end if;
 source_provenance:=jsonb_build_object('classificationId',c.id,'sourceHash',c.source_hash,'policyHash',c.policy_hash,'provider','GEMINI','model','gemini-3.8-flash');
 policy_id:=private.rpc_ru4b_record_policy_decision_service(case when c.command_type='ASK' then 'QUESTION' else 'ANSWER' end,
  c.need_id,c.need_revision,c.question_id,c.content_fingerprint,c.policy_bundle_id,outcome_value,reasons,'GEMINI_QA_V5',source_provenance);
 if c.command_type='ANSWER' and materiality_value is not null then materiality_id:=private.rpc_ru4b_record_materiality_decision_service(c.question_id,c.need_id,c.need_revision,c.content_fingerprint,materiality_value,'GEMINI_QA_V5',source_provenance);end if;
 update private.qa_ai_commands set state=case when outcome_value='ALLOW' and(c.command_type='ASK' or materiality_value='NON_MATERIAL') then 'READY' else 'REJECTED' end,
  outcome=outcome_value,materiality=materiality_value,rule_ids=rules,safe_reason_codes=reasons,policy_decision_id=policy_id,materiality_decision_id=materiality_id,output_hash=output_digest,updated_at=clock_timestamp() where id=c.id;
 return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid, p_output jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; t private.worker_ai_turns; hash text; next_candidate jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||p_account_id::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=p_account_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id and purpose='PROFILE' for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 select * into t from private.worker_ai_turns where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or t.conversation_id is distinct from p_conversation_id or t.attempt_id is distinct from p_attempt_id then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 if t.cancelled_at is not null then return private.worker_ai_turn_document(t.turn_id);end if;
 hash:=encode(extensions.digest(p_output::text,'sha256'),'hex');
 if t.state='SUCCEEDED' then
  if t.completion_hash is distinct from hash then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
  return private.worker_ai_turn_document(t.turn_id);
 end if;
 if t.state<>'PROCESSING' or not t.provider_dispatched or t.cancelled_at is not null or t.lease_expires_at<clock_timestamp() or t.source_revision<>s.revision
 then raise exception 'WORKER_AI_TURN_STALE' using errcode='PT409'; end if;
 perform public.rpc_read_worker_ai_context_service(p_account_id,p_conversation_id);
 if jsonb_typeof(p_output) is distinct from 'object' or p_output-array['assistantMessage','safety','patch']<>'{}'::jsonb
  or not(p_output?&array['assistantMessage','safety','patch'])
  or jsonb_typeof(p_output->'assistantMessage') is distinct from 'string'
  or length(btrim(p_output->>'assistantMessage')) not between 1 and 1200
  or coalesce(p_output->>'safety','') not in ('ALLOW','CLARIFY','REVIEW','BLOCK')
 then raise exception 'WORKER_AI_OUTPUT_INVALID' using errcode='22023'; end if;
 next_candidate:=private.worker_ai_patch(s.candidate,p_output->'patch',s.profile_id,s.account_id,false);
 if p_output->>'safety' in ('BLOCK','REVIEW') then next_candidate:=s.candidate; end if;
 update private.worker_ai_sessions set candidate=next_candidate,revision=revision+1,safety=p_output->>'safety' where conversation_id=p_conversation_id;
 insert into public.ai_messages(account_id,conversation_id,role,body,safety)
 values(p_account_id,p_conversation_id,'ASSISTANT',p_output->>'assistantMessage',p_output->>'safety');
 update private.worker_ai_turns set state='SUCCEEDED',completion_hash=hash where turn_id=t.turn_id;
 return private.worker_ai_turn_document(t.turn_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_complete_worker_profile(p_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_profile public.app_profiles%rowtype;
  v_previous_token text :=
    coalesce(current_setting('uskoci.profile_mutation', true), '');
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select *
    into v_profile
    from public.app_profiles
   where id = p_profile_id
   for update;

  if not found then
    raise exception 'PROFILE_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_profile.account_id <> v_uid or v_profile.kind <> 'WORKER' then
    raise exception 'NOT_WORKER_PROFILE_OWNER' using errcode = '42501';
  end if;

  if v_profile.profile_status = 'ACTIVE' then
    return;
  end if;

  if v_profile.profile_status <> 'DRAFT' then
    raise exception 'PROFILE_NOT_ACTIVATABLE'
      using errcode = 'P0001',
            detail = v_profile.profile_status;
  end if;

  if char_length(btrim(v_profile.display_name)) < 2 then
    raise exception 'DISPLAY_NAME_REQUIRED' using errcode = 'P0001';
  end if;

  if char_length(btrim(v_profile.city)) < 2 then
    raise exception 'CITY_REQUIRED' using errcode = 'P0001';
  end if;

  if cardinality(v_profile.skills) < 1 then
    raise exception 'SKILL_REQUIRED' using errcode = 'P0001';
  end if;

  perform set_config(
    'uskoci.profile_mutation',
    'COMPLETE_WORKER_PROFILE',
    true
  );

  update public.app_profiles
     set profile_status = 'ACTIVE'
   where id = p_profile_id
     and profile_status = 'DRAFT';

  if not found then
    raise exception 'PROFILE_ACTIVATION_RACE' using errcode = 'P0001';
  end if;

  perform private.requeue_open_needs_for_worker_v5(v_uid);

  perform set_config(
    'uskoci.profile_mutation',
    v_previous_token,
    true
  );
exception
  when others then
    perform set_config(
      'uskoci.profile_mutation',
      v_previous_token,
      true
    );
    raise;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_confirm_completion(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  v_completed_at timestamptz;
  need_completed boolean;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if a.need_id<>n.id then raise exception 'AGREEMENT_NEED_MISMATCH' using errcode='P0001'; end if;
  if a.requester_account_id<>uid then
    raise exception 'ONLY_REQUESTER_CAN_CONFIRM_COMPLETION' using errcode='42501';
  end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.agreement_version<>a.current_version then
    raise exception 'EXECUTION_VERSION_MISMATCH' using errcode='P0001';
  end if;

  if a.status='COMPLETED' and x.state='COMPLETED' then
    return jsonb_build_object(
      'agreementId',a.id,'state','COMPLETED',
      'completedAt',x.completed_at,
      'idempotentReplay',true,'authoritative',true
    );
  end if;

  if a.status='CANCELLED' or x.state='CANCELLED' then
    raise exception 'AGREEMENT_CANCELLED' using errcode='P0001';
  end if;

  if a.status<>'CONFIRMED'
     or x.state not in ('CONFIRMED','AWAITING_REQUESTER') then
    raise exception 'COMPLETION_NOT_CONFIRMABLE'
      using errcode='P0001',
            detail=jsonb_build_object('agreementStatus',a.status,'executionState',x.state)::text;
  end if;

  if exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then
    raise exception 'AGREEMENT_CHANGE_PENDING' using errcode='P0001';
  end if;

  v_completed_at:=statement_timestamp();

  update public.agreement_execution ex
     set state='COMPLETED',
         completed_at=coalesce(ex.completed_at,v_completed_at),
         requester_deadline_at=null,
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
  returning ex.* into x;

  update public.agreements ag
     set status='COMPLETED',updated_at=statement_timestamp()
   where ag.id=a.id;

  need_completed:=private.sync_need_completion(n.id);

  perform private.emit_event(
    a.worker_account_id,'WORKER','EXECUTION_STATE_CHANGED',
    'AGREEMENT',a.id,a.current_version,
    'Dogovor je završen',
    'Naručilac je potvrdio završetak.',
    'completed:worker:'||a.id::text||':'||a.current_version::text,
    'NORMAL',
    jsonb_build_object('completedAt',x.completed_at),
    null
  );

  return jsonb_build_object(
    'agreementId',a.id,
    'state','COMPLETED',
    'completedAt',x.completed_at,
    'needCompleted',need_completed,
    'problemWasPreviouslyReported',x.problem_opened_at is not null,
    'idempotentReplay',false,
    'authoritative',true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_confirm_need_edit(p_need_id uuid, p_expected_revision integer, p_client_request_id text, p_material jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_request_id text := btrim(coalesce(p_client_request_id, ''));
  v_request_hash text;
  v_existing private.need_edit_commands%rowtype;
  v_need public.needs%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_private jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'NEED_ID_REVISION_REQUIRED' using errcode='22023';
  end if;
  if char_length(v_request_id) not between 8 and 200 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;
  if p_material is null or jsonb_typeof(p_material) <> 'object' then
    raise exception 'MATERIAL_OBJECT_REQUIRED' using errcode='22023';
  end if;

  if (p_material - array[
    'title','description','category','requiredSlots','mode','requesterPriceRsd',
    'requiredSkills','requiredTools','requiredVehicles','requiredLicenses',
    'minimumExperienceYears','verifiedIdentityRequired','scheduleKind','startsAt','endsAt',
    'executionLocationMode','approximateLat','approximateLng','approximateCity','approximateArea',
    'publicPhotoPaths','privateLocation'
  ]) <> '{}'::jsonb then
    raise exception 'UNSUPPORTED_MATERIAL_FIELD' using errcode='22023';
  end if;

  if not (p_material ?& array[
    'title','description','category','requiredSlots','mode','requesterPriceRsd',
    'requiredSkills','requiredTools','requiredVehicles','requiredLicenses',
    'minimumExperienceYears','verifiedIdentityRequired','scheduleKind','startsAt','endsAt',
    'executionLocationMode','approximateLat','approximateLng','approximateCity','approximateArea',
    'publicPhotoPaths','privateLocation'
  ]) then
    raise exception 'FULL_MATERIAL_SNAPSHOT_REQUIRED' using errcode='22023';
  end if;

  if jsonb_typeof(p_material->'requiredSkills') <> 'array'
     or jsonb_typeof(p_material->'requiredTools') <> 'array'
     or jsonb_typeof(p_material->'requiredVehicles') <> 'array'
     or jsonb_typeof(p_material->'requiredLicenses') <> 'array'
     or jsonb_typeof(p_material->'publicPhotoPaths') <> 'array' then
    raise exception 'MATERIAL_ARRAY_FIELD_INVALID' using errcode='22023';
  end if;

  if jsonb_typeof(p_material->'privateLocation') not in ('object','null') then
    raise exception 'PRIVATE_LOCATION_INVALID' using errcode='22023';
  end if;

  if p_material->'privateLocation' ? 'resolvedLocation' then raise exception 'LOCATION_EDITOR_REQUIRED' using errcode='42501'; end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(jsonb_build_object(
        'needId', p_need_id,
        'expectedRevision', p_expected_revision,
        'material', p_material
      )::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || E'\n' || v_request_id, 4404));

  select * into v_existing
    from private.need_edit_commands c
   where c.requester_account_id = v_actor
     and c.client_request_id = v_request_id
   for update;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';
    end if;
    return v_existing.result || jsonb_build_object('idempotentReplay', true);
  end if;

  select * into v_need from public.needs n where n.id = p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id <> v_actor then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.revision <> p_expected_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then raise exception 'NEED_NOT_EDITABLE_PUBLIC_STATE' using errcode='P0001'; end if;

  if exists (select 1 from public.agreements a where a.need_id = v_need.id)
     or exists (select 1 from public.need_selections s where s.need_id = v_need.id)
     or exists (select 1 from public.marketplace_responses r where r.need_id = v_need.id and r.status = 'SELECTED') then
    raise exception 'NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR' using errcode='P0001';
  end if;

  -- PED01: this legacy writer only edits public tasks; successful replay above remains readable.
  raise exception 'PUBLISHED_TASK_EDIT_NOT_READY' using errcode='P0001';

  v_before := private.need_material_snapshot(v_need.id);
  if v_before is null then raise exception 'NEED_SNAPSHOT_FAILED' using errcode='P0001'; end if;

  v_private := p_material->'privateLocation';

  perform set_config('uskoci.need_lifecycle', 'CONFIRM_EDIT', true);
  update public.needs n
     set title = btrim(p_material->>'title'),
         description = btrim(p_material->>'description'),
         category = btrim(p_material->>'category'),
         required_slots = (p_material->>'requiredSlots')::integer,
         mode = p_material->>'mode',
         requester_price_rsd = (p_material->>'requesterPriceRsd')::integer,
         required_skills = private.jsonb_text_array(p_material->'requiredSkills'),
         required_tools = private.jsonb_text_array(p_material->'requiredTools'),
         required_vehicles = private.jsonb_text_array(p_material->'requiredVehicles'),
         required_licenses = private.jsonb_text_array(p_material->'requiredLicenses'),
         minimum_experience_years = (p_material->>'minimumExperienceYears')::integer,
         verified_identity_required = (p_material->>'verifiedIdentityRequired')::boolean,
         schedule_kind = p_material->>'scheduleKind',
         starts_at = (p_material->>'startsAt')::timestamptz,
         ends_at = (p_material->>'endsAt')::timestamptz,
         execution_location_mode = p_material->>'executionLocationMode',
         approximate_lat = (p_material->>'approximateLat')::numeric,
         approximate_lng = (p_material->>'approximateLng')::numeric,
         approximate_city = coalesce(p_material->>'approximateCity',''),
         approximate_area = coalesce(p_material->>'approximateArea',''),
         public_photo_paths = private.jsonb_text_array(p_material->'publicPhotoPaths'),
         status = 'DRAFT',
         revision = v_need.revision + 1,
         published_at = null,
         response_deadline = null,
         urgent = false,
         urgent_activated_at = null,
         urgent_expires_at = null,
         urgent_policy_version = null,
         updated_at = statement_timestamp()
   where n.id = v_need.id
     and n.revision = v_need.revision
     and n.status in ('PUBLISHED','SELECTION')
  returning n.* into v_need;
  perform set_config('uskoci.need_lifecycle', '', true);

  if not found then raise exception 'NEED_EDIT_CONFLICT' using errcode='PT409'; end if;

  insert into public.need_sensitive(need_id, exact_address, access_notes, exact_lat, exact_lng, updated_at)
  values (
    v_need.id,
    case when jsonb_typeof(v_private)='object' then coalesce(v_private->>'exactAddress','') else '' end,
    case when jsonb_typeof(v_private)='object' then coalesce(v_private->>'accessNotes','') else '' end,
    case when jsonb_typeof(v_private)='object' then (v_private->>'exactLat')::numeric else null end,
    case when jsonb_typeof(v_private)='object' then (v_private->>'exactLng')::numeric else null end,
    statement_timestamp()
  )
  on conflict (need_id) do update
    set exact_address = excluded.exact_address,
        access_notes = excluded.access_notes,
        exact_lat = excluded.exact_lat,
        exact_lng = excluded.exact_lng,
        updated_at = excluded.updated_at;

  -- Legacy scalar edit remains available, but cannot attest or retain route pins.
  if exists(select 1 from public.need_sensitive where need_id=v_need.id and resolved_location is not null) then
    update public.needs set approximate_lat=null,approximate_lng=null where id=v_need.id;
  end if;
  update public.need_sensitive set resolved_location=null,exact_lat=null,exact_lng=null where need_id=v_need.id and resolved_location is not null;
  delete from private.dispatch_schedule where need_id = v_need.id;

  v_after := private.need_material_snapshot(v_need.id);
  if v_after is not distinct from v_before then
    raise exception 'NO_MATERIAL_CHANGE' using errcode='22023';
  end if;

  insert into private.need_revision_events(
    need_id, from_revision, to_revision, from_status,
    previous_material_snapshot, new_material_snapshot, created_by_account_id
  ) values (
    v_need.id, p_expected_revision, v_need.revision,
    case when v_need.status='DRAFT' then 'PUBLISHED_OR_SELECTION' else v_need.status end,
    v_before, v_after, v_actor
  ) returning id into v_event_id;

  perform private.audit_marketplace(
    v_actor,
    'NEED_EDIT_CONFIRMED',
    'NEED',
    v_need.id,
    v_need.revision,
    jsonb_build_object('fromRevision', p_expected_revision, 'toRevision', v_need.revision, 'revisionEventId', v_event_id)
  );

  v_result := jsonb_build_object(
    'needId', v_need.id,
    'fromRevision', p_expected_revision,
    'revision', v_need.revision,
    'status', v_need.status,
    'revisionEventId', v_event_id,
    'requiresReadmission', true,
    'idempotentReplay', false,
    'authoritative', true
  );

  insert into private.need_edit_commands(
    requester_account_id, client_request_id, request_hash,
    need_id, from_revision, to_revision, revision_event_id, result
  ) values (
    v_actor, v_request_id, v_request_hash,
    v_need.id, p_expected_revision, v_need.revision, v_event_id, v_result
  );

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_confirm_need_edit_from_review(p_need_id uuid, p_expected_revision integer, p_conversation_id uuid, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_request_id text:=btrim(coalesce(p_client_request_id,''));
  v_request_hash text;
  v_existing private.need_edit_commands%rowtype;
  v_conv public.ai_conversations%rowtype;
  v_need public.needs%rowtype;
  v_old_sensitive public.need_sensitive%rowtype;
  v_facts jsonb;
  v_handoff jsonb;
  v_missing text[];
  v_key text;
  v_value jsonb;
  v_title text;
  v_description text;
  v_category text;
  v_mode text;
  v_price integer;
  v_schedule_kind text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_slots integer;
  v_skills text[];
  v_tools text[];
  v_vehicles text[];
  v_licenses text[];
  v_min_exp integer;
  v_verified boolean;
  v_photos text[];
  v_conditions text[];
  v_geo jsonb;
  v_old_geo jsonb;
  v_exec_mode text;
  v_start jsonb;
  v_service jsonb;
  v_city text;
  v_area text;
  v_exact_address text;
  v_access_notes text;
  v_country text; v_timezone text; v_region_token text;
  v_exact_lat numeric;
  v_exact_lng numeric;
  v_before jsonb;
  v_after jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_from_status text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_conversation_id is null or p_expected_revision is null or p_expected_revision<1 then
    raise exception 'EDIT_REVIEW_IDENTITY_REQUIRED' using errcode='22004';
  end if;
  if char_length(v_request_id) not between 8 and 200 then raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023'; end if;

  select * into v_conv from public.ai_conversations where id=p_conversation_id for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  if v_conv.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_conv.purpose<>'NEED_INTAKE' or v_conv.fact_schema_version<>'NEED_FACT_V2' or v_conv.status<>'OPEN' then
    raise exception 'EDIT_CONVERSATION_NOT_CONFIRMABLE' using errcode='P0001';
  end if;
  if v_conv.bound_need_id is distinct from p_need_id then raise exception 'EDIT_CONVERSATION_NEED_MISMATCH' using errcode='42501'; end if;

  select * into v_need from public.needs where id=p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id<>v_uid then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.revision<>p_expected_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;
  if v_need.status not in ('DRAFT','PUBLISHED','SELECTION') then raise exception 'NEED_NOT_EDITABLE_PUBLIC_STATE' using errcode='P0001'; end if;
  -- PED01: until staged replacement is implemented, never unpublish a live task.
  if v_need.status in ('PUBLISHED','SELECTION') then
    raise exception 'PUBLISHED_TASK_EDIT_NOT_READY' using errcode='P0001';
  end if;
  v_from_status:=v_need.status;
  perform 1 from public.need_geography where need_id=v_need.id for share;
  perform 1 from public.need_sensitive where need_id=v_need.id for share;
  perform 1 from public.need_requirement_details where need_id=v_need.id for share;
  if (v_need.status='DRAFT' and v_conv.need_edit_base_fingerprint is null) or (v_conv.need_edit_base_fingerprint is not null and v_conv.need_edit_base_fingerprint is distinct from private.need_edit_base_marker(v_need.id)) then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409';
  end if;
  if exists(select 1 from public.agreements a where a.need_id=v_need.id)
     or exists(select 1 from public.need_selections s where s.need_id=v_need.id)
     or exists(select 1 from public.marketplace_responses r where r.need_id=v_need.id and r.status='SELECTED') then
    raise exception 'NEED_EDIT_LOCKED_AFTER_FIRST_DOGOVOR' using errcode='P0001';
  end if;

  if exists(
    select 1 from public.ai_structured_facts f
     where f.conversation_id=p_conversation_id
       and f.superseded_at is null
       and f.status<>'CONFIRMED'
  ) then
    raise exception 'EDIT_FACTS_REQUIRE_HUMAN_CONFIRMATION' using errcode='P0001';
  end if;

  for v_key,v_value in
    select fact_key,fact_value from public.ai_structured_facts
     where conversation_id=p_conversation_id
       and superseded_at is null
       and fact_schema_version='NEED_FACT_V2'
       and status='CONFIRMED'
  loop
    perform private.validate_need_v2_fact(v_key,v_value);
  end loop;

  select coalesce(jsonb_object_agg(fact_key,fact_value),'{}'::jsonb)
    into v_facts
    from public.ai_structured_facts
   where conversation_id=p_conversation_id
     and superseded_at is null
     and fact_schema_version='NEED_FACT_V2'
     and status='CONFIRMED';

  select array_agg(r.fact_key order by r.fact_key)
    into v_missing
    from private.need_fact_registry r
   where r.required_for_draft and not (v_facts ? r.fact_key);
  if cardinality(coalesce(v_missing,'{}'::text[]))>0 then
    raise exception 'REQUIRED_CONFIRMED_FACTS_MISSING' using errcode='P0001',detail=array_to_string(v_missing,',');
  end if;

  v_title:=v_facts->>'need.title';
  v_description:=v_facts->>'need.description';
  v_category:=v_facts->>'need.category';
  v_mode:=v_facts->>'need.price_mode';
  if v_facts ? 'need.price_rsd' then v_price:=(v_facts->>'need.price_rsd')::integer; end if;
  if v_mode='MY_PRICE' and v_price is null then raise exception 'MY_PRICE_AMOUNT_REQUIRED' using errcode='P0001'; end if;
  if v_mode<>'MY_PRICE' then v_price:=null; end if;

  v_schedule_kind:=v_facts->>'need.schedule_kind';
  if v_facts ? 'need.starts_at' then v_starts_at:=(v_facts->>'need.starts_at')::timestamptz; end if;
  if v_facts ? 'need.ends_at' then v_ends_at:=(v_facts->>'need.ends_at')::timestamptz; end if;
  if v_schedule_kind='FIXED_WINDOW' and (v_starts_at is null or not isfinite(v_starts_at)
      or (v_ends_at is not null and (not isfinite(v_ends_at) or v_ends_at<=v_starts_at))) then
    raise exception 'FIXED_WINDOW_BOUNDS_REQUIRED' using errcode='P0001';
  end if;

  v_slots:=(v_facts->>'need.people_needed')::integer;
  select coalesce(array_agg(value),'{}'::text[]) into v_skills from jsonb_array_elements_text(coalesce(v_facts->'need.required_skills','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_tools from jsonb_array_elements_text(coalesce(v_facts->'need.required_tools','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_vehicles from jsonb_array_elements_text(coalesce(v_facts->'need.required_vehicles','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_licenses from jsonb_array_elements_text(coalesce(v_facts->'need.required_licenses','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_photos from jsonb_array_elements_text(coalesce(v_facts->'need.public_photo_paths','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_conditions from jsonb_array_elements_text(coalesce(v_facts->'need.critical_conditions','[]'::jsonb));
  if v_facts ? 'need.minimum_experience_years' then v_min_exp:=(v_facts->>'need.minimum_experience_years')::integer; end if;
  v_verified:=case when v_facts ? 'need.verified_identity_required' then (v_facts->>'need.verified_identity_required')::boolean else false end;

  v_country:=private.require_location_country(v_facts->'need.task_country_code');
  select default_timezone into v_timezone from private.location_market_configs where country_code=v_country;
  v_geo:=v_facts->'need.task_geography';
  perform private.validate_need_v2_fact('need.task_geography',v_geo);
  v_exec_mode:=v_geo->>'mode';
  v_handoff:=case when v_exec_mode='REMOTE' then v_facts->'need.handoff' else null end;
  if v_exec_mode='REMOTE' and v_handoff is null then
    raise exception 'HANDOFF_REQUIRED' using errcode='22023';
  end if;
  if v_handoff is not null then
    perform private.validate_need_v2_fact('need.handoff',v_handoff);
    v_conditions:=array_append(array_remove(v_conditions,'Predaja: '||private.taxonomy_handoff_display_v1(v_handoff)),
      'Predaja: '||private.taxonomy_handoff_display_v1(v_handoff));
  end if;
  v_start:=coalesce(v_geo->'start','null'::jsonb);
  v_service:=coalesce(v_geo->'serviceArea','null'::jsonb);
  v_city:=coalesce(nullif(btrim(v_start->>'city'),''),nullif(btrim(v_service->>'city'),''));
  v_area:=coalesce(nullif(btrim(v_start->>'area'),''),nullif(btrim(v_service->>'area'),''));
  if v_exec_mode='REMOTE' then v_city:=''; v_area:=''; end if;

  if v_facts ? 'need.exact_address' then v_exact_address:=v_facts->>'need.exact_address'; end if;
  if v_facts ? 'need.access_notes' then v_access_notes:=v_facts->>'need.access_notes'; end if;
  select * into v_old_sensitive from public.need_sensitive where need_id=v_need.id;
  select g.public_topology into v_old_geo from public.need_geography g where g.need_id=v_need.id;
  if v_old_sensitive.need_id is not null
     and coalesce(v_exact_address,'')=coalesce(v_old_sensitive.exact_address,'')
     and v_geo is not distinct from v_old_geo and v_country is not distinct from v_need.task_country_code then
    v_exact_lat:=v_old_sensitive.exact_lat;
    v_exact_lng:=v_old_sensitive.exact_lng;
  end if;

  v_before:=private.need_full_edit_snapshot(v_need.id);
  if v_before is null then raise exception 'NEED_SNAPSHOT_FAILED' using errcode='P0001'; end if;

  v_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'needId',p_need_id,'expectedRevision',p_expected_revision,'conversationId',p_conversation_id,'facts',v_facts
  )::text,'UTF8'),'sha256'),'hex');

  perform pg_advisory_xact_lock(hashtextextended(v_uid::text||E'\n'||v_request_id,4411));
  select * into v_existing from private.need_edit_commands c
   where c.requester_account_id=v_uid and c.client_request_id=v_request_id for update;
  if found then
    if v_existing.request_hash<>v_request_hash then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023'; end if;
    return v_existing.result||jsonb_build_object('idempotentReplay',true);
  end if;

  v_region_token:=current_setting('uskoci.need_region',true);
  perform set_config('uskoci.need_region','CONFIRMED_REVIEW',true);
  perform set_config('uskoci.need_lifecycle','CONFIRM_EDIT',true);
  update public.needs n
     set title=btrim(v_title),description=btrim(v_description),category=btrim(v_category),
         required_slots=v_slots,mode=v_mode,requester_price_rsd=v_price,price_basis=case when v_mode='MY_PRICE' then nullif(btrim(coalesce(v_facts->>'need.price_basis','')),'') end,
         required_skills=v_skills,required_tools=v_tools,required_vehicles=v_vehicles,required_licenses=v_licenses,
         minimum_experience_years=v_min_exp,verified_identity_required=v_verified,
         schedule_kind=v_schedule_kind,starts_at=v_starts_at,ends_at=v_ends_at,
         execution_location_mode=v_exec_mode,task_country_code=v_country,task_timezone=v_timezone,
         approximate_lat=case when v_geo is not distinct from v_old_geo and v_country is not distinct from v_need.task_country_code then v_need.approximate_lat else null end,
         approximate_lng=case when v_geo is not distinct from v_old_geo and v_country is not distinct from v_need.task_country_code then v_need.approximate_lng else null end,
         approximate_city=coalesce(v_city,''),approximate_area=coalesce(v_area,''),
         public_photo_paths=v_photos,status='DRAFT',revision=v_need.revision+1,
         published_at=null,response_deadline=null,urgent=false,urgent_activated_at=null,urgent_expires_at=null,urgent_policy_version=null,
         updated_at=statement_timestamp()
   where n.id=v_need.id and n.revision=v_need.revision and n.status in ('DRAFT','PUBLISHED','SELECTION')
   returning n.* into v_need;
  perform set_config('uskoci.need_lifecycle','',true);
  perform set_config('uskoci.need_region',coalesce(v_region_token,''),true);
  if not found then raise exception 'NEED_EDIT_CONFLICT' using errcode='PT409'; end if;

  insert into public.need_geography(need_id,public_topology,updated_at)
  values(v_need.id,v_geo,statement_timestamp())
  on conflict(need_id) do update set public_topology=excluded.public_topology,updated_at=excluded.updated_at;

  insert into public.need_requirement_details(need_id,critical_conditions,handoff,updated_at)
  values(v_need.id,v_conditions,v_handoff,statement_timestamp())
  on conflict(need_id) do update set critical_conditions=excluded.critical_conditions,handoff=excluded.handoff,updated_at=excluded.updated_at;

  insert into public.need_sensitive(need_id,exact_address,access_notes,exact_lat,exact_lng,updated_at)
  values(v_need.id,coalesce(v_exact_address,''),coalesce(v_access_notes,''),v_exact_lat,v_exact_lng,statement_timestamp())
  on conflict(need_id) do update set exact_address=excluded.exact_address,access_notes=excluded.access_notes,
    exact_lat=excluded.exact_lat,exact_lng=excluded.exact_lng,updated_at=excluded.updated_at;

  perform private.materialize_resolved_location(v_need.id,p_conversation_id);

  delete from private.dispatch_schedule where need_id=v_need.id;

  v_after:=private.need_full_edit_snapshot(v_need.id);
  if v_after is not distinct from v_before then raise exception 'NO_MATERIAL_CHANGE' using errcode='22023'; end if;

  insert into private.need_revision_events(
    need_id,from_revision,to_revision,from_status,previous_material_snapshot,new_material_snapshot,created_by_account_id
  ) values (
    v_need.id,p_expected_revision,v_need.revision,case when v_from_status='DRAFT' then 'DRAFT' else 'PUBLISHED_OR_SELECTION' end,v_before,v_after,v_uid
  ) returning id into v_event_id;

  update public.ai_conversations
     set status='COMPLETED',completed_at=statement_timestamp()
   where id=p_conversation_id and status='OPEN';

  perform private.audit_marketplace(v_uid,'NEED_AI_EDIT_CONFIRMED','NEED',v_need.id,v_need.revision,
    jsonb_build_object('fromRevision',p_expected_revision,'toRevision',v_need.revision,'revisionEventId',v_event_id,'conversationId',p_conversation_id));

  v_result:=jsonb_build_object(
    'needId',v_need.id,'fromRevision',p_expected_revision,'revision',v_need.revision,'status','DRAFT',
    'revisionEventId',v_event_id,'conversationId',p_conversation_id,'requiresReadmission',true,
    'idempotentReplay',false,'authoritative',true
  );

  insert into private.need_edit_commands(
    requester_account_id,client_request_id,request_hash,need_id,from_revision,to_revision,revision_event_id,result
  ) values(v_uid,v_request_id,v_request_hash,v_need.id,p_expected_revision,v_need.revision,v_event_id,v_result);

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_confirm_need_edit_from_review_v2(p_need_id uuid, p_expected_revision integer, p_conversation_id uuid, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_request_id text:=btrim(coalesce(p_client_request_id,''));
  v_conv public.ai_conversations%rowtype;
  v_facts jsonb;
  v_request_hash text;
  v_existing private.need_edit_commands%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_conversation_id is null or p_expected_revision is null or p_expected_revision<1 then
    raise exception 'EDIT_REVIEW_IDENTITY_REQUIRED' using errcode='22004';
  end if;
  if char_length(v_request_id) not between 8 and 200 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;

  select * into v_conv from public.ai_conversations where id=p_conversation_id;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  if v_conv.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_conv.purpose<>'NEED_INTAKE' or v_conv.fact_schema_version<>'NEED_FACT_V2' then
    raise exception 'EDIT_CONVERSATION_NOT_CONFIRMABLE' using errcode='P0001';
  end if;
  if v_conv.bound_need_id is distinct from p_need_id then
    raise exception 'EDIT_CONVERSATION_NEED_MISMATCH' using errcode='42501';
  end if;

  select coalesce(jsonb_object_agg(fact_key,fact_value),'{}'::jsonb)
    into v_facts
    from public.ai_structured_facts
   where conversation_id=p_conversation_id
     and superseded_at is null
     and fact_schema_version='NEED_FACT_V2'
     and status='CONFIRMED';

  v_request_hash:=encode(
    extensions.digest(
      convert_to(jsonb_build_object(
        'needId',p_need_id,
        'expectedRevision',p_expected_revision,
        'conversationId',p_conversation_id,
        'facts',v_facts
      )::text,'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_uid::text||E'\n'||v_request_id,4411));
  select * into v_existing
    from private.need_edit_commands c
   where c.requester_account_id=v_uid
     and c.client_request_id=v_request_id
   for update;

  if found then
    if v_existing.need_id is distinct from p_need_id
       or v_existing.from_revision is distinct from p_expected_revision
       or v_existing.request_hash<>v_request_hash then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';
    end if;
    return v_existing.result||jsonb_build_object('idempotentReplay',true);
  end if;

  if v_conv.status<>'OPEN' then
    raise exception 'EDIT_CONVERSATION_NOT_CONFIRMABLE' using errcode='P0001';
  end if;

  return public.rpc_confirm_need_edit_from_review(
    p_need_id,p_expected_revision,p_conversation_id,v_request_id
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_delete_abandoned_intake_conversation(p_conversation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ DECLARE v_conv RECORD; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode = '28000'; END IF; SELECT * INTO v_conv FROM public.ai_conversations WHERE id = p_conversation_id AND account_id = auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'CONVERSATION_NOT_FOUND' USING errcode = 'P0002'; END IF; IF v_conv.bound_need_id IS NOT NULL THEN IF EXISTS (SELECT 1 FROM public.needs WHERE id = v_conv.bound_need_id AND status IN ('PUBLISHED', 'SELECTION', 'ACCEPTED', 'COMPLETED')) THEN RAISE EXCEPTION 'CANNOT_DELETE_PUBLISHED_TASK_CONVERSATION' USING errcode = '22000'; END IF; END IF; DELETE FROM public.need_facts_v2 WHERE conversation_id = p_conversation_id; DELETE FROM public.ai_conversation_messages WHERE conversation_id = p_conversation_id; DELETE FROM public.ai_conversations WHERE id = p_conversation_id; RETURN true; END; $function$;


CREATE OR REPLACE FUNCTION public.rpc_delete_draft_need(p_need_id uuid, p_need_revision integer, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  n public.needs;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;

  select * into n
    from public.needs x
   where x.id = p_need_id
   for update;

  if not found then
    if exists (
      select 1
        from private.marketplace_audit_log a
       where a.actor_user_id = u
         and a.event_type = 'NEED_DRAFT_DELETED'
         and a.entity_type = 'NEED'
         and a.entity_id = p_need_id
         and a.entity_version = p_need_revision
    ) then
      return jsonb_build_object(
        'needId', p_need_id,
        'revision', p_need_revision,
        'deleted', true,
        'idempotentReplay', true,
        'authoritative', true
      );
    end if;
    raise exception using errcode='P0002', message='NEED_NOT_FOUND';
  end if;

  if n.requester_account_id <> u then
    raise exception using errcode='42501', message='FORBIDDEN';
  end if;
  if n.revision is distinct from p_need_revision then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;
  if n.status <> 'DRAFT' or n.published_at is not null then
    raise exception using errcode='22023', message='NEED_NOT_DELETABLE_DRAFT';
  end if;
  if cardinality(n.public_photo_paths) > 0 then
    raise exception using errcode='55000', message='DRAFT_MEDIA_CLEANUP_REQUIRED';
  end if;

  if exists (select 1 from public.marketplace_responses r where r.need_id = n.id)
     or exists (select 1 from public.need_selections s where s.need_id = n.id)
     or exists (select 1 from public.agreements a where a.need_id = n.id)
     or exists (select 1 from public.dispatch_rounds d where d.need_id = n.id)
     or exists (select 1 from public.opportunity_deliveries o where o.need_id = n.id)
     or exists (select 1 from private.dispatch_schedule q where q.need_id = n.id)
     or exists (
       select 1 from public.user_activity_events e
        where e.entity_type = 'NEED' and e.entity_id = n.id
     ) then
    raise exception using errcode='55000', message='DRAFT_HAS_AUTHORITATIVE_HISTORY';
  end if;

  delete from public.needs x where x.id = n.id;

  perform private.audit_marketplace(
    u,
    'NEED_DRAFT_DELETED',
    'NEED',
    n.id,
    n.revision,
    jsonb_build_object('reason', left(btrim(coalesce(p_reason, '')), 500))
  );

  return jsonb_build_object(
    'needId', n.id,
    'revision', n.revision,
    'deleted', true,
    'idempotentReplay', false,
    'authoritative', true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_discard_profile_avatar(p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 perform private.closure_assert_open(auth.uid());
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=auth.uid() and scope='AVATAR';
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 perform 1 from public.app_profiles where id=a.profile_id and account_id=auth.uid() for update;
 select * into a from private.owned_media_assets where id=p_asset_id for update;
 if a.avatar_apply_receipt is not null then raise exception 'MEDIA_NOT_EDITABLE' using errcode='55000'; end if;
 update private.owned_media_assets set selected=false where id=a.id;
 return jsonb_build_object('assetId',a.id,'profileId',a.profile_id,'accountId',auth.uid(),'discarded',true,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_discovery_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
 r jsonb:=p_request; f jsonb; a jsonb; scope jsonb; cursor_doc jsonb; result jsonb;
 query_text text; locality text; price text; location_mode text; when_mode text; scope_mode text; request_mode text;
 filter_key text; scope_key text; need_id uuid; people integer; page_limit integer;
 now_at timestamptz:=statement_timestamp(); time_at timestamptz; through_at timestamptz; expires_at timestamptz;
 before_at timestamptz; before_id uuid; before_section integer;
 west numeric; south numeric; east numeric; north numeric; point_lat numeric; point_lng numeric;
 range_from text; range_to text; iso_pattern text:='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$';
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 if jsonb_typeof(r) is distinct from 'object' then raise exception 'P6_INVALID_REQUEST' using errcode='22023'; end if;
 request_mode:=r->>'mode';
 if request_mode='EXACT_PUBLIC' then
  if r-array['mode','needId']<>'{}' or not(r?&array['mode','needId']) or jsonb_typeof(r->'needId')<>'string'
    or r->>'needId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'P6_INVALID_REQUEST' using errcode='22023'; end if;
  need_id:=(r->>'needId')::uuid; time_at:=now_at; through_at:=now_at; page_limit:=1;
  f:='{"text":"","price":"all","where":"any","places":1,"when":"any","dates":null,"place":null}';
  scope:='{"kind":"ALL"}';
 elsif request_mode='PAGE' then
  if r-array['mode','filter','anchor','scope','limit','after']<>'{}' or not(r?&array['mode','filter','anchor','scope','limit','after'])
    or jsonb_typeof(r->'limit')<>'number' or (r->>'limit')::numeric<>trunc((r->>'limit')::numeric)
    or (r->>'limit')::numeric not between 1 and 100 then raise exception 'P6_INVALID_REQUEST' using errcode='22023'; end if;
  page_limit:=(r->>'limit')::integer; f:=r->'filter'; scope:=r->'scope';
 else raise exception 'P6_MODE_NOT_IMPLEMENTED' using errcode='22023'; end if;
 if jsonb_typeof(f) is distinct from 'object' or f-array['text','price','where','places','when','dates','place']<>'{}'
   or not(f?&array['text','price','where','places','when','dates','place'])
   or jsonb_typeof(f->'text')<>'string' or octet_length(f->>'text')>16000
   or coalesce(f->>'price','') not in ('all','MY_PRICE','OFFERS') or coalesce(f->>'where','') not in ('any','onsite','remote')
   or coalesce(f->>'when','') not in ('any','today','tomorrow','week','weekend','next7')
   or jsonb_typeof(f->'places')<>'number' or (f->>'places')::numeric<>trunc((f->>'places')::numeric)
   or (f->>'places')::numeric not between 1 and 10 then raise exception 'P6_INVALID_FILTER' using errcode='22023'; end if;
 query_text:=lower(public.p6_discovery_trim(f->>'text') collate pg_catalog."sr-Latn-RS-x-icu");
 price:=f->>'price'; location_mode:=f->>'where'; people:=(f->>'places')::integer; when_mode:=f->>'when';
 if f->'dates'<>'null'::jsonb then
  if jsonb_typeof(f->'dates')<>'object' or (f->'dates')-array['from','to']<>'{}'
    or not public.p6_discovery_civil(f#>>'{dates,from}') or not public.p6_discovery_civil(f#>>'{dates,to}')
    or f#>>'{dates,from}'>f#>>'{dates,to}' then raise exception 'P6_INVALID_FILTER' using errcode='22023'; end if;
  range_from:=f#>>'{dates,from}'; range_to:=f#>>'{dates,to}'; when_mode:='any';
 end if;
 if f->'place'<>'null'::jsonb then
  if jsonb_typeof(f->'place')<>'string' or octet_length(f->>'place')>16000 then raise exception 'P6_INVALID_FILTER' using errcode='22023'; end if;
  locality:=nullif(public.p6_discovery_key(f->>'place'),'');
 end if;
 if location_mode='remote' then locality:=null; scope:='{"kind":"ALL"}'; end if;
 f:=jsonb_build_object('text',query_text,'price',price,'where',location_mode,'places',people,'when',when_mode,
   'dates',case when range_from is null then null else jsonb_build_object('from',range_from,'to',range_to) end,'place',locality);
 filter_key:=md5(f::text);
 if request_mode='PAGE' then
  if r->'anchor'='null'::jsonb then
   if r->'after'<>'null'::jsonb then raise exception 'P6_INVALID_CURSOR' using errcode='22023'; end if;
   time_at:=now_at; through_at:=now_at; expires_at:=now_at+interval '30 minutes';
  else
   a:=r->'anchor';
   if jsonb_typeof(a)<>'object' or a-array['version','filterKey','timeAt','publishedThrough','expiresAt']<>'{}'
     or not(a?&array['version','filterKey','timeAt','publishedThrough','expiresAt'])
     or a->>'version' is distinct from 'DISCOVERY_V1' or a->>'filterKey' is distinct from filter_key
     or coalesce(a->>'timeAt','')!~iso_pattern or coalesce(a->>'publishedThrough','')!~iso_pattern or coalesce(a->>'expiresAt','')!~iso_pattern
     then raise exception 'P6_INVALID_ANCHOR' using errcode='22023'; end if;
   time_at:=(a->>'timeAt')::timestamptz; through_at:=(a->>'publishedThrough')::timestamptz; expires_at:=(a->>'expiresAt')::timestamptz;
   if not isfinite(time_at) or time_at>now_at or through_at<>time_at or expires_at<>time_at+interval '30 minutes' then raise exception 'P6_INVALID_ANCHOR' using errcode='22023'; end if;
   if expires_at<=now_at then raise exception 'P6_ANCHOR_EXPIRED' using errcode='22023'; end if;
  end if;
 end if;
 if jsonb_typeof(scope) is distinct from 'object' then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
 scope_mode:=scope->>'kind';
 if scope_mode='ALL' then
  if scope-array['kind']<>'{}' then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
 elsif scope_mode='AREA' then
  if scope-array['kind','bounds']<>'{}' or jsonb_typeof(scope->'bounds') is distinct from 'array' or jsonb_array_length(scope->'bounds')<>4
    or exists(select 1 from jsonb_array_elements(scope->'bounds') x where jsonb_typeof(x)<>'number') then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
  west:=(scope#>>'{bounds,0}')::numeric; south:=(scope#>>'{bounds,1}')::numeric; east:=(scope#>>'{bounds,2}')::numeric; north:=(scope#>>'{bounds,3}')::numeric;
  if abs(west)>180 or abs(east)>180 or south< -90 or north>90 or south>north then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
  scope:=jsonb_build_object('kind',scope_mode,'bounds',jsonb_build_array(west::double precision,south::double precision,east::double precision,north::double precision));
 elsif scope_mode in ('POINT_LIST','POINT_MEMBERS') then
  if scope-array['kind','point']<>'{}' or jsonb_typeof(scope->'point') is distinct from 'object' or (scope->'point')-array['lat','lng']<>'{}'
    or jsonb_typeof(scope#>'{point,lat}') is distinct from 'number' or jsonb_typeof(scope#>'{point,lng}') is distinct from 'number' then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
  point_lat:=(scope#>>'{point,lat}')::numeric; point_lng:=(scope#>>'{point,lng}')::numeric;
  if abs(point_lat)>90 or abs(point_lng)>180 or round(point_lat,2)<>point_lat or round(point_lng,2)<>point_lng then raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
  scope:=jsonb_build_object('kind',scope_mode,'point',jsonb_build_object('lat',point_lat::double precision,'lng',point_lng::double precision));
 else raise exception 'P6_INVALID_SCOPE' using errcode='22023'; end if;
 scope_key:=md5(jsonb_build_object('filterKey',filter_key,'scope',scope,'timeAt',to_char(time_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text);
 cursor_doc:=r->'after';
 if request_mode='PAGE' and cursor_doc<>'null'::jsonb then
  if jsonb_typeof(cursor_doc)<>'object' or cursor_doc-array['scopeKey','section','sortAt','id']<>'{}'
    or not(cursor_doc?&array['scopeKey','section','sortAt','id']) or cursor_doc->>'scopeKey' is distinct from scope_key
    or cursor_doc->'section' not in ('0'::jsonb,'1'::jsonb) or coalesce(cursor_doc->>'sortAt','')!~iso_pattern
    or coalesce(cursor_doc->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then raise exception 'P6_INVALID_CURSOR' using errcode='22023'; end if;
  before_at:=(cursor_doc->>'sortAt')::timestamptz; before_id:=(cursor_doc->>'id')::uuid; before_section:=(cursor_doc->>'section')::integer;
  if before_at>through_at or (scope_mode in ('ALL','POINT_MEMBERS') and before_section<>0) then raise exception 'P6_INVALID_CURSOR' using errcode='22023'; end if;
 end if;
 with base as materialized (
  select n.id,n.revision,n.published_at,n.title,n.category,n.status,n.urgent,n.schedule_kind,n.starts_at,n.ends_at,n.execution_location_mode,
   n.task_country_code,n.task_timezone,n.verified_identity_required,n.approximate_city,n.approximate_area,n.approximate_lat,n.approximate_lng,
   n.required_slots,n.required_skills,n.required_tools,n.required_vehicles,n.required_licenses,n.minimum_experience_years,n.mode,
   n.requester_price_rsd,n.price_basis,n.requester_profile_id,n.response_deadline,
   public.covered_slots(jsonb_populate_record(null::public.needs,jsonb_build_object('id',n.id))) as covered_now,
   public.p6_discovery_days(n.schedule_kind,n.starts_at,n.ends_at,n.task_timezone,time_at) as days,
   public.p6_discovery_area(n.approximate_area,n.approximate_city,n.execution_location_mode='REMOTE') as area_text,
   case when n.execution_location_mode='REMOTE' or n.approximate_lat is null or n.approximate_lng is null then false else true end as has_point,
   (time_at at time zone coalesce(n.task_timezone,'UTC'))::date as today
  from public.needs n where n.status in ('PUBLISHED','SELECTION') and n.published_at is not null and n.remaining_search_closed_at is null
   and (request_mode='EXACT_PUBLIC' and n.id=need_id or request_mode='PAGE' and n.published_at<=through_at)
 ), shared as materialized (
  select b.*,case when range_from is not null then array[range_from,range_to] else case when_mode
   when 'today' then array[today::text,today::text] when 'tomorrow' then array[(today+1)::text,(today+1)::text]
   when 'week' then array[today::text,(today+7-extract(isodow from today)::integer)::text]
   when 'next7' then array[today::text,(today+6)::text]
   when 'weekend' then array[(today+greatest(0,6-extract(isodow from today)::integer))::text,(today+7-extract(isodow from today)::integer)::text] else null end end as wanted
  from base b where (price='all' or b.mode=price)
   and (location_mode='any' or location_mode='remote' and b.execution_location_mode='REMOTE'
     or location_mode='onsite' and b.execution_location_mode is not null and b.execution_location_mode<>'REMOTE')
   and (people=1 or greatest(0,coalesce(nullif(b.required_slots,0),1)-coalesce(b.covered_now,0))>=people)
   and (locality is null or b.execution_location_mode is distinct from 'REMOTE' and public.p6_discovery_key(b.area_text)=locality
     and public.p6_discovery_key(b.area_text) not in ('na daljinu','lokacija nije navedena'))
   and (query_text='' or strpos(lower((coalesce(b.title,'')||' '||b.area_text||' '||array_to_string(coalesce(b.required_skills,'{}')||coalesce(b.required_tools,'{}')||coalesce(b.required_vehicles,'{}'),' ')) collate pg_catalog."sr-Latn-RS-x-icu"),query_text)>0)
 ), qualified as materialized (
  select s.*,(wanted is null or days[1]<=wanted[2] and days[2]>=wanted[1]) is true as time_ok,
   case when scope_mode='ALL' then true when not has_point then false when scope_mode='AREA' then
    approximate_lat between south and north and (west<=east and approximate_lng between west and east or west>east and (approximate_lng>=west or approximate_lng<=east))
    else approximate_lat=point_lat and approximate_lng=point_lng end as in_area
  from shared s
 ), scoped as materialized (
  select q.*,case when scope_mode in ('AREA','POINT_LIST') and not has_point then 1 else 0 end as section
  from qualified q where in_area or not has_point and scope_mode in ('AREA','POINT_LIST')
 ), page as materialized (
  select * from scoped where time_ok and (before_id is null or section>before_section or section=before_section and (published_at,id)<(before_at,before_id))
  order by section,published_at desc,id desc limit page_limit+1
 ), shown as materialized (select * from page order by section,published_at desc,id desc limit page_limit), projected as (
  select s.section,s.published_at,s.id,jsonb_build_object(
   'id',s.id,'revision',s.revision,'sortAt',to_char(s.published_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'publishedAt',s.published_at,'title',s.title,'category',s.category,'status',s.status,'urgent',s.urgent,
   'scheduleKind',s.schedule_kind,'startsAt',s.starts_at,'endsAt',s.ends_at,'executionLocationMode',s.execution_location_mode,
   'taskCountryCode',s.task_country_code,'taskTimezone',s.task_timezone,'verifiedIdentityRequired',s.verified_identity_required,
   'approximateCity',nullif(btrim(s.approximate_city),''),'approximateArea',nullif(btrim(s.approximate_area),''),
   'pin',case when not s.has_point then null else jsonb_build_object('lat',s.approximate_lat,'lng',s.approximate_lng,'precision','COARSE_1KM') end,
   'requiredSlots',s.required_slots,'coveredSlots',s.covered_now,'requiredSkills',to_jsonb(s.required_skills),'requiredTools',to_jsonb(s.required_tools),
   'requiredVehicles',to_jsonb(s.required_vehicles),'requiredLicenses',to_jsonb(s.required_licenses),'minimumExperienceYears',s.minimum_experience_years,
   'priceMode',s.mode,'requesterPriceRsd',s.requester_price_rsd,'priceBasis',s.price_basis,'requesterProfileId',s.requester_profile_id,
   'responseDeadline',s.response_deadline,'acceptsApplications',s.required_slots>s.covered_now and (s.response_deadline is null or s.response_deadline>now_at),
   'publicTopology',(select g.public_topology from public.need_geography g where g.need_id=s.id),
   'criticalConditions',(select to_jsonb(d.critical_conditions) from public.need_requirement_details d where d.need_id=s.id)) as item from shown s
 ) select jsonb_build_object('version','DISCOVERY_V1','mode',request_mode,'asOf',now_at,'filterKey',filter_key,
  'anchor',jsonb_build_object('version','DISCOVERY_V1','filterKey',filter_key,'timeAt',to_char(time_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'publishedThrough',to_char(through_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expiresAt',to_char(expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'items',coalesce((select jsonb_agg(item order by section,published_at desc,id desc) from projected),'[]'::jsonb),
  'hasMore',(select count(*)>page_limit from page),
  'nextCursor',case when (select count(*)>page_limit from page) then (select jsonb_build_object('scopeKey',scope_key,'section',section,
   'sortAt',to_char(published_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'id',id) from shown order by section desc,published_at,id limit 1) else null end,
  'counts',jsonb_build_object('kind','exact_live','observedAt',now_at,
   'mapped',case when scope_mode='POINT_MEMBERS' then (select count(*) from scoped where time_ok) else (select count(*) from qualified where time_ok) end,
   'listed',(select count(*) from scoped where time_ok),'inArea',(select count(*) from scoped where time_ok and in_area),
   'withoutPoint',(select count(*) from scoped where time_ok and section=1),
   'undated',(select count(*) from scoped where wanted is not null and days is null)),
  'availability',jsonb_build_object('hasKnownWorkMode',exists(select 1 from base where execution_location_mode is not null),
   'hasKnownSchedule',exists(select 1 from base where days is not null),'priceModes',(select coalesce(jsonb_agg(mode order by mode),'[]') from (select distinct mode from base) modes))) into result;
 if request_mode='EXACT_PUBLIC' then return result-array['anchor','filterKey','counts','availability']; end if;
 return result;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
 raise exception 'P6_INVALID_REQUEST' using errcode='22023';
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_dispatch_account_closure_action_service(p_account_id uuid, p_generation uuid, p_action_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e private.closure_executions_v5;a private.closure_actions_v5;begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform private.closure_erasure_lock_v5(p_account_id);
 select * into e from private.closure_executions_v5 where account_id=p_account_id and generation=p_generation;
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then perform private.closure_erasure_assert_current_v5(e);else perform private.closure_assert_current_v5(e);end if;
 select * into a from private.closure_actions_v5 where id=p_action_id and generation=e.generation and account_id=p_account_id;
 if not found or p_attempt_id is null or a.attempt_id is distinct from p_attempt_id then raise exception 'CLOSURE_ATTEMPT_STALE' using errcode='PT409';end if;
 if a.state<>'PENDING' then return jsonb_build_object('admitted',false,'action',private.closure_action_document_v5(a,e));end if;
 if a.kind='STORAGE_DELETE' and a.bucket='profile-media' and private.closure_erasure_media_protected_v5(p_account_id,a.object_path) then raise exception 'CLOSURE_SCOPED_EXCEPTION' using errcode='55000';end if;
 if a.kind in('RELATIONAL_REDACT','AUTH_IDENTITY_ERASE') and exists(select 1 from private.closure_actions_v5 where generation=e.generation and kind='STORAGE_DELETE' and state<>'VERIFIED') then raise exception 'CLOSURE_STORAGE_NOT_CLEAN' using errcode='55000';end if;
 if a.kind='AUTH_IDENTITY_ERASE' then
  if exists(select 1 from storage.objects where owner_id=p_account_id::text or split_part(name,'/',1)=p_account_id::text) then raise exception 'CLOSURE_STORAGE_NOT_CLEAN' using errcode='55000';end if;
  if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' and (
   cardinality(private.closure_erasure_exceptions_v5(p_account_id))>0
   or not exists(select 1 from private.closure_actions_v5 where generation=e.generation and kind='RELATIONAL_REDACT' and state='VERIFIED')
   or exists(select 1 from private.closure_redaction_steps_v5 where generation=e.generation and state<>'VERIFIED')) then raise exception 'CLOSURE_RELATIONAL_NOT_CLEAN' using errcode='55000';end if;
 end if;
 update private.closure_actions_v5 set state='DISPATCHED',dispatched_at=clock_timestamp() where id=a.id returning * into a;
 return jsonb_build_object('admitted',true,'action',private.closure_action_document_v5(a,e));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_dispatch_media_upload_service(p_account_id uuid, p_asset_id uuid, p_attempt_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=p_account_id for update;
 if not found or p_attempt_id is null or a.attempt_id is distinct from p_attempt_id then raise exception 'MEDIA_ATTEMPT_STALE' using errcode='PT409'; end if;
 if a.state<>'STAGED' or a.dispatch_state<>'NOT_DISPATCHED' then return false; end if;
 update private.owned_media_assets set dispatch_state='DISPATCHING' where id=a.id;
 return true;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_dispatch_qa_classification_service(p_account_id uuid, p_need_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.qa_ai_commands;src jsonb;
begin
 if p_account_id is null or p_need_id is null or p_client_request_id is null or p_attempt_id is null then raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_assert_open(p_account_id);
 perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||p_account_id::text||':'||p_client_request_id::text,0));
 select * into c from private.qa_ai_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or c.need_id<>p_need_id or c.attempt_id is distinct from p_attempt_id or c.state<>'PROCESSING' or c.provider_dispatched or c.lease_expires_at<=clock_timestamp() then return false;end if;
 perform private.qa_ai_assert_actor(c.account_id,c.need_id,c.need_revision,c.question_id,c.command_type);
 src:=private.qa_ai_source(c.need_id,c.need_revision,c.question_id);
 if src->>'sourceHash' is distinct from c.source_hash then update private.qa_ai_commands set state='STALE',updated_at=clock_timestamp() where id=c.id;return false;end if;
 update private.qa_ai_commands set provider_dispatched=true,updated_at=clock_timestamp() where id=c.id;return true;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_dispatch_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; t private.worker_ai_turns; parent_open boolean;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform private.closure_assert_open(p_account_id);
 if p_client_request_id is null or p_attempt_id is null then raise exception 'WORKER_AI_ID_REQUIRED' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-turn:'||p_account_id::text||p_client_request_id::text,0));
 select * into s from private.worker_ai_sessions where account_id=p_account_id and conversation_id=p_conversation_id for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 perform 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id and purpose='PROFILE' and status='OPEN' for update;parent_open:=found;
 select * into t from private.worker_ai_turns where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or t.conversation_id is distinct from p_conversation_id or t.attempt_id is distinct from p_attempt_id then raise exception 'WORKER_AI_DENIED' using errcode='42501';end if;
 if t.state<>'PROCESSING' or t.provider_dispatched or t.cancelled_at is not null or t.lease_expires_at<=clock_timestamp()
 or t.source_revision<>s.revision or not parent_open or s.safety not in('ALLOW','CLARIFY') or s.base_hash is distinct from private.worker_ai_source_hash(p_account_id)
 then return jsonb_build_object('dispatched',false,'turn',private.worker_ai_turn_document(t.turn_id));end if;
 update private.worker_ai_turns set provider_dispatched=true where turn_id=t.turn_id;
 return jsonb_build_object('dispatched',true,'turn',private.worker_ai_turn_document(t.turn_id));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_execute_retention_job(p_job_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'TRUSTED_SERVER_REQUIRED' using errcode='42501';end if;
 return private.execute_retention_job(p_job_id,p_attempt_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_fail_data_export(p_receipt_id uuid, p_attempt_id uuid, p_failure_code text, p_retryable boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; retry boolean; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_failure_code is null or p_failure_code not in ('EXPORT_STORAGE_UNAVAILABLE','EXPORT_UPLOAD_FAILED','EXPORT_VERIFY_FAILED','EXPORT_WORKER_FAILED') or p_retryable is null then raise exception 'EXPORT_FAILURE_CODE_INVALID' using errcode='22023'; end if;
 r:=private.data_export_lock(p_receipt_id,null);v_now:=clock_timestamp();
 select * into a from private.data_export_artifacts where id=p_attempt_id and receipt_id=r.id for update;
 if not found or r.active_export_attempt_id is distinct from a.id or r.export_revoked_at is not null or r.status<>'PROCESSING' or a.lease_until<=v_now then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 retry:=p_retryable and r.export_attempt_count<5;
 update private.data_export_artifacts set cleanup_not_before=greatest(lease_until,v_now),download_grant_id=null,download_grant_expires_at=null where id=a.id;
 update public.data_export_requests set status=case when retry then 'REQUESTED' else 'FAILED' end,completed_at=case when retry then null else v_now end,
 failure_code=case when retry then null else p_failure_code end,export_next_attempt_at=case when retry then v_now+make_interval(secs=>30*r.export_attempt_count) else null end,updated_at=v_now where id=r.id;
 perform private.audit_marketplace(r.account_id,'DATA_EXPORT_ATTEMPT_FAILED','SYSTEM',r.id,null,jsonb_build_object('attempt',a.attempt_number,'code',p_failure_code,'retryScheduled',retry));
 return jsonb_build_object('receiptId',r.id,'status',case when retry then 'REQUESTED' else 'FAILED' end,'retryScheduled',retry);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_fail_media_upload_service(p_account_id uuid, p_asset_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=p_account_id for update;
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 if p_attempt_id is null or a.attempt_id is distinct from p_attempt_id then raise exception 'MEDIA_ATTEMPT_STALE' using errcode='PT409'; end if;
 if a.state='PROCESSING' then update private.owned_media_assets set state='FAILED',selected=false where id=a.id returning * into a; end if;
 return private.media_asset_document(a);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_fail_qa_classification_service(p_account_id uuid, p_need_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.qa_ai_commands;
begin
 if p_account_id is null or p_need_id is null or p_client_request_id is null or p_attempt_id is null then
  raise exception 'QA_INPUT_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||p_account_id::text||':'||p_client_request_id::text,0));
 select * into c from private.qa_ai_commands where account_id=p_account_id and client_request_id=p_client_request_id for update;
 if not found or c.need_id<>p_need_id or c.attempt_id is distinct from p_attempt_id then
  raise exception 'QA_CLASSIFICATION_NOT_FOUND' using errcode='42501';end if;
 if c.state<>'PROCESSING' then return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);end if;
 -- Honor retained canonical writers as well; never claim cancellation over an
 -- existing receipt. The owned client reads that receipt before classification.
 perform pg_advisory_xact_lock(hashtextextended(p_account_id::text||E'\n'||p_client_request_id::text,
  case when c.command_type='ASK' then 4412 else 4413 end));
 if exists(select 1 from private.preselection_qa_commands where actor_account_id=p_account_id and request_id=p_client_request_id) then
  return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);end if;
 -- Reuse the existing technical cancellation state (also used by the sweep).
 -- No policy decision, refund, lease refresh or repeat provider dispatch.
 update private.qa_ai_commands set state='CANCELLED',safe_reason_codes=array['QA_PROCESSING_FAILED'],updated_at=clock_timestamp()
  where id=c.id;
 return private.qa_ai_status(p_account_id,p_need_id,p_client_request_id);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_fail_worker_ai_turn_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare t private.worker_ai_turns;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into t from private.worker_ai_turns where account_id=p_account_id and conversation_id=p_conversation_id and client_request_id=p_client_request_id for update;
 if not found or t.attempt_id is distinct from p_attempt_id then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 if t.state='PROCESSING' and t.lease_expires_at>=clock_timestamp() then update private.worker_ai_turns set state='FAILED' where turn_id=t.turn_id; end if;
 return private.worker_ai_turn_document(t.turn_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_finalize_account_closure_service(p_account_id uuid, p_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e private.closure_executions_v5;v_receipt jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform private.closure_erasure_lock_v5(p_account_id);
 select * into e from private.closure_executions_v5 where account_id=p_account_id and generation=p_generation;
 if not found then raise exception 'CLOSURE_GENERATION_STALE' using errcode='PT409';end if;
 if e.state='CLOSED' then return e.receipt;end if;
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then
  perform private.closure_erasure_assert_current_v5(e);
  if cardinality(private.closure_erasure_exceptions_v5(p_account_id))>0 or exists(select 1 from private.closure_redaction_steps_v5 where generation=e.generation and state<>'VERIFIED')
  or not exists(select 1 from private.closure_actions_v5 where generation=e.generation and kind='RELATIONAL_REDACT' and state='VERIFIED') then raise exception 'CLOSURE_RELATIONAL_NOT_CLEAN' using errcode='55000';end if;
 else perform private.closure_assert_current_v5(e);end if;
 if exists(select 1 from private.closure_actions_v5 where generation=e.generation and state<>'VERIFIED')
 or exists(select 1 from storage.objects where owner_id=p_account_id::text or split_part(name,'/',1)=p_account_id::text)
 or not exists(select 1 from auth.users where id=p_account_id and deleted_at is not null)
 or exists(select 1 from auth.sessions where user_id=p_account_id) then raise exception 'CLOSURE_EVIDENCE_INCOMPLETE' using errcode='55000';end if;
 v_receipt:=jsonb_build_object('accountId',e.account_id,'requestId',e.request_id,'generation',e.generation,'state','CLOSED','closedAt',clock_timestamp(),'policySha256',e.policy_sha256,
 'authOutcome','AUTH_IDENTITY_ERASED_SUBJECT_RETAINED','mediaOutcome','OWNED_OBJECTS_DELETED',
 'relationalOutcome',case when e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then 'ORDINARY_PERSONAL_CONTENT_ERASED' else 'RETAINED_RESTRICTED' end,
 'retainedDatasets',case when e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then '[]'::jsonb else e.binding#>'{execution,datasets}' end,'authoritative',true);
 if e.binding->>'adapterVersion'='OWNER_AF_D22_EVENT_ERASURE_V1' then v_receipt:=v_receipt||jsonb_build_object('adapterVersion','OWNER_AF_D22_EVENT_ERASURE_V1','pseudonymousAuditRetained',true,'exceptions','[]'::jsonb);end if;
 update private.closure_executions_v5 set state='CLOSED',closed_at=(v_receipt->>'closedAt')::timestamptz,receipt=v_receipt where account_id=p_account_id;
 update private.account_closure_requests set state='CLOSED',revision=revision+1,closed_at=(v_receipt->>'closedAt')::timestamptz,execution_receipt=v_receipt,updated_at=clock_timestamp() where account_id=p_account_id;
 return v_receipt;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_get_account_block(p_target_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); r private.account_blocks;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_target_account_id is null or u=p_target_account_id then raise exception 'BLOCK_INPUT_INVALID' using errcode='22023'; end if;
 select * into r from private.account_blocks where blocker_account_id=u and blocked_account_id=p_target_account_id;
 -- Only the caller's outgoing choice is visible. Never disclose an incoming block.
 return jsonb_build_object('accountId',u,'targetAccountId',p_target_account_id,'blocked',coalesce(r.active,false),'revision',coalesce(r.revision,0),'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_account_closure(p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); r private.account_closure_requests;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 select * into r from private.account_closure_requests where account_id=u;
 if not found then return jsonb_build_object('accountId',u,'request',null,'revision',0,'restricted',false,'canExecute',false,'authoritative',true); end if;
 return jsonb_build_object('accountId',u,'request',private.account_closure_document(r),'revision',r.revision,
  'restricted',private.closure_account_restricted(u),'canExecute',false,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_account_closure_receipt(p_expected_user_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); c private.account_closure_commands;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 if p_client_request_id is null then raise exception 'CLOSURE_INPUT_INVALID' using errcode='22023'; end if;
 select * into c from private.account_closure_commands where account_id=u and client_request_id=p_client_request_id;
 return jsonb_build_object('accountId',u,'clientRequestId',p_client_request_id,'found',found,
  'receipt',case when found then c.receipt else null end,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_account_reputation(p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_account_id is null or not exists(select 1 from public.app_accounts where id=p_account_id)
 or private.closure_account_restricted(auth.uid()) or private.closure_account_restricted(p_account_id)
 or (auth.uid()<>p_account_id and private.safety_pair_blocked(auth.uid(),p_account_id)) then
  raise exception 'REPUTATION_NOT_AVAILABLE' using errcode='42501';
 end if;
 return private.account_reputation(p_account_id);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_agreement_workspace(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select jsonb_build_object(
      'id', a.id,
      'currentVersion', a.current_version,
      'status', coalesce(ae.state, a.status),
      'agreementStatus', a.status,
      'title', n.title,
      'approximateArea', n.approximate_area,
      'approximateCity', n.approximate_city,
      'requiredSlots', n.required_slots,
      'startsAt', n.starts_at,
      'terms', av.terms,
      'requesterAccountId', a.requester_account_id,
      'workerAccountId', a.worker_account_id, 'requesterProfileId', a.requester_profile_id, 'workerProfileId', a.worker_profile_id,
      'requesterName', rp.display_name,
      'workerName', wp.display_name,
      'executionMode', ae.mode,
      'requesterDeadlineAt', ae.requester_deadline_at,
      'problemOpened', (ae.problem_opened_at is not null),
      'myPhoneShared', exists (
        select 1 from public.access_grants g
         where g.agreement_id = a.id
           and g.channel = 'PHONE'
           and g.granted_by_account_id = v_uid
           and g.status = 'GRANTED'
             and private.safety_grant_valid(g.granted_by_account_id, g.granted_to_account_id, g.granted_at)
           and (g.expires_at is null or g.expires_at > statement_timestamp())
      ),
      'theirPhone', case
        when a.status = 'CONFIRMED' and exists (
          select 1 from public.access_grants g
           where g.agreement_id = a.id
             and g.channel = 'PHONE'
             and g.granted_to_account_id = v_uid
             and g.status = 'GRANTED'
             and private.safety_grant_valid(g.granted_by_account_id, g.granted_to_account_id, g.granted_at)
             and (g.expires_at is null or g.expires_at > statement_timestamp())
        ) then (
          select nullif(btrim(acc.phone), '')
            from public.app_accounts acc
           where acc.id = case when v_uid = a.requester_account_id then a.worker_account_id else a.requester_account_id end
        )
        else null
      end,
      'needId', a.need_id,
      'applicationId', a.selected_response_id,
      'createdAt', a.created_at
    )
    into v_result
    from public.agreements a
    join public.agreement_versions av
      on av.agreement_id = a.id and av.version = a.current_version
    join public.needs n on n.id = a.need_id
    join public.app_profiles rp on rp.id = a.requester_profile_id
    join public.app_profiles wp on wp.id = a.worker_profile_id
    left join public.agreement_execution ae on ae.agreement_id = a.id
   where a.id = p_agreement_id
     and v_uid in (a.requester_account_id, a.worker_account_id);

  if v_result is null then
    raise exception 'AGREEMENT_NOT_FOUND_OR_FORBIDDEN' using errcode = 'P0002';
  end if;
  return v_result || jsonb_build_object('actionState', private.agreement_action_state(p_agreement_id,v_uid));
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_data_export_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  r public.data_export_requests%rowtype;
  descriptor jsonb;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select * into r
  from public.data_export_requests d
  where d.account_id=u
  order by d.requested_at desc, d.id desc
  limit 1;

  if r.id is null then
    return jsonb_build_object(
      'hasRequest',false,'request',null,'fulfillment',null,
      'downloadAvailable',false,'serverFulfillmentRequired',true,'externalDsrChannelReady',false
    );
  end if;

  descriptor:=private.data_export_descriptor(r.id,u);
  return jsonb_build_object(
    'hasRequest',true,
    'request',jsonb_build_object(
      'receiptId',r.id,'clientRequestId',r.client_request_id,
      'kind',r.request_kind,'source',r.request_source,'status',r.status,
      'requestedAt',r.requested_at,'updatedAt',r.updated_at,
      'cancelledAt',r.cancelled_at,'completedAt',r.completed_at,
      'failureCode',r.failure_code
    ),
    'fulfillment',descriptor,'downloadAvailable',descriptor is not null,'serverFulfillmentRequired',true,'externalDsrChannelReady',false
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_legal_bundle()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  terms_row private.legal_document_versions%rowtype;
  privacy_row private.legal_document_versions%rowtype;
  u uuid:=auth.uid();
  accepted_current boolean:=false;
begin
  select * into terms_row
  from private.legal_document_versions d
  where d.document_kind='TERMS' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null;

  select * into privacy_row
  from private.legal_document_versions d
  where d.document_kind='PRIVACY' and d.is_active
    and d.published_at<=statement_timestamp() and d.effective_at<=statement_timestamp()
    and d.retired_at is null;

  if terms_row.id is null or privacy_row.id is null then
    return jsonb_build_object(
      'ready',false,
      'acceptedCurrentBundle',false,
      'documents','[]'::jsonb,
      'reason','LEGAL_DOCUMENTS_NOT_PUBLISHED'
    );
  end if;

  if u is not null then
    select exists(
      select 1 from public.account_legal_acceptance_events a
      where a.account_id=u
        and a.terms_document_id=terms_row.id
        and a.terms_content_sha256=terms_row.content_sha256
        and a.privacy_document_id=privacy_row.id
        and a.privacy_content_sha256=privacy_row.content_sha256
    ) into accepted_current;
  end if;

  return jsonb_build_object(
    'ready',true,
    'acceptedCurrentBundle',accepted_current,
    'reason',null,
    'documents',jsonb_build_array(
      jsonb_build_object('kind','TERMS','version',terms_row.version_label,'sha256',terms_row.content_sha256,'url',terms_row.public_url,'publishedAt',terms_row.published_at,'effectiveAt',terms_row.effective_at),
      jsonb_build_object('kind','PRIVACY','version',privacy_row.version_label,'sha256',privacy_row.content_sha256,'url',privacy_row.public_url,'publishedAt',privacy_row.published_at,'effectiveAt',privacy_row.effective_at)
    )
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_my_agreement_review(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews; own_review jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id);
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 select * into r from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u;
 own_review:=case when found then private.review_receipt(r,false) else null end;
 return jsonb_build_object('accountId',u,'agreementId',a.id,
 'targetAccountId',case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
 'eligible',own_review is null and not private.closure_account_restricted(u) and a.status='COMPLETED' and exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED'),
 'review',own_review,'tagCatalog',jsonb_build_object('version','PRE_V3_REVIEW_TAGS_V1','maxTags',3,'tags',to_jsonb(private.review_tag_catalog())),
 'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_my_agreement_review_v2(p_agreement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews; own_review jsonb; own_comment text;
begin
 -- D12: the legacy context (same participant gate, same eligibility incl. the closure restriction, same tag catalog) plus the author's OWN comment inside the review and the comment policy.
 -- The presence of THIS function is the capability a new client tests; an older server answers PGRST202 and the client falls back to the legacy pair.
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id);
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 select * into r from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u;
 if found then
  select c.comment into own_comment from private.agreement_review_comments_v1 c where c.review_id=r.id;
  own_review:=private.review_receipt(r,false)||jsonb_build_object('comment',own_comment);
 end if;
 return jsonb_build_object('accountId',u,'agreementId',a.id,
 'targetAccountId',case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
 'eligible',own_review is null and not private.closure_account_restricted(u) and a.status='COMPLETED' and exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED'),
 'review',own_review,'tagCatalog',jsonb_build_object('version','PRE_V3_REVIEW_TAGS_V1','maxTags',3,'tags',to_jsonb(private.review_tag_catalog())),
 'commentPolicy',jsonb_build_object('supported',true,'maxLength',500,'version','REVIEW_COMMENT_V1'),
 'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_my_safety_report(p_report_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r private.safety_reports;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into r from private.safety_reports where id=p_report_id and reporter_account_id=auth.uid();
 if not found then raise exception 'REPORT_NOT_AVAILABLE' using errcode='42501'; end if;
 return jsonb_build_object('reportId',r.id,'received',true,'createdAt',r.created_at,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_my_task_relations(p_need_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_items jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if p_need_ids is null or cardinality(p_need_ids) < 1 or cardinality(p_need_ids) > 100
     or array_position(p_need_ids, null) is not null then
    raise exception 'INVALID_INPUT' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(x.item order by x.need_id), '[]'::jsonb) into v_items
  from (
    select n.id as need_id, jsonb_build_object(
        'needId', n.id, 'relation', 'OWNER',
        'applicationId', null, 'applicationState', null, 'agreementId', null) as item
      from public.needs n
     where n.id = any(p_need_ids)
       and n.requester_account_id = v_uid
    union all
    -- The newest application that was ever sent; a DRAFT was never sent and is nobody's relation.
    select mine.need_id, jsonb_build_object(
        'needId', mine.need_id, 'relation', 'APPLIED',
        'applicationId', mine.application_id,
        'applicationState', private.my_application_state(
          mine.raw_status, mine.submitted_revision, mine.current_revision, mine.need_status, mine.agreement_id is not null),
        'agreementId', mine.agreement_id) as item
      from (
        select distinct on (r.need_id)
          r.need_id, r.id as application_id, r.status as raw_status,
          r.submitted_against_need_revision as submitted_revision,
          n.revision as current_revision, n.status as need_status,
          (select a.id from public.agreements a
            where a.selected_response_id = r.id
            order by a.created_at desc, a.id desc limit 1) as agreement_id
        from public.marketplace_responses r
        join public.needs n on n.id = r.need_id
        where r.need_id = any(p_need_ids)
          and r.worker_account_id = v_uid
          and r.status <> 'DRAFT'
          and n.requester_account_id <> v_uid
        order by r.need_id, r.created_at desc, r.id desc
      ) mine
  ) x;

  return jsonb_build_object('items', v_items, 'asOf', statement_timestamp());
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_need_lifecycle_receipt(p_need_id uuid, p_need_revision integer, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  revision_now integer;
  receipt jsonb;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;
  if p_need_id is null or p_need_revision is null or p_need_revision < 1
     or p_action is null or p_action not in ('CANCEL','DELETE_DRAFT') then
    raise exception using errcode='22023', message='NEED_COMMAND_INVALID_INPUT';
  end if;
  if p_action = 'DELETE_DRAFT' then
    if exists (select 1 from private.marketplace_audit_log a
      where a.actor_user_id=u and a.entity_type='NEED' and a.entity_id=p_need_id
        and a.entity_version=p_need_revision and a.event_type='NEED_DRAFT_DELETED') then
      receipt := jsonb_build_object('needId',p_need_id,'revision',p_need_revision,'deleted',true,'idempotentReplay',true);
    end if;
  else
    select n.revision into revision_now from public.needs n
      where n.id=p_need_id and n.requester_account_id=u and n.status='CANCELLED';
    if revision_now is not null and exists (select 1 from private.marketplace_audit_log a
      where a.actor_user_id=u and a.entity_type='NEED' and a.entity_id=p_need_id
        and a.entity_version=revision_now and a.event_type='NEED_CANCELLED') then
      receipt := jsonb_build_object('needId',p_need_id,'revision',revision_now,
        'status','CANCELLED','affectedResponses',0,'idempotentReplay',true);
    end if;
  end if;
  -- Absence is deliberately NOT a failure/deletion claim. A timed-out write can still commit later.
  return jsonb_build_object('authoritative',true,'action',p_action,
    'state',case when receipt is null then 'NOT_CONFIRMED' else 'CONFIRMED' end,
    'receipt',receipt);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_need_location_review(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
