CREATE OR REPLACE FUNCTION public.rpc_get_need_search_state(p_need_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  actor uuid := auth.uid(); n public.needs%rowtype;
  covered integer; missing integer; timed boolean; closing boolean; allowed boolean;
  why text; next_action text; total_agreements integer; active_agreements integer;
  awaiting integer; problems integer; at_now timestamptz := statement_timestamp();
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null then raise exception 'NEED_ID_REQUIRED' using errcode='22023'; end if;
  select * into n from public.needs where id=p_need_id and requester_account_id=actor;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  covered := public.fn_need_covered_slots(n.id);
  missing := greatest(0,n.required_slots-covered);
  timed := private.need_search_time_admitted_v1(n.id,at_now);
  closing := private.closure_account_restricted(actor);
  allowed := n.status in ('PUBLISHED','SELECTION') and missing>0
    and n.remaining_search_closed_at is not null and timed and not closing;
  why := case when closing then 'ACCOUNT_CLOSING'
    when n.status not in ('PUBLISHED','SELECTION','ACTIVE') then 'TASK_NOT_OPEN'
    when missing=0 then 'NO_MISSING_CAPACITY'
    when not timed then 'SEARCH_WINDOW_CLOSED'
    when n.remaining_search_closed_at is null then 'SEARCH_ALREADY_OPEN'
    when n.status not in ('PUBLISHED','SELECTION') then 'TASK_NOT_REOPENABLE'
    else 'CAN_REOPEN' end;
  select count(*)::integer,
    count(*) filter(where a.status in ('CONFIRMED','SUPERSEDED'))::integer,
    count(*) filter(where a.status='CONFIRMED' and x.state='AWAITING_REQUESTER')::integer,
    count(*) filter(where a.status='CONFIRMED' and x.problem_opened_at is not null)::integer
    into total_agreements,active_agreements,awaiting,problems
    from public.agreements a left join public.agreement_execution x on x.agreement_id=a.id
    where a.need_id=n.id;
  -- Navigation guidance only; existing Agreement workspace still authorizes its actions.
  next_action := case when closing then 'REVIEW_ACCOUNT' when why='TASK_NOT_OPEN' then 'VIEW_TASK_HISTORY'
    when problems>0 or awaiting>0 then 'OPEN_AGREEMENTS'
    when allowed then 'REOPEN_SEARCH'
    when active_agreements>0 then 'OPEN_AGREEMENTS'
    when not timed then 'REVIEW_TASK_TIME'
    when n.remaining_search_closed_at is not null then 'REVIEW_TASK'
    when missing>0 then 'SEARCH_IN_PROGRESS' else 'VIEW_TASK' end;
  return jsonb_build_object('schemaVersion',1,'authoritative',true,'serverAsOf',at_now,
    'needId',n.id,'revision',n.revision,'status',n.status,
    'requiredSlots',n.required_slots,'coveredSlots',covered,'missingSlots',missing,
    'searchAuthority',case when n.remaining_search_closed_at is null then 'OPEN' else 'CLOSED' end,
    'closedAt',n.remaining_search_closed_at,'searchTimeAdmitted',timed,
    'canReopen',allowed,'reason',why,'nextAction',next_action,
    'agreementCount',total_agreements,'activeAgreementCount',active_agreements,
    'awaitingConfirmationCount',awaiting,'openProblemCount',problems);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_notification_preferences(p_expected_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); d public.notification_preferences%rowtype; v_exists boolean:=true;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_expected_user_id is null or p_expected_user_id<>v_uid then
    raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
  if p_role is null or p_role not in ('REQUESTER','WORKER') then
    raise exception 'INVALID_NOTIFICATION_ROLE' using errcode='22023'; end if;
  select * into d from public.notification_preferences where user_id=v_uid and role_context=p_role;
  if not found then
    v_exists:=false;
    -- An absent row is revision0, with the existing emitter defaults. Reading
    -- never inserts a row and never acquires transport permission.
    d:=jsonb_populate_record(null::public.notification_preferences,
      '{"revision":0,"in_app_enabled":true,"push_enabled":false,"opportunities_enabled":true,
        "responses_enabled":true,"dogovor_enabled":true,"execution_enabled":true,
        "recovery_enabled":true,"account_enabled":true,"quiet_hours_enabled":false,
        "quiet_start":null,"quiet_end":null,"quiet_timezone":"Europe/Belgrade",
        "urgent_overrides_quiet_hours":false}'::jsonb);
    d.role_context:=p_role;
  end if;
  return jsonb_build_object('userId',v_uid,'exists',v_exists,'roleContext',d.role_context,'revision',d.revision,
    'updatedAt',d.updated_at,'settings',private.notification_preferences_settings(d));
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_processor_map_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  p private.processor_map_sets%rowtype;
  active_count integer;
  technical_count integer;
  required_count integer;
  covered_count integer;
  missing jsonb;
  mapped jsonb;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select count(*) into technical_count from private.processor_provider_inventory x;
  select count(*) into required_count from private.processor_provider_inventory x where x.active and x.required_current;
  select count(*) into active_count from private.processor_map_sets x where x.retired_at is null and x.effective_at<=statement_timestamp();

  if active_count=0 then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_NOT_PUBLISHED',
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'runtimeProviderGateAdmitted',false);
  end if;
  if active_count<>1 then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_AMBIGUOUS',
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'runtimeProviderGateAdmitted',false);
  end if;

  select * into p from private.processor_map_sets x
  where x.retired_at is null and x.effective_at<=statement_timestamp()
  order by x.effective_at desc limit 1;

  select count(*) into covered_count
  from private.processor_provider_inventory i
  where i.active and i.required_current
    and exists(select 1 from private.processor_map_entries e where e.map_id=p.id and e.provider_code=i.code);

  select coalesce(jsonb_agg(i.code order by i.code),'[]'::jsonb) into missing
  from private.processor_provider_inventory i
  where i.active and i.required_current
    and not exists(select 1 from private.processor_map_entries e where e.map_id=p.id and e.provider_code=i.code);

  if covered_count<>required_count then
    return jsonb_build_object('ready',false,'reason','PROCESSOR_MAP_INCOMPLETE','mapVersion',p.map_version,
      'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,'coveredCurrentProviders',covered_count,
      'missingProviders',missing,'runtimeProviderGateAdmitted',false);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'providerCode',e.provider_code,'providerDisplayName',i.display_name,'legalEntityName',e.legal_entity_name,
    'legalRole',e.legal_role,'purpose',e.purpose,'dataCategories',e.data_categories,'processingRegions',e.processing_regions,
    'crossBorderTransfer',e.cross_border_transfer,'transferMechanism',e.transfer_mechanism,'dpaReference',e.dpa_reference,
    'privacyNoticeUrl',e.privacy_notice_url,'retentionDeletionTerms',e.retention_deletion_terms,
    'subprocessorTerms',e.subprocessor_terms,'legalBasisReference',e.legal_basis_reference
  ) order by i.display_name),'[]'::jsonb) into mapped
  from private.processor_map_entries e
  join private.processor_provider_inventory i on i.code=e.provider_code
  where e.map_id=p.id and i.active;

  return jsonb_build_object('ready',true,'reason',null,'mapVersion',p.map_version,'effectiveAt',p.effective_at,
    'counselReference',p.counsel_reference,'technicalProviderCount',technical_count,'requiredCurrentProviders',required_count,
    'coveredCurrentProviders',covered_count,'providers',mapped,'runtimeProviderGateAdmitted',false);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_public_profile(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_profile public.app_profiles;
  v_completed bigint := 0;
  v_reputation jsonb;
begin
  if v_actor is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if p_profile_id is null then
    raise exception 'PROFILE_ID_REQUIRED' using errcode = '22023';
  end if;

  select p.*
  into v_profile
  from public.app_profiles p
  where p.id = p_profile_id
    and p.profile_status = 'ACTIVE'
    and p.kind in ('REQUESTER', 'WORKER');

  if not found then
    return null;
  end if;

  if private.closure_account_restricted(v_actor) or private.closure_account_restricted(v_profile.account_id) then return null; end if;
  if private.safety_pair_blocked(v_actor,v_profile.account_id) then return null; end if;
  if not private.accounts_same_world(v_actor, v_profile.account_id) then return null; end if;
  if v_profile.kind = 'REQUESTER' then
    select count(*)
    into v_completed
    from public.agreements a
    where a.requester_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  else
    select count(*)
    into v_completed
    from public.agreements a
    where a.worker_profile_id = v_profile.id
      and a.status = 'COMPLETED';
  end if;

  v_reputation:=private.account_reputation(v_profile.account_id);
  return jsonb_build_object(
    'profileId', v_profile.id,
    'role', v_profile.kind,
    'displayName', nullif(btrim(v_profile.display_name), ''),
    'avatarPath', v_profile.avatar_path,
    'city', nullif(btrim(v_profile.city), ''),
    'publicSummary', jsonb_build_object(
      'headline', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.headline), '') else null end,
      'bio', case when v_profile.kind = 'WORKER' then nullif(btrim(v_profile.bio), '') else null end
    ),
    'trust', jsonb_build_object(
      'ratingAverage', v_reputation->'averageRating',
      'reviewCount', v_reputation->'reviewCount',
      'completedCount', v_completed,
      'identityVerified', false,
      'ratingAvailable', (v_reputation->>'reviewCount')::bigint>0,
      'reviewsAvailable', true,
      'identityVerificationAvailable', false
    )
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_push_device(p_expo_push_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); d public.notification_push_devices%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_expo_push_token is null or p_expo_push_token !~ '^(ExpoPushToken|ExponentPushToken)\[[A-Za-z0-9_-]+\]$' then
    raise exception 'INVALID_PUSH_TOKEN' using errcode='22023'; end if;
  select * into d from public.notification_push_devices where user_id=v_uid and expo_push_token=p_expo_push_token;
  if not found then return jsonb_build_object('exists',false,'revision',0,'active',false); end if;
  return jsonb_build_object('exists',true,'id',d.id,'revision',d.revision,'active',d.active,'platform',d.platform,'lastSeenAt',d.last_seen_at);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_push_device_owned(p_expected_user_id uuid, p_expo_push_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); sid uuid; d public.notification_push_devices%rowtype; result jsonb;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid; exception when invalid_text_representation then raise exception 'AUTH_REQUIRED' using errcode='28000'; end;
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 if p_expo_push_token is null or length(p_expo_push_token)>256 then raise exception 'INVALID_PUSH_TOKEN' using errcode='22023'; end if;
 result:=public.rpc_get_push_device(p_expo_push_token);
 select * into d from public.notification_push_devices where user_id=u and expo_push_token=p_expo_push_token;
 return result||jsonb_build_object('sessionBound',coalesce(d.active and d.bound_session_id=sid and d.bound_revision=d.revision,false));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_get_push_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r private.push_runtime_readiness; t timestamptz:=statement_timestamp(); fresh boolean; expired boolean; overdue boolean; state text; reason text;
begin
 if auth.uid() is null and auth.role() is distinct from 'service_role' then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into r from private.push_runtime_readiness where singleton;
 fresh:=r.observed_at is not null and r.observed_at<=t and r.observed_at>t-interval '300 seconds';
 -- Existence uses existing partial lease/delivery indexes; no per-user lists,
 -- token/attempt IDs or full backlog counts escape through the read model.
 expired:=exists(select 1 from public.notification_push_attempts where lease_until<=t);
 overdue:=exists(select 1 from public.notification_deliveries d where d.channel='PUSH' and d.state in('CREATED','QUEUED','FAILED_RETRYABLE')
  and d.created_at<t-interval '15 minutes' and (d.expires_at is null or d.expires_at>t));
 if not fresh then state:='UNKNOWN';reason:=case when r.observed_at is null then 'NO_RUNTIME_OBSERVATION' else 'STALE_RUNTIME_OBSERVATION' end;
 elsif r.observation='PROBE_DISABLED' then state:='NOT_READY';reason:='DEPLOYMENT_DISABLED';
 elsif expired or overdue then state:='DEGRADED';reason:=case when expired then 'EXPIRED_LEASE' else 'OVERDUE_BACKLOG' end;
 elsif r.observation in('TICK_DEGRADED','TICK_FAILED') then state:='DEGRADED';reason:='LAST_TICK_UNHEALTHY';
 elsif r.observation='TICK_OK' and r.last_success_at=r.observed_at then state:='OPERATIONAL';reason:='HEALTHY_TRANSPORT_TICK';
 else state:='UNKNOWN';reason:='SUCCESSFUL_TICK_NOT_OBSERVED';end if;
 return jsonb_build_object('state',state,'reason',reason,'checkedAt',t,'observedAt',r.observed_at,'lastSuccessAt',r.last_success_at,
  'freshnessSeconds',300,'overdueWindowSeconds',900,'fresh',fresh,'senderVersion',r.sender_version,
  'senderDeployment',case when fresh then 'RUNTIME_OBSERVED' else 'UNKNOWN' end,
  'senderConfiguration',case when not fresh then 'UNKNOWN' when r.observation='PROBE_DISABLED' then 'DISABLED' else 'ENABLED' end,
  'expiredLease',expired,'overdueBacklog',overdue,'evidenceScope','TRANSPORT_ONLY','authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_push_session_device(p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); sid uuid; d public.notification_push_devices%rowtype; n integer;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid; exception when invalid_text_representation then raise exception 'AUTH_REQUIRED' using errcode='28000'; end;
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 select count(*) into n from public.notification_push_devices where user_id=u and active and bound_session_id=sid and bound_revision=revision;
 if n<>1 then return jsonb_build_object('kind',case when n=0 then 'NONE' else 'AMBIGUOUS' end); end if;
 select * into d from public.notification_push_devices where user_id=u and active and bound_session_id=sid and bound_revision=revision;
 return jsonb_build_object('kind','DEVICE','id',d.id,'revision',d.revision,'expoPushToken',d.expo_push_token,'platform',d.platform);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_get_reopen_remaining_search_receipt(p_need_id uuid, p_expected_revision integer, p_expected_closed_at timestamp with time zone, p_client_request_id text, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  actor uuid := auth.uid(); request_id text:=btrim(coalesce(p_client_request_id,''));
  reason_text text:=left(btrim(coalesce(p_reason,'')),500); request_hash text;
  stored private.remaining_search_close_commands%rowtype;
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_expected_revision is null or p_expected_revision<1
     or p_expected_closed_at is null or not isfinite(p_expected_closed_at)
     or char_length(request_id) not between 8 and 193 then
    raise exception 'SEARCH_RECEIPT_INPUT_INVALID' using errcode='22023';
  end if;
  perform 1 from public.needs where id=p_need_id and requester_account_id=actor;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'command','REOPEN_REMAINING_SEARCH_V1','needId',p_need_id,'expectedRevision',p_expected_revision,
    'reason',reason_text,'expectedClosedAtEpoch',extract(epoch from p_expected_closed_at)
  )::text,'UTF8'),'sha256'),'hex');
  select * into stored from private.remaining_search_close_commands
    where requester_account_id=actor and client_request_id='reopen:'||request_id;
  if not found then
    return jsonb_build_object('authoritative',true,'command','REOPEN_REMAINING_SEARCH_V1',
      'needId',p_need_id,'state','NOT_CONFIRMED','receipt',null);
  end if;
  if stored.request_hash is distinct from request_hash or stored.need_id<>p_need_id
     or stored.result->>'command' is distinct from 'REOPEN_REMAINING_SEARCH_V1'
     or stored.result->'remainingSearchClosed' is distinct from 'false'::jsonb
     or stored.result->'authoritative' is distinct from 'true'::jsonb then
    raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='PT409';
  end if;
  return jsonb_build_object('authoritative',true,'command','REOPEN_REMAINING_SEARCH_V1',
    'needId',p_need_id,'state','CONFIRMED','receipt',stored.result||jsonb_build_object('idempotentReplay',true));
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_requester_profile_for_edit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into p from public.app_profiles where account_id=auth.uid() and kind='REQUESTER';
 if not found then raise exception 'REQUESTER_PROFILE_REQUIRED' using errcode='55000'; end if;
