CREATE OR REPLACE FUNCTION public.rpc_get_retention_execution_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare b jsonb;source_ready boolean;ready boolean;unsupported jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 b:=private.retention_execution_binding();source_ready:=coalesce(private.retention_ai_source_ready(),false);ready:=b is not null and source_ready;
 select coalesce(jsonb_agg(code order by code),'[]'::jsonb) into unsupported from private.retention_data_classes where active and code<>'AI_VOLATILE';
 return jsonb_build_object('engineVersion','P3_AI_ABANDONED_UNBOUND_V1','executionAdmitted',ready,'policyVersion',b->>'policyVersion',
 'datasets',jsonb_build_array(jsonb_build_object('dataset','AI_ABANDONED_UNBOUND','dataClass','AI_VOLATILE','action','DELETE','ready',ready,
 'reason',case when b is null then 'POLICY_NOT_READY' when not source_ready then 'SOURCE_NOT_READY' else null end)),
 'unsupportedDataClasses',unsupported,'storageCleanup','NOT_APPLICABLE');
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_get_retention_policy_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  p private.retention_policy_sets%rowtype;
  active_count integer;
  required_count integer;
  rule_count integer;
  missing jsonb;
  rules jsonb;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select count(*) into required_count from private.retention_data_classes d where d.active and d.required;
  select count(*) into active_count from private.retention_policy_sets x where x.retired_at is null and x.effective_at<=statement_timestamp();
  if active_count=0 then
    return jsonb_build_object('ready',false,'reason','RETENTION_POLICY_NOT_PUBLISHED','requiredDataClasses',required_count,'executionAdmitted',false);
  end if;
  if active_count<>1 then
    return jsonb_build_object('ready',false,'reason','RETENTION_POLICY_AMBIGUOUS','requiredDataClasses',required_count,'executionAdmitted',false);
  end if;
  select * into p from private.retention_policy_sets x where x.retired_at is null and x.effective_at<=statement_timestamp() order by x.effective_at desc limit 1;
  select count(*) into rule_count
  from private.retention_policy_rules r join private.retention_data_classes d on d.code=r.data_class
  where r.policy_id=p.id and d.active and d.required;
  select coalesce(jsonb_agg(d.code order by d.code),'[]'::jsonb) into missing
  from private.retention_data_classes d
  where d.active and d.required and not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=d.code);
  if rule_count<>required_count then
    return jsonb_build_object('ready',false,'reason','RETENTION_POLICY_INCOMPLETE','policyVersion',p.policy_version,
      'requiredDataClasses',required_count,'coveredDataClasses',rule_count,'missingDataClasses',missing,'executionAdmitted',false);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('dataClass',r.data_class,'purpose',r.purpose,'retentionPeriod',r.retention_period_text,
    'deletionTrigger',r.deletion_trigger,'exceptionRule',r.exception_rule,'legalBasis',r.legal_basis_reference) order by r.data_class),'[]'::jsonb)
  into rules from private.retention_policy_rules r where r.policy_id=p.id;
  return jsonb_build_object('ready',true,'reason',null,'policyVersion',p.policy_version,'effectiveAt',p.effective_at,'counselReference',p.counsel_reference,
    'rules',rules,'requiredDataClasses',required_count,'coveredDataClasses',rule_count,'executionAdmitted',false);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_worker_availability()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare pid uuid; status text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select p.id,p.profile_status into pid,status from public.app_profiles p
    where p.account_id=auth.uid() and p.kind='WORKER';
  if pid is null then raise exception 'WORKER_PROFILE_REQUIRED' using errcode='55000'; end if;
  if status not in ('DRAFT','ACTIVE') then raise exception 'WORKER_PROFILE_RESTRICTED' using errcode='42501'; end if;
  return private.worker_availability_document(pid);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_get_worker_calendar(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_profile_id uuid;
  v_events jsonb;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_from is null or p_to is null or p_from >= p_to or not isfinite(p_from) or not isfinite(p_to) then
    raise exception 'CALENDAR_RANGE_INVALID' using errcode = '22023';
  end if;

  select p.id into v_profile_id
  from public.app_profiles p
  where p.account_id = v_uid and p.kind = 'WORKER';

  if v_profile_id is null then
    return jsonb_build_object(
      'from', p_from,
      'to', p_to,
      'events', '[]'::jsonb,
      'authoritative', true
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'eventId', e.id,
        'agreementId', e.agreement_id,
        'agreementVersion', e.agreement_version,
        'startsAt', e.starts_at,
        'endsAt', e.ends_at,
        'agreementStatus', e.agreement_status,
        'source', 'AGREEMENT'
      ) order by e.starts_at, e.ends_at, e.id
    ),
    '[]'::jsonb
  ) into v_events
  from private.worker_calendar_events e
  where e.worker_account_id = v_uid
    and e.worker_profile_id = v_profile_id
    and e.state = 'BLOCKING'
    and e.starts_at < p_to
    and e.ends_at > p_from;

  return jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'events', v_events,
    'authoritative', true
  );
end;
$function$;


