CREATE OR REPLACE FUNCTION public.rpc_read_safety_target(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_actor uuid := auth.uid(); v_profile public.app_profiles; v_block private.account_blocks;
begin
 if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_profile_id is null then raise exception 'SAFETY_TARGET_INPUT_INVALID' using errcode='22023'; end if;
 -- Exactly the visibility of rpc_get_public_profile: anything it hides has no safety target either.
 select p.* into v_profile from public.app_profiles p
  where p.id=p_profile_id and p.profile_status='ACTIVE' and p.kind in ('REQUESTER','WORKER');
 if not found or v_profile.account_id=v_actor then return null; end if;
 if private.closure_account_restricted(v_actor) or private.closure_account_restricted(v_profile.account_id) then return null; end if;
 if private.safety_pair_blocked(v_actor,v_profile.account_id) then return null; end if;
 if not private.accounts_same_world(v_actor,v_profile.account_id) then return null; end if;
 -- The caller's own outgoing choice only. An incoming block is never disclosed; a block in either
 -- direction has already returned null above, so a returned target is never an active block.
 select * into v_block from private.account_blocks
  where blocker_account_id=v_actor and blocked_account_id=v_profile.account_id;
 return jsonb_build_object('profileId',v_profile.id,'accountId',v_actor,'targetAccountId',v_profile.account_id,
  'blocked',coalesce(v_block.active,false),'revision',coalesce(v_block.revision,0),'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_read_task(p_need_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  -- RLS remains the authority for the task and all embedded relations.
  -- Composite computed fields receive ONLY an ID, never a whole-row reference.
  select jsonb_build_object(
    'id', n.id,
    'requester_profile_id', n.requester_profile_id,
    'status', n.status,
    'title', n.title,
    'description', n.description,
    'category', n.category,
    'approximate_city', n.approximate_city,
    'approximate_area', n.approximate_area,
    'approximate_lat', n.approximate_lat,
    'approximate_lng', n.approximate_lng,
    'schedule_kind', n.schedule_kind,
    'starts_at', n.starts_at,
    'ends_at', n.ends_at,
    'required_slots', n.required_slots,
    'mode', n.mode,
    'requester_price_rsd', n.requester_price_rsd,
    'required_skills', n.required_skills,
    'required_tools', n.required_tools,
    'required_vehicles', n.required_vehicles,
    'verified_identity_required', n.verified_identity_required,
    'urgent', n.urgent,
    'public_photo_paths', n.public_photo_paths,
    'revision', n.revision,
    'published_at', n.published_at,
    'created_at', n.created_at,
    'updated_at', n.updated_at,
    'response_deadline', n.response_deadline,
    'urgent_activated_at', n.urgent_activated_at,
    'urgent_expires_at', n.urgent_expires_at,
    'urgent_policy_version', n.urgent_policy_version,
    'minimum_experience_years', n.minimum_experience_years,
    'execution_location_mode', n.execution_location_mode,
    'required_licenses', n.required_licenses,
    'remaining_search_closed_at', n.remaining_search_closed_at,
    'task_country_code', n.task_country_code,
    'task_timezone', n.task_timezone,
    'price_basis', n.price_basis,
    'covered_slots', public.covered_slots(jsonb_populate_record(null::public.needs, jsonb_build_object('id', n.id))),
    'selectable_application_count', public.selectable_application_count(jsonb_populate_record(null::public.needs, jsonb_build_object('id', n.id))),
    'marketplace_responses', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id) order by r.id), '[]'::jsonb) from public.marketplace_responses r where r.need_id=n.id),
    'need_geography', (select jsonb_build_object('public_topology', g.public_topology) from public.need_geography g where g.need_id=n.id),
    'need_requirement_details', (select jsonb_build_object('critical_conditions', d.critical_conditions) from public.need_requirement_details d where d.need_id=n.id)
  ) into result from public.needs n where n.id=p_need_id;
  return result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_read_task_photos(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations; refs text[]; photos jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 select * into c from public.ai_conversations where id=p_conversation_id and account_id=auth.uid();
 if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 refs:=private.media_task_refs(c.id);
 select coalesce(jsonb_agg(private.media_asset_document(a)||jsonb_build_object('selected',a.storage_path=any(refs) or (a.conversation_id=c.id and a.selected and a.state in('PROCESSING','STAGED'))) order by a.created_at,a.id),'[]'::jsonb)
 into photos from private.owned_media_assets a where a.account_id=auth.uid() and a.scope='TASK'
  and (a.storage_path=any(refs) or (a.conversation_id=c.id and a.selected and a.state in('PROCESSING','STAGED')));
 return jsonb_build_object('conversationId',c.id,'accountId',auth.uid(),'photos',photos,'ready',private.media_refs_ready(auth.uid(),refs)
  and not exists(select 1 from private.owned_media_assets where conversation_id=c.id and selected and state in('PROCESSING','STAGED')),'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_read_worker_ai(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=auth.uid())
 then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 return private.worker_ai_document(p_conversation_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_read_worker_ai_context_service(p_account_id uuid, p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare doc jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from private.worker_ai_sessions where conversation_id=p_conversation_id and account_id=p_account_id)
 then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 doc:=private.worker_ai_document(p_conversation_id);
 if doc is null or doc->>'status'<>'OPEN' or doc->>'safety' in ('BLOCK','REVIEW') or doc->'stale'='true'::jsonb then raise exception 'WORKER_AI_NOT_EDITABLE' using errcode='55000'; end if;
 -- Keep owned history intact. Only the exact USER message attached by a new
 -- claim and subsequently cancelled before dispatch is excluded from provider
 -- context. Legacy rows have no fabricated timestamp-based association.
 return jsonb_set(doc-array['review','saved'],'{messages}',coalesce((
  select jsonb_agg(m.value order by m.ordinality) from jsonb_array_elements(doc->'messages') with ordinality m(value,ordinality)
  where not exists(select 1 from private.worker_ai_turns t where t.account_id=p_account_id and t.conversation_id=p_conversation_id
   and t.cancelled_at is not null and t.user_message_id=(m.value->>'id')::uuid)), '[]'::jsonb)) || jsonb_build_object('serviceModeContext',
   private.worker_ai_service_mode_context_v1(p_account_id,p_conversation_id));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_read_worker_ai_taxonomy(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_document jsonb;v_review jsonb;v_saved jsonb;v_review_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.worker_ai_sessions
  WHERE conversation_id=p_conversation_id AND account_id=auth.uid())
 THEN RAISE EXCEPTION 'WORKER_AI_DENIED' USING errcode='42501'; END IF;
 v_document:=private.worker_ai_document(p_conversation_id);
 IF v_document IS NULL THEN RAISE EXCEPTION 'WORKER_AI_DENIED' USING errcode='42501'; END IF;
 SELECT r.envelope,r.id INTO v_review,v_review_id
 FROM private.worker_ai_reviews r
 WHERE r.conversation_id=p_conversation_id AND r.account_id=auth.uid()
   AND r.envelope ? 'classificationState'
 ORDER BY EXISTS(SELECT 1 FROM private.worker_ai_saves saved
   WHERE saved.review_id=r.id) DESC,r.created_at DESC,r.id DESC LIMIT 1;
 IF NOT FOUND THEN RETURN v_document; END IF;
 SELECT saved.receipt INTO v_saved FROM private.worker_ai_saves saved
 WHERE saved.review_id=v_review_id AND saved.account_id=auth.uid()
 ORDER BY saved.created_at DESC LIMIT 1;
 RETURN v_document||jsonb_build_object('review',v_review,'saved',v_saved);
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_read_worker_ai_turn_recovery(p_expected_user_id uuid, p_conversation_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null or p_expected_user_id is distinct from auth.uid() then raise exception 'AUTH_REQUIRED' using errcode='42501';end if;
 if p_conversation_id is null or p_client_request_id is null then raise exception 'WORKER_AI_ID_REQUIRED' using errcode='22023';end if;
 return private.worker_ai_turn_recovery_v5(auth.uid(),p_conversation_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_record_need_publication_decision_service(p_need_id uuid, p_expected_revision integer, p_policy_id text, p_jurisdiction text, p_outcome text, p_rule_ids text[], p_decision_source text, p_safe_reason_codes text[] DEFAULT '{}'::text[], p_provider_ref text DEFAULT NULL::text, p_model_ref text DEFAULT NULL::text, p_reviewer_provenance jsonb DEFAULT '{}'::jsonb, p_service_provenance jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_need public.needs%rowtype;
  v_bundle_id uuid;
  v_policy_id text;
  v_policy_version integer;
  v_jurisdiction text;
  v_rule_ids text[];
  v_safe_reason_codes text[];
  v_rule_count integer;
  v_rule_snapshot jsonb;
  v_fp jsonb;
  v_identity_payload jsonb;
  v_identity text;
  v_decision_id uuid;
  v_sequence bigint;
  v_context jsonb;
  v_decision_at timestamptz;
begin
  if p_need_id is null or p_expected_revision is null then
    raise exception 'DECISION_NEED_REVISION_REQUIRED' using errcode='22004';
  end if;
  if coalesce(btrim(p_policy_id), '') = ''
     or coalesce(btrim(p_jurisdiction), '') = '' then
    raise exception 'POLICY_ID_JURISDICTION_REQUIRED' using errcode='22023';
  end if;
  if p_outcome is null or p_outcome not in ('ALLOW','CLARIFY','REVIEW','BLOCK') then
    raise exception 'DECISION_OUTCOME_INVALID' using errcode='22023';
  end if;
  if p_decision_source is distinct from 'PUBLICATION_EVALUATOR_V1' then
    raise exception 'DECISION_SOURCE_REQUIRED' using errcode='22023';
  end if;
  if jsonb_typeof(coalesce(p_reviewer_provenance, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_service_provenance, 'null'::jsonb)) <> 'object'
     or coalesce(p_service_provenance, '{}'::jsonb) = '{}'::jsonb then
    raise exception 'DECISION_PROVENANCE_INVALID' using errcode='22023';
  end if;

  if p_rule_ids is null or cardinality(p_rule_ids) not between 1 and 64 or array_ndims(p_rule_ids)<>1
     or exists(select 1 from unnest(p_rule_ids) r where r is null or r !~ '^[A-Z][A-Z0-9_-]{0,63}$')
     or (select count(distinct r) from unnest(p_rule_ids) r)<>cardinality(p_rule_ids)
     or p_safe_reason_codes is null or cardinality(p_safe_reason_codes)>64 or coalesce(array_ndims(p_safe_reason_codes),1)<>1
     or exists(select 1 from unnest(p_safe_reason_codes) r where r is null or r !~ '^[A-Z][A-Z0-9_-]{0,63}$')
     or (select count(distinct r) from unnest(p_safe_reason_codes) r)<>cardinality(p_safe_reason_codes)
     or octet_length(p_service_provenance::text)>65536 or octet_length(p_reviewer_provenance::text)>8192 then
    raise exception 'DECISION_OUTPUT_INVALID' using errcode='22023';
  end if;
  v_context:=private.need_publication_context(p_need_id,p_expected_revision,null);
  if v_context->>'kind'<>'READY' then raise exception 'PUBLICATION_CONTEXT_NOT_READY' using errcode='P0001',detail=v_context->>'code'; end if;
  if p_service_provenance is distinct from jsonb_build_object('evaluationContext',v_context->'binding') then
    raise exception 'PUBLICATION_CONTEXT_STALE' using errcode='PT409';
  end if;
  if p_policy_id is distinct from v_context#>>'{binding,policyId}' or p_jurisdiction is distinct from v_context#>>'{binding,jurisdiction}' then
    raise exception 'PUBLICATION_POLICY_STALE' using errcode='PT409';
  end if;
  if exists(select 1 from unnest(p_rule_ids) id where not exists(
       select 1 from jsonb_array_elements(v_context#>'{policy,rules}') r where r->>'ruleId'=id and (r->'outcomes') ? p_outcome))
     or exists(select 1 from unnest(p_safe_reason_codes) code where not exists(
       select 1 from jsonb_array_elements(v_context#>'{policy,rules}') r where r->>'ruleId'=any(p_rule_ids) and (r->'safeReasonCodes') ? code)) then
    raise exception 'DECISION_OUTPUT_NOT_IN_POLICY' using errcode='22023';
  end if;

  select * into v_need
    from public.needs
   where id = p_need_id
   for update;
  if not found then
    raise exception 'NEED_NOT_FOUND' using errcode='P0002';
  end if;
  if v_need.status <> 'DRAFT' then
    raise exception 'NEED_NOT_DRAFT' using errcode='P0001';
  end if;
  if v_need.revision <> p_expected_revision then
    raise exception 'NEED_REVISION_STALE' using errcode='PT409';
  end if;

  if not exists (
    select 1 from public.need_geography g
     where g.need_id = p_need_id
       and jsonb_typeof(g.public_topology) = 'object'
  ) then
    raise exception 'PUBLIC_GEOGRAPHY_NOT_CANONICAL' using errcode='P0001';
  end if;

  if not private.media_refs_ready(v_need.requester_account_id,v_need.public_photo_paths) then
    raise exception 'PUBLIC_MEDIA_REVIEW_AUTHORITY_NOT_READY' using errcode='P0001';
  end if;

  v_bundle_id := private.current_publication_policy_bundle(
    btrim(p_policy_id),
    btrim(p_jurisdiction),
    clock_timestamp()
  );
  if v_bundle_id is null then
    raise exception 'POLICY_BUNDLE_NOT_READY' using errcode='P0001';
  end if;

  select b.policy_id, b.version, b.jurisdiction
    into v_policy_id, v_policy_version, v_jurisdiction
    from private.publication_policy_bundles b
   where b.id = v_bundle_id;

  select coalesce(array_agg(x.rule_id order by x.rule_id), '{}'::text[])
    into v_rule_ids
    from (
      select distinct btrim(rid) as rule_id
        from unnest(coalesce(p_rule_ids, '{}'::text[])) rid
       where btrim(rid) <> ''
    ) x;

  if cardinality(v_rule_ids) = 0 then
    raise exception 'RULE_PROVENANCE_REQUIRED' using errcode='22023';
  end if;

  select count(*)::integer,
         coalesce(
           jsonb_agg(
             jsonb_build_object(
               'ruleId', r.rule_id,
               'provenance', r.rule_provenance
             ) order by r.rule_id
           ),
           '[]'::jsonb
         )
    into v_rule_count, v_rule_snapshot
    from private.publication_policy_rule_refs r
   where r.bundle_id = v_bundle_id
     and r.rule_id = any(v_rule_ids);

  if v_rule_count <> cardinality(v_rule_ids) then
    raise exception 'RULE_PROVENANCE_MISMATCH' using errcode='P0001';
  end if;

  select coalesce(array_agg(x.reason_code order by x.reason_code), '{}'::text[])
    into v_safe_reason_codes
    from (
      select distinct btrim(rc) as reason_code
        from unnest(coalesce(p_safe_reason_codes, '{}'::text[])) rc
       where btrim(rc) <> ''
    ) x;

  v_fp := private.need_publication_fingerprint_snapshot(p_need_id);
  if (v_fp->>'needRevision')::integer <> p_expected_revision then
    raise exception 'NEED_REVISION_STALE' using errcode='PT409';
  end if;

  v_identity_payload := jsonb_build_object(
    'needId', p_need_id,
    'needRevision', p_expected_revision,
    'canonicalFingerprint', v_fp->>'canonicalFingerprint',
    'policyBundleId', v_bundle_id,
    'policyId', v_policy_id,
    'policyVersion', v_policy_version,
    'jurisdiction', v_jurisdiction,
    'ruleIds', to_jsonb(v_rule_ids),
    'outcome', p_outcome,
    'safeReasonCodes', to_jsonb(v_safe_reason_codes),
    'decisionSource', btrim(p_decision_source),
    'providerRef', nullif(btrim(coalesce(p_provider_ref,'')),''),
    'modelRef', nullif(btrim(coalesce(p_model_ref,'')),''),
    'reviewerProvenance', p_reviewer_provenance,
    'serviceProvenance', p_service_provenance
  );
  v_identity := encode(
    extensions.digest(convert_to(v_identity_payload::text, 'UTF8'), 'sha256'),
    'hex'
  );

  if not private.publication_policy_bundle_ready(v_bundle_id,v_jurisdiction,clock_timestamp()) then raise exception 'POLICY_BUNDLE_NOT_READY' using errcode='P0001'; end if;

  insert into private.need_publication_decisions(
    need_id,
    need_revision,
    fingerprint_schema_version,
    canonical_fingerprint,
    private_materiality_marker,
    public_geography_snapshot,
    public_media_refs,
    policy_bundle_id,
    policy_id,
    policy_version,
    jurisdiction,
    rule_ids,
    rule_provenance_snapshot,
    outcome,
    safe_reason_codes,
    decision_source,
    provider_ref,
    model_ref,
    reviewer_provenance,
    service_provenance,
    decision_identity
  ) values (
    p_need_id,
    p_expected_revision,
    'NEED_PUBLICATION_FINGERPRINT_V1',
    v_fp->>'canonicalFingerprint',
    v_fp->>'privateMaterialityMarker',
    v_fp->'publicGeography',
    array(select jsonb_array_elements_text(v_fp->'publicMediaRefs')),
    v_bundle_id,
    v_policy_id,
    v_policy_version,
    v_jurisdiction,
    v_rule_ids,
    v_rule_snapshot,
    p_outcome,
    v_safe_reason_codes,
    btrim(p_decision_source),
    nullif(btrim(coalesce(p_provider_ref,'')),''),
    nullif(btrim(coalesce(p_model_ref,'')),''),
    p_reviewer_provenance,
    p_service_provenance,
    v_identity
  )
  on conflict (decision_identity) do nothing
  returning id, decision_sequence, created_at into v_decision_id, v_sequence, v_decision_at;

  if v_decision_id is null then
    select d.id, d.decision_sequence, d.created_at
      into v_decision_id, v_sequence, v_decision_at
      from private.need_publication_decisions d
     where d.decision_identity = v_identity;
  end if;

  return jsonb_build_object(
    'decisionId', v_decision_id,
    'decisionSequence', v_sequence,
    'needId', p_need_id,
    'needRevision', p_expected_revision,
    'canonicalFingerprint', v_fp->>'canonicalFingerprint',
    'policyBundleId', v_bundle_id,
    'policyVersion', v_policy_version,
    'jurisdiction', v_jurisdiction,
    'outcome', p_outcome,
    'decisionAt', v_decision_at,
    'ruleIds', to_jsonb(v_rule_ids),
    'safeReasonCodes', to_jsonb(v_safe_reason_codes),
    'publishable', p_outcome='ALLOW',
    'authoritative', true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_record_push_readiness(p_sender_version text, p_observation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare t timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_sender_version is distinct from 'PRE_V3_PUSH_READINESS_V1' or p_observation is null
 or p_observation not in('PROBE_ENABLED','PROBE_DISABLED','TICK_OK','TICK_DEGRADED','TICK_FAILED') then
  raise exception 'PUSH_READINESS_INPUT_INVALID' using errcode='22023'; end if;
 -- Timestamp AFTER serialization, so concurrent reports cannot move observed_at
 -- backwards or put last_success_at beyond a newer failed/disabled observation.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-runtime-readiness',11122));t:=clock_timestamp();
 insert into private.push_runtime_readiness(singleton,sender_version,observation,observed_at,last_success_at)
 values(true,p_sender_version,p_observation,t,case when p_observation='TICK_OK' then t end)
 on conflict(singleton) do update set sender_version=excluded.sender_version,observation=excluded.observation,observed_at=excluded.observed_at,
  last_success_at=case when excluded.observation='TICK_OK' then excluded.observed_at else private.push_runtime_readiness.last_success_at end;
 return jsonb_build_object('recorded',true,'observation',p_observation,'observedAt',t,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_redact_account_closure_step_service(p_account_id uuid, p_generation uuid, p_action_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare e private.closure_executions_v5;act private.closure_actions_v5;s private.closure_redaction_steps_v5;
 r record;plan jsonb;where_sql text;rel regclass;sets text;cnt integer:=0;more boolean;finished boolean;next_row jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 perform private.closure_erasure_lock_v5(p_account_id);
 select * into e from private.closure_executions_v5 where account_id=p_account_id and generation=p_generation;
 perform private.closure_erasure_assert_current_v5(e);
 select * into act from private.closure_actions_v5 where id=p_action_id and generation=e.generation and account_id=e.account_id for update;
 if not found or act.kind<>'RELATIONAL_REDACT' or p_attempt_id is null or act.attempt_id is distinct from p_attempt_id or act.state='PENDING' then raise exception 'CLOSURE_ATTEMPT_STALE' using errcode='PT409';end if;
 if exists(select 1 from private.closure_actions_v5 where generation=e.generation and kind='STORAGE_DELETE' and state<>'VERIFIED') then raise exception 'CLOSURE_STORAGE_NOT_CLEAN' using errcode='55000';end if;
 select * into s from private.closure_redaction_steps_v5 where action_id=act.id and state='PENDING' order by ordinal limit 1 for update;
 if found then
  where_sql:=private.closure_redaction_scope_v5(s.relation_name);rel:=s.relation_name::regclass;
  if where_sql is null then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
  for r in execute format('select t.ctid as row_ctid,to_jsonb(t) as row_json from %s t where (%s) and private.closure_redaction_patch_v5($2,to_jsonb(t),$1,$3) is not null order by t.ctid limit 100 for update of t',rel,where_sql) using e.account_id,s.relation_name,e.generation loop
   plan:=private.closure_redaction_patch_v5(s.relation_name,r.row_json,e.account_id,e.generation);
   if plan is null then continue;end if;
   insert into private.closure_redaction_certificate_v5 values(pg_backend_pid(),txid_current(),e.account_id,e.generation,act.id,rel::oid,plan->>'operation',
    encode(extensions.digest(convert_to(r.row_json::text,'UTF8'),'sha256'),'hex'),plan->'patch');
   if plan->>'operation'='DELETE' then
    execute format('delete from %s where ctid=$1',rel) using r.row_ctid;
   elsif plan->>'operation'='UPDATE' then
    select string_agg(format('%I=(jsonb_populate_record(NULL::%s,$2)).%I',k,rel,k),',' order by k) into sets from jsonb_object_keys(plan->'patch') k;
    execute format('update %s as target set %s where ctid=$1 returning to_jsonb(target)',rel,sets) into next_row using r.row_ctid,plan->'patch';
    if rel='public.needs'::regclass and plan->'patch'@>'{"approximate_lat":null,"approximate_lng":null}'::jsonb and next_row->'approx_geog' is distinct from 'null'::jsonb then raise exception 'ERASURE_GENERATED_LOCATION_NOT_CLEAN';end if;
   else raise exception 'ERASURE_PATCH_INVALID';end if;
   delete from private.closure_redaction_certificate_v5 where backend_pid=pg_backend_pid() and transaction_id=txid_current();cnt:=cnt+1;
  end loop;
  execute format('select exists(select 1 from %s t where (%s) and private.closure_redaction_patch_v5($2,to_jsonb(t),$1,$3) is not null)',rel,where_sql) into more using e.account_id,s.relation_name,e.generation;
  if not more and rel='public.ai_structured_facts'::regclass and exists(select 1 from public.ai_structured_facts f where account_id=e.account_id and not exists(select 1 from private.retention_holds h where h.account_id=e.account_id and h.active and h.conversation_id=f.conversation_id)) then raise exception 'ERASURE_FOREIGN_REFERENCE';end if;
  update private.closure_redaction_steps_v5 set affected_rows=affected_rows+cnt,state=case when more then 'PENDING' else 'VERIFIED' end,verified_at=case when more then null else clock_timestamp() end where action_id=act.id and ordinal=s.ordinal;
 end if;
 finished:=not exists(select 1 from private.closure_redaction_steps_v5 where action_id=act.id and state<>'VERIFIED');
 if finished and act.state<>'VERIFIED' then update private.closure_actions_v5 set state='VERIFIED',verified_at=clock_timestamp(),evidence='RELATIONAL_ORDINARY_CONTENT_ERASED' where id=act.id;end if;
 return jsonb_build_object('accountId',e.account_id,'generation',e.generation,'actionId',act.id,'attemptId',act.attempt_id,'kind','RELATIONAL_REDACT',
  'state',case when finished then 'VERIFIED' else 'DISPATCHED' end,'rowsChanged',cnt,'completedSteps',(select count(*) from private.closure_redaction_steps_v5 where action_id=act.id and state='VERIFIED'),
  'totalSteps',cardinality(private.closure_redaction_relations_v5()),'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_remove_task_photo(p_conversation_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations; a private.owned_media_assets; refs text[];
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 c:=private.media_assert_task_edit(auth.uid(),p_conversation_id); refs:=private.media_task_refs(c.id);
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=auth.uid() and scope='TASK' for update;
 if not found or (a.conversation_id<>c.id and not(a.storage_path=any(refs))) then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 if a.conversation_id=c.id then update private.owned_media_assets set selected=false where id=a.id; end if;
 perform private.media_write_task_refs(c,array_remove(refs,a.storage_path));
 return public.rpc_read_task_photos(c.id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_renew_data_export_lease(p_receipt_id uuid, p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts; b jsonb; v_now timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 r:=private.data_export_lock(p_receipt_id,null);v_now:=clock_timestamp();
 select * into a from private.data_export_artifacts where id=p_attempt_id and receipt_id=r.id for update;
 if not found or r.active_export_attempt_id is distinct from a.id or r.status<>'PROCESSING' or r.export_revoked_at is not null or a.lease_until<=v_now or a.artifact_expires_at<=v_now then raise exception 'EXPORT_ATTEMPT_STALE' using errcode='PT409'; end if;
 b:=private.data_export_policy_binding();if b is null or b->>'sha256'<>a.policy_sha256 then raise exception 'EXPORT_POLICY_CHANGED' using errcode='PT409'; end if;
 update private.data_export_artifacts set lease_until=least(v_now+interval '120 seconds',artifact_expires_at) where id=a.id returning * into a;
 return jsonb_build_object('receiptId',r.id,'attemptId',a.id,'leaseExpiresAt',a.lease_until);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_reopen_remaining_search(p_need_id uuid, p_expected_revision integer, p_expected_closed_at timestamp with time zone, p_client_request_id text, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_request_id text := btrim(coalesce(p_client_request_id,''));
  v_reason text := left(btrim(coalesce(p_reason,'')),500);
  v_request_hash text;
  v_existing private.remaining_search_close_commands%rowtype;
  v_need public.needs%rowtype;
  v_selected_slots integer := 0;
  v_remaining integer := 0;
  v_at timestamptz;
  v_result jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'NEED_ID_REVISION_REQUIRED' using errcode='22023';
  end if;
  if p_expected_closed_at is null or not isfinite(p_expected_closed_at) then
    raise exception 'SEARCH_CLOSURE_WITNESS_REQUIRED' using errcode='22023';
  end if;
  if char_length(v_request_id) not between 8 and 193 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;

  v_request_hash := encode(
    extensions.digest(convert_to(jsonb_build_object(
      'command','REOPEN_REMAINING_SEARCH_V1',
      'needId',p_need_id,'expectedRevision',p_expected_revision,'reason',v_reason,
      'expectedClosedAtEpoch',extract(epoch from p_expected_closed_at)
    )::text,'UTF8'),'sha256'),'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || E'\n' || ('reopen:'||v_request_id), 4410));

  select * into v_existing
  from private.remaining_search_close_commands c
  where c.requester_account_id=v_actor and c.client_request_id='reopen:'||v_request_id
  for update;
  if found then
    if v_existing.request_hash is distinct from v_request_hash
       or v_existing.result->>'command' is distinct from 'REOPEN_REMAINING_SEARCH_V1'
       or v_existing.result->>'needId' is distinct from p_need_id::text
       or v_existing.result->'remainingSearchClosed' is distinct from 'false'::jsonb
       or v_existing.result->'authoritative' is distinct from 'true'::jsonb then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='PT409';
    end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;

  select * into v_need from public.needs n where n.id=p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id <> v_actor then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.revision <> p_expected_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;
  if v_need.remaining_search_closed_at is distinct from p_expected_closed_at then
    raise exception 'STALE_SEARCH_STATE' using errcode='PT409';
  end if;
  if v_need.remaining_search_closed_at is null then
    raise exception 'REMAINING_SEARCH_ALREADY_OPEN' using errcode='P0001';
  end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then
    raise exception 'NEED_REMAINING_SEARCH_NOT_REOPENABLE' using errcode='P0001';
  end if;

  select coalesce(sum(s.covered_slots),0)::integer into v_selected_slots
  from public.need_selections s
  where s.need_id=v_need.id and s.status='SELECTED';

  v_remaining := greatest(v_need.required_slots-v_selected_slots,0);
  if v_remaining < 1 then raise exception 'NO_REMAINING_SEARCH' using errcode='P0001'; end if;
  -- Sample after the Need lock: a request may have waited across the execution boundary.
  v_at := clock_timestamp();
  if not private.need_search_time_admitted_v1(v_need.id,v_at) then
    raise exception 'REMAINING_SEARCH_REOPEN_WINDOW_CLOSED' using errcode='P0001';
  end if;
  if private.closure_account_restricted(v_actor) then
    raise exception 'ACCOUNT_CLOSING' using errcode='P0001';
  end if;

  perform set_config('uskoci.need_lifecycle','CLOSE_REMAINING_SEARCH',true);
  update public.needs
     set remaining_search_closed_at=null,
         remaining_search_closed_by_account_id=null,
         remaining_search_close_reason=null,
         updated_at=v_at
   where id=v_need.id;
  perform set_config('uskoci.need_lifecycle','',true);

  perform private.enqueue_dispatch(v_need.id,v_at);

  perform private.audit_marketplace(
    v_actor,'REMAINING_SEARCH_REOPENED','NEED',v_need.id,v_need.revision,
    jsonb_build_object(
      'requiredSlots',v_need.required_slots,
      'selectedSlots',v_selected_slots,
      'reopenedRemainingSlots',v_remaining,
      'reasonProvided',v_reason<>''
    )
  );

  v_result := jsonb_build_object(
    'command','REOPEN_REMAINING_SEARCH_V1',
    'observedClosedAt',p_expected_closed_at,
    'needId',v_need.id,
    'revision',v_need.revision,
    'status',v_need.status,
    'requiredSlots',v_need.required_slots,
    'selectedSlots',v_selected_slots,
    'reopenedRemainingSlots',v_remaining,
    'remainingSearchClosed',false,
    'reopenedAt',v_at,
    'idempotentReplay',false,
    'authoritative',true
  );

  insert into private.remaining_search_close_commands(
    requester_account_id,client_request_id,request_hash,need_id,need_revision,result
  ) values(v_actor,'reopen:'||v_request_id,v_request_hash,v_need.id,v_need.revision,v_result);

  return v_result;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_report_problem(p_agreement_id uuid, p_narrative text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid:=auth.uid();
  v_need_id uuid;
  n public.needs%rowtype;
  a public.agreements%rowtype;
  x public.agreement_execution%rowtype;
  narrative text:=nullif(btrim(p_narrative),'');
  first_report boolean;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if narrative is null then raise exception 'NARRATIVE_REQUIRED' using errcode='22023'; end if;
  if length(narrative)>4000 then raise exception 'NARRATIVE_TOO_LONG' using errcode='22023'; end if;

  select ag.need_id into v_need_id from public.agreements ag where ag.id=p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;

  select * into n from public.needs nd where nd.id=v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into a from public.agreements ag where ag.id=p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if uid<>a.requester_account_id and uid<>a.worker_account_id then
    raise exception 'NOT_PARTY' using errcode='42501';
  end if;
  if a.status<>'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_REPORTABLE' using errcode='P0001',detail=a.status;
  end if;

  select * into x from public.agreement_execution ex where ex.agreement_id=a.id for update;
  if not found then raise exception 'EXECUTION_NOT_FOUND' using errcode='P0002'; end if;
  if x.state not in ('CONFIRMED','AWAITING_REQUESTER') then
    raise exception 'EXECUTION_NOT_REPORTABLE' using errcode='P0001',detail=x.state;
  end if;

  first_report:=x.problem_opened_at is null;

  update public.agreement_execution ex
     set problem_opened_at=coalesce(ex.problem_opened_at,statement_timestamp()),
         problem_narrative=coalesce(ex.problem_narrative,narrative),
         problem_opened_by=coalesce(ex.problem_opened_by,uid),
         updated_at=statement_timestamp()
   where ex.agreement_id=a.id
  returning ex.* into x;

  if first_report then
    if not private.safety_pair_blocked(a.requester_account_id,a.worker_account_id)
     and not private.closure_account_restricted(a.requester_account_id) and not private.closure_account_restricted(a.worker_account_id) then
    insert into public.agreement_messages(agreement_id,agreement_version,sender_account_id,body)
    values (a.id,a.current_version,uid,'⚠️ Prijavljen problem: '||narrative);
    end if;

    perform private.emit_event(
      case when uid=a.requester_account_id then a.worker_account_id else a.requester_account_id end,
      case when uid=a.requester_account_id then 'WORKER' else 'REQUESTER' end,
      'RECOVERY_OPENED',
      'AGREEMENT',a.id,a.current_version,
      'Prijavljen je problem',
      'Otvorite Dogovor da vidite prijavljeni problem.',
      'problem:'||a.id::text||':'||a.current_version::text,
      'NORMAL',
      jsonb_build_object('reportedByRole',
        case when uid=a.requester_account_id then 'REQUESTER' else 'WORKER' end),
      null
    );
  end if;

  return jsonb_build_object(
    'agreementId',a.id,
    'problemOpenedAt',x.problem_opened_at,
    'problemOpenedBy',x.problem_opened_by,
    'idempotentReplay',not first_report,
    'noAutomaticFaultOrDebt',true,
    'authoritative',true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_request_data_export(p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=auth.uid();
  v_request_id text:=btrim(coalesce(p_client_request_id,''));
  existing public.data_export_requests%rowtype;
  open_request public.data_export_requests%rowtype;
  created public.data_export_requests%rowtype;
begin
  if u is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if char_length(v_request_id)<16 or char_length(v_request_id)>96 or v_request_id !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'INVALID_CLIENT_REQUEST_ID' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('uskoci:data-export:'||u::text,0));

  select * into existing from public.data_export_requests d
  where d.account_id=u and d.client_request_id=v_request_id;
  if found then
    return jsonb_build_object(
      'receiptId',existing.id,'clientRequestId',existing.client_request_id,
      'status',existing.status,'requestedAt',existing.requested_at,
      'idempotentReplay',true,'downloadAvailable',false,'serverFulfillmentRequired',true
    );
  end if;

  -- PKG-029d (deep read 6.2): without a delivery policy no export can ever be delivered; say so instead of
  -- accepting a request that nothing would fulfil.
  if private.data_export_policy_binding() is null then
    raise exception 'DATA_EXPORT_POLICY_NOT_READY' using errcode='55000';
  end if;

  select * into open_request from public.data_export_requests d
  where d.account_id=u and d.status in ('REQUESTED','PROCESSING')
  order by d.requested_at desc limit 1;
  if open_request.id is not null then
    raise exception 'DATA_EXPORT_REQUEST_ALREADY_OPEN' using errcode='55000';
  end if;

  insert into public.data_export_requests(account_id,client_request_id)
  values(u,v_request_id)
  returning * into created;

  perform private.audit_marketplace(u,'DATA_EXPORT_REQUESTED','SYSTEM',created.id,null,
    jsonb_build_object('kind',created.request_kind,'source',created.request_source));

  return jsonb_build_object(
    'receiptId',created.id,'clientRequestId',created.client_request_id,
    'status',created.status,'requestedAt',created.requested_at,
    'idempotentReplay',false,'downloadAvailable',false,'serverFulfillmentRequired',true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_activity_application_v1(p_expected_user_id uuid, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
 u uuid := private.support_auth_v5(p_expected_user_id);
 v_need uuid;
 v_response uuid;
 v_worker uuid;
 v_type text;
 unavailable jsonb := jsonb_build_object('schema','ACTIVITY_APPLICATION_TARGET_V1',
   'accountId',u,'kind','UNAVAILABLE','authoritative',true);
begin
 select n.id,r.id,r.worker_account_id,e.event_type
 into v_need,v_response,v_worker,v_type
 from public.user_activity_events e
 join public.marketplace_responses r on r.id=e.entity_id
 join public.needs n on n.id=r.need_id
 join public.marketplace_response_versions rv on rv.response_id=r.id and rv.version=e.entity_version
 join public.notification_deliveries d on d.event_id=e.id
   and d.recipient_user_id=u and d.recipient_role='REQUESTER'
   and d.channel='IN_APP' and d.dedupe_key=e.dedupe_key||':in_app'
 where e.id=p_event_id and e.recipient_user_id=u and e.recipient_role='REQUESTER'
   and e.event_type in ('RESPONSE_RECEIVED','RESPONSE_UPDATED')
   and e.entity_type='RESPONSE' and e.entity_version>0
   and e.entity_version=r.current_version
   and rv.need_revision=n.revision
   and ((e.event_type='RESPONSE_RECEIVED' and e.entity_version=1
      and e.dedupe_key='response-received:'||r.id::text||':1')
    or (e.event_type='RESPONSE_UPDATED' and e.entity_version>1
      and e.dedupe_key='response-updated:'||r.id::text||':'||e.entity_version::text))
   and e.payload->>'needId'=n.id::text
   and e.payload->>'responseId'=r.id::text
   and e.payload->>'responseVersion'=e.entity_version::text
   and n.requester_account_id=u and r.worker_account_id<>u
   and n.status in ('PUBLISHED','SELECTION')
   and r.status in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
   and r.submitted_against_need_revision=n.revision
   and d.state in ('CREATED','SENT','DELIVERED','READ') and d.suppression_reason is null
   and private.accounts_same_world(u,r.worker_account_id)
   and not private.safety_event_blocked(e)
   and exists (select 1 from private.need_candidate_states_v5(n.id,array[r.id]) c
     where c.response_id=r.id and c.candidate_state='SELECTABLE')
 limit 1;
 if not found then
   perform private.support_auth_v5(u);
   return unavailable;
 end if;
 begin
   perform private.closure_assert_open(u,v_worker);
 exception when sqlstate '42501' then
   perform private.support_auth_v5(u);
   return unavailable;
 end;
 perform private.support_auth_v5(u);
 return jsonb_build_object('schema','ACTIVITY_APPLICATION_TARGET_V1',
   'accountId',u,'kind','APPLICATION','eventId',p_event_id,'eventType',v_type,
   'needId',v_need,'responseId',v_response,'role','REQUESTER','authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_activity_event(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  e public.user_activity_events%rowtype;
  a public.agreements%rowtype;
  r public.marketplace_responses%rowtype;
  n public.needs%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  select * into e from public.user_activity_events where id=p_event_id and recipient_user_id=v_uid
    and exists(select 1 from public.notification_deliveries d where d.event_id=public.user_activity_events.id
      and d.recipient_user_id=v_uid and d.channel='IN_APP' and d.state<>'SUPPRESSED');
  if not found then raise exception 'EVENT_NOT_FOUND' using errcode='P0002'; end if;
  if e.entity_type='AGREEMENT' then
    select * into a from public.agreements where id=e.entity_id
      and v_uid in (requester_account_id,worker_account_id);
    if found then return jsonb_build_object('kind','AGREEMENT','id',a.id,'role',e.recipient_role); end if;
  elsif e.entity_type='RESPONSE' then
    select * into r from public.marketplace_responses where id=e.entity_id;
    if found then
      select * into a from public.agreements where selected_response_id=r.id
        and v_uid in (requester_account_id,worker_account_id) order by created_at desc,id desc limit 1;
      if found then return jsonb_build_object('kind','AGREEMENT','id',a.id,'role',e.recipient_role); end if;
      if r.worker_account_id=v_uid then return jsonb_build_object('kind','APPLICATIONS','id',r.id,'role','WORKER'); end if;
      select id into n.id from public.needs where id=r.need_id and public.is_my_task(id);
      if found then return jsonb_build_object('kind','CANDIDATES','id',n.id,'role','REQUESTER'); end if;
    end if;
  elsif e.entity_type='CLARIFICATION' then
    -- Only the existing safe context ID; current Need RLS is checked again.
    if coalesce(e.payload->>'needId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then return jsonb_build_object('kind','UNAVAILABLE'); end if;
    select id into n.id from public.needs where id=(e.payload->>'needId')::uuid;
    if found then return jsonb_build_object('kind',case when public.is_my_task(n.id) then 'OWN_NEED' else 'OPPORTUNITY' end,
      'id',n.id,'role',case when public.is_my_task(n.id) then 'REQUESTER' else 'WORKER' end); end if;
  elsif e.entity_type='NEED' then
    select id into n.id from public.needs where id=e.entity_id;
    if found then return jsonb_build_object('kind',case when public.is_my_task(n.id) then 'OWN_NEED' else 'OPPORTUNITY' end,
      'id',n.id,'role',case when public.is_my_task(n.id) then 'REQUESTER' else 'WORKER' end); end if;
  end if;
  return jsonb_build_object('kind','UNAVAILABLE');
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_activity_message_v1(p_expected_user_id uuid, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=private.support_auth_v5(p_expected_user_id);
  ag public.agreements; target_message uuid; target_role text;
  unavailable jsonb:=jsonb_build_object('schema','ACTIVITY_MESSAGE_TARGET_V1',
    'accountId',u,'kind','UNAVAILABLE','authoritative',true);
begin
  -- The first lookup reveals nothing. It identifies the two closure locks before
  -- the final authoritative join; foreign/unknown IDs have the same envelope.
  select g.* into ag from public.user_activity_events e
    join public.agreements g on g.id=e.entity_id
    where e.id=p_event_id and e.recipient_user_id=u
      and e.event_type='MESSAGE_RECEIVED' and e.entity_type='AGREEMENT'
      and (u=g.requester_account_id or u=g.worker_account_id);
  if not found then
    perform private.support_auth_v5(u);return unavailable;
  end if;
  if (u is distinct from ag.requester_account_id and u is distinct from ag.worker_account_id)
    or ag.requester_account_id is null or ag.worker_account_id is null
    or ag.requester_account_id=ag.worker_account_id then
    perform private.support_auth_v5(u);return unavailable;
  end if;
  begin
    -- Same ordered shared account locks as canonical writers; a closing caller
    -- OR counterpart makes an event unavailable. No closure state is returned.
    perform private.closure_assert_open(ag.requester_account_id,ag.worker_account_id);
  exception when sqlstate '42501' then
    perform private.support_auth_v5(u);return unavailable;
  end;
  target_role:=case when u=ag.requester_account_id then 'REQUESTER' else 'WORKER' end;
  select m.id into target_message from public.user_activity_events e
    join public.agreements g on g.id=e.entity_id
    join public.agreement_messages m on m.id=case
      when jsonb_typeof(e.payload->'message_id')='string'
        and (e.payload->>'message_id')~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then (e.payload->>'message_id')::uuid else null end
    where e.id=p_event_id and e.recipient_user_id=u and e.recipient_role=target_role
      and e.event_type='MESSAGE_RECEIVED' and e.entity_type='AGREEMENT'
      and g.id=ag.id and g.requester_account_id=ag.requester_account_id
      and g.worker_account_id=ag.worker_account_id
      and m.agreement_id=g.id and m.agreement_version=e.entity_version
      and m.sender_account_id=case when target_role='REQUESTER' then g.worker_account_id else g.requester_account_id end
      and e.dedupe_key='agreement_message:'||m.id::text
      and exists(select 1 from public.notification_deliveries d
        where d.event_id=e.id and d.recipient_user_id=u and d.recipient_role=target_role
          and d.channel='IN_APP' and d.dedupe_key=e.dedupe_key||':in_app'
          -- Delivery expiry stops new delivery, not access to an exact historical
          -- target still shown by Inbox. Canonical ACK changes e.read_at only;
          -- cancellation expires CREATED deliveries whether read or unread.
          -- Queue/retry/failure/suppression never admit a historical target.
          and d.state in('CREATED','SENT','DELIVERED','READ','EXPIRED')
          and d.suppression_reason is null);
  perform private.support_auth_v5(u);
  if target_message is null then return unavailable;end if;
  -- No current-status/version equality: terminal/historical Agreement messages
  -- remain exact targets while their current authorization and delivery permit.
  return jsonb_build_object('schema','ACTIVITY_MESSAGE_TARGET_V1','accountId',u,
    'kind','AGREEMENT_MESSAGE','eventId',p_event_id,'agreementId',ag.id,
    'messageId',target_message,'role',target_role,'authoritative',true);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_activity_opportunity_v1(p_expected_user_id uuid, p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
 u uuid := private.support_auth_v5(p_expected_user_id);
 v_need uuid;
 v_requester uuid;
 unavailable jsonb := jsonb_build_object('schema','ACTIVITY_OPPORTUNITY_TARGET_V1',
   'accountId',u,'kind','UNAVAILABLE','authoritative',true);
begin
 select n.id,n.requester_account_id into v_need,v_requester
 from public.user_activity_events e
 join public.needs n on n.id=e.entity_id
 join public.opportunity_deliveries od
   on od.worker_account_id=u and od.need_id=n.id and od.need_revision=n.revision
 join public.app_profiles p on p.id=od.worker_profile_id and p.account_id=u
 join public.notification_deliveries d
   on d.event_id=e.id and d.recipient_user_id=u and d.recipient_role='WORKER'
   and d.channel='IN_APP' and d.dedupe_key=e.dedupe_key||':in_app'
 where e.id=p_event_id and e.recipient_user_id=u
   and e.recipient_role='WORKER' and e.event_type='OPPORTUNITY_AVAILABLE'
   and e.entity_type='NEED' and e.entity_version=n.revision
   and e.dedupe_key='opp:'||n.id::text||':'||n.revision::text||':'||u::text
   and n.status in ('PUBLISHED','SELECTION')
   and n.requester_account_id<>u and n.requester_account_id is not null
   and p.kind='WORKER' and p.profile_status='ACTIVE'
   and od.status in ('READY','SEEN','RESPONDED')
   and od.expires_at>clock_timestamp()
   and d.state in ('CREATED','SENT','DELIVERED','READ')
   and d.suppression_reason is null
   and private.accounts_same_world(n.requester_account_id,u)
   and not private.safety_event_blocked(e)
 limit 1;
 if not found then
   perform private.support_auth_v5(u);
   return unavailable;
 end if;
 begin
   perform private.closure_assert_open(u,v_requester);
 exception when sqlstate '42501' then
   perform private.support_auth_v5(u);
   return unavailable;
 end;
 perform private.support_auth_v5(u);
 return jsonb_build_object('schema','ACTIVITY_OPPORTUNITY_TARGET_V1',
  'accountId',u,'kind','OPPORTUNITY','eventId',p_event_id,
  'needId',v_need,'role','WORKER','authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_data_export_download(p_receipt_id uuid, p_download_grant_id uuid, p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare r public.data_export_requests; a private.data_export_artifacts;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 if p_account_id is null or p_download_grant_id is null then raise exception 'EXPORT_GRANT_EXPIRED' using errcode='55000'; end if;
 r:=private.data_export_lock(p_receipt_id,p_account_id);
 if private.data_export_descriptor(r.id,r.account_id) is null then raise exception 'EXPORT_NOT_READY' using errcode='55000'; end if;
 select * into a from private.data_export_artifacts where id=r.active_export_attempt_id for update;
 if a.download_grant_id is distinct from p_download_grant_id or a.download_grant_expires_at<=clock_timestamp() then raise exception 'EXPORT_GRANT_EXPIRED' using errcode='55000'; end if;
 return jsonb_build_object('receiptId',r.id,'accountId',r.account_id,'downloadGrantId',a.download_grant_id,'artifactGeneration',a.id,'expiresAt',least(a.download_grant_expires_at,a.artifact_expires_at),'artifactExpiresAt',a.artifact_expires_at,'bucket','data-export-artifacts','objectPath',a.object_path,'byteLength',a.byte_length,'sha256',a.sha256,'md5',a.md5);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_resolve_stale_response_after_need_edit(p_response_id uuid, p_expected_response_version integer, p_expected_need_revision integer, p_client_request_id text, p_action text, p_covered_slots integer, p_price_rsd integer, p_proposed_start_at timestamp with time zone, p_proposed_end_at timestamp with time zone, p_scope_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_request_id text := btrim(coalesce(p_client_request_id,''));
  v_action text := upper(btrim(coalesce(p_action,'')));
  v_request_hash text;
  v_existing private.response_revision_resolution_commands%rowtype;
  v_need_id uuid;
  v_need public.needs%rowtype;
  v_response public.marketplace_responses%rowtype;
  v_match jsonb;
  v_profile public.app_profiles;
  v_selected_slots integer;
  v_remaining_slots integer;
  v_new_version integer;
  v_covered integer;
  v_price integer;
  v_start timestamptz;
  v_end timestamptz;
  v_note text;
  v_content_hash text;
  v_result jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_response_id is null or p_expected_response_version is null or p_expected_response_version < 1
     or p_expected_need_revision is null or p_expected_need_revision < 1 then
    raise exception 'RESPONSE_VERSION_NEED_REVISION_REQUIRED' using errcode='22023';
  end if;
  if char_length(v_request_id) not between 8 and 200 then raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023'; end if;
  if v_action not in ('KEEP','UPDATE','WITHDRAW') then raise exception 'STALE_RESPONSE_ACTION_INVALID' using errcode='22023'; end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(jsonb_build_object(
        'responseId', p_response_id,
        'expectedResponseVersion', p_expected_response_version,
        'expectedNeedRevision', p_expected_need_revision,
        'action', v_action,
        'coveredSlots', p_covered_slots,
        'priceRsd', p_price_rsd,
        'proposedStartAt', p_proposed_start_at,
        'proposedEndAt', p_proposed_end_at,
        'scopeNote', coalesce(p_scope_note,'')
      )::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || E'\n' || v_request_id, 4405));

  select * into v_existing
    from private.response_revision_resolution_commands c
   where c.worker_account_id = v_actor
     and c.client_request_id = v_request_id
   for update;
  if found then
    if v_existing.request_hash <> v_request_hash then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023'; end if;
    return v_existing.result || jsonb_build_object('idempotentReplay', true);
  end if;

  select r.need_id into v_need_id from public.marketplace_responses r where r.id = p_response_id;
  if not found then raise exception 'RESPONSE_NOT_FOUND' using errcode='P0002'; end if;

  select * into v_need from public.needs n where n.id = v_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;

  select * into v_response from public.marketplace_responses r where r.id = p_response_id for update;
  if not found then raise exception 'RESPONSE_NOT_FOUND' using errcode='P0002'; end if;

  if v_response.worker_account_id <> v_actor then raise exception 'RESPONSE_NOT_OWNED' using errcode='42501'; end if;
  if v_response.current_version <> p_expected_response_version then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;
  if v_need.revision <> p_expected_need_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;
  if v_response.status <> 'STALE_REVIEW_REQUIRED' then raise exception 'RESPONSE_NOT_AWAITING_REVIEW' using errcode='P0001'; end if;
  if v_response.submitted_against_need_revision >= v_need.revision then raise exception 'RESPONSE_ALREADY_CURRENT' using errcode='P0001'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then raise exception 'NEED_NOT_OPEN' using errcode='P0001'; end if;
  if exists (select 1 from public.agreements a where a.selected_response_id = v_response.id) then
    raise exception 'RESPONSE_ALREADY_SELECTED' using errcode='P0001';
  end if;

  if v_action = 'WITHDRAW' then
    update public.notification_deliveries d set state='EXPIRED'
      from public.user_activity_events e
      where d.event_id=e.id and e.entity_type='RESPONSE' and e.entity_id=v_response.id
        and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');
    update public.marketplace_responses
       set status = 'WITHDRAWN', withdrawn_at = statement_timestamp(), selected_at = null
     where id = v_response.id
     returning * into v_response;

    perform private.emit_event(v_need.requester_account_id,'REQUESTER','RESPONSE_WITHDRAWN',
      'RESPONSE',v_response.id,v_response.current_version,
      'Prijava je povučena','Prijava za tvoj zadatak je povučena.',
      'response-withdrawn:'||v_response.id::text||':'||v_response.current_version::text,
      'NORMAL',jsonb_build_object('needId',v_need.id,'needRevision',v_need.revision),null);
    if (v_need.response_deadline is null or v_need.response_deadline > statement_timestamp())
       and public.fn_need_covered_slots(v_need.id) < v_need.required_slots then
      perform private.enqueue_dispatch(v_need.id,statement_timestamp());
    end if;

    v_result := jsonb_build_object(
      'responseId', v_response.id,
      'needId', v_need.id,
      'needRevision', v_need.revision,
      'version', v_response.current_version,
      'status', v_response.status,
      'action', v_action,
      'idempotentReplay', false,
      'authoritative', true
    );
  else
    -- PKG-033: reconfirmation is an application to today's task, not a bypass.
    -- Withdrawal stays possible without a ready profile or matching world.
    if not private.accounts_same_world(v_need.requester_account_id, v_actor) then
      raise exception 'NEED_NOT_FOUND' using errcode='P0002';
    end if;
    if v_need.response_deadline is not null and v_need.response_deadline <= statement_timestamp() then
      raise exception 'RESPONSE_WINDOW_EXPIRED' using errcode='22023';
    end if;
    -- KEEP/UPDATE is a new application to the current task. WITHDRAW and
    -- committed idempotent replays remain outside this admission check.
    if not private.need_search_time_admitted_v1(v_need.id,clock_timestamp()) then
      raise exception 'NEED_EXECUTION_WINDOW_EXPIRED' using errcode='PT409',
        hint='Vreme za ovaj zadatak je isteklo.';
    end if;
    select * into v_profile from public.app_profiles p
      where p.id = v_response.worker_profile_id for update;
    if not found or v_profile.account_id <> v_actor or v_profile.kind <> 'WORKER' then
      raise exception 'PROFILE_NOT_OWNED_BY_ACCOUNT' using errcode='42501';
    end if;
    if v_profile.profile_status is distinct from 'ACTIVE'
       or char_length(btrim(coalesce(v_profile.display_name,''))) < 2
       or char_length(btrim(coalesce(v_profile.city,''))) < 2
       or cardinality(coalesce(v_profile.skills,'{}')) < 1 then
      raise exception 'WORKER_PROFILE_NOT_READY' using errcode='P0001';
    end if;
    select coalesce(sum(s.covered_slots),0)::integer into v_selected_slots
      from public.need_selections s where s.need_id=v_need.id and s.status='SELECTED';
    v_remaining_slots := greatest(0, v_need.required_slots-v_selected_slots);
    if v_remaining_slots < 1 then raise exception 'NEED_FULL' using errcode='P0001'; end if;

    if v_action = 'KEEP' then
      v_covered := v_response.covered_slots;
      v_price := v_response.price_rsd;
      v_start := v_response.proposed_start_at;
      v_end := v_response.proposed_end_at;
      v_note := v_response.scope_note;
    else
      v_covered := p_covered_slots;
      v_price := p_price_rsd;
      v_start := p_proposed_start_at;
      v_end := p_proposed_end_at;
      v_note := coalesce(p_scope_note,'');
    end if;

    if v_covered is null or v_covered < 1 then
      raise exception 'INVALID_COVERED_SLOTS' using errcode='22023';
    end if;
    -- WPP01: no personal-profile team limit; keep the task remaining-slot bound.
    if v_covered > v_remaining_slots then
      raise exception 'NEED_REMAINING_CAPACITY_EXCEEDED' using errcode='22023';
    end if;
    perform private.assert_application_price_v5(v_need, v_covered, v_price);
    if (v_start is null) <> (v_end is null)
       or (v_start is not null and v_end is not null and v_start >= v_end) then
      raise exception 'INVALID_PROPOSED_INTERVAL' using errcode='22023';
    end if;
    if char_length(coalesce(v_note,'')) > 1200 then raise exception 'SCOPE_NOTE_TOO_LONG' using errcode='22023'; end if;
    if v_start is null and v_need.schedule_kind='FIXED_WINDOW'
      and (v_need.starts_at is null or not isfinite(v_need.starts_at)
        or (v_need.ends_at is not null and (not isfinite(v_need.ends_at) or v_need.starts_at>=v_need.ends_at))) then
      raise exception 'NEED_FIXED_INTERVAL_INVALID' using errcode='22023';
    end if;
    v_match := private.match_detail_for_calendar_interval(v_need.id, v_response.worker_profile_id,
      coalesce(v_start,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.starts_at end),
      coalesce(v_end,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.ends_at end));
    if not coalesce((v_match->>'responseAllowed')::boolean,false) then
      raise exception 'WORKER_NOT_ELIGIBLE' using errcode='P0001', detail=coalesce((v_match->'hardBlockers')::text,'[]');
    end if;

  v_content_hash := encode(sha256(convert_to(jsonb_build_object(
    'needRevision', v_need.revision,
    'pricingMode', v_need.mode,
    'priceRsd', v_price,
    'coveredSlots', v_covered,
    'proposedStartAt', v_start,
    'proposedEndAt', v_end,
    'scopeNote', coalesce(btrim(v_note), ''),
    'snapshotSchema', 'APPLICATION_V1_SELF_DECLARED',
    'workerTeamCapacity', v_profile.team_capacity,
    'workerSkills', to_jsonb(v_profile.skills),
    'workerTools', '[]'::jsonb,
    'workerLicenses', to_jsonb(v_profile.licenses),
    'workerVehicles', '[]'::jsonb
  )::text, 'UTF8')), 'hex');

    v_new_version := v_response.current_version + 1;

    update public.marketplace_responses
       set current_version = v_new_version,
           status = 'SUBMITTED',
           submitted_against_need_revision = v_need.revision,
           covered_slots = v_covered,
           price_rsd = v_price,
           proposed_start_at = v_start,
           proposed_end_at = v_end,
           scope_note = coalesce(v_note,''),
           submitted_at = statement_timestamp(),
           withdrawn_at = null,
           selected_at = null
     where id = v_response.id
     returning * into v_response;

    insert into public.marketplace_response_versions(
      response_id, version, need_revision, covered_slots, price_rsd,
      proposed_start_at, proposed_end_at, scope_note, content_hash
    ) values (
      v_response.id, v_new_version, v_need.revision, v_covered, v_price,
      v_start, v_end, coalesce(v_note,''), v_content_hash
    );

  insert into private.response_application_snapshots (
    response_id, response_version, snapshot_schema,
    worker_profile_id, worker_team_capacity, covered_slots,
    need_required_slots, need_selected_slots_before_submit,
    need_remaining_slots_before_submit, pricing_mode, requester_price_rsd,
    worker_skills, worker_tools, worker_licenses, worker_vehicles
  ) values (
    v_response.id, v_new_version, 'APPLICATION_V1_SELF_DECLARED',
    v_profile.id, v_profile.team_capacity, v_covered,
    v_need.required_slots, v_selected_slots, v_remaining_slots,
    v_need.mode, v_need.requester_price_rsd,
    v_profile.skills, '{}'::text[], v_profile.licenses, '{}'::text[]
  );


    v_result := jsonb_build_object(
      'responseId', v_response.id,
      'needId', v_need.id,
      'needRevision', v_need.revision,
      'version', v_new_version,
      'contentHash', v_content_hash,
      'status', v_response.status,
      'action', v_action,
      'idempotentReplay', false,
      'authoritative', true
    );
  end if;

  perform private.audit_marketplace(
    v_actor,
    case when v_action='WITHDRAW' then 'STALE_RESPONSE_WITHDRAWN' else 'STALE_RESPONSE_RECONFIRMED' end,
    'RESPONSE',
    v_response.id,
    v_response.current_version,
    jsonb_build_object('needId',v_need.id,'needRevision',v_need.revision,'action',v_action)
  );

  insert into private.response_revision_resolution_commands(
    worker_account_id, client_request_id, request_hash, response_id, result
  ) values (v_actor, v_request_id, v_request_hash, v_response.id, v_result);

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_respond_agreement_change(p_proposal_id uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_proposal public.agreement_change_proposals%rowtype;
  v_agreement public.agreements%rowtype;
  v_agreement_id uuid;
  v_base_terms jsonb;
  v_terms jsonb;
  v_new_version integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_accept is null then raise exception 'DECISION_REQUIRED' using errcode='22004'; end if;

  -- Discover without locking. Every decision then locks Agreement -> proposal,
  -- including rejection/replay, so sibling acceptances cannot form a cycle.
  select agreement_id into v_agreement_id from public.agreement_change_proposals where id=p_proposal_id;
  if not found then raise exception 'CHANGE_PROPOSAL_NOT_FOUND' using errcode='P0002'; end if;
  perform 1 from public.needs where id=(select ag.need_id from public.agreements ag
    where ag.id=v_agreement_id and v_uid in (ag.requester_account_id,ag.worker_account_id)) for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND_OR_FORBIDDEN' using errcode='P0002'; end if;
  select * into v_agreement from public.agreements where id=v_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_uid not in (v_agreement.requester_account_id,v_agreement.worker_account_id) then raise exception 'NOT_PARTY' using errcode='42501'; end if;
  select * into v_proposal from public.agreement_change_proposals
    where id=p_proposal_id and agreement_id=v_agreement.id for update;
  if not found then raise exception 'CHANGE_PROPOSAL_NOT_FOUND' using errcode='P0002'; end if;
  if v_uid = v_proposal.proposed_by_account_id then raise exception 'PROPOSER_CANNOT_RESPOND' using errcode='42501'; end if;

  if v_proposal.status = 'ACCEPTED' and p_accept then
    return jsonb_build_object('proposalId',v_proposal.id,'accepted',true,'agreementVersion',v_proposal.base_version+1,'authoritative',true);
  elsif v_proposal.status = 'REJECTED' and not p_accept then
    return jsonb_build_object('proposalId',v_proposal.id,'accepted',false,'agreementVersion',v_proposal.base_version,'authoritative',true);
  elsif v_proposal.status <> 'PENDING' then
    raise exception 'PROPOSAL_NOT_PENDING' using errcode='P0001', detail=v_proposal.status;
  end if;
  if not exists(select 1 from public.agreement_execution ex where ex.agreement_id=v_agreement.id
    and ex.agreement_version=v_agreement.current_version and ex.state='CONFIRMED' and ex.worker_marked_done_at is null) then
    raise exception 'AGREEMENT_CHANGE_AFTER_WORK_DONE' using errcode='P0001';
  end if;

  if v_agreement.status <> 'CONFIRMED' then raise exception 'AGREEMENT_NOT_ACTIVE' using errcode='P0001'; end if;
  if v_agreement.current_version <> v_proposal.base_version then raise exception 'VERSION_CONFLICT' using errcode='P0001'; end if;

  if not p_accept then
    update public.agreement_change_proposals
       set status='REJECTED', responded_by_account_id=v_uid, responded_at=statement_timestamp()
     where id=v_proposal.id;
    perform private.emit_event(
      v_proposal.proposed_by_account_id,
      case when v_proposal.proposed_by_account_id=v_agreement.requester_account_id then 'REQUESTER' else 'WORKER' end,
      'AGREEMENT_CHANGE_REJECTED','AGREEMENT',v_agreement.id,v_agreement.current_version,
      'Predlog izmene nije prihvaćen','Važeći uslovi Dogovora ostaju nepromenjeni.',
      'agreement_change_rejected:'||v_proposal.id::text,'NORMAL',jsonb_build_object('proposal_id',v_proposal.id)
    );
    return jsonb_build_object('proposalId',v_proposal.id,'accepted',false,'agreementVersion',v_proposal.base_version,'authoritative',true);
  end if;

  -- Revalidate stored proposals too: older pending rows were not type-checked.
  -- Invalid historical data remains immutable and can still be rejected.
  v_terms := v_proposal.proposed_terms;
  select terms into v_base_terms from public.agreement_versions
    where agreement_id=v_agreement.id and version=v_proposal.base_version;
  if not found then raise exception 'AGREEMENT_VERSION_NOT_FOUND' using errcode='P0002'; end if;
  if coalesce(v_terms->'scope_note','null'::jsonb)='null'::jsonb and coalesce(v_base_terms->'scope_note','null'::jsonb)<>'null'::jsonb then raise exception 'CHANGE_SCOPE_INVALID' using errcode='22023'; end if;
  if jsonb_typeof(v_terms) is distinct from 'object' or
     (v_terms-array['price_rsd','currency','proposed_start_at','proposed_end_at','scope_note']) is distinct from
     (v_base_terms-array['price_rsd','currency','proposed_start_at','proposed_end_at','scope_note']) then
    raise exception 'CHANGE_TERMS_INVALID' using errcode='22023';
  end if;
  if jsonb_typeof(v_terms->'price_rsd') is distinct from 'number' then
    raise exception 'INVALID_PRICE' using errcode='22023';
  end if;
  if (v_terms->>'price_rsd')::numeric <= 0 or (v_terms->>'price_rsd')::numeric > 2147483647
     or trunc((v_terms->>'price_rsd')::numeric) <> (v_terms->>'price_rsd')::numeric then
    raise exception 'INVALID_PRICE' using errcode='22023';
  end if;
  if (coalesce(v_terms->'scope_note','null'::jsonb)<>'null'::jsonb and jsonb_typeof(v_terms->'scope_note') is distinct from 'string')
    or char_length(v_terms->>'scope_note')>4000 then
    raise exception 'CHANGE_SCOPE_INVALID' using errcode='22023';
  end if;
  if v_terms ? 'currency' and (jsonb_typeof(v_terms->'currency') is distinct from 'string'
     or v_terms->>'currency' is distinct from 'RSD') then
    raise exception 'CHANGE_CURRENCY_INVALID' using errcode='22023';
  end if;
  perform 1 from private.agreement_calendar_interval(v_terms);
  if encode(extensions.digest(convert_to(v_terms::text,'UTF8'),'sha256'),'hex') is distinct from v_proposal.content_hash then
    raise exception 'CHANGE_TERMS_INVALID' using errcode='22023';
  end if;

  v_new_version := v_agreement.current_version + 1;
  insert into public.agreement_versions(
    agreement_id,version,status,terms,content_hash,supersedes_version,created_by_account_id
  ) values (
    v_agreement.id,v_new_version,'CONFIRMED',v_proposal.proposed_terms,v_proposal.content_hash,
    v_agreement.current_version,v_proposal.proposed_by_account_id
  );
  update public.agreement_versions set status='SUPERSEDED'
   where agreement_id=v_agreement.id and version=v_agreement.current_version;
  update public.agreements set current_version=v_new_version, updated_at=statement_timestamp()
   where id=v_agreement.id;
  update public.agreement_execution set agreement_version=v_new_version, updated_at=statement_timestamp()
   where agreement_id=v_agreement.id;
  update public.agreement_change_proposals
     set status='ACCEPTED', responded_by_account_id=v_uid, responded_at=statement_timestamp()
   where id=v_proposal.id;
  update public.agreement_change_proposals
     set status='SUPERSEDED', responded_at=coalesce(responded_at,statement_timestamp())
   where agreement_id=v_agreement.id and id<>v_proposal.id and status='PENDING';
  perform private.emit_event(
    v_proposal.proposed_by_account_id,
    case when v_proposal.proposed_by_account_id=v_agreement.requester_account_id then 'REQUESTER' else 'WORKER' end,
    'AGREEMENT_VERSION_CHANGED','AGREEMENT',v_agreement.id,v_new_version,
    'Izmena Dogovora je prihvaćena','Pogledajte važeće uslove u Dogovoru.',
    'agreement_version_changed:'||v_proposal.id::text,'NORMAL',jsonb_build_object('proposal_id',v_proposal.id)
  );
  return jsonb_build_object('proposalId',v_proposal.id,'accepted',true,'agreementVersion',v_new_version,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_retire_push_account(p_account_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare d record;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if p_account_id is null then raise exception 'INVALID_ACCOUNT' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-user:'||p_account_id::text,0));
 for d in select id,expo_push_token from public.notification_push_devices where user_id=p_account_id and active order by expo_push_token loop
  perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||d.expo_push_token,0));
  update public.notification_push_devices set active=false,revision=revision+1,bound_session_id=null,bound_revision=null where id=d.id and user_id=p_account_id and active;
 end loop;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_reveal_contact(p_agreement_id uuid, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid(); a public.agreements; g public.access_grants;
  v_owner uuid; v_phone text; s public.need_sensitive;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;
  if p_channel is null or p_channel not in ('PHONE','EXACT_LOCATION') then
    raise exception using errcode='22023', message='UNSUPPORTED_CHANNEL';
  end if;

  select * into a from public.agreements where id = p_agreement_id;
  if not found then raise exception using errcode='P0002', message='AGREEMENT_NOT_FOUND'; end if;
  if u not in (a.requester_account_id, a.worker_account_id) then
    raise exception using errcode='42501', message='NOT_PARTY';
  end if;
  -- Dozvola zivi samo dok Dogovor zivi.
  if a.status <> 'CONFIRMED' then
    raise exception using errcode='42501', message='AGREEMENT_NOT_ACTIVE';
  end if;

  select * into g from public.access_grants
   where agreement_id = p_agreement_id and channel = p_channel
     and granted_to_account_id = u and status = 'GRANTED'
     and (expires_at is null or expires_at > statement_timestamp())
   limit 1;
  if not found then raise exception using errcode='42501', message='NO_ACTIVE_GRANT'; end if;

  if not private.safety_grant_valid(g.granted_by_account_id,g.granted_to_account_id,g.granted_at) then
    raise exception 'NO_ACTIVE_GRANT' using errcode='42501';
  end if;
  if not private.grant_is_ownable(p_agreement_id, p_channel, g.granted_by_account_id) then
    raise exception using errcode='42501', message='GRANT_NOT_FROM_DATA_OWNER';
  end if;
  if not private.grant_counterparty_ok(p_agreement_id, g.granted_by_account_id, u) then
    raise exception using errcode='42501', message='GRANT_NOT_TO_COUNTERPARTY';
  end if;

  if p_channel = 'PHONE' then
    v_owner := g.granted_by_account_id;
    select nullif(btrim(acc.phone),'') into v_phone from public.app_accounts acc where acc.id = v_owner;
    return jsonb_build_object('channel','PHONE','agreementId',a.id,'ownerAccountId',v_owner,
      'phone',v_phone,'grantedAt',g.granted_at,'expiresAt',g.expires_at,'authoritative',true);
  end if;

  select * into s from public.need_sensitive where need_id = a.need_id;
  if not found then raise exception using errcode='P0002', message='LOCATION_NOT_SET'; end if;
  if s.resolved_location is not null and not exists (
    select 1 from public.needs n join public.need_geography geo on geo.need_id=n.id where n.id=a.need_id
      and private.resolved_location_record_valid(s.resolved_location,n.task_country_code,geo.public_topology,s.exact_address,n.requester_account_id)
  ) then raise exception 'LOCATION_BINDING_CHANGED' using errcode='22023'; end if;
  return jsonb_build_object('channel','EXACT_LOCATION','agreementId',a.id,
    'needId',a.need_id,'needRevision',(select revision from public.needs where id=a.need_id),
    'grantId',g.id,'ownerAccountId',g.granted_by_account_id,'resolvedLocation',s.resolved_location,
    'exactAddress',s.exact_address,'accessNotes',s.access_notes,
    'exactLat',s.exact_lat,'exactLng',s.exact_lng,
    'grantedAt',g.granted_at,'expiresAt',g.expires_at,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_review_account_closure_execution(p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);b jsonb;r private.account_closure_requests;codes text[];begin
 perform private.closure_erasure_lock_v5(u);
 select * into r from private.account_closure_requests where account_id=u;b:=private.closure_erasure_binding_v5();codes:=private.closure_erasure_hard_blockers_v5(u);
 return jsonb_build_object('accountId',u,'requestId',r.id,'revision',coalesce(r.revision,0),
  'ready',b is not null and cardinality(codes)=0 and r.id is not null and r.revision<2147483646 and not private.closure_account_restricted(u),
  'policySha256',b->>'sha256','blockers',to_jsonb(codes),'code',case when b is null then 'CLOSURE_POLICY_NOT_READY' when r.id is null then 'CLOSURE_PREPARATION_REQUIRED' when cardinality(codes)>0 then 'CLOSURE_BLOCKED' else null end,
  'adapterVersion','OWNER_AF_D22_EVENT_ERASURE_V1','retainedDatasets',null,'exceptions',to_jsonb(private.closure_erasure_exceptions_v5(u)),
  'authAction','AUTH_IDENTITY_ERASED_SUBJECT_RETAINED','mediaAction','DELETE_UNPROTECTED_OWNED_OBJECTS','relationalAction','ERASE_ORDINARY_PERSONAL_CONTENT','authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_revoke_data_export_download(p_receipt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 return private.revoke_data_export_receipt(p_receipt_id,auth.uid());
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_revoke_push_session(p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); sid uuid; d record; n integer:=0;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid; exception when invalid_text_representation then raise exception 'AUTH_REQUIRED' using errcode='28000'; end;
 if sid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-user:'||u::text,0));
 for d in select id,expo_push_token from public.notification_push_devices where user_id=u and bound_session_id=sid order by expo_push_token loop
  perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||d.expo_push_token,0));
  update public.notification_push_devices set active=false,revision=revision+1,bound_session_id=null,bound_revision=null where id=d.id and user_id=u and bound_session_id=sid;
  if found then n:=n+1; end if;
 end loop;
 return jsonb_build_object('userId',u,'revoked',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_rotate_push_device_owned(p_expected_user_id uuid, p_previous_device_id uuid, p_previous_revision bigint, p_expo_push_token text, p_platform text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); sid uuid; old_device public.notification_push_devices%rowtype; next_device public.notification_push_devices%rowtype; token text; result jsonb;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid; exception when invalid_text_representation then raise exception 'AUTH_REQUIRED' using errcode='28000'; end;
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 if p_previous_device_id is null or p_previous_revision is null or p_previous_revision<1 or p_expo_push_token is null or length(p_expo_push_token)>256 or p_expo_push_token!~'^(ExpoPushToken|ExponentPushToken)\[[A-Za-z0-9_-]+\]$' or p_platform is null or p_platform not in ('IOS','ANDROID') then raise exception 'INVALID_PUSH_REGISTRATION' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-user:'||u::text,0));
 select * into old_device from public.notification_push_devices where id=p_previous_device_id and user_id=u;
 if not found or not old_device.active or old_device.revision<>p_previous_revision or old_device.bound_revision is distinct from old_device.revision or old_device.bound_session_id is distinct from sid then raise exception 'PUSH_REVISION_CONFLICT' using errcode='PT409'; end if;
 if old_device.expo_push_token=p_expo_push_token or old_device.platform<>p_platform then raise exception 'INVALID_PUSH_REGISTRATION' using errcode='22023'; end if;
 for token in select x from unnest(array[old_device.expo_push_token,p_expo_push_token]) x order by x loop
  perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||token,0));
 end loop;
 -- Legacy N06 writers do not take the user lock; recheck after both token locks.
 select * into old_device from public.notification_push_devices where id=p_previous_device_id for update;
 if not old_device.active or old_device.revision<>p_previous_revision or old_device.bound_revision is distinct from old_device.revision or old_device.bound_session_id is distinct from sid then raise exception 'PUSH_REVISION_CONFLICT' using errcode='PT409'; end if;
 select * into next_device from public.notification_push_devices where user_id=u and expo_push_token=p_expo_push_token;
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 perform public.rpc_set_push_device(old_device.expo_push_token,old_device.platform,false,p_previous_revision);
 update public.notification_push_devices set bound_session_id=null,bound_revision=null where id=old_device.id;
 result:=public.rpc_set_push_device(p_expo_push_token,p_platform,true,coalesce(next_device.revision,0));
 update public.notification_push_devices set bound_session_id=sid,bound_revision=revision where id=(result->>'id')::uuid;
 return result||jsonb_build_object('sessionBound',true,'previousDeviceId',old_device.id,'previousRevision',p_previous_revision+1);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_answer_preselection_question(p_question_id uuid, p_answer_text text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_q private.preselection_qa_questions%rowtype;
  v_need public.needs%rowtype;
  v_text text:=btrim(coalesce(p_answer_text,''));
  v_floor text;
  v_fp text;
  v_materiality text;
  v_semantic text;
  v_existing private.preselection_qa_commands%rowtype;
  v_version integer;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if;
  if p_request_id is null then raise exception 'REQUEST_ID_REQUIRED' using errcode='P0001'; end if;
  if v_text='' then raise exception 'ANSWER_REQUIRED' using errcode='P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || E'\n' || p_request_id::text,4413));
  v_semantic:=encode(extensions.digest(convert_to(jsonb_build_object(
    'command','RU4B_ANSWER','questionId',p_question_id,'answer',v_text
  )::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from private.preselection_qa_commands where actor_account_id=v_uid and request_id=p_request_id;
  if found then
    if v_existing.command_type<>'ANSWER' or v_existing.semantic_hash<>v_semantic then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='P0001'; end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;
  select * into v_q from private.preselection_qa_questions where id=p_question_id for update;
  if not found then raise exception 'QUESTION_NOT_FOUND' using errcode='P0001'; end if;
  if v_q.status in ('IGNORED','REPORTED') then raise exception 'QUESTION_NOT_ANSWERABLE' using errcode='P0001'; end if;
  select * into v_need from public.needs where id=v_q.need_id for share;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0001'; end if;
  if v_need.requester_account_id<>v_uid then raise exception 'NOT_NEED_OWNER' using errcode='P0001'; end if;
  if v_need.revision<>v_q.need_revision then raise exception 'QUESTION_STALE_AFTER_NEED_REVISION' using errcode='P0001'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then raise exception 'NEED_NOT_PUBLIC' using errcode='P0001'; end if;
  perform private.ru4b_assert_block_authority_ready(v_q.asker_account_id,v_uid);
  perform private.ru4b_assert_numeric_policy_v5(v_uid,'ANSWER',v_q.need_id,v_q.need_revision,v_q.id,v_text);
  v_floor:=private.ru4b_public_floor_reason(v_text);
  if v_floor is not null then raise exception '%',v_floor using errcode='P0001'; end if;
  v_fp:=private.ru4b_content_fingerprint('ANSWER',v_q.need_id,v_q.need_revision,v_q.id,v_text);
  v_materiality:=private.ru4b_exact_materiality(v_q.id,v_q.need_id,v_q.need_revision,v_fp);
  if v_materiality is null then raise exception 'RU4B_MATERIALITY_NOT_READY' using errcode='P0001'; end if;
  if v_materiality='MATERIAL' then raise exception 'RU4B_MATERIAL_REQUIRES_RU4_EDIT' using errcode='P0001'; end if;
  if not private.ru4b_has_exact_policy_allow('ANSWER',v_q.need_id,v_q.need_revision,v_q.id,v_fp) then
    raise exception 'PRESELECTION_QA_POLICY_NOT_READY' using errcode='P0001';
  end if;
  select coalesce(max(answer_version),0)+1 into v_version from private.preselection_qa_answer_versions where question_id=v_q.id;
  insert into private.preselection_qa_answer_versions(question_id,answer_version,answer_text,answer_fingerprint,answered_by_account_id)
  values(v_q.id,v_version,v_text,v_fp,v_uid);
  update private.preselection_qa_questions
    set status='ANSWERED_PUBLIC',answered_at=statement_timestamp(),updated_at=statement_timestamp()
    where id=v_q.id;
  perform private.emit_event(
    v_q.asker_account_id,'WORKER','CLARIFICATION_ANSWERED','CLARIFICATION',v_q.id,v_version,
    'Odgovor na pitanje','Naručilac je odgovorio na Vaše pitanje.',
    'ru4b:clarification:'||v_q.id::text||':answer:'||v_version::text,'NORMAL',
    jsonb_build_object('needId',v_q.need_id,'needRevision',v_q.need_revision,'questionId',v_q.id,'answerVersion',v_version),null
  );
  v_result:=jsonb_build_object('ok',true,'questionId',v_q.id,'status','ANSWERED_PUBLIC','answerVersion',v_version,'edited',v_version>1,'idempotentReplay',false);
  insert into private.preselection_qa_commands(actor_account_id,request_id,command_type,semantic_hash,result)
  values(v_uid,p_request_id,'ANSWER',v_semantic,v_result);
  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_ask_preselection_question(p_need_id uuid, p_expected_revision integer, p_question_text text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_need public.needs%rowtype;
  v_text text:=btrim(coalesce(p_question_text,''));
  v_floor text;
  v_fp text;
  v_semantic text;
  v_existing private.preselection_qa_commands%rowtype;
  v_question_id uuid;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if;
  if p_request_id is null then raise exception 'REQUEST_ID_REQUIRED' using errcode='P0001'; end if;
  if v_text='' then raise exception 'QUESTION_REQUIRED' using errcode='P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || E'\n' || p_request_id::text,4412));
  v_semantic:=encode(extensions.digest(convert_to(jsonb_build_object(
    'command','RU4B_ASK','needId',p_need_id,'expectedRevision',p_expected_revision,'question',v_text
  )::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from private.preselection_qa_commands where actor_account_id=v_uid and request_id=p_request_id;
  if found then
    if v_existing.command_type<>'ASK' or v_existing.semantic_hash<>v_semantic then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='P0001'; end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;
  select * into v_need from public.needs where id=p_need_id for share;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0001'; end if;
  if v_need.revision<>p_expected_revision then raise exception 'STALE_NEED_REVISION' using errcode='P0001'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then raise exception 'NEED_NOT_PUBLIC' using errcode='P0001'; end if;
  if v_need.requester_account_id=v_uid then raise exception 'REQUESTER_CANNOT_ASK_OWN_TASK' using errcode='P0001'; end if;
  if not exists(select 1 from public.app_profiles p where p.account_id=v_uid and p.kind='WORKER' and p.profile_status='ACTIVE') then
    raise exception 'ACTIVE_WORKER_REQUIRED' using errcode='P0001';
  end if;
  perform private.ru4b_assert_block_authority_ready(v_uid,v_need.requester_account_id);
  perform private.ru4b_assert_numeric_policy_v5(v_uid,'QUESTION',p_need_id,p_expected_revision,null,v_text);
  v_floor:=private.ru4b_public_floor_reason(v_text);
  if v_floor is not null then raise exception '%',v_floor using errcode='P0001'; end if;
  v_fp:=private.ru4b_content_fingerprint('QUESTION',p_need_id,p_expected_revision,null,v_text);
  if not private.ru4b_has_exact_policy_allow('QUESTION',p_need_id,p_expected_revision,null,v_fp) then
    raise exception 'PRESELECTION_QA_POLICY_NOT_READY' using errcode='P0001';
  end if;
  insert into private.preselection_qa_questions(need_id,need_revision,asker_account_id,question_text,question_fingerprint,created_at,updated_at)
  values(p_need_id,p_expected_revision,v_uid,v_text,v_fp,clock_timestamp(),clock_timestamp()) returning id into v_question_id;
  perform private.emit_event(
    v_need.requester_account_id,'REQUESTER','CLARIFICATION_CREATED','CLARIFICATION',v_question_id,1,
    'Novo pitanje o Zadatku','Uskočer je postavio anonimno pitanje o Zadatku.',
    'ru4b:clarification:'||v_question_id::text||':created','NORMAL',
    jsonb_build_object('needId',p_need_id,'needRevision',p_expected_revision,'questionId',v_question_id),null
  );
  v_result:=jsonb_build_object('ok',true,'questionId',v_question_id,'status','PENDING_ANSWER','needRevision',p_expected_revision,'idempotentReplay',false);
  insert into private.preselection_qa_commands(actor_account_id,request_id,command_type,semantic_hash,result)
  values(v_uid,p_request_id,'ASK',v_semantic,v_result);
  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_disposition_preselection_question(p_question_id uuid, p_action text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); v_q private.preselection_qa_questions%rowtype; v_need public.needs%rowtype;
  v_semantic text; v_existing private.preselection_qa_commands%rowtype; v_status text; v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if;
  if p_action not in ('IGNORE','REPORT') then raise exception 'RU4B_DISPOSITION_INVALID' using errcode='P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || E'\n' || p_request_id::text,4414));
  v_semantic:=encode(extensions.digest(convert_to(jsonb_build_object('command','RU4B_DISPOSITION','questionId',p_question_id,'action',p_action)::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from private.preselection_qa_commands where actor_account_id=v_uid and request_id=p_request_id;
  if found then
    if v_existing.command_type<>'DISPOSITION' or v_existing.semantic_hash<>v_semantic then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='P0001'; end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;
  select * into v_q from private.preselection_qa_questions where id=p_question_id for update;
  if not found then raise exception 'QUESTION_NOT_FOUND' using errcode='P0001'; end if;
  select * into v_need from public.needs where id=v_q.need_id;
  if v_need.requester_account_id<>v_uid then raise exception 'NOT_NEED_OWNER' using errcode='P0001'; end if;
  if v_q.status<>'PENDING_ANSWER' then raise exception 'QUESTION_NOT_PENDING' using errcode='P0001'; end if;
  v_status:=case when p_action='IGNORE' then 'IGNORED' else 'REPORTED' end;
  update private.preselection_qa_questions set status=v_status,updated_at=statement_timestamp(),
    ignored_at=case when p_action='IGNORE' then statement_timestamp() else ignored_at end,
    reported_at=case when p_action='REPORT' then statement_timestamp() else reported_at end
    where id=v_q.id;
  v_result:=jsonb_build_object('ok',true,'questionId',v_q.id,'status',v_status,'idempotentReplay',false);
  insert into private.preselection_qa_commands(actor_account_id,request_id,command_type,semantic_hash,result)
  values(v_uid,p_request_id,'DISPOSITION',v_semantic,v_result);
  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_owner_preselection_questions(p_need_id uuid)
 RETURNS TABLE(question_id uuid, need_revision integer, question_text text, status text, created_at timestamp with time zone, answer_version integer, answer_text text, edited boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select q.id,q.need_revision,q.question_text,q.status,q.created_at,
         a.answer_version,a.answer_text,coalesce(a.answer_version>1,false)
  from private.preselection_qa_questions q
  join public.needs n on n.id=q.need_id
  left join lateral (
    select av.answer_version,av.answer_text from private.preselection_qa_answer_versions av
    where av.question_id=q.id order by av.answer_version desc limit 1
  ) a on true
  where q.need_id=p_need_id and n.requester_account_id=auth.uid()
  order by q.created_at desc,q.id desc
$function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_public_preselection_qa(p_need_id uuid)
 RETURNS TABLE(question_id uuid, need_revision integer, question_text text, answer_version integer, answer_text text, edited boolean, answered_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select q.id,q.need_revision,q.question_text,a.answer_version,a.answer_text,(a.answer_version>1),q.answered_at
 from private.preselection_qa_questions q
 join public.needs n on n.id=q.need_id and n.revision=q.need_revision and n.status in('PUBLISHED','SELECTION')
 join lateral(select av.answer_version,av.answer_text from private.preselection_qa_answer_versions av
  where av.question_id=q.id order by av.answer_version desc limit 1) a on true
 where q.need_id=p_need_id and q.status='ANSWERED_PUBLIC' and auth.uid() is not null
 and not private.closure_account_restricted(auth.uid()) and not private.closure_account_restricted(n.requester_account_id)
 and not private.safety_pair_blocked(auth.uid(),n.requester_account_id)
 order by q.answered_at,q.id
 $function$;


CREATE OR REPLACE FUNCTION public.rpc_ru4b_record_materiality_decision_service(p_question_id uuid, p_need_id uuid, p_need_revision integer, p_answer_fingerprint text, p_materiality text, p_decision_source text, p_service_provenance jsonb)
