CREATE OR REPLACE FUNCTION public.rpc_save_need_draft_from_review(p_conversation_id uuid, p_requester_profile_id uuid, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_conv public.ai_conversations%rowtype;
  v_profile public.app_profiles%rowtype;
  v_facts jsonb;
  v_handoff jsonb;
  v_snapshot jsonb;
  v_missing text[];
  v_hash text;
  v_existing private.need_draft_save_commands%rowtype;
  v_need_id uuid;
  v_result jsonb;
  v_title text;
  v_description text;
  v_category text;
  v_mode text;
  v_price integer;
  v_schedule_kind text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_slots integer;
  v_skills text[];
  v_tools text[];
  v_vehicles text[];
  v_licenses text[];
  v_min_exp integer;
  v_verified boolean;
  v_photos text[];
  v_conditions text[];
  v_geo jsonb;
  v_exec_mode text;
  v_start jsonb;
  v_service jsonb;
  v_city text;
  v_area text;
  v_exact_address text;
  v_access_notes text;
  v_key text;
  v_value jsonb;
  v_safety text;
  v_country text; v_timezone text; v_region_token text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_conversation_id is null or p_requester_profile_id is null then raise exception 'DRAFT_IDENTITY_REQUIRED' using errcode='22004'; end if;
  if coalesce(char_length(btrim(p_client_request_id)),0)<8 or char_length(btrim(p_client_request_id))>200 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;

  select * into v_conv
    from public.ai_conversations
   where id=p_conversation_id
   for update;
  if not found then raise exception 'CONVERSATION_NOT_FOUND' using errcode='P0002'; end if;
  if v_conv.account_id<>v_uid then raise exception 'NOT_OWNER' using errcode='42501'; end if;
  if v_conv.purpose<>'NEED_INTAKE' then raise exception 'CONVERSATION_PURPOSE_MISMATCH' using errcode='P0001'; end if;
  if v_conv.fact_schema_version<>'NEED_FACT_V2' then raise exception 'LEGACY_CONVERSATION_NOT_CANONICAL_SAVE_ELIGIBLE' using errcode='P0001'; end if;

  select * into v_profile
    from public.app_profiles
   where id=p_requester_profile_id
   for share;
  if not found or v_profile.account_id<>v_uid or v_profile.kind<>'REQUESTER' or v_profile.profile_status<>'ACTIVE' then
    raise exception 'REQUESTER_PROFILE_NOT_READY' using errcode='42501';
  end if;

  if exists (
    select 1 from public.ai_structured_facts
     where conversation_id=p_conversation_id
       and superseded_at is null
       and fact_schema_version<>'NEED_FACT_V2'
  ) then
    raise exception 'MIXED_SCHEMA_CONVERSATION_NOT_SAVE_ELIGIBLE' using errcode='P0001';
  end if;

  for v_key,v_value in
    select fact_key,fact_value
      from public.ai_structured_facts
     where conversation_id=p_conversation_id
       and superseded_at is null
       and fact_schema_version='NEED_FACT_V2'
       and status='CONFIRMED'
  loop
    perform private.validate_need_v2_fact(v_key,v_value);
  end loop;

  select coalesce(jsonb_object_agg(fact_key,fact_value),'{}'::jsonb)
    into v_facts
    from public.ai_structured_facts
   where conversation_id=p_conversation_id
     and superseded_at is null
     and fact_schema_version='NEED_FACT_V2'
     and status='CONFIRMED';

  select array_agg(r.fact_key order by r.fact_key)
    into v_missing
    from private.need_fact_registry r
   where r.required_for_draft
     and not (v_facts ? r.fact_key);

  if cardinality(coalesce(v_missing,'{}'::text[]))>0 then
    raise exception 'REQUIRED_CONFIRMED_FACTS_MISSING'
      using errcode='P0001',detail=array_to_string(v_missing,',');
  end if;

  v_title:=v_facts->>'need.title';
  v_description:=v_facts->>'need.description';
  v_category:=v_facts->>'need.category';
  v_mode:=v_facts->>'need.price_mode';
  if v_facts ? 'need.price_rsd' then v_price:=(v_facts->>'need.price_rsd')::integer; end if;
  if v_mode='MY_PRICE' and v_price is null then raise exception 'MY_PRICE_AMOUNT_REQUIRED' using errcode='P0001'; end if;
  if v_mode<>'MY_PRICE' then v_price:=null; end if;

  v_schedule_kind:=v_facts->>'need.schedule_kind';
  if v_facts ? 'need.starts_at' then v_starts_at:=(v_facts->>'need.starts_at')::timestamptz; end if;
  if v_facts ? 'need.ends_at' then v_ends_at:=(v_facts->>'need.ends_at')::timestamptz; end if;
  if v_schedule_kind='FIXED_WINDOW' and (v_starts_at is null or not isfinite(v_starts_at)
      or (v_ends_at is not null and (not isfinite(v_ends_at) or v_ends_at<=v_starts_at))) then
    raise exception 'FIXED_WINDOW_BOUNDS_REQUIRED' using errcode='P0001';
  end if;

  v_slots:=(v_facts->>'need.people_needed')::integer;

  select coalesce(array_agg(value),'{}'::text[]) into v_skills from jsonb_array_elements_text(coalesce(v_facts->'need.required_skills','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_tools from jsonb_array_elements_text(coalesce(v_facts->'need.required_tools','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_vehicles from jsonb_array_elements_text(coalesce(v_facts->'need.required_vehicles','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_licenses from jsonb_array_elements_text(coalesce(v_facts->'need.required_licenses','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_photos from jsonb_array_elements_text(coalesce(v_facts->'need.public_photo_paths','[]'::jsonb));
  select coalesce(array_agg(value),'{}'::text[]) into v_conditions from jsonb_array_elements_text(coalesce(v_facts->'need.critical_conditions','[]'::jsonb));

  if v_facts ? 'need.minimum_experience_years' then v_min_exp:=(v_facts->>'need.minimum_experience_years')::integer; end if;
  v_verified:=case when v_facts ? 'need.verified_identity_required' then (v_facts->>'need.verified_identity_required')::boolean else false end;

  v_country:=private.require_location_country(v_facts->'need.task_country_code');
  select default_timezone into v_timezone from private.location_market_configs where country_code=v_country;
  v_geo:=v_facts->'need.task_geography';
  v_exec_mode:=v_geo->>'mode';
  v_handoff:=case when v_exec_mode='REMOTE' then v_facts->'need.handoff' else null end;
  if v_exec_mode='REMOTE' and v_handoff is null then
    raise exception 'HANDOFF_REQUIRED' using errcode='22023';
  end if;
  if v_handoff is not null then
    perform private.validate_need_v2_fact('need.handoff',v_handoff);
    v_conditions:=array_append(array_remove(v_conditions,'Predaja: '||private.taxonomy_handoff_display_v1(v_handoff)),
      'Predaja: '||private.taxonomy_handoff_display_v1(v_handoff));
  end if;
  v_start:=coalesce(v_geo->'start','null'::jsonb);
  v_service:=coalesce(v_geo->'serviceArea','null'::jsonb);
  v_city:=coalesce(nullif(btrim(v_start->>'city'),''),nullif(btrim(v_service->>'city'),''));
  v_area:=coalesce(nullif(btrim(v_start->>'area'),''),nullif(btrim(v_service->>'area'),''));
  if v_exec_mode='REMOTE' then
    v_city:=''; v_area:='';
  end if;

  if v_facts ? 'need.exact_address' then v_exact_address:=v_facts->>'need.exact_address'; end if;
  if v_facts ? 'need.access_notes' then v_access_notes:=v_facts->>'need.access_notes'; end if;

  v_snapshot:=jsonb_build_object(
    'conversationId',p_conversation_id,
    'requesterProfileId',p_requester_profile_id,
    'confirmedFacts',v_facts
  );
  v_hash:=encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');

  select * into v_existing
    from private.need_draft_save_commands
   where account_id=v_uid
     and client_request_id=btrim(p_client_request_id)
   for update;

  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'CLIENT_REQUEST_ID_REUSED_WITH_DIFFERENT_SNAPSHOT' using errcode='22023';
    end if;
    return v_existing.result;
  end if;

  if v_conv.status<>'OPEN' then raise exception 'CONVERSATION_CLOSED' using errcode='P0001'; end if;
  if v_conv.bound_need_id is not null then raise exception 'CONVERSATION_ALREADY_BOUND' using errcode='P0001'; end if;

  if exists(select 1 from public.ai_structured_facts where conversation_id=p_conversation_id
    and superseded_at is null and status<>'CONFIRMED') then
    raise exception 'EDIT_FACTS_REQUIRE_HUMAN_CONFIRMATION' using errcode='P0001';
  end if;

  -- Successful semantic-command replay above remains an acknowledgment only.
  -- For every new DRAFT, recheck safety under the same conversation lock used
  -- by the service writer; a prior committed BLOCK cannot race past this gate.
  -- Ignore null/unsupported rows so they cannot clear an earlier BLOCK.
  -- No supported decision retains the existing conservative REVIEW fallback.
  select coalesce((
    select m.safety from public.ai_messages m
     where m.conversation_id=p_conversation_id
       and m.role='ASSISTANT'
       and m.safety in ('ALLOW','CLARIFY','REVIEW','BLOCK')
     order by m.sequence_no desc
     limit 1
  ),'REVIEW') into v_safety;
  if v_safety='BLOCK' then
    raise exception 'AI_NEED_DRAFT_BLOCKED' using errcode='P0001';
  end if;

  v_region_token:=current_setting('uskoci.need_region',true);
  perform set_config('uskoci.need_region','CONFIRMED_REVIEW',true);
  insert into public.needs(
    requester_account_id,requester_profile_id,status,title,description,category,
    approximate_city,approximate_area,schedule_kind,starts_at,ends_at,required_slots,
    mode,requester_price_rsd,required_skills,required_tools,required_vehicles,
    required_licenses,verified_identity_required,minimum_experience_years,
    execution_location_mode,public_photo_paths,task_country_code,task_timezone,price_basis
  ) values (
    v_uid,p_requester_profile_id,'DRAFT',v_title,v_description,v_category,
    coalesce(v_city,''),coalesce(v_area,''),v_schedule_kind,v_starts_at,v_ends_at,v_slots,
    v_mode,v_price,v_skills,v_tools,v_vehicles,v_licenses,v_verified,v_min_exp,
    v_exec_mode,v_photos,v_country,v_timezone,case when v_mode='MY_PRICE' then nullif(btrim(coalesce(v_facts->>'need.price_basis','')),'') end
  )
  returning id into v_need_id;
  perform set_config('uskoci.need_region',coalesce(v_region_token,''),true);

  insert into public.need_geography(need_id,public_topology)
  values(v_need_id,v_geo);

  if v_exact_address is not null or v_access_notes is not null then
    insert into public.need_sensitive(need_id,exact_address,access_notes)
    values(v_need_id,coalesce(v_exact_address,''),coalesce(v_access_notes,''));
  end if;

  perform private.materialize_resolved_location(v_need_id,p_conversation_id);

  if cardinality(v_conditions)>0 then
    insert into public.need_requirement_details(need_id,critical_conditions,handoff)
    values(v_need_id,v_conditions,v_handoff);
  end if;

  update public.ai_structured_facts
     set subject_need_id=v_need_id
   where conversation_id=p_conversation_id
     and fact_schema_version='NEED_FACT_V2';

  update public.ai_conversations
     set bound_need_id=v_need_id,status='COMPLETED',completed_at=statement_timestamp()
   where id=p_conversation_id;

  v_result:=jsonb_build_object(
    'needId',v_need_id,
    'status','DRAFT',
    'revision',1,
    'conversationId',p_conversation_id,
    'authoritative',true
  );

  insert into private.need_draft_save_commands(
    account_id,client_request_id,request_hash,conversation_id,requester_profile_id,need_id,result
  ) values (
    v_uid,btrim(p_client_request_id),v_hash,p_conversation_id,p_requester_profile_id,v_need_id,v_result
  );

  return v_result;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_save_need_location_review(p_conversation_id uuid, p_expected_revision text, p_value jsonb, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c public.ai_conversations; before_doc jsonb; wanted jsonb; k text; fv jsonb;
  old_fact public.ai_structured_facts; new_id uuid; display text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_confirmed is distinct from true then raise exception 'LOCATION_CONFIRMATION_REQUIRED' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{64}$' then
    raise exception 'LOCATION_INPUT_INVALID' using errcode='22023';
  end if;
  wanted:=private.normalize_need_location(p_value);
  select * into c from public.ai_conversations where id=p_conversation_id and account_id=auth.uid() for update;
  if not found or c.purpose<>'NEED_INTAKE' or c.fact_schema_version<>'NEED_FACT_V2' then
    raise exception 'LOCATION_REVIEW_NOT_FOUND' using errcode='42501';
  end if;
  if c.status<>'OPEN' then raise exception 'LOCATION_REVIEW_NOT_EDITABLE' using errcode='55000'; end if;
  -- The conversation lock is also taken by the existing AI turn and reviewed-save
  -- commands. Each accepted write updates that row, fencing stale RR snapshots.
  before_doc:=private.need_location_review_document(c.id);
  if before_doc->'confirmed'='true'::jsonb and before_doc->'value'=wanted then
    return jsonb_build_object('saved',true,'idempotentReplay',true,'review',before_doc);
  end if;
  if before_doc->>'revision'<>p_expected_revision then raise exception 'LOCATION_VERSION_CONFLICT' using errcode='PT409'; end if;
  update public.ai_conversations set status='OPEN' where id=c.id;
  foreach k in array ARRAY['need.task_country_code','need.task_geography','need.exact_address','need.access_notes','need.resolved_location'] loop
    fv:=wanted->case k when 'need.task_country_code' then 'taskCountryCode' when 'need.task_geography' then 'geography' when 'need.exact_address' then 'exactAddress' when 'need.resolved_location' then 'resolvedLocation' else 'accessNotes' end;
    select * into old_fact from public.ai_structured_facts where conversation_id=c.id and fact_key=k and superseded_at is null for update;
    if found and old_fact.fact_value=fv and old_fact.status='CONFIRMED' then continue; end if;
    if old_fact.id is not null then
      update public.ai_structured_facts set superseded_at=statement_timestamp() where id=old_fact.id;
    end if;
    if fv='null'::jsonb then continue; end if;
    perform private.validate_need_v2_fact(k,fv);
    display:=case when k='need.resolved_location' then 'Potvrđene tačke: '||jsonb_array_length(fv->'points')::text when k='need.task_geography' then
      case when fv->>'mode'='REMOTE' then 'Rad na daljinu' else
        coalesce(fv#>>'{start,city}',fv#>>'{serviceArea,city}',fv#>>'{start,area}',fv#>>'{serviceArea,area}',fv#>>'{start,label}',fv#>>'{serviceArea,label}') end
      else left(fv#>>'{}',1000) end;
    new_id:=extensions.gen_random_uuid();
    insert into public.ai_structured_facts(id,account_id,conversation_id,subject_need_id,fact_key,fact_value,status,source,scope,
      confidence,evidence_excerpt,confirmed_by_user_id,confirmed_at,fact_schema_version,value_type,display_value)
    values(new_id,auth.uid(),c.id,c.bound_need_id,k,fv,'CONFIRMED','EXPLICIT_USER_ANSWER','NEED_DRAFT',1,null,auth.uid(),statement_timestamp(),
      'NEED_FACT_V2',case when k in ('need.task_geography','need.resolved_location') then 'OBJECT' else 'TEXT' end,display);
    if old_fact.id is not null then update public.ai_structured_facts set superseded_by=new_id where id=old_fact.id; end if;
  end loop;
  return jsonb_build_object('saved',true,'idempotentReplay',false,'review',private.need_location_review_document(c.id));
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_save_requester_profile(p_expected_revision text, p_display_name jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles; previous_token text; wanted text; supplied text; h text; old_receipt private.requester_identity_commands; doc jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_client_request_id is null or p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{64}$'
   or jsonb_typeof(p_display_name) is distinct from 'string' then
   raise exception 'REQUESTER_PROFILE_INPUT_INVALID' using errcode='22023'; end if;
 supplied:=p_display_name#>>'{}';
 if octet_length(supplied)>800 or length(btrim(supplied)) not between 1 and 200 or supplied ~ '[[:cntrl:]]' then
   raise exception 'REQUESTER_PROFILE_INPUT_INVALID' using errcode='22023'; end if;
 wanted:=btrim(supplied);
 h:=encode(extensions.digest(jsonb_build_object('revision',p_expected_revision,'displayName',wanted)::text,'sha256'),'hex');
 -- The single existing profile row serializes different request IDs and CAS;
 -- all successful retries are read-only and return the original immutable receipt.
 select * into p from public.app_profiles where account_id=auth.uid() and kind='REQUESTER' for update;
 if not found then raise exception 'REQUESTER_PROFILE_REQUIRED' using errcode='55000'; end if;
 if p.profile_status not in('ACTIVE','DRAFT') then raise exception 'REQUESTER_PROFILE_RESTRICTED' using errcode='42501'; end if;
 select * into old_receipt from private.requester_identity_commands where account_id=auth.uid() and client_request_id=p_client_request_id;
 if found then
   if old_receipt.input_hash<>h or old_receipt.profile_id<>p.id then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
   return old_receipt.receipt||jsonb_build_object('idempotentReplay',true);
 end if;
 doc:=private.requester_identity_document(p.id);
 if doc->>'revision'<>p_expected_revision then raise exception 'REQUESTER_PROFILE_STALE' using errcode='PT409'; end if;
 if p.display_name is distinct from wanted then
   previous_token:=current_setting('uskoci.profile_mutation',true);
   perform set_config('uskoci.profile_mutation','REQUESTER_IDENTITY',true);
   update public.app_profiles set display_name=wanted where id=p.id;
   perform set_config('uskoci.profile_mutation',coalesce(previous_token,''),true);
 end if;
 doc:=jsonb_build_object('saved',true,'idempotentReplay',false,'clientRequestId',p_client_request_id,
   'identity',private.requester_identity_document(p.id));
 insert into private.requester_identity_commands(account_id,client_request_id,profile_id,input_hash,receipt)
   values(auth.uid(),p_client_request_id,p.id,h,doc);
 return doc;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_save_worker_ai_review(p_review_id uuid, p_displayed_digest text, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare s private.worker_ai_sessions; r private.worker_ai_reviews; cmd private.worker_ai_saves; p public.app_profiles; value jsonb; receipt jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(auth.uid());
 if p_client_request_id is null then raise exception 'WORKER_AI_ID_REQUIRED' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('worker-ai-save:'||auth.uid()::text||p_client_request_id::text,0));
 select * into r from private.worker_ai_reviews where id=p_review_id and account_id=auth.uid();
 if not found or r.envelope->>'displayedContentDigest' is distinct from p_displayed_digest then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 select * into s from private.worker_ai_sessions where conversation_id=r.conversation_id and account_id=auth.uid() for update;
 if not found then raise exception 'WORKER_AI_DENIED' using errcode='42501'; end if;
 select * into cmd from private.worker_ai_saves where account_id=auth.uid() and client_request_id=p_client_request_id;
 if found and cmd.review_id<>r.id then raise exception 'WORKER_AI_REQUEST_CONFLICT' using errcode='PT409'; end if;
 select * into cmd from private.worker_ai_saves where review_id=r.id;
 if found then return cmd.receipt; end if;
 perform 1 from public.ai_conversations where id=s.conversation_id and account_id=auth.uid() and purpose='PROFILE' and status='OPEN' for update;
 if not found then raise exception 'WORKER_AI_NOT_EDITABLE' using errcode='55000'; end if;
 select * into p from public.app_profiles where account_id=auth.uid() and kind='WORKER' for update;
 if r.revision<>s.revision or r.base_hash<>private.worker_ai_source_hash(auth.uid()) or r.expires_at<clock_timestamp()
  or r.envelope->'profile'<>s.candidate or r.envelope->'canAccept'<>'true'::jsonb or s.safety in ('BLOCK','REVIEW')
  or exists(select 1 from private.worker_ai_turns where conversation_id=s.conversation_id and state='PROCESSING')
 then raise exception 'WORKER_AI_STALE' using errcode='PT409'; end if;
 if p.id is not null and (p.id<>s.profile_id or p.profile_status not in ('DRAFT','ACTIVE')) then raise exception 'WORKER_PROFILE_RESTRICTED' using errcode='42501'; end if;
 value:=r.envelope->'profile';
 -- WPP01: legacy keys stay on the wire, but may not request a retired-field change.
 -- Compare the reviewed values exactly with the locked current profile (or bootstrap
 -- defaults). Never silently discard a change the owner just reviewed.
 if value->'tools' is distinct from coalesce(to_jsonb(p.tools),'[]'::jsonb)
  or value->'vehicles' is distinct from coalesce(to_jsonb(p.vehicles),'[]'::jsonb)
  or value->'licenses' is distinct from coalesce(to_jsonb(p.licenses),'[]'::jsonb)
  or value->'teamCapacity' is distinct from to_jsonb(coalesce(p.team_capacity,1))
 then raise exception 'WORKER_AI_STALE' using errcode='PT409'; end if;
 if p.id is null then
  insert into public.app_profiles(id,account_id,kind,display_name,bio,skills)
  values(s.profile_id,auth.uid(),'WORKER',value->>'displayName',value->>'bio',
   array(select jsonb_array_elements_text(value->'skills'))) returning * into p;
 else
  update public.app_profiles set display_name=value->>'displayName',bio=value->>'bio',
   skills=array(select jsonb_array_elements_text(value->'skills')) where id=p.id;
 end if;
 if value->'location'<>private.worker_location_document(p.id)-array['profileId','accountId','revision'] then
  perform public.rpc_save_worker_location(private.worker_location_document(p.id)->>'revision',value->'location',true);
 end if;
 perform public.rpc_save_worker_availability(private.worker_availability_document(p.id)->>'revision',value->'availability');
 -- WPP01: preserve existing deprecated capacity; new profiles use the stored default.
 if (r.envelope->>'activate')::boolean then perform public.rpc_complete_worker_profile(p.id); end if;
 update public.ai_conversations set status='COMPLETED',completed_at=clock_timestamp() where id=s.conversation_id;
 receipt:=jsonb_build_object('reviewId',r.id,'conversationId',s.conversation_id,'accountId',auth.uid(),'profileId',p.id,
  'profileStatus',(select profile_status from public.app_profiles where id=p.id),'saved',true,'authoritative',true);
 insert into private.worker_ai_saves(review_id,account_id,client_request_id,receipt) values(r.id,auth.uid(),p_client_request_id,receipt);
 return receipt;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_save_worker_availability(p_expected_revision text, p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET "TimeZone" TO 'UTC'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
declare
  p public.app_profiles; before_doc jsonb; after_doc jsonb; wanted jsonb;
  item jsonb; wid uuid; days smallint[]; a time; b time; sd date; ed date;
  ws timestamptz; we timestamptz; rule_ids uuid[]:='{}'; window_ids uuid[]:='{}';
  rules jsonb:='[]'; windows jsonb:='[]'; zone text; previous_token text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into p from public.app_profiles where account_id=auth.uid() and kind='WORKER' for update;
  if not found then raise exception 'WORKER_PROFILE_REQUIRED' using errcode='55000'; end if;
  if p.profile_status not in ('DRAFT','ACTIVE') then raise exception 'WORKER_PROFILE_RESTRICTED' using errcode='42501'; end if;
  if p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_value) is distinct from 'object' or octet_length(p_value::text)>262144 then
    raise exception 'AVAILABILITY_INPUT_INVALID' using errcode='22023';
  end if;
  if p_value-ARRAY['timezone','availableNow','rules','windows']<>'{}'::jsonb
    or jsonb_typeof(p_value->'availableNow') is distinct from 'boolean'
    or jsonb_typeof(p_value->'timezone') is distinct from 'string'
    or jsonb_typeof(p_value->'rules') is distinct from 'array'
    or jsonb_typeof(p_value->'windows') is distinct from 'array' then
    raise exception 'AVAILABILITY_INPUT_INVALID' using errcode='22023';
  end if;
  zone:=p_value->>'timezone';
  if not private.availability_timezone_valid(zone) then raise exception 'AVAILABILITY_TIMEZONE_INVALID' using errcode='22023'; end if;
  -- Transport/compute safety ceilings, not booking capacity or dispatch policy.
  if jsonb_array_length(p_value->'rules')>128 or jsonb_array_length(p_value->'windows')>512 then
    raise exception 'AVAILABILITY_INPUT_TOO_LARGE' using errcode='22023';
  end if;
  for item in select value from jsonb_array_elements(p_value->'rules') loop
    if jsonb_typeof(item) is distinct from 'object'
      or item-ARRAY['id','weekdays','startTime','endTime','startsOn','endsOn','label','active']<>'{}'::jsonb
      or jsonb_typeof(item->'id') is distinct from 'string'
      or (item->>'id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
      or jsonb_typeof(item->'weekdays') is distinct from 'array'
      or jsonb_typeof(item->'active') is distinct from 'boolean'
      or jsonb_typeof(item->'label') is distinct from 'string' or length(item->>'label')>256
      or coalesce(item->>'startTime','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]{1,6})?)?$'
      or coalesce(item->>'endTime','') !~ '^(([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]{1,6})?)?|24:00(:00)?)$'
      or coalesce(item->>'startsOn','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      or not (item?'endsOn') or (item->'endsOn'<>'null'::jsonb and coalesce(item->>'endsOn','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    if exists(select 1 from jsonb_array_elements(item->'weekdays') d where jsonb_typeof(d)<>'number' or d::text !~ '^[0-6]$') then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    select array_agg(d::text::smallint order by d::text::smallint) into days from jsonb_array_elements(item->'weekdays') d;
    if coalesce(cardinality(days),0) not between 1 and 7 or cardinality(days)<>(select count(distinct x) from unnest(days) x) then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    begin
      wid:=(item->>'id')::uuid; a:=(item->>'startTime')::time; b:=(item->>'endTime')::time;
      sd:=(item->>'startsOn')::date; ed:=(item->>'endsOn')::date;
    exception when invalid_datetime_format or datetime_field_overflow then raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023'; end;
    if a>=b or not isfinite(sd) or (ed is not null and (not isfinite(ed) or ed<sd)) or wid=any(rule_ids)
      or exists(select 1 from public.profile_availability_rules r where r.id=wid and r.profile_id<>p.id) then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    rule_ids:=array_append(rule_ids,wid);
    rules:=rules||jsonb_build_array(jsonb_build_object('id',wid,'weekdays',days,'startTime',a::text,'endTime',b::text,
      'startsOn',sd::text,'endsOn',ed::text,'label',item->>'label','active',(item->>'active')::boolean));
  end loop;
  for item in select value from jsonb_array_elements(p_value->'windows') loop
    if jsonb_typeof(item) is distinct from 'object' or item-ARRAY['id','startsAt','endsAt','state','label']<>'{}'::jsonb
      or jsonb_typeof(item->'id') is distinct from 'string'
      or (item->>'id') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
      or jsonb_typeof(item->'label') is distinct from 'string' or length(item->>'label')>256
      or coalesce(item->>'state','') not in ('AVAILABLE','UNAVAILABLE')
      or coalesce(item->>'startsAt','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$'
      or coalesce(item->>'endsAt','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-](0[0-9]|1[0-5]):[0-5][0-9])$' then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    begin wid:=(item->>'id')::uuid; ws:=(item->>'startsAt')::timestamptz; we:=(item->>'endsAt')::timestamptz;
    exception when invalid_datetime_format or datetime_field_overflow then raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023'; end;
    if not isfinite(ws) or not isfinite(we) or ws>=we or wid=any(window_ids)
      or exists(select 1 from public.profile_availability_windows w where w.id=wid and w.profile_id<>p.id) then
      raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023';
    end if;
    window_ids:=array_append(window_ids,wid);
    windows:=windows||jsonb_build_array(jsonb_build_object('id',wid,
      'startsAt',to_char(ws,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'endsAt',to_char(we,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'state',item->>'state','label',item->>'label'));
  end loop;
  select coalesce(jsonb_agg(x order by x->>'id'),'[]'::jsonb) into rules from jsonb_array_elements(rules) x;
  select coalesce(jsonb_agg(x order by x->>'id'),'[]'::jsonb) into windows from jsonb_array_elements(windows) x;
  wanted:=jsonb_build_object('profileId',p.id,'accountId',p.account_id,'timezone',zone,
    'availableNow',(p_value->>'availableNow')::boolean,'rules',rules,'windows',windows);
  before_doc:=private.worker_availability_document(p.id);
  -- A lost response may be safely retried: an already-identical result performs
  -- no writes. A stale different document must never erase newer edits.
  if before_doc-'revision'=wanted then
    return jsonb_build_object('saved',true,'idempotentReplay',true,'availability',before_doc);
  end if;
  if before_doc->>'revision'<>p_expected_revision then raise exception 'AVAILABILITY_VERSION_CONFLICT' using errcode='PT409'; end if;
  previous_token:=current_setting('uskoci.profile_mutation',true);
  perform set_config('uskoci.profile_mutation','AVAILABILITY_REVIEW',true);
  insert into public.worker_match_preferences(worker_profile_id,worker_account_id,timezone)
    values(p.id,p.account_id,zone) on conflict(worker_profile_id) do update set timezone=excluded.timezone;
  update public.app_profiles set available_now=(p_value->>'availableNow')::boolean where id=p.id;
  delete from public.profile_availability_rules where profile_id=p.id and not(id=any(rule_ids));
  delete from public.profile_availability_windows where profile_id=p.id and not(id=any(window_ids));
  for item in select value from jsonb_array_elements(rules) loop
    insert into public.profile_availability_rules(id,profile_id,weekdays,start_time,end_time,starts_on,ends_on,label,active)
      values((item->>'id')::uuid,p.id,ARRAY(select x::text::smallint from jsonb_array_elements(item->'weekdays') x),
        (item->>'startTime')::time,(item->>'endTime')::time,(item->>'startsOn')::date,(item->>'endsOn')::date,item->>'label',(item->>'active')::boolean)
      on conflict(id) do update set weekdays=excluded.weekdays,start_time=excluded.start_time,end_time=excluded.end_time,
        starts_on=excluded.starts_on,ends_on=excluded.ends_on,label=excluded.label,active=excluded.active
      where public.profile_availability_rules.profile_id=p.id;
    if not found then raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023'; end if;
  end loop;
  for item in select value from jsonb_array_elements(windows) loop
    insert into public.profile_availability_windows(id,profile_id,starts_at,ends_at,availability_state,label)
      values((item->>'id')::uuid,p.id,(item->>'startsAt')::timestamptz,(item->>'endsAt')::timestamptz,item->>'state',item->>'label')
      on conflict(id) do update set starts_at=excluded.starts_at,ends_at=excluded.ends_at,availability_state=excluded.availability_state,label=excluded.label
      where public.profile_availability_windows.profile_id=p.id;
    if not found then raise exception 'AVAILABILITY_ITEM_INVALID' using errcode='22023'; end if;
  end loop;
  perform set_config('uskoci.profile_mutation',coalesce(previous_token,''),true);
  perform private.requeue_open_needs_for_worker_v5(p.account_id);
  after_doc:=private.worker_availability_document(p.id);
  return jsonb_build_object('saved',true,'idempotentReplay',false,'availability',after_doc);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_save_worker_capacity(p_expected_revision text, p_team_capacity jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles; before_doc jsonb; wanted integer; prior_token text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_team_capacity) is distinct from 'number' then
    raise exception 'WORKER_CAPACITY_INPUT_INVALID' using errcode='22023';
  end if;
  if (p_team_capacity#>>'{}')::numeric <> trunc((p_team_capacity#>>'{}')::numeric)
    or (p_team_capacity#>>'{}')::numeric not between 1 and 50 then
    raise exception 'WORKER_CAPACITY_INPUT_INVALID' using errcode='22023';
  end if;
  wanted:=(p_team_capacity#>>'{}')::integer;
  -- Existing submit/selection also lock this profile. No second allocation model.
  select * into p from public.app_profiles where account_id=auth.uid() and kind='WORKER' for update;
  if not found then raise exception 'WORKER_PROFILE_REQUIRED' using errcode='55000'; end if;
  if p.profile_status not in ('DRAFT','ACTIVE') then raise exception 'WORKER_PROFILE_RESTRICTED' using errcode='42501'; end if;
  before_doc:=private.worker_capacity_document(p.id);
  if p.team_capacity=wanted then
    return jsonb_build_object('saved',true,'idempotentReplay',true,'capacity',before_doc);
  end if;
  if before_doc->>'revision'<>p_expected_revision then
    raise exception 'WORKER_CAPACITY_VERSION_CONFLICT' using errcode='PT409';
  end if;
  prior_token:=current_setting('uskoci.profile_mutation',true);
  perform set_config('uskoci.profile_mutation','CAPACITY_REVIEW',true);
  update public.app_profiles set team_capacity=wanted where id=p.id;
  perform set_config('uskoci.profile_mutation',coalesce(prior_token,''),true);
  perform private.requeue_open_needs_for_worker_v5(p.account_id);
  return jsonb_build_object('saved',true,'idempotentReplay',false,'capacity',private.worker_capacity_document(p.id));
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_save_worker_location(p_expected_revision text, p_value jsonb, p_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p public.app_profiles; before_doc jsonb; wanted jsonb; v_city text; radius integer; coords jsonb; lat numeric; lng numeric; country text; previous_token text;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_confirmed is distinct from true then raise exception 'LOCATION_CONFIRMATION_REQUIRED' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_value) is distinct from 'object' or octet_length(p_value::text)>4096 then
    raise exception 'LOCATION_INPUT_INVALID' using errcode='22023';
  end if;
  if p_value-ARRAY['operatingCountryCode','city','radiusKm','approximatePosition']<>'{}'::jsonb or not (p_value ?& ARRAY['operatingCountryCode','city','radiusKm','approximatePosition'])
    or private.location_text_valid(p_value->'city',160) is distinct from true
    or jsonb_typeof(p_value->'radiusKm') is distinct from 'number' then
    raise exception 'LOCATION_INPUT_INVALID' using errcode='22023';
  end if;
  if (p_value->>'radiusKm')::numeric not between 1 and 200 or trunc((p_value->>'radiusKm')::numeric)<>(p_value->>'radiusKm')::numeric then
    raise exception 'LOCATION_INPUT_INVALID' using errcode='22023';
  end if;
  country:=private.require_location_country(p_value->'operatingCountryCode');
  v_city:=btrim(p_value->>'city');radius:=(p_value->>'radiusKm')::numeric::integer;coords:=p_value->'approximatePosition';
  if coords<>'null'::jsonb then
    if jsonb_typeof(coords) is distinct from 'object' then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
    if coords-ARRAY['latitude','longitude']<>'{}'::jsonb or jsonb_typeof(coords->'latitude') is distinct from 'number'
      or jsonb_typeof(coords->'longitude') is distinct from 'number' then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
    lat:=(coords->>'latitude')::numeric;lng:=(coords->>'longitude')::numeric;
    if lat not between -90 and 90 or lng not between -180 and 180 or lat<>round(lat,2) or lng<>round(lng,2) then
      raise exception 'LOCATION_INPUT_INVALID' using errcode='22023';
    end if;
  end if;
  wanted:=jsonb_build_object('operatingCountryCode',country,'city',v_city,'radiusKm',radius,'approximatePosition',coords);
  select * into p from public.app_profiles where account_id=auth.uid() and kind='WORKER' for update;
  if not found then raise exception 'WORKER_PROFILE_REQUIRED' using errcode='55000'; end if;
  if p.profile_status not in ('DRAFT','ACTIVE') then raise exception 'WORKER_PROFILE_RESTRICTED' using errcode='42501'; end if;
  before_doc:=private.worker_location_document(p.id);
  if before_doc-ARRAY['revision','accountId','profileId']=wanted then
    return jsonb_build_object('saved',true,'idempotentReplay',true,'location',before_doc);
  end if;
  if before_doc->>'revision'<>p_expected_revision then raise exception 'LOCATION_VERSION_CONFLICT' using errcode='PT409'; end if;
  previous_token:=current_setting('uskoci.profile_mutation',true);
  perform set_config('uskoci.profile_mutation','LOCATION_REVIEW',true);
  update public.app_profiles set operating_country_code=country, city=v_city, radius_km=radius where id=p.id;
  insert into public.worker_match_preferences(worker_profile_id,worker_account_id,approximate_lat,approximate_lng)
    values(p.id,auth.uid(),lat,lng) on conflict(worker_profile_id) do update set approximate_lat=excluded.approximate_lat,approximate_lng=excluded.approximate_lng;
  perform set_config('uskoci.profile_mutation',coalesce(previous_token,''),true);
  perform private.requeue_open_needs_for_worker_v5(p.account_id);
  return jsonb_build_object('saved',true,'idempotentReplay',false,'location',private.worker_location_document(p.id));
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_select_response(p_need_id uuid, p_need_revision integer, p_response_id uuid, p_response_version integer, p_content_hash text, p_client_request_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  uid uuid := auth.uid();
  v_need public.needs%rowtype;
  v_resp public.marketplace_responses%rowtype;
  v_ver public.marketplace_response_versions%rowtype;
  v_requested_ver public.marketplace_response_versions%rowtype;
  v_profile public.app_profiles%rowtype;
  v_command private.selection_commands%rowtype;
  v_policy private.connection_policy_versions%rowtype;
  v_selection_id uuid;
  v_agreement_id uuid;
  v_covered integer;
  v_terms jsonb;
  v_match jsonb;
  v_request_hash text;
  v_legacy_selected_by uuid;
  v_legacy_need_revision integer;
  v_legacy_response_id uuid;
  v_legacy_covered_slots integer;
  v_legacy_agreement_id uuid;
  v_legacy_response_version integer;
  v_legacy_content_hash text;
begin
  if uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if p_client_request_id is null
     or char_length(btrim(p_client_request_id)) not between 8 and 200 then
    raise exception 'INVALID_CLIENT_REQUEST_ID' using errcode = '22023';
  end if;

  select * into v_requested_ver
    from public.marketplace_response_versions
   where response_id = p_response_id
     and version = p_response_version;

  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'requesterAccountId', uid,
    'needId', p_need_id,
    'needRevision', p_need_revision,
    'responseId', p_response_id,
    'responseVersion', p_response_version,
    'contentHash', p_content_hash,
    'coveredSlots', v_requested_ver.covered_slots
  )::text, 'UTF8')), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(uid::text || ':' || p_client_request_id, 7242)
  );

  select * into v_command
    from private.selection_commands c
   where c.requester_account_id = uid
     and c.client_request_id = p_client_request_id;

  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;
    return v_command.agreement_id;
  end if;

  -- Pre-P0D-02/P0D-03 historical rows remain authoritative and are not
  -- retroactively charged or given fabricated activation receipts.
  select s.selected_by_account_id,
         s.need_revision,
         s.response_id,
         s.covered_slots,
         a.id,
         nullif(av.terms->>'response_version','')::integer,
         av.content_hash
    into v_legacy_selected_by,
         v_legacy_need_revision,
         v_legacy_response_id,
         v_legacy_covered_slots,
         v_legacy_agreement_id,
         v_legacy_response_version,
         v_legacy_content_hash
    from public.need_selections s
    join public.agreements a on a.selection_id = s.id
    left join public.agreement_versions av
      on av.agreement_id = a.id and av.version = 1
   where s.need_id = p_need_id
     and s.client_request_id = p_client_request_id;

  if found then
    if v_legacy_selected_by <> uid then
      raise exception 'NOT_REQUESTER' using errcode = '42501';
    end if;
    if v_legacy_need_revision <> p_need_revision
       or v_legacy_response_id is distinct from p_response_id
       or (v_requested_ver.response_id is not null
           and v_legacy_covered_slots <> v_requested_ver.covered_slots)
       or (v_legacy_response_version is not null
           and v_legacy_response_version <> p_response_version)
       or (v_legacy_content_hash is not null
           and v_legacy_content_hash <> p_content_hash) then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '22023';
    end if;
    return v_legacy_agreement_id;
  end if;

  select * into v_need from public.needs where id = p_need_id for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_need.requester_account_id <> uid then raise exception 'NOT_REQUESTER' using errcode = '42501'; end if;
  if v_need.status not in ('PUBLISHED','SELECTION') then
    raise exception 'NEED_NOT_OPEN' using errcode = 'P0001', detail = v_need.status; end if;

  if v_need.response_deadline is not null
     and v_need.response_deadline <= statement_timestamp() then
    raise exception 'RESPONSE_WINDOW_EXPIRED' using errcode = 'P0001', hint = 'Rok za prijave je istekao.';
  end if;

  -- Existing agreements and idempotent selection receipts returned above.
  -- Only a NEW selection is refused after the actual task-time boundary.
  if not private.need_search_time_admitted_v1(v_need.id,clock_timestamp()) then
    raise exception 'NEED_EXECUTION_WINDOW_EXPIRED' using errcode='PT409',
      hint='Vreme za ovaj zadatak je isteklo.';
  end if;

  if v_need.revision <> p_need_revision then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'need_revision',
      hint = 'Potreba je izmenjena. Pogledajte prijave ponovo.'; end if;

  select * into v_resp from public.marketplace_responses where id = p_response_id for update;
  if not found then raise exception 'RESPONSE_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_resp.need_id <> p_need_id then raise exception 'RESPONSE_NEED_MISMATCH' using errcode = 'P0001'; end if;
  if v_resp.status not in ('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED') then
    raise exception 'RESPONSE_NOT_SELECTABLE' using errcode = 'P0001', detail = v_resp.status; end if;

  if v_resp.current_version <> p_response_version then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'response_version',
      hint = 'Uskocer je izmenio prijavu. Proverite je ponovo.'; end if;

  select * into v_ver from public.marketplace_response_versions
   where response_id = p_response_id and version = p_response_version;
  if not found then raise exception 'RESPONSE_VERSION_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_ver.content_hash <> p_content_hash then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'content_hash',
      hint = 'Uslovi prijave su izmenjeni.'; end if;
  if v_ver.need_revision <> v_need.revision then
    raise exception 'STALE_REVIEW_REQUIRED' using errcode = 'P0001', detail = 'response_need_revision'; end if;

  select * into v_profile
    from public.app_profiles p
   where p.id = v_resp.worker_profile_id
   for share;

  if not found
     or v_profile.kind <> 'WORKER'
     or v_profile.account_id <> v_resp.worker_account_id
     or v_profile.profile_status <> 'ACTIVE'
     or char_length(btrim(v_profile.display_name)) < 2
     or char_length(btrim(v_profile.city)) < 2
     or cardinality(v_profile.skills) < 1 then
    raise exception 'WORKER_PROFILE_NOT_READY' using errcode = 'P0001',
      hint = 'Uskocer vise nema vazeci spreman profil za izbor.';
  end if;

  -- WPP01: accept the people committed by this offer, subject to the
  -- existing task remaining-slot, calendar and price checks below.

  if (v_ver.proposed_start_at is null)<>(v_ver.proposed_end_at is null) then
    raise exception 'AGREEMENT_CALENDAR_INTERVAL_INVALID' using errcode='22023';
  end if;
  if v_ver.proposed_start_at is null and v_need.schedule_kind='FIXED_WINDOW'
    and (v_need.starts_at is null or not isfinite(v_need.starts_at)
      or (v_need.ends_at is not null and (not isfinite(v_need.ends_at) or v_need.starts_at>=v_need.ends_at))) then
    raise exception 'NEED_FIXED_INTERVAL_INVALID' using errcode='22023';
  end if;
  -- An old start-only task cannot be selected after its precise beginning.
  if v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is null
     and v_need.starts_at is not null and v_need.starts_at<=statement_timestamp() then
    raise exception 'FIXED_WINDOW_START_PASSED' using errcode='22023';
  end if;
  v_match := private.match_detail_for_calendar_interval(p_need_id, v_resp.worker_profile_id,
    coalesce(v_ver.proposed_start_at,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.starts_at end),
    coalesce(v_ver.proposed_end_at,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.ends_at end));
  if not coalesce((v_match->>'responseAllowed')::boolean, false) then
    raise exception 'WORKER_NO_LONGER_ELIGIBLE' using errcode = 'P0001',
      detail = coalesce((v_match->'hardBlockers')::text,'[]'),
      hint = 'Uskocer vise ne ispunjava uslove Potrebe.';
  end if;

  -- Start-only selection must still reject an existing confirmed Dogovor
  -- that blocks the precise declared start. One microsecond is only a
  -- point-overlap probe, NOT a booked duration or task finish.
  if v_ver.proposed_start_at is null and v_need.schedule_kind='FIXED_WINDOW'
     and v_need.ends_at is null and
     private.worker_calendar_conflict(v_resp.worker_profile_id,v_need.starts_at,
       v_need.starts_at+interval '1 microsecond',null) then
    raise exception 'WORKER_CALENDAR_CONFLICT' using errcode='P0001';
  end if;
  v_covered := public.fn_need_covered_slots(p_need_id);
  if v_covered + v_resp.covered_slots > v_need.required_slots then
    raise exception 'OVERFILL' using errcode = 'P0001', hint = 'Ta prijava pokriva vise mesta nego sto je preostalo.'; end if;

  -- PKG-033: historical/reconfirmed offers cannot bypass today's fixed-price rule at selection.
  perform private.assert_application_price_v5(v_need, v_ver.covered_slots, v_ver.price_rsd);

  select * into v_policy
    from private.connection_policy_versions
   where policy_key='REQUESTER_SELECTION_V1' and version=1;
  if not found
     or v_policy.beneficiary_role <> 'REQUESTER'
     or v_policy.activation_reason <> 'SELECTION'
     or v_policy.charge_mode <> 'PROMOTIONAL_FREE'
     or v_policy.unit_basis <> 'HEADCOUNT'
     or v_policy.platform_cost_rsd <> 0 then
    raise exception 'CONNECTION_POLICY_NOT_READY' using errcode='55000';
  end if;

  insert into public.need_selections(
    need_id,need_revision,selected_by_account_id,client_request_id,covered_slots,
    response_id,worker_account_id,worker_profile_id,selection_mode,status
  ) values (
    p_need_id,v_need.revision,uid,p_client_request_id,v_resp.covered_slots,
    p_response_id,v_resp.worker_account_id,v_resp.worker_profile_id,
    case when v_need.mode='FASTEST' then 'AUTO_FILL' else 'REQUESTER_SELECTS' end,
    'SELECTED'
  ) returning id into v_selection_id;

  v_terms := jsonb_build_object(
    'price_rsd',v_ver.price_rsd,'covered_slots',v_ver.covered_slots,
    -- Agreement calendar terms stay an honest complete pair or BOTH NULL.
    -- A declared start-only moment stays authoritative on the task; it is
    -- not a fabricated booking in private.agreement_calendar_interval().
    'proposed_start_at',coalesce(v_ver.proposed_start_at,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.starts_at end),
    'proposed_end_at',coalesce(v_ver.proposed_end_at,case when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then v_need.ends_at end),
    'schedule_source',case when v_ver.proposed_start_at is not null then 'APPLICATION_PROPOSAL'
      when v_need.schedule_kind='FIXED_WINDOW' and v_need.ends_at is not null then 'NEED_FIXED_WINDOW' else 'UNSCHEDULED' end,
    'scope_note',v_ver.scope_note,'need_revision',v_need.revision,
    'response_version',v_ver.version
  );
  -- Snapshot the requested exact start separately from the calendar reservation.
  -- Calendar interval uses ONLY a complete proposed_start_at/proposed_end_at pair.
  if v_ver.proposed_start_at is null and v_need.schedule_kind='FIXED_WINDOW'
     and v_need.ends_at is null and v_need.starts_at is not null then
    v_terms:=v_terms||jsonb_build_object('declared_start_at',v_need.starts_at);
  end if;

  insert into public.agreements(
    need_id,selection_id,selected_response_id,requester_account_id,requester_profile_id,
    worker_account_id,worker_profile_id,current_version,status
  ) values (
    p_need_id,v_selection_id,p_response_id,v_need.requester_account_id,v_need.requester_profile_id,
    v_resp.worker_account_id,v_resp.worker_profile_id,1,'CONFIRMED'
  ) returning id into v_agreement_id;

  insert into public.agreement_versions(
    agreement_id,version,status,terms,content_hash,created_by_account_id
  ) values (v_agreement_id,1,'CONFIRMED',v_terms,v_ver.content_hash,uid);

  insert into public.agreement_execution(agreement_id,agreement_version,mode,state)
  values (
    v_agreement_id,1,
    -- PKG-029b (deep read 12.7): remote or physical follows the place; the schedule decides only for a task
    -- written before the place had a mode.
    case when coalesce(v_need.execution_location_mode = 'REMOTE', v_need.schedule_kind = 'REMOTE_ANYTIME')
      then 'REMOTE' else 'PHYSICAL' end,
    'CONFIRMED'
  );

  insert into private.connection_activations(
    requester_account_id,beneficiary_account_id,client_request_id,request_hash,
    policy_key,policy_version,policy_snapshot,activation_reason,
    need_id,need_revision,selection_id,agreement_id,response_id,response_version,
    response_content_hash,worker_account_id,worker_profile_id,units,platform_cost_rsd,state
  ) values (
    uid,uid,p_client_request_id,v_request_hash,
    v_policy.policy_key,v_policy.version,v_policy.policy_snapshot,'SELECTION',
    p_need_id,p_need_revision,v_selection_id,v_agreement_id,p_response_id,p_response_version,
    p_content_hash,v_resp.worker_account_id,v_resp.worker_profile_id,v_ver.covered_slots,0,'SATISFIED'
  );

  update public.marketplace_responses
     set status='SELECTED',selected_at=statement_timestamp()
   where id=p_response_id;

  perform set_config('uskoci.need_lifecycle','SELECT',true);
  update public.needs
     set status=case when v_covered+v_resp.covered_slots >= v_need.required_slots
                     then 'ACTIVE' else 'SELECTION' end
   where id=p_need_id;

  insert into private.selection_commands(
    requester_account_id,client_request_id,request_hash,
    need_id,need_revision,response_id,response_version,
    response_content_hash,covered_slots,selection_id,agreement_id
  ) values (
    uid,p_client_request_id,v_request_hash,
    p_need_id,p_need_revision,p_response_id,p_response_version,
    p_content_hash,v_ver.covered_slots,v_selection_id,v_agreement_id
  );

  -- N02: domain event shares the Selection/Agreement/activation transaction.
  -- Preferences, suppression and channel dedupe remain owned by emit_event.
  perform private.emit_event(
    v_resp.worker_account_id, 'WORKER', 'RESPONSE_SELECTED',
    'RESPONSE', v_resp.id, v_ver.version,
    'Vaša prijava je izabrana', 'Otvorite Dogovor za detalje zadatka.',
    'response_selected:' || v_selection_id::text,
    'NORMAL', jsonb_build_object('agreement_id', v_agreement_id, 'need_id', v_need.id)
  );

  return v_agreement_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_send_agreement_message(p_agreement_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_agreement public.agreements%rowtype;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if char_length(btrim(coalesce(p_body, ''))) < 1 then
    raise exception 'MESSAGE_REQUIRED' using errcode = 'P0001';
  end if;
  if char_length(btrim(p_body)) > 2000 then
    raise exception 'MESSAGE_TOO_LONG' using errcode = '22001';
  end if;

  select * into v_agreement from public.agreements where id = p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_uid not in (v_agreement.requester_account_id, v_agreement.worker_account_id) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;
  if v_agreement.status not in ('CONFIRMED','SUPERSEDED') then
    raise exception 'CHAT_NOT_AVAILABLE' using errcode = 'P0001', detail = v_agreement.status;
  end if;

  insert into public.agreement_messages(agreement_id, agreement_version, sender_account_id, body)
  values (p_agreement_id, v_agreement.current_version, v_uid, btrim(p_body))
  returning id into v_id;
  -- Durable domain event only; private.emit_event owns preference/delivery logic.
  -- Do not copy message text, contact details, location or task title into payload.
  perform private.emit_event(
    case when v_uid = v_agreement.requester_account_id
      then v_agreement.worker_account_id else v_agreement.requester_account_id end,
    case when v_uid = v_agreement.requester_account_id then 'WORKER' else 'REQUESTER' end,
    'MESSAGE_RECEIVED', 'AGREEMENT', p_agreement_id, v_agreement.current_version,
    'Nova poruka', 'Imate novu poruku u Dogovoru.',
    'agreement_message:' || v_id::text,
    'NORMAL', jsonb_build_object('message_id', v_id)
  );
  return v_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_send_agreement_message_v2(p_expected_user_id uuid, p_agreement_id uuid, p_client_message_id text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_body text:=btrim(coalesce(p_body,''));
  v_agreement public.agreements%rowtype;
  v_previous public.agreement_messages%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_expected_user_id is null or p_expected_user_id<>v_uid then
    raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
  if p_client_message_id is null or p_client_message_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{7,199}$' then
    raise exception 'INVALID_CLIENT_MESSAGE_ID' using errcode='22023'; end if;
  if char_length(v_body)<1 then raise exception 'MESSAGE_REQUIRED' using errcode='P0001'; end if;
  if char_length(v_body)>2000 then raise exception 'MESSAGE_TOO_LONG' using errcode='22001'; end if;

  -- Sender-global command ownership: moving the same key to another agreement
  -- is a conflict, never a second message. Identical concurrent retries wait.
  perform pg_advisory_xact_lock(hashtextextended('uskoci:message:'||v_uid::text||':'||p_client_message_id,0));
  -- Serialize against current lifecycle changes before invoking the unchanged
  -- writer. A replay still requires current membership, but may acknowledge a
  -- previously committed message after the agreement became read-only.
  select * into v_agreement from public.agreements where id=p_agreement_id for share;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode='P0002'; end if;
  if v_uid not in (v_agreement.requester_account_id,v_agreement.worker_account_id) then
    raise exception 'NOT_PARTY' using errcode='42501'; end if;

  select * into v_previous from public.agreement_messages
    where sender_account_id=v_uid and client_message_id=p_client_message_id;
  if found then
    if v_previous.agreement_id<>p_agreement_id or v_previous.body<>v_body then
      raise exception 'MESSAGE_COMMAND_CONFLICT' using errcode='PT409'; end if;
    return v_previous.id;
  end if;

  -- The proven legacy function remains the sole domain writer: same validation,
  -- agreement version, message UUID and one durable counterpart event.
  v_id:=public.rpc_send_agreement_message(p_agreement_id,v_body);
  update public.agreement_messages set client_message_id=p_client_message_id
    where id=v_id and sender_account_id=v_uid and agreement_id=p_agreement_id
      and client_message_id is null;
  if not found then raise exception 'MESSAGE_COMMAND_PERSISTENCE_FAILED' using errcode='55000'; end if;
  return v_id;
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_send_agreement_photo_message_v5(p_expected_user_id uuid, p_agreement_id uuid, p_expected_version integer, p_client_message_id text, p_body text, p_asset_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);ag public.agreements;m public.agreement_messages;b text:=btrim(coalesce(p_body,''));begin
 if p_client_message_id is null or p_client_message_id!~'^[A-Za-z0-9][A-Za-z0-9_.:-]{7,199}$' or p_expected_version is null or p_expected_version<1
 or char_length(b)>2000 or p_asset_ids is null or cardinality(p_asset_ids) not between 1 and 6 or array_ndims(p_asset_ids)<>1 or array_lower(p_asset_ids,1)<>1
 or array_position(p_asset_ids,null) is not null or(select count(distinct x) from unnest(p_asset_ids)x)<>cardinality(p_asset_ids) then raise exception 'MEDIA_INPUT_INVALID' using errcode='22023';end if;
 ag:=private.agreement_photo_context_v5(u,p_agreement_id,null,false);
 perform private.closure_assert_open(ag.requester_account_id,ag.worker_account_id);
 perform pg_advisory_xact_lock(private.agreement_photo_key_v5(u));
 perform pg_advisory_xact_lock(hashtextextended('uskoci:message:'||u::text||':'||p_client_message_id,0));
 select * into ag from public.agreements where id=p_agreement_id for share;
 select * into m from public.agreement_messages where sender_account_id=u and client_message_id=p_client_message_id;
 if found then
  if m.agreement_id<>p_agreement_id or m.agreement_version<>p_expected_version or m.body<>b or m.photo_asset_ids<>p_asset_ids then raise exception 'MEDIA_COMMAND_CONFLICT' using errcode='PT409';end if;
 else
  perform private.agreement_photo_context_v5(u,p_agreement_id,p_expected_version,true);
  -- Existing text writers stay unchanged. This attachment-specific writer uses
  -- the same canonical table, existing safety/closure triggers and one event.
  insert into public.agreement_messages(agreement_id,agreement_version,sender_account_id,client_message_id,body,photo_asset_ids)
  values(p_agreement_id,p_expected_version,u,p_client_message_id,b,p_asset_ids) returning * into m;
  update private.agreement_photo_uploads_v5 set attached_message_id=m.id where id=any(p_asset_ids);
  perform private.emit_event(case when u=ag.requester_account_id then ag.worker_account_id else ag.requester_account_id end,
   case when u=ag.requester_account_id then 'WORKER' else 'REQUESTER' end,'MESSAGE_RECEIVED','AGREEMENT',ag.id,p_expected_version,
   'Nova poruka','Imate novu poruku u Dogovoru.','agreement_message:'||m.id::text,'NORMAL',jsonb_build_object('message_id',m.id));
 end if;
 perform private.support_auth_v5(u);
 return jsonb_build_object('messageId',m.id,'agreementId',m.agreement_id,'agreementVersion',m.agreement_version,'clientMessageId',m.client_message_id,'body',m.body,'assetIds',to_jsonb(m.photo_asset_ids));
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_send_agreement_voice_message_v1(p_expected_user_id uuid, p_agreement_id uuid, p_expected_version integer, p_client_message_id text, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid := private.support_auth_v5(p_expected_user_id); ag public.agreements; m public.agreement_messages;
begin
  if p_client_message_id is null or p_client_message_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{7,199}$' or p_expected_version is null or p_expected_version < 1 or p_asset_id is null then
    raise exception 'MEDIA_INPUT_INVALID' using errcode = '22023';
  end if;
  ag := private.agreement_voice_context_v1(u, p_agreement_id, null, false);
  perform private.closure_assert_open(ag.requester_account_id, ag.worker_account_id);
  perform pg_advisory_xact_lock(private.agreement_voice_key_v1(u));
  perform pg_advisory_xact_lock(hashtextextended('uskoci:message:' || u::text || ':' || p_client_message_id, 0));
  select * into ag from public.agreements where id = p_agreement_id for share;
  select * into m from public.agreement_messages where sender_account_id = u and client_message_id = p_client_message_id;
  if found then
    if m.agreement_id <> p_agreement_id or m.agreement_version <> p_expected_version or m.voice_asset_id is distinct from p_asset_id
       or btrim(m.body) <> '' or cardinality(m.photo_asset_ids) <> 0 then
      raise exception 'MEDIA_COMMAND_CONFLICT' using errcode = 'PT409';
    end if;
  else
    perform private.agreement_voice_context_v1(u, p_agreement_id, p_expected_version, true);
    insert into public.agreement_messages(agreement_id, agreement_version, sender_account_id, client_message_id, body, voice_asset_id)
      values (p_agreement_id, p_expected_version, u, p_client_message_id, '', p_asset_id) returning * into m;
    update private.agreement_voice_uploads_v1 set attached_message_id = m.id where id = p_asset_id;
    perform private.emit_event(case when u = ag.requester_account_id then ag.worker_account_id else ag.requester_account_id end,
      case when u = ag.requester_account_id then 'WORKER' else 'REQUESTER' end, 'MESSAGE_RECEIVED', 'AGREEMENT', ag.id, p_expected_version,
      'Nova poruka', 'Imate novu poruku u Dogovoru.', 'agreement_message:' || m.id::text, 'NORMAL', jsonb_build_object('message_id', m.id));
  end if;
  perform private.support_auth_v5(u);
  return jsonb_build_object('messageId', m.id, 'agreementId', m.agreement_id, 'agreementVersion', m.agreement_version,
    'clientMessageId', m.client_message_id, 'voiceAssetId', m.voice_asset_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_send_group_message_v5(p_expected_user_id uuid, p_group_id uuid, p_client_request_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid();g private.group_conversations_v5;m private.group_messages_v5;body text:=btrim(p_body);r uuid;seq bigint;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000';end if;
 if p_group_id is null or p_client_request_id is null or body is null or char_length(body) not between 1 and 2000 then raise exception 'GROUP_MESSAGE_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:group-message:'||u::text||':'||p_client_request_id::text,137));
 select * into g from private.group_conversations_v5 where id=p_group_id for update;
 if not found or not private.group_member_v5(g,u) then raise exception 'GROUP_NOT_AVAILABLE' using errcode='42501';end if;
 select * into m from private.group_messages_v5 where sender_account_id=u and client_request_id=p_client_request_id;
 if found then
  if m.group_id<>g.id or m.body<>body then raise exception 'GROUP_MESSAGE_KEY_REUSED' using errcode='22023';end if;
  return private.group_message_receipt_v5(m,true);
 end if;
 perform private.closure_assert_open(u,g.requester_account_id);
 if u<>g.requester_account_id then perform pg_advisory_xact_lock_shared(private.safety_pair_key(u,g.requester_account_id));end if;
 if not private.group_can_send_v5(g,u) then raise exception 'GROUP_READ_ONLY' using errcode='42501';end if;
 -- Safety and closure exclusive barriers never take group/domain row locks.
 -- All eligibility is read again under these shared barriers before admission.
 for r in select distinct account_id from private.group_memberships_v5 where group_id=g.id and ended_sequence is null
  union select g.requester_account_id order by 1 loop
  perform pg_advisory_xact_lock_shared(private.closure_account_key(r));
  if r<>u then perform pg_advisory_xact_lock_shared(private.safety_pair_key(u,r));end if;
 end loop;
 if not private.group_can_send_v5(g,u) then raise exception 'GROUP_READ_ONLY' using errcode='42501';end if;
 update private.group_conversations_v5 set sequence=sequence+1 where id=g.id returning sequence into seq;
 insert into private.group_messages_v5(group_id,sequence,sender_account_id,client_request_id,body,body_sha256)
 values(g.id,seq,u,p_client_request_id,body,encode(extensions.digest(convert_to(body,'UTF8'),'sha256'),'hex')) returning * into m;
 insert into private.group_message_visibility_v5(message_id,account_id,read_at)
 select m.id,x.account_id,case when x.account_id=u then m.created_at end from (
  select g.requester_account_id account_id union select t.account_id from private.group_memberships_v5 t
  where t.group_id=g.id and t.ended_sequence is null and t.joined_sequence<=seq) x
 where not private.closure_account_restricted(x.account_id) and (x.account_id=u or not private.safety_pair_blocked(u,x.account_id));
 return private.group_message_receipt_v5(m,false);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_set_account_block(p_target_account_id uuid, p_blocked boolean, p_expected_revision integer, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); r private.account_blocks; c private.account_block_commands; h text; receipt jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_target_account_id is null or p_target_account_id=u or p_blocked is null or p_client_request_id is null
 or p_expected_revision is null or p_expected_revision<0 or p_expected_revision>=2147483647 then raise exception 'BLOCK_INPUT_INVALID' using errcode='22023'; end if;
 h:=encode(extensions.digest(jsonb_build_object('target',p_target_account_id,'blocked',p_blocked,'revision',p_expected_revision)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('uskoci:block-command:'||u::text||':'||p_client_request_id::text,8318));
 select * into c from private.account_block_commands where actor_account_id=u and client_request_id=p_client_request_id;
 if found then
  if c.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return c.receipt||jsonb_build_object('idempotentReplay',true);
 end if;
 if not exists(select 1 from public.app_accounts where id=p_target_account_id) then raise exception 'TARGET_NOT_AVAILABLE' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(private.safety_pair_key(u,p_target_account_id));
 select * into r from private.account_blocks where blocker_account_id=u and blocked_account_id=p_target_account_id;
 if coalesce(r.revision,0)<>p_expected_revision then raise exception 'BLOCK_REVISION_CONFLICT' using errcode='PT409'; end if;
 insert into private.account_blocks(blocker_account_id,blocked_account_id,active,revision,last_blocked_at)
 values(u,p_target_account_id,p_blocked,p_expected_revision+1,case when p_blocked then clock_timestamp() end)
 on conflict(blocker_account_id,blocked_account_id) do update set active=excluded.active,revision=excluded.revision,
 last_blocked_at=case when excluded.active then clock_timestamp() else private.account_blocks.last_blocked_at end,updated_at=clock_timestamp();
 receipt:=jsonb_build_object('accountId',u,'targetAccountId',p_target_account_id,'blocked',p_blocked,'revision',p_expected_revision+1,
  'clientRequestId',p_client_request_id,'idempotentReplay',false,'authoritative',true);
 insert into private.account_block_commands(actor_account_id,client_request_id,target_account_id,input_hash,receipt) values(u,p_client_request_id,p_target_account_id,h,receipt);
 perform private.audit_marketplace(u,case when p_blocked then 'ACCOUNT_BLOCKED' else 'ACCOUNT_UNBLOCKED' end,'ACCOUNT',p_target_account_id,p_expected_revision+1,'{}');
 return receipt;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_set_contact_grant(p_agreement_id uuid, p_channel text, p_granted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_agreement public.agreements%rowtype;
  v_to uuid;
  v_grant_id uuid;
  v_phone text;
  v_address text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_channel not in ('PHONE', 'EXACT_LOCATION') then
    raise exception 'UNSUPPORTED_CHANNEL' using errcode = '22023';
  end if;
  if p_granted is null then
    raise exception 'GRANT_DECISION_REQUIRED' using errcode = '22004';
  end if;

  select *
    into v_agreement
    from public.agreements
   where id = p_agreement_id
   for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_uid not in (v_agreement.requester_account_id, v_agreement.worker_account_id) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;

  v_to := case
            when v_uid = v_agreement.requester_account_id then v_agreement.worker_account_id
            else v_agreement.requester_account_id
          end;

  -- Revocation is deliberately allowed after cancellation/completion so a
  -- user can always close their own grant. New grants require a live agreement.
  if p_granted and v_agreement.status <> 'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_ACTIVE' using errcode = 'P0001', detail = v_agreement.status;
  end if;

  if p_channel = 'PHONE' and p_granted then
    select nullif(btrim(a.phone), '')
      into v_phone
      from public.app_accounts a
     where a.id = v_uid;
    if v_phone is null then
      raise exception 'PHONE_NOT_SET' using errcode = 'P0001';
    end if;
  end if;

  -- Exact Need location belongs to the requester. A worker cannot grant a
  -- requester's address back to them or to anyone else.
  if p_channel = 'EXACT_LOCATION' then
    if v_uid <> v_agreement.requester_account_id then
      raise exception 'NOT_LOCATION_OWNER' using errcode = '42501';
    end if;
    if p_granted then
      select nullif(btrim(s.exact_address), '')
        into v_address
        from public.need_sensitive s
       where s.need_id = v_agreement.need_id;
      if v_address is null and not exists (
        select 1 from public.need_sensitive s join public.needs n on n.id=s.need_id join public.need_geography g on g.need_id=n.id
        where s.need_id=v_agreement.need_id and s.resolved_location is not null
          and private.resolved_location_record_valid(s.resolved_location,n.task_country_code,g.public_topology,s.exact_address,n.requester_account_id)
      ) then
        raise exception 'LOCATION_NOT_SET' using errcode = 'P0001';
      end if;
    end if;
  end if;

  if p_granted then
    insert into public.access_grants (
      agreement_id,
      channel,
      granted_by_account_id,
      granted_to_account_id,
      status,
      granted_at,
      revoked_at,
      expires_at
    ) values (
      p_agreement_id,
      p_channel,
      v_uid,
      v_to,
      'GRANTED',
      statement_timestamp(),
      null,
      null
    )
    on conflict (agreement_id, channel, granted_by_account_id, granted_to_account_id)
    do update set
      status = 'GRANTED',
      granted_at = statement_timestamp(),
      revoked_at = null,
      expires_at = null
    returning id into v_grant_id;
  else
    update public.access_grants
       set status = 'REVOKED',
           revoked_at = coalesce(revoked_at, statement_timestamp())
     where agreement_id = p_agreement_id
       and channel = p_channel
       and granted_by_account_id = v_uid
       and granted_to_account_id = v_to
    returning id into v_grant_id;
  end if;

  return jsonb_build_object(
    'agreementId', p_agreement_id,
    'channel', p_channel,
    'grantedByAccountId', v_uid,
    'grantedToAccountId', v_to,
    'granted', p_granted,
    'grantId', v_grant_id,
    'authoritative', true
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_set_notification_preferences(p_expected_user_id uuid, p_role text, p_settings jsonb, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid:=auth.uid(); d public.notification_preferences%rowtype;
  wanted public.notification_preferences%rowtype; k text; v_canonical jsonb;
  v_keys constant text[]:=array['in_app_enabled','push_enabled','opportunities_enabled','responses_enabled',
    'dogovor_enabled','execution_enabled','recovery_enabled','account_enabled','quiet_hours_enabled',
    'quiet_start','quiet_end','quiet_timezone','urgent_overrides_quiet_hours'];
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  -- The mobile request captures its initiating account. A later token switch
  -- must fail here, before reads, locks or writes under the new authenticated user.
  if p_expected_user_id is null or p_expected_user_id<>v_uid then
    raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
  if p_role is null or p_role not in ('REQUESTER','WORKER') then
    raise exception 'INVALID_NOTIFICATION_ROLE' using errcode='22023'; end if;
  if p_expected_revision is null or p_expected_revision<0 or p_expected_revision=9223372036854775807
     or p_settings is null or jsonb_typeof(p_settings)<>'object' then
    raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023'; end if;
  if not (p_settings ?& v_keys) or exists(select 1 from jsonb_object_keys(p_settings) x where not(x=any(v_keys))) then
    raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023'; end if;
  foreach k in array v_keys loop
    if k in ('quiet_start','quiet_end') then
      if jsonb_typeof(p_settings->k) not in ('null','string')
         or (jsonb_typeof(p_settings->k)='string' and
           (p_settings->>k) !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]{1,6})?)?$') then
        raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023'; end if;
    elsif k='quiet_timezone' then
      if jsonb_typeof(p_settings->k)<>'string'
         or not exists(select 1 from pg_catalog.pg_timezone_names z where z.name=p_settings->>k) then
        raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023'; end if;
    elsif jsonb_typeof(p_settings->k)<>'boolean' then
      raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023';
    end if;
  end loop;
  wanted:=jsonb_populate_record(null::public.notification_preferences,p_settings);
  if wanted.quiet_hours_enabled and (wanted.quiet_start is null or wanted.quiet_end is null) then
    raise exception 'INVALID_NOTIFICATION_PREFERENCES' using errcode='22023'; end if;
  v_canonical:=private.notification_preferences_settings(wanted);
  -- Serialize missing-row first writes as well as updates for this owner/role.
  -- No token, account switch, event, provider call or unrelated row is touched.
  perform pg_advisory_xact_lock(hashtextextended('uskoci:notification-prefs:'||v_uid::text||':'||p_role,0));
  select * into d from public.notification_preferences where user_id=v_uid and role_context=p_role for update;
  if found then
    if d.revision=p_expected_revision+1 and private.notification_preferences_settings(d)=v_canonical then
      return jsonb_build_object('userId',v_uid,'exists',true,'roleContext',d.role_context,'revision',d.revision,
        'updatedAt',d.updated_at,'settings',v_canonical);
    end if;
    if d.revision<>p_expected_revision then
      raise exception 'NOTIFICATION_PREFERENCES_REVISION_CONFLICT' using errcode='PT409'; end if;
    update public.notification_preferences set
      in_app_enabled=wanted.in_app_enabled,push_enabled=wanted.push_enabled,
      opportunities_enabled=wanted.opportunities_enabled,responses_enabled=wanted.responses_enabled,
      dogovor_enabled=wanted.dogovor_enabled,execution_enabled=wanted.execution_enabled,
      recovery_enabled=wanted.recovery_enabled,account_enabled=wanted.account_enabled,
      quiet_hours_enabled=wanted.quiet_hours_enabled,quiet_start=wanted.quiet_start,quiet_end=wanted.quiet_end,
      quiet_timezone=wanted.quiet_timezone,urgent_overrides_quiet_hours=wanted.urgent_overrides_quiet_hours
    where user_id=v_uid and role_context=p_role returning * into d;
  else
    if p_expected_revision<>0 then
      raise exception 'NOTIFICATION_PREFERENCES_REVISION_CONFLICT' using errcode='PT409'; end if;
    insert into public.notification_preferences(user_id,role_context,in_app_enabled,push_enabled,
      opportunities_enabled,responses_enabled,dogovor_enabled,execution_enabled,recovery_enabled,account_enabled,
      quiet_hours_enabled,quiet_start,quiet_end,quiet_timezone,urgent_overrides_quiet_hours)
    values(v_uid,p_role,wanted.in_app_enabled,wanted.push_enabled,wanted.opportunities_enabled,wanted.responses_enabled,
      wanted.dogovor_enabled,wanted.execution_enabled,wanted.recovery_enabled,wanted.account_enabled,
      wanted.quiet_hours_enabled,wanted.quiet_start,wanted.quiet_end,wanted.quiet_timezone,wanted.urgent_overrides_quiet_hours)
    on conflict(user_id,role_context) do nothing returning * into d;
    if not found then -- A concurrent trusted insert cannot be overwritten.
      raise exception 'NOTIFICATION_PREFERENCES_REVISION_CONFLICT' using errcode='PT409'; end if;
  end if;
  return jsonb_build_object('userId',v_uid,'exists',true,'roleContext',d.role_context,'revision',d.revision,
    'updatedAt',d.updated_at,'settings',private.notification_preferences_settings(d));
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_set_push_device(p_expo_push_token text, p_platform text, p_active boolean, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_uid uuid:=auth.uid(); d public.notification_push_devices%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_expo_push_token is null or p_expo_push_token !~ '^(ExpoPushToken|ExponentPushToken)\[[A-Za-z0-9_-]+\]$'
     or p_platform is null or p_platform not in ('IOS','ANDROID') or p_active is null
     or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'INVALID_PUSH_REGISTRATION' using errcode='22023'; end if;
  -- Serialize the transport address across users, including initial insert and
  -- account switches. A lock-hash collision only serializes unrelated tokens.
  perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||p_expo_push_token,0));
  select * into d from public.notification_push_devices
    where user_id=v_uid and expo_push_token=p_expo_push_token for update;
  if found then
    -- Exact retry returns the original acknowledged revision. A delayed enable
    -- cannot cross a later revoke or cross-account rebinding revision.
    if d.revision=p_expected_revision+1 and d.active=p_active and d.platform=p_platform then
      return jsonb_build_object('id',d.id,'revision',d.revision,'active',d.active,'platform',d.platform,'lastSeenAt',d.last_seen_at);
    end if;
    if d.revision<>p_expected_revision then raise exception 'PUSH_REVISION_CONFLICT' using errcode='PT409'; end if;
  elsif p_expected_revision<>0 then
    raise exception 'PUSH_REVISION_CONFLICT' using errcode='PT409';
  end if;
  if p_active then
    -- One Expo address must never deliver two logged-in accounts' notifications.
    -- No foreign row or identifier is returned to this authenticated caller.
    update public.notification_push_devices set active=false,revision=revision+1
      where expo_push_token=p_expo_push_token and user_id<>v_uid and active;
  end if;
  if d.id is null then
    -- Revoking an unseen token creates an inactive tombstone: late revision-0
    -- registration must fail instead of resurrecting after logout.
    insert into public.notification_push_devices(user_id,expo_push_token,platform,active,revision)
      values(v_uid,p_expo_push_token,p_platform,p_active,1) returning * into d;
  else
    update public.notification_push_devices set platform=p_platform,active=p_active,
      revision=revision+1,last_seen_at=statement_timestamp() where id=d.id returning * into d;
  end if;
  return jsonb_build_object('id',d.id,'revision',d.revision,'active',d.active,'platform',d.platform,'lastSeenAt',d.last_seen_at);
end
$function$;


CREATE OR REPLACE FUNCTION public.rpc_set_push_device_owned(p_expected_user_id uuid, p_expo_push_token text, p_platform text, p_active boolean, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); sid uuid; result jsonb; d public.notification_push_devices%rowtype;
begin
 if u is null or u is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000'; end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid; exception when invalid_text_representation then raise exception 'AUTH_REQUIRED' using errcode='28000'; end;
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 if p_expo_push_token is null or length(p_expo_push_token)>256 then raise exception 'INVALID_PUSH_REGISTRATION' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-user:'||u::text,0));
 perform pg_advisory_xact_lock(hashtextextended('uskoci:push-token:'||p_expo_push_token,0));
 if not private.push_session_valid(u,sid) then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 select * into d from public.notification_push_devices where user_id=u and expo_push_token=p_expo_push_token;
 if p_active and not coalesce(d.active and d.bound_revision=d.revision and private.push_session_valid(d.user_id,d.bound_session_id),false) and (select count(*) from public.notification_push_devices where user_id=u and active and bound_revision=revision and private.push_session_valid(user_id,bound_session_id))>=10 then raise exception 'PUSH_DEVICE_LIMIT' using errcode='22023'; end if;
 -- A replay cannot silently rebind a different login incarnation.
 if d.revision=p_expected_revision+1 and d.active=p_active and d.platform=p_platform
 and p_active and (d.bound_session_id is distinct from sid or d.bound_revision is distinct from d.revision) then raise exception 'PUSH_REVISION_CONFLICT' using errcode='PT409'; end if;
 result:=public.rpc_set_push_device(p_expo_push_token,p_platform,p_active,p_expected_revision);
 update public.notification_push_devices set bound_session_id=case when p_active then sid else null end,
 bound_revision=case when p_active then revision else null end where id=(result->>'id')::uuid;
 return result||jsonb_build_object('sessionBound',p_active);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_set_retention_hold(p_account_id uuid, p_conversation_id uuid, p_hold_key text, p_active boolean, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare h private.retention_holds;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'TRUSTED_SERVER_REQUIRED' using errcode='42501';end if;
 if p_account_id is null or p_active is null or p_expected_revision is null or p_expected_revision<0
 or p_expected_revision>=9007199254740991 or char_length(coalesce(p_hold_key,'')) not between 8 and 128 then raise exception 'RETENTION_HOLD_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:retention:'||p_account_id::text,0));
 if not exists(select 1 from public.app_accounts where id=p_account_id) then raise exception 'RETENTION_ACCOUNT_NOT_FOUND';end if;
 select * into h from private.retention_holds where account_id=p_account_id and hold_key=p_hold_key for update;
 if found then
   if h.conversation_id is distinct from p_conversation_id then raise exception 'RETENTION_HOLD_SCOPE_MISMATCH';end if;
   if h.revision=p_expected_revision+1 and h.active=p_active then return jsonb_build_object('holdId',h.id,'revision',h.revision,'active',h.active,'idempotentReplay',true);end if;
   if h.revision<>p_expected_revision then raise exception 'RETENTION_HOLD_REVISION_STALE' using errcode='PT409';end if;
 elsif p_expected_revision<>0 then raise exception 'RETENTION_HOLD_REVISION_STALE' using errcode='PT409';end if;
 if p_conversation_id is not null and not exists(select 1 from public.ai_conversations where id=p_conversation_id and account_id=p_account_id)
 then raise exception 'RETENTION_TARGET_NOT_FOUND';end if;
 insert into private.retention_holds(account_id,hold_key,conversation_id,active,revision) values(p_account_id,p_hold_key,p_conversation_id,p_active,1)
 on conflict(account_id,hold_key) do update set active=excluded.active,revision=retention_holds.revision+1,updated_at=clock_timestamp() returning * into h;
 perform private.audit_marketplace(null,case when p_active then 'RETENTION_HOLD_SET' else 'RETENTION_HOLD_RELEASED' end,'SYSTEM',h.id,null,jsonb_build_object('revision',h.revision));
 return jsonb_build_object('holdId',h.id,'revision',h.revision,'active',h.active,'idempotentReplay',false);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_set_worker_execution_modes(p_worker_profile_id uuid, p_modes text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_account uuid:=auth.uid(); v_profile public.app_profiles; v_modes text[];
BEGIN
 PERFORM private.closure_assert_open(auth.uid());
 IF v_account IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode='28000'; END IF;
 IF p_worker_profile_id IS NULL OR p_modes IS NULL OR cardinality(p_modes) NOT BETWEEN 1 AND 2
   OR array_position(p_modes,NULL) IS NOT NULL
   OR NOT (p_modes <@ ARRAY['ON_SITE','REMOTE']::text[])
   OR (SELECT count(DISTINCT x) FROM unnest(p_modes) AS x)<>cardinality(p_modes)
 THEN RAISE EXCEPTION 'WORKER_EXECUTION_MODES_INVALID' USING errcode='22023'; END IF;
 SELECT p.* INTO v_profile FROM public.app_profiles p
 WHERE p.id=p_worker_profile_id
 FOR UPDATE;
 IF NOT FOUND OR v_profile.account_id IS DISTINCT FROM v_account
   OR v_profile.kind IS DISTINCT FROM 'WORKER'
 THEN RAISE EXCEPTION 'WORKER_PROFILE_NOT_OWNED' USING errcode='42501'; END IF;
 IF v_profile.profile_status NOT IN ('DRAFT','ACTIVE')
 THEN RAISE EXCEPTION 'WORKER_PROFILE_NOT_EDITABLE' USING errcode='42501'; END IF;
 v_modes:=CASE WHEN 'ON_SITE'=ANY(p_modes) AND 'REMOTE'=ANY(p_modes)
  THEN ARRAY['ON_SITE','REMOTE']::text[]
  WHEN 'ON_SITE'=ANY(p_modes) THEN ARRAY['ON_SITE']::text[]
  ELSE ARRAY['REMOTE']::text[] END;
 INSERT INTO private.worker_execution_mode_choices(worker_profile_id,worker_account_id,modes)
 VALUES(p_worker_profile_id,v_account,v_modes)
 ON CONFLICT(worker_profile_id) DO UPDATE SET modes=excluded.modes,
   confirmed_at=statement_timestamp(),updated_at=statement_timestamp()
 WHERE private.worker_execution_mode_choices.worker_account_id=v_account
   AND private.worker_execution_mode_choices.modes IS DISTINCT FROM excluded.modes;
 IF NOT EXISTS (SELECT 1 FROM private.worker_execution_mode_choices x
   WHERE x.worker_profile_id=p_worker_profile_id
   AND x.worker_account_id=v_account AND x.modes=v_modes) THEN
  RAISE EXCEPTION 'WORKER_MODE_CHOICE_CONSISTENCY_FAILED' USING errcode='42501';
 END IF;
 RETURN jsonb_build_object('workerProfileId',p_worker_profile_id,
  'modes',to_jsonb(v_modes),'confirmed',true,
  'matchingAuthority','NONE','notificationAuthority','NONE',
  'note','PREFERENCE_ONLY_UNTIL_MATCHER_INTEGRATION');
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_settle_media_upload_service(p_account_id uuid, p_asset_id uuid, p_storage_sha256 text, p_outcome text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=p_account_id for update;
 if not found or a.sanitized_sha256 is distinct from p_storage_sha256 or p_storage_sha256 is null
  or p_outcome is null or p_outcome not in('STORED','REJECTED') then raise exception 'MEDIA_STORAGE_UNCONFIRMED' using errcode='PT409'; end if;
 if a.dispatch_state='SETTLED' then
  if a.dispatch_outcome is distinct from p_outcome then raise exception 'MEDIA_STORAGE_UNCONFIRMED' using errcode='PT409'; end if;
  return true;
 end if;
 if a.dispatch_state<>'DISPATCHING' then raise exception 'MEDIA_STORAGE_UNCONFIRMED' using errcode='PT409'; end if;
 update private.owned_media_assets set dispatch_state='SETTLED',dispatch_outcome=p_outcome,
  selected=case when p_outcome='REJECTED' then false else selected end where id=a.id;
 return true;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_stage_media_upload_service(p_account_id uuid, p_asset_id uuid, p_attempt_id uuid, p_sha256 text, p_width integer, p_height integer, p_byte_size integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a private.owned_media_assets; path text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
 perform private.closure_assert_open(p_account_id);
 select * into a from private.owned_media_assets where id=p_asset_id and account_id=p_account_id for update;
 if not found then raise exception 'MEDIA_NOT_FOUND' using errcode='42501'; end if;
 if p_attempt_id is null or a.attempt_id is distinct from p_attempt_id then raise exception 'MEDIA_ATTEMPT_STALE' using errcode='PT409'; end if;
 if p_sha256 is null or p_sha256!~'^[a-f0-9]{64}$' or p_width is null or p_width not between 1 and 1600 or p_height is null or p_height not between 1 and 1600
  or p_byte_size is null or p_byte_size not between 1 and 5242880 then raise exception 'MEDIA_INPUT_INVALID' using errcode='22023'; end if;
 path:=a.account_id::text||'/v5/'||a.id::text||'/'||p_sha256||'.jpg';
 if a.state in('STAGED','READY') then
  if a.storage_path is distinct from path or a.width is distinct from p_width or a.height is distinct from p_height or a.byte_size is distinct from p_byte_size
  then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023'; end if;
 elsif a.state='PROCESSING' then
  update private.owned_media_assets set state='STAGED',sanitized_sha256=p_sha256,storage_path=path,width=p_width,height=p_height,byte_size=p_byte_size where id=a.id;
 else raise exception 'MEDIA_NOT_EDITABLE' using errcode='55000'; end if;
 return jsonb_build_object('path',path,'sha256',p_sha256,'byteSize',p_byte_size);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_start_account_closure_execution(p_expected_user_id uuid, p_request_id uuid, p_expected_revision integer, p_client_request_id uuid, p_policy_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid();b jsonb;r private.account_closure_requests;e private.closure_executions_v5;c private.closure_start_commands_v5;h text;receipt jsonb;redaction_id uuid;begin
 if u is null or u is distinct from p_expected_user_id or auth.role() is distinct from 'authenticated' then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='42501';end if;
 if p_request_id is null or p_client_request_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_revision>=2147483646 or coalesce(p_policy_sha256,'')!~'^[a-f0-9]{64}$' then raise exception 'CLOSURE_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_erasure_lock_v5(u);
 h:=encode(extensions.digest(jsonb_build_array(u,p_request_id,p_expected_revision,p_policy_sha256)::text,'sha256'),'hex');
 select * into c from private.closure_start_commands_v5 where account_id=u and client_request_id=p_client_request_id;
 if found then if c.input_sha256<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023';end if;return c.receipt||jsonb_build_object('idempotentReplay',true);end if;
 -- Exact existing metadata replay survives Auth erasure. Only a fresh start
 -- requires a still-live human session, as in every narrative-producing seam.
 perform private.support_auth_v5(p_expected_user_id);
 select * into r from private.account_closure_requests where account_id=u;
 if r.id is distinct from p_request_id or r.revision is distinct from p_expected_revision then raise exception 'CLOSURE_REVISION_CONFLICT' using errcode='PT409';end if;
 if private.closure_account_restricted(u) then raise exception 'ACCOUNT_CLOSING' using errcode='42501';end if;
 b:=private.closure_erasure_binding_v5();
 if b is null or b->>'sha256' is distinct from p_policy_sha256 then raise exception 'CLOSURE_POLICY_NOT_READY' using errcode='55000';end if;
 if cardinality(private.closure_erasure_hard_blockers_v5(u))>0 then raise exception 'CLOSURE_BLOCKED' using errcode='55000';end if;
 insert into private.closure_executions_v5(account_id,request_id,policy_id,policy_sha256,binding) values(u,r.id,null,p_policy_sha256,b) returning * into e;
 update private.account_closure_requests set state='EXECUTING',revision=revision+1,updated_at=clock_timestamp() where account_id=u;
 -- Freeze field attribution before any hash/content is changed. Only source
 -- identities are retained here; no free text or original-content hash copy.
 insert into private.closure_scope_sources_v5(account_id,generation,agreement_id,source_kind,source_id,scope_author)
 select u,e.generation,v.agreement_id,'VERSION',v.version::text,private.closure_erasure_scope_author_v5(v.agreement_id,v.version)
 from public.agreement_versions v join public.agreements ag on ag.id=v.agreement_id where u in(ag.requester_account_id,ag.worker_account_id)
 union all
 select u,e.generation,p.agreement_id,'PROPOSAL',p.id::text,
 coalesce((select ss.scope_author from private.closure_scope_sources_v5 ss join private.closure_executions_v5 ce on ce.generation=ss.generation
  where ss.agreement_id=p.agreement_id and ss.source_kind='PROPOSAL' and ss.source_id=p.id::text and ss.scope_author is not null order by ce.requested_at,ss.generation limit 1),
 case when jsonb_typeof(p.proposed_terms->'scope_note') is distinct from 'string' or v.agreement_id is null then null
  when p.proposed_terms->'scope_note' is not distinct from v.terms->'scope_note' then private.closure_erasure_scope_author_v5(p.agreement_id,p.base_version) else p.proposed_by_account_id end
 )
 from public.agreement_change_proposals p join public.agreements ag on ag.id=p.agreement_id left join public.agreement_versions v on v.agreement_id=p.agreement_id and v.version=p.base_version where u in(ag.requester_account_id,ag.worker_account_id);
 insert into private.closure_actions_v5(generation,account_id,kind,bucket,object_path)
 select e.generation,u,'STORAGE_DELETE',x.bucket,x.path from (
  select bucket_id bucket,name path from storage.objects where split_part(name,'/',1)=u::text
  union select 'profile-media',storage_path from private.owned_media_assets where account_id=u and storage_path is not null
  union select 'profile-media',storage_path from private.agreement_photo_uploads_v5 where account_id=u and storage_path is not null
  union select 'agreement-voice',storage_path from private.agreement_voice_uploads_v1 where account_id=u and storage_path is not null
  union select 'data-export-artifacts',object_path from private.data_export_artifacts where account_id=u) x
 where x.bucket<>'profile-media' or not private.closure_erasure_media_protected_v5(u,x.path);
 insert into private.closure_actions_v5(generation,account_id,kind) values(e.generation,u,'RELATIONAL_REDACT') returning id into redaction_id;
 insert into private.closure_redaction_steps_v5(action_id,account_id,generation,ordinal,relation_name)
 select redaction_id,u,e.generation,ord,rn from unnest(private.closure_redaction_relations_v5()) with ordinality x(rn,ord);
 insert into private.closure_actions_v5(generation,account_id,kind) values(e.generation,u,'AUTH_IDENTITY_ERASE');
 receipt:=jsonb_build_object('accountId',u,'requestId',r.id,'generation',e.generation,'state','EXECUTING','clientRequestId',p_client_request_id,'policySha256',p_policy_sha256,'idempotentReplay',false,'authoritative',true);
 insert into private.closure_start_commands_v5 values(u,p_client_request_id,h,receipt);return receipt;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_storage_account_open()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 begin if auth.uid() is null then return false;end if;perform private.closure_assert_open(auth.uid());return true;end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_submit_agreement_review(p_agreement_id uuid, p_target_account_id uuid, p_rating jsonb, p_tags jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews;
 rating_value numeric; tags_value text[]; h text; target_role text;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_agreement_id is null or p_target_account_id is null or p_target_account_id=u or p_client_request_id is null
 or jsonb_typeof(p_rating) is distinct from 'number' or length(p_rating::text)>30 then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 rating_value:=(p_rating#>>'{}')::numeric;
 if rating_value not between 1 and 5 or trunc(rating_value)<>rating_value then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 if jsonb_typeof(p_tags) is distinct from 'array' then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 if jsonb_array_length(p_tags)>3 or exists(select 1 from jsonb_array_elements(p_tags) t
  where jsonb_typeof(t.value)<>'string' or not (t.value#>>'{}'=any(private.review_tag_catalog()))) then
  raise exception 'REVIEW_TAGS_INVALID' using errcode='22023';
 end if;
 tags_value:=array(select t.value#>>'{}' from jsonb_array_elements(p_tags) t order by (t.value#>>'{}') collate "C");
 if not private.review_tags_valid(tags_value) then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 h:=encode(extensions.digest(jsonb_build_object('agreementId',p_agreement_id,'target',p_target_account_id,
  'rating',rating_value::integer,'tags',to_jsonb(tags_value))::text,'sha256'),'hex');
 -- Same successful command remains an immutable read, even after a later block.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-command:'||u::text||':'||p_client_request_id::text,9120));
 select * into r from private.agreement_reviews where reviewer_account_id=u and client_request_id=p_client_request_id;
 if found then
  if r.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return private.review_receipt(r,true);
 end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id) for share;
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 if p_target_account_id<>(case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end) then
  raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501';
 end if;
 if a.status<>'COMPLETED' or not exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED') then
  raise exception 'REVIEW_NOT_COMPLETED' using errcode='55000';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-agreement:'||a.id::text||':'||u::text,9120));
 if exists(select 1 from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u) then
  raise exception 'REVIEW_ALREADY_SUBMITTED' using errcode='55000';
 end if;
 -- A block cannot remove the counterpart's completed-work review entitlement.
 -- P8 suppresses ordinary deliveries, including this event, for blocked pairs.
 insert into private.agreement_reviews(agreement_id,reviewer_account_id,target_account_id,rating,tags,client_request_id,input_hash)
 values(a.id,u,p_target_account_id,rating_value::integer,tags_value,p_client_request_id,h) returning * into r;
 perform private.audit_marketplace(u,'AGREEMENT_REVIEW_SUBMITTED','AGREEMENT',a.id,a.current_version,jsonb_build_object('reviewId',r.id));
 target_role:=case when u=a.requester_account_id then 'WORKER' else 'REQUESTER' end;
 perform private.emit_event(p_target_account_id,target_role,'REVIEW_RECEIVED','AGREEMENT',a.id,a.current_version,
  'Nova ocena','Dobili ste ocenu za završen Dogovor.','agreement-review:'||r.id::text,'NORMAL','{}'::jsonb,null);
 return private.review_receipt(r,false);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_submit_agreement_review_v2(p_agreement_id uuid, p_target_account_id uuid, p_rating jsonb, p_tags jsonb, p_client_request_id uuid, p_comment jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; r private.agreement_reviews;
 rating_value numeric; tags_value text[]; h text; target_role text;
 comment_value text; comment_sha text; stored_comment text; stored_sha text;
begin
 -- D12: the legacy review command (same auth, validation order, locks, eligibility, star hash, audit row and REVIEW_RECEIVED event, byte for byte in behaviour) plus ONE optional comment
 -- that is stored in the SAME transaction as the stars and never later. The legacy function stays untouched and keeps serving every installed build.
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_agreement_id is null or p_target_account_id is null or p_target_account_id=u or p_client_request_id is null
 or jsonb_typeof(p_rating) is distinct from 'number' or length(p_rating::text)>30 then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 rating_value:=(p_rating#>>'{}')::numeric;
 if rating_value not between 1 and 5 or trunc(rating_value)<>rating_value then
  raise exception 'REVIEW_INPUT_INVALID' using errcode='22023';
 end if;
 if jsonb_typeof(p_tags) is distinct from 'array' then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 if jsonb_array_length(p_tags)>3 or exists(select 1 from jsonb_array_elements(p_tags) t
  where jsonb_typeof(t.value)<>'string' or not (t.value#>>'{}'=any(private.review_tag_catalog()))) then
  raise exception 'REVIEW_TAGS_INVALID' using errcode='22023';
 end if;
 tags_value:=array(select t.value#>>'{}' from jsonb_array_elements(p_tags) t order by (t.value#>>'{}') collate "C");
 if not private.review_tags_valid(tags_value) then raise exception 'REVIEW_TAGS_INVALID' using errcode='22023'; end if;
 -- The star hash keeps the legacy formula exactly (so every stored hash and every replay through either function stays compatible); the comment is bound by its own digest in its own row.
 h:=encode(extensions.digest(jsonb_build_object('agreementId',p_agreement_id,'target',p_target_account_id,
  'rating',rating_value::integer,'tags',to_jsonb(tags_value))::text,'sha256'),'hex');
 comment_value:=private.review_comment_input_v1(p_comment);
 comment_sha:=case when comment_value is null then null else encode(extensions.digest(convert_to(comment_value,'UTF8'),'sha256'),'hex') end;
 -- Same successful command remains an immutable read, even after a later block.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-command:'||u::text||':'||p_client_request_id::text,9120));
 select * into r from private.agreement_reviews where reviewer_account_id=u and client_request_id=p_client_request_id;
 if found then
  if r.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  -- A comment that differs from the stored one (or one added to a stored star-only review) is another command under the same id.
  select c.comment,c.comment_sha256 into stored_comment,stored_sha from private.agreement_review_comments_v1 c where c.review_id=r.id;
  if stored_sha is distinct from comment_sha then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return private.review_receipt(r,true)||jsonb_build_object('comment',stored_comment);
 end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id) for share;
 if not found then raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501'; end if;
 if p_target_account_id<>(case when u=a.requester_account_id then a.worker_account_id else a.requester_account_id end) then
  raise exception 'REVIEW_NOT_ALLOWED' using errcode='42501';
 end if;
 if a.status<>'COMPLETED' or not exists(select 1 from public.agreement_execution where agreement_id=a.id and state='COMPLETED') then
  raise exception 'REVIEW_NOT_COMPLETED' using errcode='55000';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('uskoci:review-agreement:'||a.id::text||':'||u::text,9120));
 if exists(select 1 from private.agreement_reviews where agreement_id=a.id and reviewer_account_id=u) then
  raise exception 'REVIEW_ALREADY_SUBMITTED' using errcode='55000';
 end if;
 -- A block cannot remove the counterpart's completed-work review entitlement (stars and comment alike; a refusal would reveal the block).
 -- P8 suppresses ordinary deliveries, including this event, for blocked pairs. The comment is hidden from readers while the pair is blocked, at read time.
 insert into private.agreement_reviews(agreement_id,reviewer_account_id,target_account_id,rating,tags,client_request_id,input_hash)
 values(a.id,u,p_target_account_id,rating_value::integer,tags_value,p_client_request_id,h) returning * into r;
 if comment_value is not null then
  insert into private.agreement_review_comments_v1(review_id,author_account_id,target_account_id,comment,comment_sha256,created_at)
  values(r.id,r.reviewer_account_id,r.target_account_id,comment_value,comment_sha,r.created_at);
 end if;
 perform private.audit_marketplace(u,'AGREEMENT_REVIEW_SUBMITTED','AGREEMENT',a.id,a.current_version,jsonb_build_object('reviewId',r.id));
 target_role:=case when u=a.requester_account_id then 'WORKER' else 'REQUESTER' end;
 perform private.emit_event(p_target_account_id,target_role,'REVIEW_RECEIVED','AGREEMENT',a.id,a.current_version,
  'Nova ocena','Dobili ste ocenu za zavr'||chr(353)||'en Dogovor.','agreement-review:'||r.id::text,'NORMAL','{}'::jsonb,null);
 return private.review_receipt(r,false)||jsonb_build_object('comment',comment_value);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_submit_classified_preselection_qa(p_expected_user_id uuid, p_type text, p_need_id uuid, p_need_revision integer, p_question_id uuid, p_text text, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare a uuid:=auth.uid();c private.qa_ai_commands;h text;src jsonb;result jsonb;
begin
 if a is null or a is distinct from p_expected_user_id then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='28000';end if;
 h:=private.qa_ai_input_hash(p_type,p_need_id,p_need_revision,p_question_id,encode(extensions.digest(convert_to(btrim(coalesce(p_text,'')),'UTF8'),'sha256'),'hex'));
 perform private.closure_assert_open(a);perform pg_advisory_xact_lock(hashtextextended('v5-qa:'||a::text||':'||p_client_request_id::text,0));
 -- Retained direct writer takes this before its Need/question locks.
 perform pg_advisory_xact_lock(hashtextextended(a::text||E'\n'||p_client_request_id::text,case when p_type='ASK' then 4412 else 4413 end));
 select * into c from private.qa_ai_commands where account_id=a and client_request_id=p_client_request_id for update;
 if not found or c.request_hash<>h then raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';end if;
 if c.state='COMMITTED' then return private.qa_ai_status(a,p_need_id,p_client_request_id);end if;
 if c.state<>'READY' then return private.qa_ai_status(a,p_need_id,p_client_request_id);end if;
 perform private.qa_ai_assert_actor(a,c.need_id,c.need_revision,c.question_id,c.command_type);
 src:=private.qa_ai_source(c.need_id,c.need_revision,c.question_id);
 if src->>'sourceHash' is distinct from c.source_hash then update private.qa_ai_commands set state='STALE',updated_at=clock_timestamp() where id=c.id;
  return private.qa_ai_status(a,p_need_id,p_client_request_id);end if;
 -- Canonical RPC repeats all gates and emits its event in this transaction.
 begin
  if c.command_type='ASK' then result:=public.rpc_ru4b_ask_preselection_question(c.need_id,c.need_revision,p_text,p_client_request_id);
  else result:=public.rpc_ru4b_answer_preselection_question(c.question_id,p_text,p_client_request_id);end if;
 exception when others then
  if sqlerrm not in('QA_QUESTION_TOO_LONG','QA_ANSWER_TOO_LONG','QA_ACCOUNT_DAILY_LIMIT','QA_TASK_DAILY_LIMIT','QA_ASK_COOLDOWN','QA_DUPLICATE_QUESTION',
   'STALE_NEED_REVISION','QUESTION_STALE_AFTER_NEED_REVISION','QUESTION_NOT_ANSWERABLE','NEED_NOT_PUBLIC','INTERACTION_BLOCKED','ACTIVE_WORKER_REQUIRED') then raise;end if;
  update private.qa_ai_commands set state='REJECTED',safe_reason_codes=array[sqlerrm],updated_at=clock_timestamp() where id=c.id;
  return private.qa_ai_status(a,p_need_id,p_client_request_id);
 end;
 update private.qa_ai_commands set state='COMMITTED',receipt=result,updated_at=clock_timestamp() where id=c.id;
 return private.qa_ai_status(a,p_need_id,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_submit_response(p_need_id uuid, p_need_revision integer, p_worker_profile_id uuid, p_covered_slots integer, p_price_rsd integer, p_proposed_start_at timestamp with time zone, p_proposed_end_at timestamp with time zone, p_scope_note text, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  n public.needs;
  v_profile public.app_profiles;
  v_resp public.marketplace_responses;
  v_command private.response_submit_commands;
  v_match jsonb;
  v_content_hash text;
  v_request_hash text;
  v_result jsonb;
  v_version integer;
  v_selected_slots integer := 0;
  v_remaining_slots integer := 0;
begin
  if u is null then
    raise exception using errcode='42501', message='AUTH_REQUIRED';
  end if;

  if p_client_request_id is null
     or char_length(btrim(p_client_request_id)) not between 8 and 200 then
    raise exception using errcode='22023', message='INVALID_CLIENT_REQUEST_ID';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(u::text || ':' || p_client_request_id, 7241)
  );

  -- Bind only the semantic client command. Server-derived profile/Need snapshot
  -- intentionally does not enter the request hash, so a retry after a committed
  -- response replays the exact first result even if current context later moves.
  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'needId', p_need_id,
    'needRevision', p_need_revision,
    'workerProfileId', p_worker_profile_id,
    'coveredSlots', p_covered_slots,
    'priceRsd', p_price_rsd,
    'proposedStartAt', p_proposed_start_at,
    'proposedEndAt', p_proposed_end_at,
    'scopeNote', coalesce(p_scope_note, '')
  )::text, 'UTF8')), 'hex');

  select * into v_command
    from private.response_submit_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id;

  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  -- Shared mutation lock order remains Need first.
  select * into n
    from public.needs
   where id = p_need_id
   for update;

  if not found then
    raise exception using errcode='P0002', message='NEED_NOT_FOUND';
  end if;

  if not private.accounts_same_world(n.requester_account_id, u) then
    raise exception using errcode='P0002', message='NEED_NOT_FOUND';
  end if;

  select * into v_command
    from private.response_submit_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id
   for update;

  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  if n.status not in ('PUBLISHED','SELECTION') then
    raise exception using errcode='22023', message='NEED_NOT_OPEN';
  end if;

  if n.requester_account_id = u then
    raise exception using errcode='42501', message='OWN_NEED';
  end if;

  if n.response_deadline is not null
     and n.response_deadline <= statement_timestamp() then
    raise exception using errcode='22023', message='RESPONSE_WINDOW_EXPIRED';
  end if;

  -- New work uses the same actual task-time boundary as search/dispatch.
  -- Replay already returned above; evaluate after the Need lock was acquired.
  if not private.need_search_time_admitted_v1(n.id,clock_timestamp()) then
    raise exception 'NEED_EXECUTION_WINDOW_EXPIRED' using errcode='PT409',
      hint='Vreme za ovaj zadatak je isteklo.';
  end if;

  if n.revision is distinct from p_need_revision then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  -- Lock the current Worker profile after the Need. ACTIVE alone is not enough
  -- for legacy rows: P0C-02 rechecks the exact RU-1 minimum readiness facts.
  select * into v_profile
    from public.app_profiles p
   where p.id = p_worker_profile_id
   for update;

  if not found
     or v_profile.account_id <> u
     or v_profile.kind <> 'WORKER' then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if v_profile.profile_status <> 'ACTIVE'
     or char_length(btrim(v_profile.display_name)) < 2
     or char_length(btrim(v_profile.city)) < 2
     or cardinality(v_profile.skills) < 1 then
    raise exception using errcode='P0001', message='WORKER_PROFILE_NOT_READY';
  end if;

  select coalesce(sum(s.covered_slots), 0)::integer
    into v_selected_slots
    from public.need_selections s
   where s.need_id = n.id
     and s.status = 'SELECTED';

  v_remaining_slots := greatest(0, n.required_slots - v_selected_slots);

  if v_remaining_slots < 1 then
    raise exception using errcode='P0001', message='NEED_FULL';
  end if;

  if p_covered_slots is null or p_covered_slots < 1 then
    raise exception using errcode='22023', message='INVALID_COVERED_SLOTS';
  end if;

  -- WPP01: people are committed per offer; the personal profile is not a team limit.
  -- Existing remaining-slot and pricing checks below remain authoritative.

  if p_covered_slots > v_remaining_slots then
    raise exception using
      errcode='22023',
      message='NEED_REMAINING_CAPACITY_EXCEEDED',
      detail=format('covered=%s,remaining=%s', p_covered_slots, v_remaining_slots);
  end if;

  perform private.assert_application_price_v5(n, p_covered_slots, p_price_rsd);

  if (p_proposed_start_at is null) <> (p_proposed_end_at is null)
     or (
       p_proposed_start_at is not null
       and p_proposed_end_at is not null
       and p_proposed_start_at >= p_proposed_end_at
     ) then
    raise exception using errcode='22023', message='INVALID_PROPOSED_INTERVAL';
  end if;

  if exists (
    select 1
      from public.marketplace_responses r
     where r.need_id = p_need_id
       and r.worker_account_id = u
       and (
         r.status = 'SELECTED'
         or exists (
           select 1
             from public.agreements a
            where a.selected_response_id = r.id
              and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
         )
       )
  ) then
    raise exception using errcode='P0001', message='RESPONSE_ALREADY_SELECTED';
  end if;

  if p_proposed_start_at is null and n.schedule_kind='FIXED_WINDOW'
    and (n.starts_at is null or not isfinite(n.starts_at)
      or (n.ends_at is not null and (not isfinite(n.ends_at) or n.starts_at>=n.ends_at))) then
    raise exception 'NEED_FIXED_INTERVAL_INVALID' using errcode='22023';
  end if;
  -- Start-only appointment cannot accept a new offer after its start while lifecycle tick catches up.
  if n.schedule_kind='FIXED_WINDOW' and n.ends_at is null
     and n.starts_at is not null and n.starts_at<=statement_timestamp() then
    raise exception 'FIXED_WINDOW_START_PASSED' using errcode='22023';
  end if;
  v_match := private.match_detail_for_calendar_interval(p_need_id, p_worker_profile_id,
    coalesce(p_proposed_start_at,case when n.schedule_kind='FIXED_WINDOW' and n.ends_at is not null then n.starts_at end),
    coalesce(p_proposed_end_at,case when n.schedule_kind='FIXED_WINDOW' and n.ends_at is not null then n.ends_at end));
  if not coalesce((v_match->>'responseAllowed')::boolean, false) then
    raise exception using
      errcode='P0001',
      message='WORKER_NOT_ELIGIBLE',
      detail=coalesce((v_match->'hardBlockers')::text, '[]');
  end if;

  select * into v_resp
    from public.marketplace_responses r
   where r.need_id = p_need_id
     and r.worker_account_id = u
     and r.status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')
   order by r.created_at desc
   limit 1
   for update;

  -- Content identity includes the server-derived self-declared capability/team
  -- snapshot. It is not public trust/verification and is never copied into the
  -- global public profile DTO.
  v_content_hash := encode(sha256(convert_to(jsonb_build_object(
    'needRevision', n.revision,
    'pricingMode', n.mode,
    'priceRsd', p_price_rsd,
    'coveredSlots', p_covered_slots,
    'proposedStartAt', p_proposed_start_at,
    'proposedEndAt', p_proposed_end_at,
    'scopeNote', coalesce(btrim(p_scope_note), ''),
    'snapshotSchema', 'APPLICATION_V1_SELF_DECLARED',
    'workerTeamCapacity', v_profile.team_capacity,
    'workerSkills', to_jsonb(v_profile.skills),
    'workerTools', '[]'::jsonb,
    'workerLicenses', to_jsonb(v_profile.licenses),
    'workerVehicles', '[]'::jsonb
  )::text, 'UTF8')), 'hex');

  if v_resp.id is null then
    insert into public.marketplace_responses (
      need_id, worker_account_id, worker_profile_id, response_kind, status,
      submitted_against_need_revision, current_version, covered_slots,
      price_rsd, proposed_start_at, proposed_end_at, scope_note, submitted_at
    ) values (
      p_need_id, u, p_worker_profile_id, 'OFFER', 'SUBMITTED', n.revision, 1,
      p_covered_slots, p_price_rsd, p_proposed_start_at, p_proposed_end_at,
      coalesce(p_scope_note, ''), statement_timestamp()
    )
    returning * into v_resp;
    v_version := 1;
  else
    v_version := v_resp.current_version + 1;
    update public.marketplace_responses
       set current_version = v_version,
           status = 'SUBMITTED',
           submitted_against_need_revision = n.revision,
           covered_slots = p_covered_slots,
           price_rsd = p_price_rsd,
           proposed_start_at = p_proposed_start_at,
           proposed_end_at = p_proposed_end_at,
           scope_note = coalesce(p_scope_note, ''),
           submitted_at = statement_timestamp(),
           withdrawn_at = null
     where id = v_resp.id
     returning * into v_resp;
  end if;

  insert into public.marketplace_response_versions (
    response_id, version, need_revision, covered_slots, price_rsd,
    proposed_start_at, proposed_end_at, scope_note, content_hash
  ) values (
    v_resp.id, v_version, n.revision, p_covered_slots, p_price_rsd,
    p_proposed_start_at, p_proposed_end_at, coalesce(p_scope_note, ''),
    v_content_hash
  );

  insert into private.response_application_snapshots (
    response_id, response_version, snapshot_schema,
    worker_profile_id, worker_team_capacity, covered_slots,
    need_required_slots, need_selected_slots_before_submit,
    need_remaining_slots_before_submit, pricing_mode, requester_price_rsd,
    worker_skills, worker_tools, worker_licenses, worker_vehicles
  ) values (
    v_resp.id, v_version, 'APPLICATION_V1_SELF_DECLARED',
    v_profile.id, v_profile.team_capacity, p_covered_slots,
    n.required_slots, v_selected_slots, v_remaining_slots,
    n.mode, n.requester_price_rsd,
    v_profile.skills, '{}'::text[], v_profile.licenses, '{}'::text[]
  );

  update public.opportunity_deliveries
     set status = 'RESPONDED',
         responded_at = statement_timestamp()
   where need_id = p_need_id
     and need_revision = n.revision
     and worker_account_id = u
     and status in ('READY','SEEN');

  v_result := jsonb_build_object(
    'responseId', v_resp.id,
    'applicationId', v_resp.id,
    'version', v_version,
    'needRevision', n.revision,
    'contentHash', v_content_hash,
    'status', v_resp.status,
    'pricingMode', n.mode,
    'coveredSlots', p_covered_slots,
    'snapshotSchema', 'APPLICATION_V1_SELF_DECLARED',
    'authoritative', true,
    'idempotentReplay', false
  );

  insert into private.response_submit_commands (
    worker_account_id, client_request_id, request_hash,
    response_id, response_version, result
  ) values (
    u, p_client_request_id, v_request_hash,
    v_resp.id, v_version, v_result
  );

  -- PRE-V3: persisted version trigger owns Application semantic events.

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_submit_safety_report(p_target_account_id uuid, p_need_id uuid, p_agreement_id uuid, p_category text, p_reason text, p_narrative text, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); r private.safety_reports; h text;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_target_account_id is null or p_target_account_id=u or p_client_request_id is null or p_category is null
 or p_category not in('HARASSMENT','FRAUD','UNSAFE_WORK','DISCRIMINATION','OTHER')
 or p_reason is null or length(btrim(p_reason)) not between 1 and 200 or octet_length(p_reason)>800
 or p_narrative is null or length(p_narrative)>2000 or octet_length(p_narrative)>8000 then raise exception 'SAFETY_REPORT_INPUT_INVALID' using errcode='22023'; end if;
 h:=encode(extensions.digest(jsonb_build_object('target',p_target_account_id,'need',p_need_id,'agreement',p_agreement_id,
 'category',p_category,'reason',btrim(p_reason),'narrative',btrim(p_narrative))::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('uskoci:report:'||u::text||':'||p_client_request_id::text,8318));
 select * into r from private.safety_reports where reporter_account_id=u and client_request_id=p_client_request_id;
 if found then
  if r.input_hash<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023'; end if;
  return jsonb_build_object('reportId',r.id,'clientRequestId',p_client_request_id,'received',true,'createdAt',r.created_at,'idempotentReplay',true,'authoritative',true);
 end if;
 if not private.safety_report_context_allowed(u,p_target_account_id,p_need_id,p_agreement_id) then raise exception 'SAFETY_CONTEXT_NOT_AVAILABLE' using errcode='42501'; end if;
 insert into private.safety_reports(reporter_account_id,target_account_id,need_id,agreement_id,category,reason,narrative,client_request_id,input_hash)
 values(u,p_target_account_id,p_need_id,p_agreement_id,p_category,btrim(p_reason),btrim(p_narrative),p_client_request_id,h) returning * into r;
 perform private.audit_marketplace(u,'SAFETY_REPORT_RECEIVED','SAFETY_REPORT',r.id,1,'{}');
 return jsonb_build_object('reportId',r.id,'clientRequestId',p_client_request_id,'received',true,'createdAt',r.created_at,'idempotentReplay',false,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_support_cancel_command_v5(p_expected_user_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);begin
 if p_client_request_id is null then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 -- Opaque cancellation is safe even when an executor already restricts writes:
 -- no case/event/provider exists, and retained account subjects are not deleted.
 perform pg_advisory_xact_lock_shared(private.closure_account_key(u));perform pg_advisory_xact_lock(private.support_command_key_v5(u,p_client_request_id));perform private.support_auth_v5(u);
 insert into private.support_commands_v5(account_id,client_request_id,state) values(u,p_client_request_id,'CANCELLED') on conflict do nothing;
 return private.support_command_document_v5(u,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_capabilities_v5(p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);g integer:=private.support_operator_revision_v5(u);begin
 perform private.support_auth_v5(u);
 return jsonb_build_object('accountId',u,'operatorAvailable',g is not null,'canCreate',not exists(select 1 from private.closure_executions_v5 where account_id=u)
 and not exists(select 1 from private.account_closure_requests where account_id=u and state in('EXECUTING','CLOSED')),'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_detail_v5(p_expected_user_id uuid, p_case_id uuid, p_after_sequence text DEFAULT '0'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);g integer:=private.support_operator_revision_v5(u);c private.support_cases_v5;
 evs jsonb;ds jsonb;aps jsonb;es jsonb;ids uuid[];after_seq bigint;last_seq bigint;next_seq text;begin
 if p_after_sequence is null or p_after_sequence!~'^(0|[1-9][0-9]{0,15})$' then raise exception 'SUPPORT_CURSOR_INVALID' using errcode='22023';end if;
 after_seq:=p_after_sequence::bigint;
 select * into c from private.support_cases_v5 where id=p_case_id;
 if not found or(c.account_id<>u and g is null) then raise exception 'SUPPORT_CASE_NOT_AVAILABLE' using errcode='42501';end if;
 select coalesce(jsonb_agg(private.support_event_document_v5(e) order by e.sequence),'[]'),array_agg(e.id),max(e.sequence)
 into evs,ids,last_seq from(select * from private.support_events_v5 where case_id=c.id and sequence>after_seq order by sequence limit 50)e;
 if exists(select 1 from private.support_events_v5 where case_id=c.id and sequence>last_seq) then next_seq:=last_seq::text;end if;
 select coalesce(jsonb_agg(private.support_decision_document_v5(d) order by d.created_at,d.id),'[]') into ds from private.support_decisions_v5 d
 where d.case_id=c.id and exists(select 1 from private.support_events_v5 e where e.id=any(ids) and e.decision_id=d.id);
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'caseId',a.case_id,'decisionId',a.decision_id,'status',a.status,'decisionResultId',a.decision_result_id,'createdAt',a.created_at) order by a.created_at,a.id),'[]') into aps from private.support_appeals_v5 a
 where a.case_id=c.id and exists(select 1 from private.support_events_v5 e where e.id=any(ids) and e.appeal_id=a.id);
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'eventId',e.event_id,'reference',e.snapshot,'createdAt',e.created_at) order by e.created_at,e.id),'[]') into es from private.support_evidence_v5 e where e.case_id=c.id and e.event_id=any(ids);
 if c.account_id<>u then insert into private.support_operator_audit_v5(actor_account_id,action,case_id,grant_revision) values(u,'DETAIL_READ',c.id,g);end if;
 perform private.support_auth_v5(u);
 return jsonb_build_object('accountId',u,'case',jsonb_build_object('id',c.id,'caseNumber',c.case_number::text,'authorAccountId',c.account_id,'channel',c.channel,'topic',c.topic,'title',c.title,
 'desiredOutcome',c.desired_outcome,'context',c.context,'status',c.status,'revision',c.revision,'lastSequence',c.sequence::text,'createdAt',c.created_at,'updatedAt',c.updated_at),
 'viewerRole',case when c.account_id=u then 'AUTHOR' else 'OPERATOR' end,'operatorAvailable',g is not null,'allowedActions',to_jsonb(private.support_allowed_actions_v5(c,u,g)),
 'events',evs,'decisions',ds,'appeals',aps,'evidence',es,'nextAfterSequence',next_seq,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_find_context_v5(p_expected_user_id uuid, p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);cid uuid;begin
 if p_kind is null or p_kind not in('TASK','AGREEMENT','AGREEMENT_MESSAGE','GROUP_MESSAGE','TASK_REVIEW','SAFETY_REPORT') or p_id is null then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 -- A selected message can be evidence while the case context is its Agreement.
 -- Recovery still searches only this author's cases, never an operator inbox.
 select c.id into cid from private.support_cases_v5 c where c.account_id=u and(
  (c.context->>'kind'=p_kind and c.context->>'id'=p_id::text)
  or exists(select 1 from private.support_evidence_v5 e where e.case_id=c.id and e.submitted_by_account_id=u
   and e.source_kind=p_kind and e.source_id=p_id)) order by c.case_number desc limit 1;
 return jsonb_build_object('accountId',u,'caseId',cid,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_inbox_v5(p_expected_user_id uuid, p_mode text, p_before_case_number text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);g integer:=private.support_operator_revision_v5(u);items jsonb;last_number bigint;next_number text;before_number bigint;begin
 if p_mode is null or p_mode not in('OWN','OPERATOR','SAFETY') or (p_before_case_number is not null and p_before_case_number!~'^[1-9][0-9]{0,17}$') then raise exception 'SUPPORT_CURSOR_INVALID' using errcode='22023';end if;
 if p_mode<>'OWN' and g is null then raise exception 'SUPPORT_OPERATOR_REQUIRED' using errcode='42501';end if;
 before_number:=p_before_case_number::bigint;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'caseNumber',c.case_number::text,'channel',c.channel,'topic',c.topic,'status',c.status,'revision',c.revision,
 'lastSequence',c.sequence::text,'createdAt',c.created_at,'updatedAt',c.updated_at,
 'context',case when c.context='{}' then null else jsonb_build_object('kind',c.context->'kind','id',c.context->'id','revision',c.context->'revision') end,
 'unread',exists(select 1 from private.support_events_v5 e where e.case_id=c.id and e.actor_account_id<>u and e.sequence>coalesce((select m.sequence from private.support_read_markers_v5 m where m.account_id=u and m.case_id=c.id),0))) order by c.case_number desc),'[]'),min(c.case_number)
 into items,last_number from (select * from private.support_cases_v5 x where (p_mode<>'OWN' or x.account_id=u) and(p_mode<>'SAFETY' or x.channel='SAFETY')
 and(before_number is null or x.case_number<before_number) order by x.case_number desc limit 50)c;
 if exists(select 1 from private.support_cases_v5 c where c.case_number<last_number and(p_mode<>'OWN' or c.account_id=u) and(p_mode<>'SAFETY' or c.channel='SAFETY')) then next_number:=last_number::text;end if;
 if p_mode<>'OWN' then insert into private.support_operator_audit_v5(actor_account_id,action,grant_revision) values(u,'INBOX_'||p_mode,g);end if;
 perform private.support_auth_v5(u);
 return jsonb_build_object('accountId',u,'mode',p_mode,'operatorAvailable',g is not null,'cases',items,'nextBeforeCaseNumber',next_number,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_mark_read_v5(p_expected_user_id uuid, p_case_id uuid, p_sequence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);g integer;c private.support_cases_v5;s bigint;begin
 if p_sequence is null or p_sequence!~'^[1-9][0-9]{0,15}$' then raise exception 'SUPPORT_CURSOR_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(private.support_operator_key_v5());
 if private.closure_auth_dispatched_v5(u) then raise exception 'ACCOUNT_CLOSING' using errcode='42501';end if;
 perform pg_advisory_xact_lock_shared(private.closure_account_key(u));g:=private.support_operator_revision_v5(u);s:=p_sequence::bigint;
 select * into c from private.support_cases_v5 where id=p_case_id;
 if not found or(c.account_id<>u and g is null) or not exists(select 1 from private.support_events_v5 where case_id=c.id and sequence=s) then raise exception 'SUPPORT_CASE_NOT_AVAILABLE' using errcode='42501';end if;
 perform private.support_auth_v5(u);
 insert into private.support_read_markers_v5(account_id,case_id,sequence) values(u,c.id,s)
 on conflict(account_id,case_id) do update set sequence=greatest(support_read_markers_v5.sequence,excluded.sequence),updated_at=clock_timestamp() returning sequence into s;
 if c.account_id<>u then insert into private.support_operator_audit_v5(actor_account_id,action,case_id,grant_revision) values(u,'MARK_READ',c.id,g);end if;
 return jsonb_build_object('accountId',u,'caseId',c.id,'sequence',s::text,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_media_service_v5(p_account_id uuid, p_session_id uuid, p_case_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c private.support_cases_v5;g integer;m private.owned_media_assets;p private.agreement_photo_uploads_v5;begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 if not private.push_session_valid(p_account_id,p_session_id) then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 g:=private.support_operator_revision_v5(p_account_id);select * into c from private.support_cases_v5 where id=p_case_id;
 if not found or(c.account_id<>p_account_id and g is null) or not exists(select 1 from private.media_evidence_refs_v5 where source_kind='SUPPORT_CASE' and source_id=c.id and asset_id=p_asset_id)
 then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
 select * into p from private.agreement_photo_uploads_v5 where id=p_asset_id and state='READY' and attached_message_id is not null;
 if found then
  if c.account_id<>p_account_id then insert into private.support_operator_audit_v5(actor_account_id,action,case_id,grant_revision) values(p_account_id,'MEDIA_READ',c.id,g);end if;
  if not private.push_session_valid(p_account_id,p_session_id) then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
  return jsonb_build_object('assetId',p.id,'caseId',c.id,'bucket','profile-media','path',p.storage_path,'sha256',p.sanitized_sha256,'contentType','image/jpeg','byteSize',p.byte_size,'authoritative',true);
 end if;
 select * into m from private.owned_media_assets where id=p_asset_id and state='READY' and dispatch_outcome='STORED';
 if not found then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
 if c.account_id<>p_account_id then insert into private.support_operator_audit_v5(actor_account_id,action,case_id,grant_revision) values(p_account_id,'MEDIA_READ',c.id,g);end if;
 if not private.push_session_valid(p_account_id,p_session_id) then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 return jsonb_build_object('assetId',m.id,'caseId',c.id,'bucket','profile-media','path',m.storage_path,'sha256',m.sanitized_sha256,'contentType','image/jpeg','byteSize',m.byte_size,'authoritative',true);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_read_command_v5(p_expected_user_id uuid, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);begin
 if p_client_request_id is null then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 return private.support_command_document_v5(u,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_set_operator_service_v5(p_account_id uuid, p_active boolean, p_expected_revision integer, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare g private.support_operator_grants_v5;c private.support_grant_commands_v5;h text;r jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501';end if;
 if p_account_id is null or p_active is null or p_expected_revision is null or p_expected_revision<0 or p_expected_revision>=2147483646 or p_client_request_id is null then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 perform pg_advisory_xact_lock(private.support_operator_key_v5());
 if p_active then perform private.support_safe_exit_v5(p_account_id);else perform pg_advisory_xact_lock_shared(private.closure_account_key(p_account_id));end if;
 perform pg_advisory_xact_lock(private.support_operator_key_v5());
 h:=encode(extensions.digest(jsonb_build_array(p_account_id,p_active,p_expected_revision)::text,'sha256'),'hex');
 select * into c from private.support_grant_commands_v5 where client_request_id=p_client_request_id;
 if found then if c.input_sha256<>h then raise exception 'SUPPORT_KEY_REUSED' using errcode='22023';end if;return c.receipt;end if;
 select * into g from private.support_operator_grants_v5 where singleton;
 if coalesce(g.revision,0)<>p_expected_revision then raise exception 'SUPPORT_GRANT_STALE' using errcode='PT409';end if;
 if g.active and g.account_id<>p_account_id then raise exception 'SUPPORT_OPERATOR_ALREADY_GRANTED' using errcode='55000';end if;
 if not p_active and g.account_id is distinct from p_account_id then raise exception 'SUPPORT_GRANT_STALE' using errcode='PT409';end if;
 if p_active and not exists(select 1 from auth.users where id=p_account_id and deleted_at is null and (banned_until is null or banned_until<=clock_timestamp())) then raise exception 'AUTH_REQUIRED' using errcode='28000';end if;
 insert into private.support_operator_grants_v5(singleton,account_id,purpose,active,revision,granted_at,updated_at)
 values(true,p_account_id,'PRIVATE_TEST_OWNER_SUPPORT',p_active,p_expected_revision+1,clock_timestamp(),clock_timestamp())
 on conflict(singleton) do update set account_id=excluded.account_id,active=excluded.active,revision=excluded.revision,granted_at=case when excluded.active then excluded.granted_at else support_operator_grants_v5.granted_at end,updated_at=excluded.updated_at;
 insert into private.support_operator_audit_v5(actor_account_id,action,grant_revision) values(p_account_id,case when p_active then 'SERVICE_GRANT' else 'SERVICE_REVOKE' end,p_expected_revision+1);
 r:=jsonb_build_object('accountId',p_account_id,'purpose','PRIVATE_TEST_OWNER_SUPPORT','active',p_active,'revision',p_expected_revision+1,'authoritative',true);
 insert into private.support_grant_commands_v5(client_request_id,account_id,input_sha256,receipt) values(p_client_request_id,p_account_id,h,r);return r;
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_support_submit_v5(p_expected_user_id uuid, p_client_request_id uuid, p_kind text, p_case_id uuid, p_expected_revision integer, p_payload_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=private.support_auth_v5(p_expected_user_id);p jsonb;c private.support_cases_v5;cmd private.support_commands_v5;
 g integer;h text;body text;ev private.support_events_v5;d private.support_decisions_v5;ap private.support_appeals_v5;
 ctx jsonb;ref jsonb;snapshot jsonb;refs jsonb:='[]';evidence_ids uuid[]:='{}';eid uuid;v_ordinary boolean;owner_id uuid;role_name text;next_status text;r jsonb;
begin
 if p_client_request_id is null or p_kind is null or p_kind not in('CREATE','AUTHOR_REPLY','CLAIM','OPERATOR_REPLY','REQUEST_INFO','DECIDE','APPEAL','CLAIM_APPEAL','DECIDE_APPEAL','CLOSE')
 or p_payload_text is null or octet_length(p_payload_text)>65536
 or (p_kind='CREATE' and (p_case_id is not null or p_expected_revision is not null))
 or (p_kind<>'CREATE' and (p_case_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_revision>=2147483646)) then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 begin p:=p_payload_text::jsonb;exception when data_exception then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end;
 if jsonb_typeof(p) is distinct from 'object' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 -- Hash the actual UTF8 transport and its typed scope, never PostgreSQL's
 -- reserialized JSONB whitespace. No plaintext is retained in the command.
 h:=encode(extensions.digest(convert_to(p_kind||E'\n'||coalesce(p_case_id::text,'')||E'\n'||coalesce(p_expected_revision::text,'')||E'\n'||p_payload_text,'UTF8'),'sha256'),'hex');
 select account_id into owner_id from private.support_cases_v5 where id=p_case_id;
 perform private.support_safe_exit_v5(u,owner_id);
 -- Private-test writes share one short transaction barrier. This also orders
 -- different selected media owners and exact grant revocation without lock upgrades.
 perform pg_advisory_xact_lock(private.support_operator_key_v5());g:=private.support_operator_revision_v5(u);
 perform pg_advisory_xact_lock(private.support_command_key_v5(u,p_client_request_id));perform private.support_auth_v5(u);
 select * into cmd from private.support_commands_v5 where account_id=u and client_request_id=p_client_request_id;
 if found then
  if cmd.state='COMMITTED' and cmd.input_sha256<>h then raise exception 'SUPPORT_KEY_REUSED' using errcode='22023';end if;
  return private.support_command_document_v5(u,p_client_request_id);
 end if;
 -- One actor quota lock serializes different keys; exact replay above is free.
 perform pg_advisory_xact_lock(hashtextextended('uskoci:support:quota:'||u::text,10143));
 if p_kind='CREATE' then
  if p-array['channel','topic','title','body','desiredOutcome','context','evidence']<>'{}' or not(p?&array['channel','topic','title','body','desiredOutcome','context','evidence'])
  or jsonb_typeof(p->'channel') is distinct from 'string' or jsonb_typeof(p->'topic') is distinct from 'string'
  or jsonb_typeof(p->'title') is distinct from 'string' or length(btrim(p->>'title')) not between 1 and 200 or octet_length(p->>'title')>800
  or (p->'desiredOutcome'<>'null' and (jsonb_typeof(p->'desiredOutcome')<>'string' or length(p->>'desiredOutcome')>1000 or octet_length(p->>'desiredOutcome')>4000))
  or jsonb_typeof(p->'evidence') is distinct from 'array' or jsonb_array_length(p->'evidence')>50 then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
  if not((p->>'channel'='SERVICE' and p->>'topic' in('TECHNICAL','SERVICE_COMPLAINT','OTHER'))
   or(p->>'channel'='TASK' and p->>'topic' in('COLLABORATION','NO_SHOW','PUBLICATION_REVIEW'))
   or(p->>'channel'='LEGAL_PRIVACY' and p->>'topic' in('CONTENT_NOTICE','PRIVACY_RIGHTS')))
  then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
  v_ordinary:=p->>'topic'<>'PRIVACY_RIGHTS';
  if v_ordinary then
   if (select count(*) from private.support_cases_v5 where account_id=u and ordinary and created_at>clock_timestamp()-interval '24 hours')>=5 then raise exception 'SUPPORT_CASE_DAILY_LIMIT' using errcode='54000';end if;
   if exists(select 1 from private.support_cases_v5 where account_id=u and ordinary and created_at>clock_timestamp()-interval '60 seconds') then raise exception 'SUPPORT_CREATE_COOLDOWN' using errcode='54000';end if;
  end if;
  ctx:=case when p->'context'='null' then '{}'::jsonb else private.support_reference_v5(u,p->'context') end;
  if (p->>'topic' in('COLLABORATION','NO_SHOW') and ctx->>'kind' is distinct from 'AGREEMENT')
  or(p->>'topic'='PUBLICATION_REVIEW' and ctx->>'kind' is distinct from 'TASK_REVIEW')
  then raise exception 'SUPPORT_CONTEXT_REQUIRED' using errcode='22023';end if;
  refs:=p->'evidence';body:=p->>'body';role_name:='AUTHOR';next_status:='RECEIVED';
 else
  select * into c from private.support_cases_v5 where id=p_case_id for update;
  if not found or (c.account_id<>u and g is null) then raise exception 'SUPPORT_CASE_NOT_AVAILABLE' using errcode='42501';end if;
  if c.revision<>p_expected_revision or c.sequence>=9007199254740990 then raise exception 'SUPPORT_REVISION_STALE' using errcode='PT409';end if;
  if not(p_kind=any(private.support_allowed_actions_v5(c,u,g))) then raise exception 'SUPPORT_ACTION_NOT_AVAILABLE' using errcode='42501';end if;
  role_name:=case when c.account_id=u then 'AUTHOR' else 'OPERATOR' end;next_status:=c.status;
  if p_kind='AUTHOR_REPLY' then
   if p-array['body','evidence']<>'{}' or not(p?&array['body','evidence']) or jsonb_typeof(p->'evidence') is distinct from 'array' or jsonb_array_length(p->'evidence')>50 then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   if c.ordinary and (select count(*) from private.support_events_v5 e join private.support_cases_v5 z on z.id=e.case_id where e.actor_account_id=u and e.kind='AUTHOR_REPLY' and z.ordinary and e.created_at>clock_timestamp()-interval '24 hours')>=50 then raise exception 'SUPPORT_REPLY_DAILY_LIMIT' using errcode='54000';end if;
   body:=p->>'body';refs:=p->'evidence';next_status:=case when c.status='RECEIVED' then 'RECEIVED' else 'IN_REVIEW' end;
  elsif p_kind in('OPERATOR_REPLY','REQUEST_INFO') then
   if p-array['body']<>'{}' or not(p?'body') then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   body:=p->>'body';if p_kind='REQUEST_INFO' then next_status:='WAITING_FOR_AUTHOR';end if;
  elsif p_kind='CLAIM' then
   if p<>'{}' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;next_status:='IN_REVIEW';
  elsif p_kind='CLOSE' then
   if p<>'{}' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;next_status:='CLOSED';
  elsif p_kind='APPEAL' then
   if p-array['decisionId','body']<>'{}' or not(p?&array['decisionId','body']) or coalesce(p->>'decisionId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   select * into d from private.support_decisions_v5 where id=(p->>'decisionId')::uuid and case_id=c.id;
   if not found then raise exception 'SUPPORT_DECISION_NOT_AVAILABLE' using errcode='42501';end if;
   if exists(select 1 from private.support_appeals_v5 where decision_id=d.id and status<>'DECIDED') then raise exception 'SUPPORT_APPEAL_ALREADY_OPEN' using errcode='PT409';end if;
   insert into private.support_appeals_v5(case_id,decision_id,account_id) values(c.id,d.id,u) returning * into ap;
   body:=p->>'body';next_status:='RECEIVED';
  elsif p_kind='CLAIM_APPEAL' then
   if p-array['appealId']<>'{}' or not(p?'appealId') or coalesce(p->>'appealId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   update private.support_appeals_v5 set status='IN_REVIEW' where id=(p->>'appealId')::uuid and case_id=c.id and status='RECEIVED' returning * into ap;
   if not found then raise exception 'SUPPORT_APPEAL_NOT_AVAILABLE' using errcode='42501';end if;next_status:='IN_REVIEW';
  elsif p_kind in('DECIDE','DECIDE_APPEAL') then
   if p-array['outcome','reasonCode','body','evidenceIds','appealId']<>'{}' or not(p?&array['outcome','reasonCode','body','evidenceIds','appealId'])
   or jsonb_typeof(p->'outcome') is distinct from 'string' or p->>'outcome' not in('ACCEPTED','REJECTED')
   or jsonb_typeof(p->'reasonCode') is distinct from 'string' or (p->>'reasonCode')!~'^[A-Z][A-Z0-9_]{0,63}$'
   or jsonb_typeof(p->'evidenceIds') is distinct from 'array' or jsonb_array_length(p->'evidenceIds')>50 then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   for ref in select value from jsonb_array_elements(p->'evidenceIds') loop
    if jsonb_typeof(ref)<>'string' or (ref#>>'{}')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
    eid:=(ref#>>'{}')::uuid;if eid=any(evidence_ids) or not exists(select 1 from private.support_evidence_v5 where id=eid and case_id=c.id) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;evidence_ids:=array_append(evidence_ids,eid);
   end loop;
   if p_kind='DECIDE_APPEAL' then
    if coalesce(p->>'appealId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
    select * into ap from private.support_appeals_v5 where id=(p->>'appealId')::uuid and case_id=c.id and status='IN_REVIEW';
    if not found then raise exception 'SUPPORT_APPEAL_NOT_AVAILABLE' using errcode='42501';end if;
   elsif p->'appealId'<>'null' then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
   body:=p->>'body';next_status:='DECIDED';
  end if;
 end if;
 if p_kind in('CREATE','AUTHOR_REPLY','OPERATOR_REPLY','REQUEST_INFO','DECIDE','DECIDE_APPEAL','APPEAL')
 and(jsonb_typeof(p->'body') is distinct from 'string' or length(btrim(body)) not between 1 and 4000 or octet_length(body)>16000) then raise exception 'SUPPORT_INPUT_INVALID' using errcode='22023';end if;
 body:=btrim(body);
 if p_kind='CREATE' then
  insert into private.support_cases_v5(account_id,channel,topic,title,desired_outcome,context,ordinary)
  values(u,p->>'channel',p->>'topic',btrim(p->>'title'),p->>'desiredOutcome',ctx,v_ordinary) returning * into c;
  perform private.support_capture_media_v5(c.id,c.revision,ctx);
 else
  update private.support_cases_v5 set status=next_status,revision=revision+1,sequence=sequence+1,updated_at=clock_timestamp() where id=c.id returning * into c;
 end if;
 if p_kind in('DECIDE','DECIDE_APPEAL') then
  insert into private.support_decisions_v5(case_id,case_revision,operator_account_id,grant_revision,outcome,reason_code,explanation,evidence_ids,prior_decision_id)
  values(c.id,c.revision,u,g,p->>'outcome',p->>'reasonCode',body,evidence_ids,ap.decision_id) returning * into d;
  if ap.id is not null then update private.support_appeals_v5 set status='DECIDED',decision_result_id=d.id where id=ap.id;end if;
 end if;
 insert into private.support_events_v5(case_id,sequence,actor_account_id,author_role,kind,body,decision_id,appeal_id)
 values(c.id,c.sequence,u,role_name,p_kind,body,d.id,ap.id) returning * into ev;
 for ref in select value from jsonb_array_elements(refs) loop
  snapshot:=private.support_reference_v5(u,ref);
  perform private.support_capture_media_v5(c.id,c.revision,snapshot);
  insert into private.support_evidence_v5(case_id,event_id,submitted_by_account_id,source_kind,source_id,source_revision,snapshot,snapshot_sha256)
  values(c.id,ev.id,u,snapshot->>'kind',(snapshot->>'id')::uuid,(snapshot->>'revision')::integer,snapshot,encode(extensions.digest(snapshot::text,'sha256'),'hex'));
 end loop;
 if c.safety_report_id is not null then update private.safety_reports set status=case when next_status='CLOSED' then 'RESOLVED' when next_status='RECEIVED' then 'RECEIVED' else 'IN_REVIEW' end where id=c.safety_report_id;end if;
 if role_name='OPERATOR' then insert into private.support_operator_audit_v5(actor_account_id,action,case_id,grant_revision) values(u,p_kind,c.id,g);end if;
 perform private.support_auth_v5(u);
 r:=jsonb_build_object('accountId',u,'clientRequestId',p_client_request_id,'kind',p_kind,'caseId',c.id,'caseNumber',c.case_number::text,
 'expectedRevision',p_expected_revision,'inputSha256',h,'eventId',ev.id,'sequence',ev.sequence::text,'caseRevision',c.revision,'createdAt',ev.created_at,'authoritative',true);
 insert into private.support_commands_v5(account_id,client_request_id,kind,input_sha256,expected_revision,state,case_id,receipt) values(u,p_client_request_id,p_kind,h,p_expected_revision,'COMMITTED',c.id,r);
 return private.support_command_document_v5(u,p_client_request_id);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_ai_catalog_context_service(p_execution_location_mode text, p_limit integer DEFAULT 80, p_after_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT private.taxonomy_ai_catalog_context_v1(
  p_execution_location_mode,p_limit,p_after_key
 )
$function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_ai_scoped_preview_service(p_execution_location_mode text, p_ai_category text, p_public_description text, p_explicit_required_skills text[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT private.taxonomy_existing_ai_scoped_preview_v1(
   p_execution_location_mode,p_ai_category,p_public_description,p_explicit_required_skills)
$function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_approve_admission(p_admission_id uuid, p_plan_digest text, p_displayed_review_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_admissions_v1%ROWTYPE;v_owner uuid;
BEGIN
 PERFORM private.closure_assert_open(auth.uid());
 v_owner:=auth.uid();
 IF v_owner IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode='28000'; END IF;
 SELECT * INTO v FROM private.work_taxonomy_admissions_v1
  WHERE id=p_admission_id AND owner_account_id=v_owner FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_NOT_OWNED' USING errcode='42501'; END IF;
 IF v.status='COMMITTED' THEN RETURN v.result; END IF;
 IF v.expires_at<=statement_timestamp() THEN RAISE EXCEPTION 'ADMISSION_EXPIRED'; END IF;
 IF v.plan_digest IS DISTINCT FROM p_plan_digest
 OR v.source_review_digest IS DISTINCT FROM p_displayed_review_digest THEN
  RAISE EXCEPTION 'ADMISSION_DISPLAY_MISMATCH' USING errcode='42501'; END IF;
 -- This is not a second consent action. The EXISTING Save profile / Accept
 -- task review command must already have succeeded for the same review and
 -- exact idempotency/request key. A caller knowing the digest is not enough.
 IF v.purpose='WORKER_CAPABILITY' THEN
  PERFORM 1 FROM private.worker_ai_saves s
   WHERE s.review_id=v.source_review_id
     AND s.account_id=v.owner_account_id
     AND s.client_request_id=v.request_key;
 ELSE
  PERFORM 1 FROM private.ai_task_review_commands c
   WHERE c.review_id=v.source_review_id
     AND c.account_id=v.owner_account_id
     AND c.client_request_id=v.request_key
     AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED');
 END IF;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'ADMISSION_REVIEW_SAVE_REQUIRED' USING errcode='42501'; END IF;
 IF v.status='PENDING' THEN
   UPDATE private.work_taxonomy_admissions_v1 SET status='APPROVED',approved_at=statement_timestamp()
   WHERE id=v.id;
 END IF;
 RETURN jsonb_build_object('admissionId',v.id,'status','APPROVED');
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_assign_worker_categories_service(p_worker_account_id uuid, p_category_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
  v_cat_id uuid;
  v_labels text[] := ARRAY[]::text[];
  v_label text;
  v_assigned integer := 0;
BEGIN
 PERFORM private.closure_assert_open(p_worker_account_id);
  IF p_worker_account_id IS NULL OR p_category_ids IS NULL THEN
    RAISE EXCEPTION 'WORKER_OR_CATEGORIES_NULL' USING errcode='22023';
  END IF;

  FOREACH v_cat_id IN ARRAY p_category_ids LOOP
    SELECT label INTO v_label
    FROM private.work_taxonomy_categories
    WHERE id = v_cat_id AND state <> 'RETIRED';

    IF v_label IS NOT NULL THEN
      v_labels := array_append(v_labels, v_label);

      INSERT INTO private.work_taxonomy_worker_capabilities (
        worker_account_id, category_id, confirmed_at, allow_related_offers, excluded, origin
      ) VALUES (
        p_worker_account_id, v_cat_id, statement_timestamp(), true, false, 'WORKER_CONFIRMED'
      ) ON CONFLICT (worker_account_id, category_id) DO UPDATE
        SET confirmed_at = statement_timestamp(), updated_at = statement_timestamp(), excluded = false;

      v_assigned := v_assigned + 1;
    END IF;
  END LOOP;

  -- Synchronize canonical labels into public.app_profiles.skills
  IF cardinality(v_labels) > 0 THEN
    UPDATE public.app_profiles
    SET skills = array(SELECT DISTINCT unnest(coalesce(skills, ARRAY[]::text[]) || v_labels)),
        updated_at = statement_timestamp()
    WHERE account_id = p_worker_account_id AND kind = 'WORKER';
  END IF;

  RETURN jsonb_build_object(
    'workerAccountId', p_worker_account_id,
    'assignedCount', v_assigned,
    'skills', to_jsonb(v_labels)
  );
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_assign_worker_skills_service(p_worker_account_id uuid, p_skill_labels text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
BEGIN
  IF auth.role() NOT IN ('service_role', 'authenticated') THEN
    RAISE EXCEPTION 'PERMISSION_DENIED' USING errcode='42501';
  END IF;
  RETURN private.sync_worker_skills_to_taxonomy_capabilities(p_worker_account_id, p_skill_labels);
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_ready_reviews_service(p_limit integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_enabled boolean;
 v_q private.work_taxonomy_review_outbox_v1%ROWTYPE;
 v_profile_id uuid;v_need_id uuid;v_need_revision integer;
 v_receipt jsonb;v_sqlstate text;v_attempts integer;
 v_claimed integer:=0;v_bound integer:=0;v_review_required integer:=0;v_retry integer:=0;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role'
 THEN RAISE EXCEPTION 'BINDING_TICK_SERVICE_ROLE_REQUIRED' USING errcode='42501'; END IF;
 IF p_limit NOT BETWEEN 1 AND 5
 THEN RAISE EXCEPTION 'BINDING_TICK_LIMIT_INVALID' USING errcode='22023'; END IF;
 SELECT enabled INTO v_enabled FROM private.work_taxonomy_binding_control_v1 WHERE singleton;
 IF v_enabled IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('kind','BINDING_DISABLED','claimed',0,
   'bound',0,'retry',0,'reviewRequired',0,
   'dispatchAuthority','NONE','notificationAuthority','NONE');
 END IF;
 FOR v_q IN
  WITH candidates AS MATERIALIZED (SELECT q.id,q.owner_account_id FROM private.work_taxonomy_review_outbox_v1 q
  WHERE NOT private.closure_account_restricted(q.owner_account_id) AND q.state='COMMITTED'
    AND q.binding_state IN ('PENDING','RETRY')
    AND q.binding_retry_after<=statement_timestamp()
  ORDER BY q.created_at,q.id
  LIMIT p_limit), admitted AS MATERIALIZED (SELECT id FROM candidates WHERE private.closure_taxonomy_try_owner_v1(owner_account_id))
  SELECT q.* FROM private.work_taxonomy_review_outbox_v1 q JOIN admitted a ON a.id=q.id WHERE q.state='COMMITTED' AND q.binding_state IN ('PENDING','RETRY') AND q.binding_retry_after<=statement_timestamp() FOR UPDATE OF q SKIP LOCKED
 LOOP
  v_claimed:=v_claimed+1;v_attempts:=v_q.binding_attempts+1;
  BEGIN
   IF v_q.purpose='WORKER_CAPABILITY' THEN
    SELECT (r.envelope->>'profileId')::uuid INTO v_profile_id
    FROM private.worker_ai_reviews r
    WHERE r.id=v_q.source_review_id AND r.account_id=v_q.owner_account_id
      AND r.envelope->>'classificationState'='READY';
    IF v_profile_id IS NULL THEN
     RAISE EXCEPTION 'BINDING_SIGNED_WORKER_REVIEW_MISSING' USING errcode='42501';
    END IF;
    -- The binder rechecks original owner, Save receipt, digest, mode and current
    -- profile under lock. Never use an Edge-supplied profile or AI-proposed mode.
    v_receipt:=public.rpc_taxonomy_bind_reviewed_worker_service(
      v_q.owner_account_id,v_q.request_key,v_q.source_review_id,v_profile_id);
   ELSIF v_q.purpose='NEED_SERVICE' THEN
    SELECT c.need_id,c.need_revision INTO v_need_id,v_need_revision
    FROM private.ai_task_review_commands c
    WHERE c.review_id=v_q.source_review_id AND c.account_id=v_q.owner_account_id
      AND c.client_request_id=v_q.request_key
      AND c.state IN('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED')
    ORDER BY c.created_at DESC LIMIT 1;
    IF v_need_id IS NULL OR v_need_revision IS NULL THEN
     RAISE EXCEPTION 'BINDING_ACCEPTED_NEED_NOT_READY' USING errcode='PT409';
    END IF;
    v_receipt:=public.rpc_taxonomy_bind_reviewed_need_service(
      v_q.owner_account_id,v_q.request_key,v_q.source_review_id,
      v_need_id,v_need_revision);
   ELSE
    RAISE EXCEPTION 'BINDING_PURPOSE_INVALID' USING errcode='22023';
   END IF;
   IF v_receipt->>'status' NOT IN('BOUND_WORKER_SERVICES','BOUND_NEED_REVISION')
     OR v_receipt->>'notificationAuthority'<>'NONE'
     OR v_receipt->>'dispatchAuthority'<>'NONE' THEN
     RAISE EXCEPTION 'BINDING_RECEIPT_PROTOCOL_INVALID' USING errcode='42501';
   END IF;
   UPDATE private.work_taxonomy_review_outbox_v1
    SET binding_state='BOUND',binding_attempts=v_attempts,
      binding_error_code=NULL,binding_result=v_receipt,updated_at=statement_timestamp()
    WHERE id=v_q.id;
   v_bound:=v_bound+1;
  EXCEPTION WHEN OTHERS THEN
   -- Per-item subtransaction rolls back any partly written binder receipt,
   -- capability or snapshot. Catalog commit and prior Save remain untouched.
   GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE;
   IF v_sqlstate IN('PT409','40001','40P01','55P03','57014') AND v_attempts<5 THEN
    UPDATE private.work_taxonomy_review_outbox_v1
     SET binding_state='RETRY',binding_attempts=v_attempts,
       binding_error_code='BINDING_STALE_OR_BUSY',
       binding_retry_after=statement_timestamp()
         +make_interval(secs=>LEAST(900,15*power(2,LEAST(v_attempts,5)))::integer),
       updated_at=statement_timestamp()
     WHERE id=v_q.id;
    v_retry:=v_retry+1;
   ELSE
    UPDATE private.work_taxonomy_review_outbox_v1
     SET binding_state='REVIEW_REQUIRED',binding_attempts=v_attempts,
       binding_error_code='BINDING_REVIEW_REQUIRED',
       updated_at=statement_timestamp()
     WHERE id=v_q.id;
    v_review_required:=v_review_required+1;
   END IF;
  END;
 END LOOP;
 RETURN jsonb_build_object('kind','BINDING_ONLY_TICK','claimed',v_claimed,
  'bound',v_bound,'retry',v_retry,'reviewRequired',v_review_required,
  'dispatchAuthority','NONE','notificationAuthority','NONE');
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_reviewed_need_service(p_owner_account_id uuid, p_request_key uuid, p_source_review_id uuid, p_need_id uuid, p_need_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_existing private.work_taxonomy_need_bindings_v1%ROWTYPE;
 v_batch private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review private.ai_task_reviews%ROWTYPE;
 v_command private.ai_task_review_commands%ROWTYPE;
 v_need public.needs%ROWTYPE;
 v_plan jsonb;v_item jsonb;v_category uuid;v_scope text;v_service text;v_category_version bigint;
 v_expected_digest text;v_result jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
   RAISE EXCEPTION 'NEED_BINDER_SERVICE_ROLE_REQUIRED' USING errcode='42501';
 END IF;
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
    OR p_need_id IS NULL OR coalesce(p_need_revision,0)<1 THEN
   RAISE EXCEPTION 'NEED_BINDER_INPUT_INVALID' USING errcode='22023';
 END IF;
 SELECT * INTO v_existing FROM private.work_taxonomy_need_bindings_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
   IF v_existing.source_review_id<>p_source_review_id OR v_existing.need_id<>p_need_id
     OR v_existing.need_revision<>p_need_revision THEN
     RAISE EXCEPTION 'NEED_BINDER_REQUEST_KEY_REUSED' USING errcode='22023';
   END IF;
   RETURN v_existing.result;
 END IF;
 SELECT * INTO v_batch FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key
    AND source_review_id=p_source_review_id AND purpose='NEED_SERVICE' FOR SHARE;
 IF NOT FOUND OR v_batch.result->>'status'<>'COMMITTED'
   OR v_batch.result->'requiresBinding' IS DISTINCT FROM 'true'::jsonb
   OR v_batch.result->'capabilityAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR v_batch.result->'notificationAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR jsonb_typeof(v_batch.result->'items')<>'array'
   OR jsonb_array_length(v_batch.result->'items')<>1 THEN
   RAISE EXCEPTION 'NEED_BINDER_ADMISSION_NOT_COMMITTED' USING errcode='42501';
 END IF;
 SELECT * INTO v_review FROM private.ai_task_reviews r
  WHERE r.id=p_source_review_id AND r.account_id=p_owner_account_id FOR SHARE;
 IF NOT FOUND OR v_review.envelope->>'classificationState'<>'READY'
   OR v_review.envelope->>'displayedContentDigest' IS DISTINCT FROM v_batch.review_digest
   OR v_review.envelope->'classificationCandidates' IS DISTINCT FROM v_batch.plans
   OR jsonb_array_length(coalesce(v_review.envelope->'classificationCandidates','[]'::jsonb))<>1 THEN
   RAISE EXCEPTION 'NEED_BINDER_REVIEW_NOT_BOUND' USING errcode='42501';
 END IF;
 v_expected_digest:=encode(extensions.digest(jsonb_build_object('envelope',
   v_review.envelope-'displayedContentDigest','policy',v_review.policy_binding)::text,'sha256'),'hex');
 IF v_expected_digest<>v_batch.review_digest THEN
   RAISE EXCEPTION 'NEED_BINDER_REVIEW_DIGEST_INVALID' USING errcode='42501';
 END IF;
 SELECT * INTO v_command FROM private.ai_task_review_commands c
  WHERE c.review_id=p_source_review_id AND c.account_id=p_owner_account_id
    AND c.client_request_id=p_request_key AND c.need_id=p_need_id
    AND c.need_revision=p_need_revision
    AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'NEED_BINDER_SAVE_REQUIRED' USING errcode='42501'; END IF;
 v_plan:=v_batch.plans->0;
 v_item:=v_batch.result->'items'->0;
 IF v_plan->>'mode' IS DISTINCT FROM v_item->>'mode'
   OR private.taxonomy_normalize_v1(v_plan->>'service')
      IS DISTINCT FROM private.taxonomy_normalize_v1(v_item->>'service')
   OR v_plan->>'action' NOT IN ('REUSE_EXISTING','EXTEND_MODE','CREATE_CHILD','CREATE_NEW_BRANCH')
 THEN RAISE EXCEPTION 'NEED_BINDER_CATEGORY_RECEIPT_INVALID' USING errcode='42501'; END IF;
 v_category:=(v_item->>'categoryId')::uuid;
 v_category_version:=v_batch.catalog_version;
 SELECT * INTO v_need FROM public.needs n WHERE n.id=p_need_id FOR UPDATE;
 IF NOT FOUND OR v_need.requester_account_id<>p_owner_account_id OR
    v_need.revision<>p_need_revision OR v_need.status NOT IN ('DRAFT','PUBLISHED','SELECTION') THEN
   RAISE EXCEPTION 'NEED_BINDER_CURRENT_REVISION_REQUIRED' USING errcode='PT409';
 END IF;
 v_scope:=private.taxonomy_execution_scope_v1(v_need.execution_location_mode);
 IF v_scope IS NULL OR v_scope<>v_item->>'mode'
   OR private.taxonomy_normalize_v1(v_need.category)
      <>private.taxonomy_normalize_v1(v_item->>'service')
 THEN RAISE EXCEPTION 'NEED_BINDER_SERVICE_OR_MODE_STALE' USING errcode='PT409'; END IF;
 -- Both public projection and routing were saved from the same signed fact.
 IF (v_scope='REMOTE' AND NOT private.taxonomy_handoff_valid_v1(v_plan->'handoff'))
    OR (SELECT d.handoff FROM public.need_requirement_details d WHERE d.need_id=p_need_id)
      IS DISTINCT FROM v_plan->'handoff' THEN
   RAISE EXCEPTION 'NEED_BINDER_HANDOFF_STALE' USING errcode='PT409';
 END IF;
 PERFORM 1 FROM private.work_taxonomy_categories c
  JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
  WHERE c.id=v_category AND c.state='ESTABLISHED' AND m.execution_scope=v_scope;
 IF NOT FOUND THEN RAISE EXCEPTION 'NEED_BINDER_CATEGORY_RETIRED' USING errcode='42501'; END IF;
 IF v_need.category_id IS NOT NULL AND v_need.category_id<>v_category THEN
   RAISE EXCEPTION 'NEED_BINDER_CONFLICTING_EXISTING_CATEGORY' USING errcode='PT409'; END IF;
 PERFORM 1 FROM private.work_taxonomy_need_snapshots s
  WHERE s.need_id=p_need_id AND s.need_revision=p_need_revision FOR UPDATE;
 IF FOUND THEN RAISE EXCEPTION 'NEED_BINDER_EXISTING_SNAPSHOT_REVIEW_REQUIRED' USING errcode='PT409'; END IF;
 -- Same transaction: category reference + single authoritative revision
 -- snapshot + durable replay receipt. A failed write rolls all three back.
 UPDATE public.needs SET category_id=v_category WHERE id=p_need_id
    AND revision=p_need_revision AND category_id IS DISTINCT FROM v_category;
 INSERT INTO private.work_taxonomy_need_snapshots
  (need_id,need_revision,category_id,catalog_version,reviewed_by_requester,
   source,classification_state,original_category)
 VALUES(p_need_id,p_need_revision,v_category,v_category_version,true,
   'OWNER_REVIEWED_BATCH','CONFIRMED',v_need.category);
 v_result:=jsonb_build_object('status','BOUND_NEED_REVISION',
   'needId',p_need_id,'needRevision',p_need_revision,'categoryId',v_category,
   'catalogVersion',v_category_version,
   'dispatchAuthority','NONE','notificationAuthority','NONE');
 INSERT INTO private.work_taxonomy_need_bindings_v1
  (owner_account_id,request_key,source_review_id,need_id,need_revision,
   category_id,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_source_review_id,p_need_id,
   p_need_revision,v_category,v_category_version,v_result);
 RETURN v_result;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_reviewed_worker_service(p_owner_account_id uuid, p_request_key uuid, p_source_review_id uuid, p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_existing private.work_taxonomy_worker_bindings_v1%ROWTYPE;
 v_batch private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review private.worker_ai_reviews%ROWTYPE;
 v_save private.worker_ai_saves%ROWTYPE;
 v_profile public.app_profiles%ROWTYPE;
 v_digest text;v_item jsonb;v_plan jsonb;v_category uuid;
 v_key text;v_mode text;v_seen text[]:=ARRAY[]::text[];
 v_modes text[]:=ARRAY[]::text[];v_onsite boolean:=false;v_remote boolean:=false;
 v_result jsonb;v_count integer:=0;v_skills jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
  RAISE EXCEPTION 'WORKER_BINDER_SERVICE_ROLE_REQUIRED' USING errcode='42501';
 END IF;
 IF p_owner_account_id IS NULL OR p_request_key IS NULL
   OR p_source_review_id IS NULL OR p_profile_id IS NULL THEN
  RAISE EXCEPTION 'WORKER_BINDER_INPUT_INVALID' USING errcode='22023';
 END IF;
 -- Replays are read-only and bound to the very same worker/review/request.
 SELECT * INTO v_existing FROM private.work_taxonomy_worker_bindings_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
  IF v_existing.source_review_id<>p_source_review_id OR v_existing.profile_id<>p_profile_id
  THEN RAISE EXCEPTION 'WORKER_BINDER_REQUEST_KEY_REUSED' USING errcode='22023'; END IF;
  RETURN v_existing.result;
 END IF;
 SELECT * INTO v_batch FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key
   AND source_review_id=p_source_review_id AND purpose='WORKER_CAPABILITY'
  FOR SHARE;
 IF NOT FOUND OR v_batch.result->>'status'<>'COMMITTED'
   OR v_batch.result->'requiresBinding' IS DISTINCT FROM 'true'::jsonb
   OR v_batch.result->'capabilityAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR v_batch.result->'notificationAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR jsonb_typeof(v_batch.plans)<>'array'
   OR jsonb_typeof(v_batch.result->'items')<>'array'
   OR jsonb_array_length(v_batch.plans) NOT BETWEEN 1 AND 24
   OR jsonb_array_length(v_batch.result->'items')<>jsonb_array_length(v_batch.plans)
 THEN RAISE EXCEPTION 'WORKER_BINDER_ADMISSION_NOT_COMMITTED' USING errcode='42501'; END IF;
 SELECT * INTO v_review FROM private.worker_ai_reviews
  WHERE id=p_source_review_id AND account_id=p_owner_account_id FOR SHARE;
 IF NOT FOUND OR v_review.envelope->>'classificationState'<>'READY'
   OR v_review.envelope->>'displayedContentDigest' IS DISTINCT FROM v_batch.review_digest
   OR v_review.envelope->'classificationCandidates' IS DISTINCT FROM v_batch.plans
   OR v_review.envelope->'canAccept' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(v_review.envelope->'reviewedServiceModes')<>'array'
   OR jsonb_array_length(v_review.envelope->'reviewedServiceModes')
       <>jsonb_array_length(v_batch.plans)
   OR v_review.envelope->>'profileId' IS DISTINCT FROM p_profile_id::text
 THEN RAISE EXCEPTION 'WORKER_BINDER_REVIEW_NOT_BOUND' USING errcode='42501'; END IF;
 v_digest:=encode(extensions.digest(
  ((v_review.envelope-'displayedContentDigest')
    ||jsonb_build_object('baseHash',v_review.base_hash))::text,'sha256'),'hex');
 IF v_digest IS DISTINCT FROM v_batch.review_digest THEN
   RAISE EXCEPTION 'WORKER_BINDER_REVIEW_DIGEST_INVALID' USING errcode='42501'; END IF;
 SELECT * INTO v_save FROM private.worker_ai_saves
  WHERE review_id=p_source_review_id AND account_id=p_owner_account_id
    AND client_request_id=p_request_key FOR SHARE;
 IF NOT FOUND OR v_save.created_at>v_review.expires_at
   OR v_save.receipt->'saved' IS DISTINCT FROM 'true'::jsonb
   OR v_save.receipt->>'profileId' IS DISTINCT FROM p_profile_id::text
   OR v_save.receipt->>'profileStatus'<>'ACTIVE'
 THEN RAISE EXCEPTION 'WORKER_BINDER_SAVE_OR_ACTIVATION_REQUIRED' USING errcode='42501'; END IF;
 -- A delayed outbox command from an OLD Save must never re-enable modes
 -- superseded by a newer user-confirmed worker review for this same profile.
 IF EXISTS(SELECT 1 FROM private.worker_ai_saves newer
   WHERE newer.account_id=p_owner_account_id
     AND newer.created_at>v_save.created_at
     AND newer.receipt->>'profileId'=p_profile_id::text)
 THEN RAISE EXCEPTION 'WORKER_BINDER_NEWER_SAVE_EXISTS' USING errcode='PT409'; END IF;
 -- Hold current worker profile throughout the transaction. Reject any edit
 -- after the reviewed Save, even if the new skill text happens to be identical.
 SELECT * INTO v_profile FROM public.app_profiles
  WHERE id=p_profile_id AND account_id=p_owner_account_id AND kind='WORKER'
  FOR UPDATE;
 v_skills:=v_review.envelope#>'{profile,skills}';
 IF NOT FOUND OR v_profile.profile_status<>'ACTIVE'
   OR v_profile.updated_at>v_save.created_at
   OR jsonb_typeof(v_skills)<>'array'
   OR to_jsonb(v_profile.skills) IS DISTINCT FROM v_skills
 THEN RAISE EXCEPTION 'WORKER_BINDER_CURRENT_PROFILE_REQUIRED' USING errcode='PT409'; END IF;
 -- Make every scope and category EXACT. A related branch never certifies ability.
 FOR v_count IN 0..jsonb_array_length(v_batch.plans)-1 LOOP
   v_plan:=v_batch.plans->v_count;
   v_item:=v_batch.result->'items'->v_count;
   v_key:=private.taxonomy_normalize_v1(v_item->>'service');
   v_mode:=v_item->>'mode';
   IF v_plan->>'mode' IS DISTINCT FROM v_mode
     OR private.taxonomy_normalize_v1(v_plan->>'service') IS DISTINCT FROM v_key
     OR v_plan->>'action' NOT IN ('REUSE_EXISTING','EXTEND_MODE','CREATE_CHILD','CREATE_NEW_BRANCH')
     OR v_mode NOT IN ('ON_SITE','REMOTE')
     OR jsonb_typeof(v_item->'categoryId')<>'string'
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_skills) offered(value)
       WHERE private.taxonomy_normalize_v1(offered.value#>>'{}')=v_key)
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(
        v_review.envelope->'reviewedServiceModes') m(value)
       WHERE private.taxonomy_normalize_v1(m.value->>'service')=v_key
         AND m.value->>'mode'=v_mode)
     OR v_key||'|'||v_mode=ANY(v_seen)
   THEN RAISE EXCEPTION 'WORKER_BINDER_SERVICE_OR_MODE_NOT_REVIEWED' USING errcode='42501'; END IF;
   v_seen:=array_append(v_seen,v_key||'|'||v_mode);
   v_category:=(v_item->>'categoryId')::uuid;
   IF NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
      JOIN private.work_taxonomy_category_modes cm ON cm.category_id=c.id
      WHERE c.id=v_category AND c.state='ESTABLISHED'
        AND cm.execution_scope=v_mode
        AND (c.canonical_key=v_key OR EXISTS(
          SELECT 1 FROM private.work_taxonomy_aliases a
          WHERE a.category_id=c.id AND a.normalized_key=v_key)))
   THEN RAISE EXCEPTION 'WORKER_BINDER_CATEGORY_STALE' USING errcode='42501'; END IF;
   -- A past withdrawal (excluded=true) is NOT permanent: the owner may
   -- deliberately offer this service again in a NEW signed Save. ONLY this
   -- binder may restore it, with zero inherited related-offer consent.
   IF v_mode='ON_SITE' THEN v_onsite:=true; ELSE v_remote:=true; END IF;
 END LOOP;
 -- A recent explicit global-mode change must not be overwritten by a delayed
 -- binder from an older review. All updates below are ONE DB transaction.
 IF EXISTS(SELECT 1 FROM private.worker_execution_mode_choices choice
   WHERE choice.worker_profile_id=p_profile_id AND choice.updated_at>v_save.created_at)
 THEN RAISE EXCEPTION 'WORKER_BINDER_NEWER_GLOBAL_MODE' USING errcode='PT409'; END IF;
 IF v_onsite THEN v_modes:=array_append(v_modes,'ON_SITE'); END IF;
 IF v_remote THEN v_modes:=array_append(v_modes,'REMOTE'); END IF;
 INSERT INTO private.worker_execution_mode_choices(
   worker_profile_id,worker_account_id,modes,consent_source,confirmed_at,updated_at)
 VALUES(p_profile_id,p_owner_account_id,v_modes,'EXPLICIT_PROFILE_REVIEW',
   statement_timestamp(),statement_timestamp())
 ON CONFLICT(worker_profile_id) DO UPDATE
   SET modes=excluded.modes,consent_source='EXPLICIT_PROFILE_REVIEW',
       confirmed_at=statement_timestamp(),updated_at=statement_timestamp();
 -- Catalog identities and per-service scope are granted only AFTER the
 -- signed review, saved receipt and current profile all passed.
 FOR v_count IN 0..jsonb_array_length(v_batch.plans)-1 LOOP
   v_item:=v_batch.result->'items'->v_count;
   v_category:=(v_item->>'categoryId')::uuid;v_mode:=v_item->>'mode';
   INSERT INTO private.work_taxonomy_worker_capabilities(
      worker_account_id,category_id,confirmed_at,allow_related_offers,excluded,origin)
   VALUES(p_owner_account_id,v_category,statement_timestamp(),false,false,'WORKER_CONFIRMED')
   ON CONFLICT(worker_account_id,category_id) DO UPDATE
     SET confirmed_at=statement_timestamp(),updated_at=statement_timestamp(),
         excluded=false,allow_related_offers=false,origin='WORKER_CONFIRMED';
   INSERT INTO private.taxonomy_confirmed_worker_modes_v1(
     worker_account_id,category_id,execution_scope,source_review_id,source_request_key,
     confirmed_at,active,handoff)
   VALUES(p_owner_account_id,v_category,v_mode,p_source_review_id,p_request_key,
     statement_timestamp(),true,v_batch.plans->v_count->'handoff')
   ON CONFLICT(worker_account_id,category_id,execution_scope) DO UPDATE
    SET source_review_id=excluded.source_review_id,
        source_request_key=excluded.source_request_key,
        confirmed_at=statement_timestamp(),active=true,handoff=excluded.handoff;
 END LOOP;
 -- The CURRENT complete review replaces old per-service permission. Retain
 -- history, but deactivate obsolete modes; never manufacture a related opt-in.
 UPDATE private.taxonomy_confirmed_worker_modes_v1 old
 SET active=false
 WHERE old.worker_account_id=p_owner_account_id AND old.active
   AND NOT EXISTS(
     SELECT 1 FROM jsonb_array_elements(v_batch.result->'items') item(value)
     WHERE (item.value->>'categoryId')::uuid=old.category_id
       AND item.value->>'mode'=old.execution_scope);
 v_result:=jsonb_build_object('status','BOUND_WORKER_SERVICES',
   'workerProfileId',p_profile_id,'serviceModeCount',jsonb_array_length(v_batch.plans),
   'catalogVersion',v_batch.catalog_version,'dispatchAuthority','NONE',
   'notificationAuthority','NONE','relatedOfferAuthority','NONE');
 INSERT INTO private.work_taxonomy_worker_bindings_v1(
   owner_account_id,request_key,source_review_id,profile_id,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_source_review_id,p_profile_id,
   v_batch.catalog_version,v_result);
 RETURN v_result;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_capture_gemini_turn_hints_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_turn_id uuid, p_attempt_id uuid, p_purpose text, p_catalog_version bigint, p_proposals jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_source text;v_digest text;v_existing private.work_taxonomy_gemini_turn_hints_v1%ROWTYPE;
 v_row jsonb;v_count integer;v_seen text[]:=ARRAY[]::text[];v_normalized text;
BEGIN
 PERFORM private.closure_assert_open(p_account_id);
 -- Definer privileges alone are not authorization; require the actual JWT role.
 IF coalesce(auth.jwt()->>'role','') <> 'service_role' THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_DENIED' USING errcode='42501';
 END IF;
 IF p_account_id IS NULL OR p_conversation_id IS NULL OR
    p_client_request_id IS NULL OR p_turn_id IS NULL OR p_attempt_id IS NULL OR
    p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE') OR
    coalesce(p_catalog_version,0) < 1 OR
    jsonb_typeof(p_proposals) IS DISTINCT FROM 'array' OR
    pg_column_size(p_proposals)>18000 THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_INVALID' USING errcode='22023';
 END IF;
 v_count:=jsonb_array_length(p_proposals);
 IF (p_purpose='WORKER_CAPABILITY' AND v_count NOT BETWEEN 1 AND 24)
    OR (p_purpose='NEED_SERVICE' AND v_count NOT BETWEEN 1 AND 6) THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_INVALID' USING errcode='22023';
 END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_proposals) LOOP
   IF jsonb_typeof(v_row)<>'object'
      OR NOT (v_row ?& array['service','mode','action','categoryId','parentId','proposedPath','reason','catalogVersion'])
      OR (v_row-array['service','mode','action','categoryId','parentId','proposedPath','reason','catalogVersion','handoff'])<>'{}'::jsonb
      OR (v_row?'handoff' AND (v_row->>'mode'<>'REMOTE'
          OR NOT private.taxonomy_handoff_valid_v1(v_row->'handoff')))
      OR jsonb_typeof(v_row->'service') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'reason') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'mode') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'action') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'categoryId') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'parentId') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'catalogVersion') IS DISTINCT FROM 'number'
      OR char_length(btrim(v_row->>'service')) NOT BETWEEN 3 AND 120
      OR char_length(btrim(v_row->>'reason')) NOT BETWEEN 10 AND 1000
      OR v_row->>'mode' NOT IN ('REMOTE','ON_SITE')
      OR v_row->>'action' NOT IN ('REUSE_EXISTING','EXTEND_MODE','CREATE_CHILD','CREATE_NEW_BRANCH')
      OR (v_row->>'catalogVersion')::bigint IS DISTINCT FROM p_catalog_version
      OR jsonb_typeof(v_row->'proposedPath')<>'array'
      OR (v_row->>'action' IN ('REUSE_EXISTING','EXTEND_MODE') AND
          (v_row->>'categoryId' IS NULL OR v_row->>'categoryId'=''
           OR v_row->>'parentId'<>'' OR jsonb_array_length(v_row->'proposedPath')<>0))
      OR (v_row->>'action'='CREATE_CHILD' AND
          (v_row->>'categoryId'<>'' OR v_row->>'parentId' IS NULL
           OR v_row->>'parentId'='' OR jsonb_array_length(v_row->'proposedPath')<1))
      OR (v_row->>'action'='CREATE_NEW_BRANCH' AND
          (v_row->>'categoryId'<>'' OR v_row->>'parentId'<>''
           OR jsonb_array_length(v_row->'proposedPath')<1))
   THEN RAISE EXCEPTION 'TAXONOMY_CAPTURE_PLAN_INVALID' USING errcode='22023'; END IF;
   -- Identity duplicates cannot be used to smuggle another mode/service.
   -- The canonical normalizer collapses Serbian Cyrillic/Latin variants.
   v_normalized:=private.taxonomy_normalize_v1(v_row->>'service');
   IF p_purpose='WORKER_CAPABILITY' THEN v_normalized:=v_normalized||'|'||(v_row->>'mode'); END IF;
   IF v_normalized IS NULL OR char_length(v_normalized)<3 OR v_normalized=ANY(v_seen) THEN
     RAISE EXCEPTION 'TAXONOMY_CAPTURE_DUPLICATE_OR_INVALID_SERVICE' USING errcode='22023';
   END IF;
   v_seen:=array_append(v_seen,v_normalized);
 END LOOP;

 -- Only a DURABLY COMPLETED turn with the exact owner/attempt identity
 -- can produce a hint. A claimed/failed/cancelled or forged turn cannot.
 IF p_purpose='WORKER_CAPABILITY' THEN
   -- Completion takes this same lock before revision + 1. Hold it until the
   -- hint is inserted so a later completion cannot lend its source hash to
   -- an older succeeded turn.
   PERFORM 1 FROM private.worker_ai_sessions
    WHERE account_id=p_account_id AND conversation_id=p_conversation_id FOR UPDATE;
   SELECT encode(extensions.digest(
     convert_to(s.candidate::text||'|'||s.revision::text||'|'||s.base_hash,'UTF8'),'sha256'),'hex')
   INTO v_source
   FROM private.worker_ai_turns t
   JOIN private.worker_ai_sessions s
     ON s.account_id=t.account_id AND s.conversation_id=t.conversation_id
   WHERE t.account_id=p_account_id AND t.conversation_id=p_conversation_id
     AND t.client_request_id=p_client_request_id
     AND t.turn_id=p_turn_id AND t.attempt_id=p_attempt_id
     AND t.state='SUCCEEDED' AND t.cancelled_at IS NULL
     AND t.completion_hash ~ '^[0-9a-f]{64}$'
     AND t.source_revision+1=s.revision;
 ELSE
   -- Need completion serializes on the owned conversation. Its durable
   -- receipt names the assistant message produced by that exact completion.
   -- Refuse a late capture after another turn/message, or during a new turn.
   PERFORM 1 FROM public.ai_conversations
    WHERE id=p_conversation_id AND account_id=p_account_id FOR UPDATE;
   SELECT encode(extensions.digest(private.ai_task_review_source(c.id)::text,'sha256'),'hex')
   INTO v_source
   FROM private.ai_need_turn_commands t
   JOIN public.ai_conversations c ON c.id=t.conversation_id
   JOIN public.ai_messages message ON message.conversation_id=c.id
     AND message.account_id=p_account_id AND message.role='ASSISTANT'
     AND message.id::text=t.receipt->>'assistantMessageId'
   WHERE t.account_id=p_account_id AND t.conversation_id=p_conversation_id
     AND t.client_request_id=p_client_request_id
     AND t.turn_id=p_turn_id AND t.attempt_id=p_attempt_id
     AND t.state='SUCCEEDED' AND t.cancelled_at IS NULL AND c.account_id=p_account_id
     AND c.purpose='NEED_INTAKE'
     AND t.receipt->'authoritative'='true'::jsonb
     AND t.receipt->>'schemaVersion'='NEED_FACT_V2'
     AND NOT EXISTS(SELECT 1 FROM public.ai_messages newer
       WHERE newer.conversation_id=c.id AND newer.sequence_no>message.sequence_no)
     AND NOT EXISTS(SELECT 1 FROM private.ai_need_turn_commands newer
       WHERE newer.conversation_id=c.id AND newer.account_id=p_account_id
         AND (newer.state='PROCESSING' OR
           (newer.state='SUCCEEDED' AND newer.updated_at>t.updated_at)));
 END IF;
 IF v_source IS NULL THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_TURN_UNCONFIRMED' USING errcode='42501';
 END IF;
 -- A succeeded LLM turn is NOT proof that any named service is in the current
 -- worker profile. The candidate's saved skills must contain every proposed
 -- service now, including after a later correction/removal in the same turn.
 -- A partial set is permitted as an untrusted hint, but the eventual owner
 -- review will refuse READY unless it covers ALL current services.
 IF p_purpose='WORKER_CAPABILITY' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_proposals) proposal(value)
    WHERE NOT EXISTS(
      SELECT 1 FROM private.worker_ai_sessions s,
        LATERAL jsonb_array_elements_text(s.candidate->'skills') offered(skill)
      WHERE s.account_id=p_account_id AND s.conversation_id=p_conversation_id
        AND private.taxonomy_normalize_v1(offered.skill)=
            private.taxonomy_normalize_v1(proposal.value->>'service')
    )
 ) THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_WORKER_SERVICE_NOT_OFFERED' USING errcode='22023';
 END IF;
 v_digest:=encode(extensions.digest(p_proposals::text,'sha256'),'hex');
 INSERT INTO private.work_taxonomy_gemini_turn_hints_v1(
   purpose,account_id,conversation_id,client_request_id,turn_id,attempt_id,
   source_fingerprint,catalog_version,proposals,payload_digest)
 VALUES(p_purpose,p_account_id,p_conversation_id,p_client_request_id,
   p_turn_id,p_attempt_id,v_source,p_catalog_version,p_proposals,v_digest)
 ON CONFLICT(purpose,account_id,turn_id) DO NOTHING;
 SELECT * INTO v_existing FROM private.work_taxonomy_gemini_turn_hints_v1
   WHERE purpose=p_purpose AND account_id=p_account_id AND turn_id=p_turn_id;
 IF NOT FOUND OR v_existing.client_request_id<>p_client_request_id
   OR v_existing.attempt_id<>p_attempt_id
   OR v_existing.conversation_id<>p_conversation_id
   OR v_existing.source_fingerprint<>v_source
   OR v_existing.catalog_version<>p_catalog_version
   OR v_existing.payload_digest<>v_digest
   OR v_existing.proposals IS DISTINCT FROM p_proposals THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_REPLAY_CONFLICT' USING errcode='22023';
 END IF;
 RETURN jsonb_build_object('action','HINT_CAPTURED','authority','NONE');
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_claim_reviewed_batches_service(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_docs jsonb;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 20 THEN
  RAISE EXCEPTION 'OUTBOX_CLAIM_LIMIT_INVALID' USING errcode='22023'; END IF;
 WITH candidates AS MATERIALIZED (
  SELECT id,owner_account_id FROM private.work_taxonomy_review_outbox_v1
  WHERE NOT private.closure_account_restricted(owner_account_id) AND ((state IN ('PENDING','RETRY') AND retry_after<=statement_timestamp())
     OR (state='CLAIMED' AND lease_until<statement_timestamp()))
  ORDER BY created_at,id LIMIT p_limit
 ), admitted AS MATERIALIZED (SELECT id FROM candidates WHERE private.closure_taxonomy_try_owner_v1(owner_account_id)),
 selected AS (SELECT q.id FROM private.work_taxonomy_review_outbox_v1 q JOIN admitted a ON a.id=q.id WHERE (q.state IN ('PENDING','RETRY') AND q.retry_after<=statement_timestamp()) OR (q.state='CLAIMED' AND q.lease_until<statement_timestamp()) FOR UPDATE OF q SKIP LOCKED),
 claimed AS (
  UPDATE private.work_taxonomy_review_outbox_v1 q
   SET state='CLAIMED',attempts=q.attempts+1,
       lease_token=gen_random_uuid(),lease_until=statement_timestamp()+interval '2 minutes',
       updated_at=statement_timestamp()
   FROM selected s WHERE q.id=s.id
   RETURNING q.id,q.owner_account_id,q.request_key,q.source_review_id,
    q.purpose,q.plans,q.lease_token,q.attempts
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id',id,'ownerAccountId',owner_account_id,'requestKey',request_key,
  'sourceReviewId',source_review_id,'purpose',purpose,'plans',plans,
  'leaseToken',lease_token,'attempts',attempts) ORDER BY id),'[]'::jsonb)
 INTO v_docs FROM claimed;
 RETURN v_docs;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_commit_admission_service(p_admission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_admissions_v1%ROWTYPE;v_version bigint;
 v_action text;v_mode text;v_parent uuid;v_id uuid;v_label text;v_key text;
 v_existing_parent uuid;v_scope_exists boolean;v_added integer:=0;v_receipt jsonb;
 i integer;v_node_count integer;
BEGIN
 PERFORM private.closure_assert_open(owner_account_id) FROM private.work_taxonomy_admissions_v1 WHERE id=p_admission_id;
 SELECT * INTO v FROM private.work_taxonomy_admissions_v1 WHERE id=p_admission_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_NOT_FOUND' USING errcode='22023'; END IF;
 IF v.status='COMMITTED' THEN RETURN v.result; END IF;
 IF v.plan_digest IS DISTINCT FROM
    encode(extensions.digest(convert_to(v.plan::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'ADMISSION_PLAN_TAMPERED' USING errcode='42501'; END IF;
 IF v.status<>'APPROVED' OR v.approved_at IS NULL THEN
  RAISE EXCEPTION 'ADMISSION_OWNER_APPROVAL_REQUIRED' USING errcode='42501'; END IF;
 IF v.expires_at<=statement_timestamp() THEN RAISE EXCEPTION 'ADMISSION_EXPIRED'; END IF;
 -- Serialize admission writers. Old unsafe writers must be retired before live enable.
 SELECT catalog_version INTO v_version
  FROM private.work_taxonomy_control WHERE singleton FOR UPDATE;
 IF v_version<>v.catalog_version OR
    private.taxonomy_admission_fingerprint_v1()<>v.catalog_fingerprint THEN
  RAISE EXCEPTION 'ADMISSION_STALE_CATALOG_REPLAN' USING errcode='PT409'; END IF;
 v_action:=v.plan->>'action';v_mode:=v.plan->>'mode';
 IF v_action='REUSE_EXISTING' THEN
  v_id:=(v.plan->>'categoryId')::uuid;
  PERFORM 1 FROM private.work_taxonomy_categories c
    JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
    WHERE c.id=v_id AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_CATEGORY_CHANGED'; END IF;
 ELSE
  IF v_action<>'CREATE_CHILD' OR jsonb_typeof(v.plan->'path')<>'array' THEN
    RAISE EXCEPTION 'ADMISSION_ACTION_UNSUPPORTED'; END IF;
  v_parent:=(v.plan->>'parentId')::uuid;
  v_node_count:=jsonb_array_length(v.plan->'path');
  IF v_node_count<1 OR pg_column_size(v.plan)>12000 THEN RAISE EXCEPTION 'ADMISSION_PATH_INVALID'; END IF;
  PERFORM 1 FROM private.work_taxonomy_categories c
   WHERE c.id=v_parent AND c.state='ESTABLISHED'
     AND private.taxonomy_category_path_valid_v1(c.id);
  IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_PARENT_CHANGED'; END IF;
  IF private.taxonomy_risk_triage_v1(v.plan->'path'->>(v_node_count-1))
     <> 'LOW_RISK_CANDIDATE' THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED'; END IF;
  FOR i IN 0..v_node_count-1 LOOP
   v_label:=btrim(v.plan->'path'->>i);
   IF jsonb_typeof(v.plan->'path'->i) IS DISTINCT FROM 'string'
      OR char_length(v_label) NOT BETWEEN 3 AND 120
      OR v_label ~ '[<>{}\\]' OR v_label ~ '[[:cntrl:]]' THEN
      RAISE EXCEPTION 'ADMISSION_NODE_INVALID' USING errcode='22023'; END IF;
   IF private.taxonomy_risk_triage_v1(v_label) IN ('BLOCKED','REVIEW_REQUIRED') THEN
     RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
   v_key:=private.taxonomy_normalize_v1(v_label);
   IF char_length(v_key) NOT BETWEEN 3 AND 160 OR v_key !~ '[[:alpha:]]' THEN
      RAISE EXCEPTION 'ADMISSION_NORMALIZATION_INVALID'; END IF;
   IF EXISTS (SELECT 1 FROM private.work_taxonomy_aliases a
     WHERE a.normalized_key=v_key) THEN
     RAISE EXCEPTION 'ADMISSION_ALIAS_COLLISION_REVIEW_REQUIRED'; END IF;
   v_id:=NULL;
   SELECT c.id,c.parent_id INTO v_id,v_existing_parent
   FROM private.work_taxonomy_categories c WHERE c.canonical_key=v_key
   FOR UPDATE;
   IF FOUND THEN
    IF v_existing_parent IS DISTINCT FROM v_parent
       OR NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories WHERE id=v_id AND state='ESTABLISHED')
       OR (i=v_node_count-1 AND NOT EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes
        WHERE category_id=v_id AND execution_scope=v_mode)) THEN
      RAISE EXCEPTION 'ADMISSION_MEANING_OR_MODE_COLLISION_REVIEW_REQUIRED'; END IF;
   ELSE
    UPDATE private.work_taxonomy_control
      SET catalog_version=catalog_version+1,updated_at=statement_timestamp()
      WHERE singleton RETURNING catalog_version INTO v_version;
    INSERT INTO private.work_taxonomy_categories
      (canonical_key,label,parent_id,state,source,catalog_version)
    VALUES(v_key,v_label,v_parent,'ESTABLISHED','AI_REVIEWED',v_version)
    RETURNING id INTO v_id;
    INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
     VALUES(v_id,v_mode,'OWNER_APPROVED_ADMISSION_V1');
    INSERT INTO private.work_taxonomy_audit
      (action,category_id,normalized_key,catalog_version,source_ref)
    VALUES('AUTO_CREATED',v_id,v_key,v_version,'OWNER_APPROVED_ADMISSION_V1:'||v.id::text);
    v_added:=v_added+1;
   END IF;
   v_parent:=v_id;
  END LOOP;
 END IF;
 v_receipt:=jsonb_build_object('admissionId',v.id,'categoryId',v_id,
   'catalogVersion',v_version,'createdCount',v_added,'status','COMMITTED',
   'capabilityAuthority','NONE','notificationAuthority','NONE',
   'requiresPostSaveBinding',true);
 UPDATE private.work_taxonomy_admissions_v1
  SET status='COMMITTED',committed_at=statement_timestamp(),result=v_receipt
  WHERE id=v.id;
 RETURN v_receipt;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_commit_reviewed_batch_service(p_owner_account_id uuid, p_request_key uuid, p_purpose text, p_source_review_id uuid, p_plans jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_id uuid;v_old private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review jsonb;v_review_digest text;v_computed_digest text;
 v_expiry timestamptz;v_saved_at timestamptz;v_review_fingerprint text;
 v_version bigint;v_review_version bigint;v_fingerprint text;v_plans_digest text;
 v_catalog_changed boolean;
 v_plan jsonb;v_service text;v_mode text;v_action text;
 v_parent uuid;v_category uuid;v_canonical uuid;v_current_parent uuid;
 v_label text;v_key text;v_ref text;v_count integer;v_created integer:=0;
 v_index integer;v_step integer;v_duplicate text;
 v_seen_services text[]:=ARRAY[]::text[];
 v_seen_targets text[]:=ARRAY[]::text[];
 v_created_ids uuid[]:=ARRAY[]::uuid[];
 v_bound boolean;v_visible_mode boolean;v_found boolean;
 v_items jsonb:='[]'::jsonb;v_result jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
    OR p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE')
    OR jsonb_typeof(p_plans)<>'array'
    OR (p_purpose='WORKER_CAPABILITY' AND jsonb_array_length(p_plans) NOT BETWEEN 1 AND 24)
    OR (p_purpose='NEED_SERVICE' AND jsonb_array_length(p_plans)<>1)
    OR pg_column_size(p_plans)>16000
 THEN RAISE EXCEPTION 'BATCH_INPUT_INVALID' USING errcode='22023'; END IF;
 v_plans_digest:=encode(extensions.digest(convert_to(p_plans::text,'UTF8'),'sha256'),'hex');

 -- A replay returns its ORIGINAL receipt even if later unrelated catalog writes
 -- changed the control version. Reuse of a key for another user review fails.
 SELECT * INTO v_old FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
  IF v_old.purpose<>p_purpose OR v_old.source_review_id<>p_source_review_id
    OR v_old.plans_digest<>v_plans_digest OR v_old.plans IS DISTINCT FROM p_plans
  THEN RAISE EXCEPTION 'BATCH_REQUEST_KEY_REUSED' USING errcode='22023'; END IF;
  RETURN v_old.result;
 END IF;

 IF p_purpose='WORKER_CAPABILITY' THEN
  SELECT w.envelope,w.envelope->>'displayedContentDigest',w.expires_at,
   encode(extensions.digest(((w.envelope-'displayedContentDigest')
     ||jsonb_build_object('baseHash',w.base_hash))::text,'sha256'),'hex')
    INTO v_review,v_review_digest,v_expiry,v_computed_digest
   FROM private.worker_ai_reviews w
   WHERE w.id=p_source_review_id AND w.account_id=p_owner_account_id FOR SHARE;
  SELECT min(s.created_at) INTO v_saved_at FROM private.worker_ai_saves s
    WHERE s.review_id=p_source_review_id AND s.account_id=p_owner_account_id
      AND s.client_request_id=p_request_key;
  v_bound:=v_saved_at IS NOT NULL;
 ELSE
  SELECT t.envelope,t.envelope->>'displayedContentDigest',t.expires_at,
   encode(extensions.digest(jsonb_build_object('envelope',
     t.envelope-'displayedContentDigest','policy',t.policy_binding)::text,'sha256'),'hex')
    INTO v_review,v_review_digest,v_expiry,v_computed_digest
   FROM private.ai_task_reviews t
   WHERE t.id=p_source_review_id AND t.account_id=p_owner_account_id FOR SHARE;
  SELECT min(c.created_at) INTO v_saved_at FROM private.ai_task_review_commands c
    WHERE c.review_id=p_source_review_id AND c.account_id=p_owner_account_id
      AND c.client_request_id=p_request_key
      AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED');
  v_bound:=v_saved_at IS NOT NULL;
 END IF;
 IF NOT coalesce(v_bound,false) THEN
  RAISE EXCEPTION 'BATCH_EXISTING_USER_SAVE_REQUIRED' USING errcode='42501'; END IF;
 -- Approval must have happened WHILE the review was valid.
 -- Outbox retries may run later; expiring the review AFTER a successful human
 -- Save/Accept must not silently discard a confirmed service.
 IF v_review IS NULL OR v_review->'canAccept' IS DISTINCT FROM 'true'::jsonb
    OR v_saved_at>v_expiry OR v_review_digest IS NULL
    OR v_review_digest !~ '^[0-9a-f]{64}$'
    OR v_computed_digest IS DISTINCT FROM v_review_digest
    OR v_review->'classificationCandidates' IS DISTINCT FROM p_plans
 THEN RAISE EXCEPTION 'BATCH_REVIEW_NOT_BOUND' USING errcode='42501'; END IF;
 v_review_fingerprint:=v_review->>'classificationCatalogFingerprint';
 IF v_review_fingerprint IS NULL OR
    v_review_fingerprint !~ '^[0-9a-f]{32}$' THEN
   RAISE EXCEPTION 'BATCH_CATALOG_FINGERPRINT_REQUIRED' USING errcode='42501'; END IF;

 -- Single serialized admission pass: intermediate catalog bumps do NOT make
 -- later items in the SAME reviewed batch stale.
 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control
  WHERE singleton FOR UPDATE;
 IF v_version IS NULL THEN RAISE EXCEPTION 'BATCH_CATALOG_MISSING'; END IF;
 -- The immutable signed plan keeps its original version. A successful Save
 -- remains authority after an unrelated catalog write, but every identity,
 -- mode and path below must still validate against the locked CURRENT catalog.
 -- Never rewrite the review, its fingerprint or the reviewed semantic plan.
 IF jsonb_typeof(v_review->'classificationCatalogVersion') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'BATCH_REVIEW_CATALOG_VERSION_INVALID' USING errcode='42501'; END IF;
 v_review_version:=(v_review->>'classificationCatalogVersion')::bigint;
 v_fingerprint:=private.taxonomy_admission_fingerprint_v1();
 IF v_review_version<1 OR v_version<v_review_version OR v_fingerprint IS NULL THEN
   RAISE EXCEPTION 'BATCH_STALE_CATALOG' USING errcode='PT409'; END IF;
 v_catalog_changed:=v_fingerprint IS DISTINCT FROM v_review_fingerprint
   OR v_version IS DISTINCT FROM v_review_version;
 FOR v_index IN 0..jsonb_array_length(p_plans)-1 LOOP
  v_plan:=p_plans->v_index;
  IF jsonb_typeof(v_plan)<>'object'
     OR v_plan ?& array['action','service','mode','catalogVersion','reason'] IS NOT TRUE
     OR jsonb_typeof(v_plan->'catalogVersion')<>'number'
     OR (v_plan->>'catalogVersion')::bigint<> (v_review->>'classificationCatalogVersion')::bigint
     OR (v_plan->>'catalogVersion')::bigint<>v_review_version
     OR jsonb_typeof(v_plan->'reason')<>'string'
     OR char_length(btrim(v_plan->>'reason')) NOT BETWEEN 10 AND 1000
  THEN RAISE EXCEPTION 'BATCH_INVALID_OR_STALE_PLAN' USING errcode='22023'; END IF;
  v_service:=btrim(v_plan->>'service');
  v_mode:=v_plan->>'mode';
  v_action:=v_plan->>'action';
  IF char_length(v_service) NOT BETWEEN 3 AND 120 OR
     v_mode NOT IN ('ON_SITE','REMOTE') OR
     v_action NOT IN ('REUSE_EXISTING','EXTEND_MODE','CREATE_CHILD','CREATE_NEW_BRANCH')
  THEN RAISE EXCEPTION 'BATCH_SCOPE_OR_SERVICE_INVALID' USING errcode='22023'; END IF;
  IF v_plan?'handoff' AND (v_mode<>'REMOTE'
     OR NOT private.taxonomy_handoff_valid_v1(v_plan->'handoff')) THEN
    RAISE EXCEPTION 'BATCH_HANDOFF_INVALID' USING errcode='22023'; END IF;
  v_key:=private.taxonomy_normalize_v1(v_service);
  v_duplicate:=v_key||'|'||v_mode;
  IF v_duplicate=ANY(v_seen_services) THEN
   RAISE EXCEPTION 'BATCH_DUPLICATE_SERVICE' USING errcode='22023'; END IF;
  v_seen_services:=array_append(v_seen_services,v_duplicate);

  -- Require the service to be a HUMAN-REVIEWED meaning in the existing
  -- profile/need content. A model may not add undeclared worker skills.
  IF p_purpose='WORKER_CAPABILITY' THEN
    v_found:=EXISTS(SELECT 1 FROM jsonb_array_elements_text(
       coalesce(v_review#>'{profile,skills}','[]'::jsonb)) x(service)
       WHERE private.taxonomy_normalize_v1(x.service)=v_key);
    v_visible_mode:=EXISTS(SELECT 1 FROM jsonb_array_elements(
      coalesce(v_review->'reviewedServiceModes','[]'::jsonb)) x(item)
       WHERE private.taxonomy_normalize_v1(x.item->>'service')=v_key
         AND x.item->>'mode'=v_mode);
  ELSE
    v_found:=EXISTS(SELECT 1 FROM jsonb_array_elements(
       coalesce(v_review->'publicProjection','[]'::jsonb)) x(fact)
       WHERE x.fact->>'key'='need.category'
         AND private.taxonomy_normalize_v1(x.fact->>'value')=v_key);
    v_visible_mode:=(CASE v_review#>>'{location,geography,mode}'
      WHEN 'REMOTE' THEN 'REMOTE'
      WHEN 'STATIONARY' THEN 'ON_SITE'
      WHEN 'POINT_TO_POINT' THEN 'ON_SITE'
      WHEN 'MULTI_STOP' THEN 'ON_SITE'
      WHEN 'AREA_BASED' THEN 'ON_SITE'
      ELSE 'UNCONFIRMED' END)=v_mode;
  END IF;
  IF NOT coalesce(v_found,false) OR NOT coalesce(v_visible_mode,false)
   THEN RAISE EXCEPTION 'BATCH_SERVICE_OR_MODE_NOT_REVIEWED' USING errcode='42501'; END IF;

  IF v_action IN ('REUSE_EXISTING','EXTEND_MODE') THEN
   IF (v_plan->>'categoryId') IS NULL OR
      v_plan ? 'parentId' OR v_plan ? 'path' THEN
    RAISE EXCEPTION 'BATCH_REUSE_STRUCTURE_INVALID' USING errcode='22023'; END IF;
   v_category:=(v_plan->>'categoryId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
    WHERE c.id=v_category AND c.state='ESTABLISHED'
      AND (v_action='EXTEND_MODE' OR EXISTS(
        SELECT 1 FROM private.work_taxonomy_category_modes m
        WHERE m.category_id=c.id AND m.execution_scope=v_mode));
   IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_CATEGORY_OR_MODE_MISSING' USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '22023' END; END IF;
   -- A model-provided existing ID cannot change the actual meaning of
   -- a human-reviewed service. Only a canonical name or STORED alias qualifies.
   SELECT count(DISTINCT c.id),min(c.id::text)::uuid INTO v_count,v_canonical
     FROM private.work_taxonomy_categories c
     WHERE c.state<>'RETIRED' AND (c.canonical_key=v_key OR EXISTS (
       SELECT 1 FROM private.work_taxonomy_aliases a
       WHERE a.category_id=c.id AND a.normalized_key=v_key));
   IF v_count<>1 OR v_canonical IS DISTINCT FROM v_category THEN
     RAISE EXCEPTION 'BATCH_SEMANTIC_IDENTITY_MISMATCH'
       USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '42501' END;
   END IF;
   IF v_action='EXTEND_MODE' THEN
     IF jsonb_typeof(v_plan->'categoryLabel') IS DISTINCT FROM 'string'
       OR NOT(v_plan?'categoryParentId')
       OR NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
         WHERE c.id=v_category AND c.label IS NOT DISTINCT FROM v_plan->>'categoryLabel'
           AND coalesce(to_jsonb(c.parent_id),'null'::jsonb) IS NOT DISTINCT FROM v_plan->'categoryParentId')
       OR NOT private.taxonomy_category_path_valid_v1(v_category) THEN
       RAISE EXCEPTION 'BATCH_EXTENSION_IDENTITY_CHANGED' USING errcode='PT409'; END IF;
     -- SQL screens risk and signed identity; it does not prove physical
     -- feasibility. The captured AI reason + visible owner review are retained.
     IF private.taxonomy_risk_triage_v1(v_service) IS DISTINCT FROM 'LOW_RISK_CANDIDATE'
       OR private.taxonomy_risk_triage_v1(v_plan->>'categoryLabel') IS DISTINCT FROM 'LOW_RISK_CANDIDATE' THEN
       RAISE EXCEPTION 'BATCH_EXTENSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
     IF NOT EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes
       WHERE category_id=v_category AND execution_scope=v_mode) THEN
       UPDATE private.work_taxonomy_control
         SET catalog_version=catalog_version+1,updated_at=statement_timestamp()
         WHERE singleton RETURNING catalog_version INTO v_version;
       INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
         VALUES(v_category,v_mode,'REVIEWED_MODE_EXTENSION_V1');
       INSERT INTO private.work_taxonomy_audit(action,category_id,normalized_key,catalog_version,source_ref)
         VALUES('CORRECTED',v_category,private.taxonomy_normalize_v1(v_plan->>'categoryLabel'),v_version,
           'REVIEWED_MODE_EXTENSION_V1:'||p_request_key::text);
     ELSIF NOT v_catalog_changed THEN
       RAISE EXCEPTION 'BATCH_EXTENSION_MODE_ALREADY_PRESENT' USING errcode='22023';
     END IF;
   END IF;
  ELSE
   IF v_plan ? 'categoryId' OR jsonb_typeof(v_plan->'path')<>'array'
      OR jsonb_array_length(v_plan->'path')<1
      OR (v_action='CREATE_CHILD' AND (v_plan->>'parentId') IS NULL)
      OR (v_action='CREATE_NEW_BRANCH' AND
          (v_plan->'parentId' IS DISTINCT FROM 'null'::jsonb
           OR v_plan->'parentLabel' IS DISTINCT FROM 'null'::jsonb)) THEN
    RAISE EXCEPTION 'BATCH_CHILD_STRUCTURE_INVALID' USING errcode='22023'; END IF;
   -- A newly created leaf must be exactly the reviewed human service meaning.
   IF private.taxonomy_normalize_v1(v_plan->'path'->>(jsonb_array_length(v_plan->'path')-1))
       <>private.taxonomy_normalize_v1(v_service) THEN
      RAISE EXCEPTION 'BATCH_SERVICE_LEAF_MISMATCH' USING errcode='42501'; END IF;
   IF v_action='CREATE_CHILD' THEN
     v_parent:=(v_plan->>'parentId')::uuid;
     PERFORM 1 FROM private.work_taxonomy_categories c
      WHERE c.id=v_parent AND c.state='ESTABLISHED'
        AND private.taxonomy_category_path_valid_v1(c.id);
     IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_PARENT_OR_MODE_MISSING'
       USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '22023' END; END IF;
     -- The signed parent label anchors the reviewed organization as well as UUID.
     IF NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
       WHERE c.id=v_parent AND c.label IS NOT DISTINCT FROM v_plan->>'parentLabel') THEN
       RAISE EXCEPTION 'BATCH_PARENT_IDENTITY_CHANGED' USING errcode='PT409'; END IF;
   ELSE
     v_parent:=NULL;
   END IF;
   FOR v_step IN 0..jsonb_array_length(v_plan->'path')-1 LOOP
    v_label:=btrim(v_plan->'path'->>v_step);
    IF jsonb_typeof(v_plan->'path'->v_step) IS DISTINCT FROM 'string' OR
       char_length(v_label) NOT BETWEEN 3 AND 120 OR
       v_label ~ '[<>{}\\]' OR v_label ~ '[[:cntrl:]]' OR
       private.taxonomy_risk_triage_v1(v_label) IN ('BLOCKED','REVIEW_REQUIRED')
    THEN RAISE EXCEPTION 'BATCH_UNSAFE_CATEGORY' USING errcode='42501'; END IF;
    IF v_step=jsonb_array_length(v_plan->'path')-1 AND
       private.taxonomy_risk_triage_v1(v_label)<>'LOW_RISK_CANDIDATE'
    THEN RAISE EXCEPTION 'BATCH_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
    v_key:=private.taxonomy_normalize_v1(v_label);
    IF char_length(v_key) NOT BETWEEN 3 AND 160 OR v_key !~ '[[:alpha:]]' OR
       EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a
          WHERE a.normalized_key=v_key)
    THEN RAISE EXCEPTION 'BATCH_ALIAS_OR_KEY_COLLISION'
      USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '22023' END; END IF;
    v_category:=NULL;v_current_parent:=NULL;
    SELECT c.id,c.parent_id INTO v_category,v_current_parent
      FROM private.work_taxonomy_categories c WHERE c.canonical_key=v_key
      FOR UPDATE;
    IF FOUND THEN
     IF NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
       WHERE c.id=v_category AND c.state='ESTABLISHED') THEN
       RAISE EXCEPTION 'BATCH_PATH_CATEGORY_RETIRED' USING errcode='PT409'; END IF;
     IF v_current_parent IS DISTINCT FROM v_parent THEN
       RAISE EXCEPTION 'BATCH_SEMANTIC_OR_MODE_COLLISION'
         USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '22023' END;
     END IF;
     IF v_step=jsonb_array_length(v_plan->'path')-1 AND
       NOT EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes
       WHERE category_id=v_category AND execution_scope=v_mode) THEN
       -- Only nodes born in THIS atomic, owner-signed batch may receive a
       -- second explicitly reviewed scope. Older catalog entries remain closed.
       IF NOT (v_category=ANY(v_created_ids)) THEN
         RAISE EXCEPTION 'BATCH_SEMANTIC_OR_MODE_COLLISION'
         USING errcode=CASE WHEN v_catalog_changed THEN 'PT409' ELSE '22023' END;
       END IF;
       INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
         VALUES(v_category,v_mode,'REVIEWED_BATCH_V1');
     END IF;
    ELSE
     UPDATE private.work_taxonomy_control
      SET catalog_version=catalog_version+1,updated_at=statement_timestamp()
      WHERE singleton RETURNING catalog_version INTO v_version;
     INSERT INTO private.work_taxonomy_categories
       (canonical_key,label,parent_id,state,source,catalog_version)
     VALUES(v_key,v_label,v_parent,'ESTABLISHED','AI_REVIEWED',v_version)
      RETURNING id INTO v_category;
     INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
      VALUES(v_category,v_mode,'REVIEWED_BATCH_V1');
     INSERT INTO private.work_taxonomy_audit
      (action,category_id,normalized_key,catalog_version,source_ref)
      VALUES('AUTO_CREATED',v_category,v_key,v_version,
        'REVIEWED_BATCH_V1:'||p_request_key::text);
     v_created:=v_created+1;
     v_created_ids:=array_append(v_created_ids,v_category);
    END IF;
    v_parent:=v_category;
   END LOOP;
  END IF;
  v_ref:=v_category::text||'|'||v_mode;
  IF v_ref=ANY(v_seen_targets) THEN
    RAISE EXCEPTION 'BATCH_DUPLICATE_CANONICAL_ID' USING errcode='22023'; END IF;
  v_seen_targets:=array_append(v_seen_targets,v_ref);
  v_items:=v_items||jsonb_build_array(jsonb_build_object(
    'service',v_service,'mode',v_mode,'categoryId',v_category));
 END LOOP;
 -- All category changes and ONE receipt share the same DB transaction.
 v_result:=jsonb_build_object('status','COMMITTED','items',v_items,
  'createdCount',v_created,'catalogVersion',v_version,
  'capabilityAuthority','NONE','needRevisionAuthority','NONE',
  'notificationAuthority','NONE','requiresBinding',true);
 INSERT INTO private.work_taxonomy_review_batches_v1
 (owner_account_id,request_key,purpose,source_review_id,review_digest,
  plans_digest,plans,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_purpose,p_source_review_id,
  v_review_digest,v_plans_digest,p_plans,v_version,v_result);
 RETURN v_result;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_consume_turn_hint_revision_service(p_conversation_id uuid, p_draft_revision bigint, p_service text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_count integer;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then
  raise exception 'TAXONOMY_HINT_DENIED' using errcode='42501'; end if;
 if p_conversation_id is null or p_draft_revision is null or p_draft_revision<0 then
  raise exception 'TAXONOMY_HINT_INVALID' using errcode='22023'; end if;
 update private.classification_turn_hints set consumed_at=clock_timestamp()
  where conversation_id=p_conversation_id and draft_revision=p_draft_revision and consumed_at is null
    and (p_service is null or service is not distinct from p_service);
 get diagnostics v_count=row_count;
 return jsonb_build_object('consumed',v_count,'draftRevision',p_draft_revision);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_consume_turn_hint_service(p_conversation_id uuid, p_service text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_count integer;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
  RAISE EXCEPTION 'TAXONOMY_HINT_DENIED' USING errcode='42501'; END IF;
 UPDATE private.classification_turn_hints SET consumed_at=now()
  WHERE conversation_id=p_conversation_id AND consumed_at IS NULL
    AND (p_service IS NULL OR service IS NOT DISTINCT FROM p_service);
 GET DIAGNOSTICS v_count = ROW_COUNT;
 RETURN jsonb_build_object('consumed',v_count);
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_ensure_path_service(p_path text[], p_execution_location_mode text DEFAULT 'STATIONARY'::text, p_related_labels text[] DEFAULT ARRAY[]::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
BEGIN
 RAISE EXCEPTION 'LEGACY_AUTO_CATEGORY_PATH_DISABLED_USE_REVIEWED_ADMISSION'
 USING ERRCODE='42501';
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_fetch_snapshot_v1(p_generation integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
 v_version bigint; v_fingerprint text; v_items jsonb; v_result jsonb;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
  RAISE EXCEPTION 'TAXONOMY_SNAPSHOT_DENIED' USING errcode='42501'; END IF;
 IF p_generation IS DISTINCT FROM 1 THEN
  RAISE EXCEPTION 'TAXONOMY_SNAPSHOT_INVALID' USING errcode='22023'; END IF;
 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control WHERE singleton;
 v_fingerprint:=private.taxonomy_admission_fingerprint_v1();
 IF v_version IS NULL OR v_version<1 OR v_fingerprint IS NULL OR v_fingerprint!~'^[0-9a-f]{32}$' THEN
  RAISE EXCEPTION 'TAXONOMY_SNAPSHOT_CATALOG_UNAVAILABLE' USING errcode='55000'; END IF;

 -- Top-down walk from the roots over ESTABLISHED categories. Ancestry is organisation, not permission to perform a
 -- leaf's mode (the same rule the paged catalogue query states): an item is listed when it has its OWN direct
 -- ON_SITE/REMOTE mode row and an ESTABLISHED chain to a root; ancestors need no mode of their own.
 WITH RECURSIVE modes AS (
   SELECT m.category_id, array_agg(DISTINCT m.execution_scope::text ORDER BY m.execution_scope::text) AS scopes
   FROM private.work_taxonomy_category_modes m
   WHERE m.execution_scope IN('ON_SITE','REMOTE')
   GROUP BY m.category_id
 ), tree(id,label,canonical_key,parent_id,path_labels,path_ids) AS (
   SELECT c.id,c.label,c.canonical_key,c.parent_id,ARRAY[c.label]::text[],ARRAY[c.id]::uuid[]
   FROM private.work_taxonomy_categories c
   WHERE c.state='ESTABLISHED' AND c.parent_id IS NULL
  UNION ALL
   SELECT c.id,c.label,c.canonical_key,c.parent_id,t.path_labels||c.label,t.path_ids||c.id
   FROM tree t
   JOIN private.work_taxonomy_categories c ON c.parent_id=t.id AND c.state='ESTABLISHED'
   WHERE NOT c.id=ANY(t.path_ids)
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object(
   'categoryId',t.id,'label',t.label,'parentId',t.parent_id,
   'aliases',coalesce((SELECT jsonb_agg(a.label ORDER BY a.label COLLATE "C")
      FROM (SELECT DISTINCT al.label FROM private.work_taxonomy_aliases al WHERE al.category_id=t.id) a),'[]'::jsonb),
   'modes',to_jsonb(mo.scopes),
   'path',to_jsonb(t.path_labels),'pathIds',to_jsonb(t.path_ids),
   'isLeaf',NOT EXISTS(SELECT 1 FROM tree ch JOIN modes cm ON cm.category_id=ch.id WHERE ch.parent_id=t.id)
  ) ORDER BY t.canonical_key COLLATE "C",t.id),'[]'::jsonb)
 INTO v_items FROM tree t JOIN modes mo ON mo.category_id=t.id;

 v_result:=jsonb_build_object('schemaVersion','TAXONOMY_CATALOG_SNAPSHOT_V1','generation',1,
  'catalogVersion',v_version,'catalogFingerprint',v_fingerprint,
  'count',jsonb_array_length(v_items),'categories',v_items,
  'classificationAuthority','NONE','capabilityAuthority','NONE','notificationAuthority','NONE');
 IF octet_length(v_result::text)>4194304 THEN
  RAISE EXCEPTION 'TAXONOMY_SNAPSHOT_TOO_LARGE' USING errcode='54000'; END IF;
 RETURN v_result;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_finalize_reviewed_batch_service(p_outbox_id uuid, p_lease_token uuid, p_error_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_review_outbox_v1%ROWTYPE;v_receipt jsonb;
 v_status text;v_retry timestamptz;
BEGIN
 PERFORM private.closure_assert_open(owner_account_id) FROM private.work_taxonomy_review_outbox_v1 WHERE id=p_outbox_id;
 SELECT * INTO v FROM private.work_taxonomy_review_outbox_v1
 WHERE id=p_outbox_id FOR UPDATE;
 IF NOT FOUND OR v.state<>'CLAIMED' OR v.lease_token IS DISTINCT FROM p_lease_token
    OR v.lease_until<=statement_timestamp()
 THEN RAISE EXCEPTION 'OUTBOX_STALE_LEASE' USING errcode='42501'; END IF;
 IF p_error_code IS NULL THEN
  SELECT b.result INTO v_receipt FROM private.work_taxonomy_review_batches_v1 b
  WHERE b.owner_account_id=v.owner_account_id AND b.request_key=v.request_key
    AND b.source_review_id=v.source_review_id AND b.purpose=v.purpose
    AND b.plans IS NOT DISTINCT FROM v.plans;
  IF v_receipt IS NULL OR v_receipt->>'status'<>'COMMITTED' THEN
   RAISE EXCEPTION 'OUTBOX_COMMIT_RECEIPT_MISSING' USING errcode='42501'; END IF;
  v_status:='COMMITTED';v_retry:=statement_timestamp();
 ELSE
  IF p_error_code !~ '^[A-Z][A-Z0-9_]{2,79}$' THEN
   RAISE EXCEPTION 'OUTBOX_ERROR_CODE_INVALID' USING errcode='22023'; END IF;
  -- Invalid/stale semantic plans require re-planning or internal review.
  -- Network/timeouts are retryable without consuming any new owner consent.
  IF p_error_code IN('TIMEOUT','NETWORK_UNAVAILABLE','TEMPORARY_UNAVAILABLE')
    AND v.attempts<5 THEN
   v_status:='RETRY';
   v_retry:=statement_timestamp()+make_interval(secs=>LEAST(1800,15*power(2,LEAST(v.attempts,7)))::integer);
  ELSE
   v_status:='REVIEW_REQUIRED';v_retry:=statement_timestamp();
  END IF;
 END IF;
 UPDATE private.work_taxonomy_review_outbox_v1
 SET state=v_status,lease_token=NULL,lease_until=NULL,retry_after=v_retry,
   error_code=p_error_code,result=v_receipt,updated_at=statement_timestamp()
 WHERE id=v.id;
 RETURN jsonb_build_object('status',v_status,'outboxId',v.id);
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_get_unconsumed_turn_hint_service(p_conversation_id uuid, p_draft_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_row private.classification_turn_hints%rowtype;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then
  raise exception 'TAXONOMY_HINT_DENIED' using errcode='42501'; end if;
 if p_conversation_id is null or p_draft_revision is null or p_draft_revision<0 then
  raise exception 'TAXONOMY_HINT_INVALID' using errcode='22023'; end if;
 if private.classification_conversation_revision_v1(p_conversation_id) is distinct from p_draft_revision then return null; end if;
 select * into v_row from private.classification_turn_hints
  where conversation_id=p_conversation_id and draft_revision=p_draft_revision
    and consumed_at is null and created_at>clock_timestamp()-interval '1 day'
  order by created_at desc,id desc limit 1;
 if not found then return null; end if;
 return jsonb_build_object('conversationId',v_row.conversation_id,'draftRevision',v_row.draft_revision,
  'service',v_row.service,'mode',v_row.mode,'ambiguityPrompt',v_row.ambiguity_prompt,'reason',v_row.reason);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_prepare_admission_service(p_owner_account_id uuid, p_request_key uuid, p_purpose text, p_source_review_id uuid, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_review_digest text;v_expiry timestamptz;v_version bigint;
 v_review_plan jsonb;v_expected_review_digest text;
 v_plan_digest text;v_id uuid;v_existing private.work_taxonomy_admissions_v1%ROWTYPE;
 v_action text;v_mode text;v_parent uuid;v_category uuid;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
 OR p_plan IS NULL OR jsonb_typeof(p_plan)<>'object'
 OR p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE') THEN
  RAISE EXCEPTION 'ADMISSION_INPUT_INVALID' USING errcode='22023'; END IF;
 IF pg_column_size(p_plan)>12000 THEN RAISE EXCEPTION 'ADMISSION_PLAN_TOO_LARGE' USING errcode='22023'; END IF;
 v_action:=p_plan->>'action';v_mode:=p_plan->>'mode';
 IF v_action NOT IN ('REUSE_EXISTING','CREATE_CHILD') OR v_mode NOT IN ('ON_SITE','REMOTE')
 OR jsonb_typeof(p_plan->'catalogVersion')<>'number'
 OR jsonb_typeof(p_plan->'reason')<>'string'
 OR char_length(btrim(p_plan->>'reason')) NOT BETWEEN 10 AND 1000
 THEN RAISE EXCEPTION 'ADMISSION_PLAN_REVIEW_REQUIRED' USING errcode='22023'; END IF;
 IF p_purpose='WORKER_CAPABILITY' THEN
  SELECT w.envelope->>'displayedContentDigest',w.expires_at,
         w.envelope->'classificationProposal',
         encode(extensions.digest(
          ((w.envelope - 'displayedContentDigest') ||
           jsonb_build_object('baseHash',w.base_hash))::text,'sha256'),'hex')
    INTO v_review_digest,v_expiry,v_review_plan,v_expected_review_digest
  FROM private.worker_ai_reviews w
  WHERE w.id=p_source_review_id AND w.account_id=p_owner_account_id
    AND (w.envelope->>'canAccept')::boolean IS TRUE AND w.expires_at>statement_timestamp();
 ELSE
  SELECT t.envelope->>'displayedContentDigest',t.expires_at,
         t.envelope->'classificationProposal',
         encode(extensions.digest(
            jsonb_build_object('envelope',t.envelope - 'displayedContentDigest',
                               'policy',t.policy_binding)::text,'sha256'),'hex')
    INTO v_review_digest,v_expiry,v_review_plan,v_expected_review_digest
  FROM private.ai_task_reviews t
  WHERE t.id=p_source_review_id AND t.account_id=p_owner_account_id
    AND (t.envelope->>'canAccept')::boolean IS TRUE AND t.expires_at>statement_timestamp();
 END IF;
 -- Fail closed for legacy reviews: the classification must be part of the
 -- SAME server-owned payload that the owner actually reviewed.
 IF v_review_digest IS NULL OR v_review_digest !~ '^[0-9a-f]{64}$'
    OR v_review_plan IS NULL OR v_review_plan IS DISTINCT FROM p_plan
    OR v_review_digest IS DISTINCT FROM v_expected_review_digest THEN
  RAISE EXCEPTION 'ADMISSION_REVIEW_PLAN_NOT_DISPLAYED' USING errcode='42501';
 END IF;
 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control WHERE singleton;
 IF v_version IS NULL OR (p_plan->>'catalogVersion')::bigint <> v_version THEN
  RAISE EXCEPTION 'ADMISSION_STALE_CATALOG' USING errcode='PT409'; END IF;
 IF v_action='REUSE_EXISTING' THEN
   IF (p_plan->>'categoryId') IS NULL THEN RAISE EXCEPTION 'ADMISSION_ID_REQUIRED'; END IF;
   v_category:=(p_plan->>'categoryId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
    JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
    WHERE c.id=v_category AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
   IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_UNKNOWN_CATEGORY_OR_MODE'; END IF;
 ELSE
   IF jsonb_typeof(p_plan->'path')<>'array'
      OR jsonb_array_length(p_plan->'path')<1
      OR (p_plan->>'parentId') IS NULL THEN
    RAISE EXCEPTION 'ADMISSION_PATH_INVALID' USING errcode='22023'; END IF;
   v_parent:=(p_plan->>'parentId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
     WHERE c.id=v_parent AND c.state='ESTABLISHED'
       AND private.taxonomy_category_path_valid_v1(c.id);
   IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_UNKNOWN_PARENT_OR_MODE'; END IF;
   -- New root or subtree restructure always requires a separate operator gate.
   IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_plan->'path') t(label)
      WHERE char_length(btrim(t.label)) NOT BETWEEN 3 AND 120
        OR btrim(t.label) ~ '[<>{}\\]' OR btrim(t.label) ~ '[[:cntrl:]]')
     THEN RAISE EXCEPTION 'ADMISSION_NODE_INVALID' USING errcode='22023'; END IF;
   IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_plan->'path') t(label)
      WHERE jsonb_typeof(t.label) IS DISTINCT FROM 'string'
        OR private.taxonomy_normalize_v1(t.label#>>'{}') !~ '[[:alpha:]]')
     THEN RAISE EXCEPTION 'ADMISSION_NODE_INVALID' USING errcode='22023'; END IF;
   -- Every new level is screened; a safe leaf cannot hide an unsafe ancestor.
   IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_plan->'path') t(label)
      WHERE private.taxonomy_risk_triage_v1(t.label) IN ('BLOCKED','REVIEW_REQUIRED'))
     THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
   -- Server risk triage is a risk gate, NOT a semantic classifier.
   IF private.taxonomy_risk_triage_v1(p_plan->'path'->>(jsonb_array_length(p_plan->'path')-1))
      <> 'LOW_RISK_CANDIDATE'
     THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
 END IF;
 v_plan_digest:=encode(extensions.digest(convert_to(p_plan::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO v_existing FROM private.work_taxonomy_admissions_v1
 WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key;
 IF FOUND THEN
  IF v_existing.plan_digest<>v_plan_digest OR v_existing.source_review_id<>p_source_review_id
      OR v_existing.purpose<>p_purpose THEN
   RAISE EXCEPTION 'ADMISSION_REQUEST_REUSED' USING errcode='22023'; END IF;
  RETURN jsonb_build_object('admissionId',v_existing.id,'planDigest',v_existing.plan_digest,
    'status',v_existing.status,'catalogVersion',v_existing.catalog_version);
 END IF;
 INSERT INTO private.work_taxonomy_admissions_v1
 (owner_account_id,request_key,purpose,source_review_id,source_review_digest,plan,
  plan_digest,catalog_version,catalog_fingerprint,expires_at)
 VALUES(p_owner_account_id,p_request_key,p_purpose,p_source_review_id,v_review_digest,p_plan,
 v_plan_digest,v_version,private.taxonomy_admission_fingerprint_v1(),
 least(v_expiry,statement_timestamp()+interval '30 minutes'))
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('admissionId',v_id,'planDigest',v_plan_digest,
  'status','PENDING','catalogVersion',v_version);
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_query_catalog_service(p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
 v_operation text;v_scope text;v_text text;v_anchor uuid;v_ids uuid[];
 v_limit integer:=32;v_version bigint;v_fingerprint text;v_query_digest text;
 v_cursor jsonb;v_after_rank integer;v_after_key text;v_after_id uuid;
 v_count integer;v_complete integer;v_total bigint;v_more boolean;v_items jsonb;
 v_next_rank integer;v_next_key text;v_next_id uuid;v_next text;v_result jsonb;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
  RAISE EXCEPTION 'TAXONOMY_QUERY_DENIED' USING errcode='42501'; END IF;
 IF jsonb_typeof(p_query) IS DISTINCT FROM 'object' OR octet_length(p_query::text)>16384
 OR p_query-array['operation','scope','text','categoryId','categoryIds','limit','cursor','catalogVersion','catalogFingerprint']<>'{}'::jsonb
 OR jsonb_typeof(p_query->'operation') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
 v_operation:=p_query->>'operation';v_scope:=coalesce(p_query->>'scope','ALL');
 IF v_operation NOT IN('META','EXACT','SEARCH','ROOTS','CHILDREN','SIBLINGS','ANCESTORS','RESOLVE')
 OR v_scope NOT IN('ALL','REMOTE','ON_SITE')
 OR (p_query?'scope' AND jsonb_typeof(p_query->'scope') IS DISTINCT FROM 'string')
 OR (v_operation='EXACT' AND v_scope<>'ALL') THEN
  RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
 IF p_query?'limit' THEN
  IF jsonb_typeof(p_query->'limit') IS DISTINCT FROM 'number' OR (p_query->>'limit')!~'^[0-9]{1,3}$' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  v_limit:=(p_query->>'limit')::integer;
 END IF;
 IF v_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
 IF v_operation IN('SEARCH','EXACT') THEN
  IF jsonb_typeof(p_query->'text') IS DISTINCT FROM 'string' OR char_length(btrim(p_query->>'text')) NOT BETWEEN 1 AND 256
   OR (p_query->>'text')~'[[:cntrl:]]' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  v_text:=private.taxonomy_normalize_v1(p_query->>'text');
  IF v_text='' THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
 ELSIF p_query?'text' THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023';
 END IF;
 IF v_operation IN('CHILDREN','SIBLINGS','ANCESTORS') THEN
  IF jsonb_typeof(p_query->'categoryId') IS DISTINCT FROM 'string'
   OR (p_query->>'categoryId')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  v_anchor:=(p_query->>'categoryId')::uuid;
 ELSIF p_query?'categoryId' THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023';
 END IF;
 IF v_operation='RESOLVE' THEN
  IF jsonb_typeof(p_query->'categoryIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_query->'categoryIds') NOT BETWEEN 1 AND 100 THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_query->'categoryIds') x(value)
   WHERE jsonb_typeof(x.value) IS DISTINCT FROM 'string' OR (x.value#>>'{}')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  SELECT array_agg(DISTINCT x.value::uuid ORDER BY x.value::uuid) INTO v_ids FROM jsonb_array_elements_text(p_query->'categoryIds') x(value);
  IF cardinality(v_ids)<>jsonb_array_length(p_query->'categoryIds') THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
 ELSIF p_query?'categoryIds' THEN RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023';
 END IF;

 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control WHERE singleton;
 v_fingerprint:=private.taxonomy_admission_fingerprint_v1();
 IF v_version IS NULL OR v_version<1 OR v_fingerprint IS NULL OR v_fingerprint!~'^[0-9a-f]{32}$' THEN
  RAISE EXCEPTION 'TAXONOMY_QUERY_CATALOG_UNAVAILABLE' USING errcode='55000'; END IF;
 -- The same canonical snapshot pair used by signed reviews. A new request may
 -- establish the snapshot; every supplied pair and cursor must match it exactly.
 IF p_query?'catalogVersion' OR p_query?'catalogFingerprint' THEN
  IF jsonb_typeof(p_query->'catalogVersion') IS DISTINCT FROM 'number'
   OR (p_query->>'catalogVersion')!~'^[1-9][0-9]{0,17}$'
   OR jsonb_typeof(p_query->'catalogFingerprint') IS DISTINCT FROM 'string'
   OR (p_query->>'catalogFingerprint')!~'^[0-9a-f]{32}$' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_INVALID' USING errcode='22023'; END IF;
  IF (p_query->>'catalogVersion')::bigint<>v_version OR p_query->>'catalogFingerprint'<>v_fingerprint THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_STALE_CATALOG' USING errcode='PT409'; END IF;
 END IF;
 v_query_digest:=md5(jsonb_build_object('operation',v_operation,'scope',v_scope,'text',v_text,'categoryId',v_anchor,'categoryIds',v_ids)::text);
 IF p_query->>'cursor' IS NOT NULL THEN
  IF jsonb_typeof(p_query->'cursor') IS DISTINCT FROM 'string' OR char_length(p_query->>'cursor') NOT BETWEEN 1 AND 2048 OR v_operation='META' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_CURSOR_INVALID' USING errcode='22023'; END IF;
  BEGIN v_cursor:=convert_from(decode(p_query->>'cursor','base64'),'UTF8')::jsonb;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'TAXONOMY_QUERY_CURSOR_INVALID' USING errcode='22023'; END;
  IF jsonb_typeof(v_cursor) IS DISTINCT FROM 'object' OR NOT(v_cursor?&array['schema','query','version','fingerprint','rank','key','id'])
   OR v_cursor-array['schema','query','version','fingerprint','rank','key','id']<>'{}'::jsonb
   OR v_cursor->>'schema' IS DISTINCT FROM '1' OR v_cursor->>'query' IS DISTINCT FROM v_query_digest
   OR jsonb_typeof(v_cursor->'version') IS DISTINCT FROM 'number' OR (v_cursor->>'version')!~'^[1-9][0-9]{0,17}$'
   OR jsonb_typeof(v_cursor->'fingerprint') IS DISTINCT FROM 'string' OR (v_cursor->>'fingerprint')!~'^[0-9a-f]{32}$'
   OR jsonb_typeof(v_cursor->'rank') IS DISTINCT FROM 'number' OR (v_cursor->>'rank')!~'^[0-9]{1,9}$'
   OR jsonb_typeof(v_cursor->'key') IS DISTINCT FROM 'string' OR char_length(v_cursor->>'key') NOT BETWEEN 1 AND 160
   OR jsonb_typeof(v_cursor->'id') IS DISTINCT FROM 'string' OR (v_cursor->>'id')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_CURSOR_INVALID' USING errcode='22023'; END IF;
  IF (v_cursor->>'version')::bigint<>v_version OR v_cursor->>'fingerprint'<>v_fingerprint THEN
   RAISE EXCEPTION 'TAXONOMY_QUERY_STALE_CATALOG' USING errcode='PT409'; END IF;
  v_after_rank:=(v_cursor->>'rank')::integer;v_after_key:=v_cursor->>'key';v_after_id:=(v_cursor->>'id')::uuid;
 END IF;
 IF v_anchor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
  WHERE c.id=v_anchor AND c.state='ESTABLISHED') THEN
  RAISE EXCEPTION 'TAXONOMY_QUERY_ANCHOR_NOT_FOUND' USING errcode='P0002'; END IF;

 IF v_operation='META' THEN
  SELECT count(*) INTO v_total FROM private.work_taxonomy_categories c WHERE c.state='ESTABLISHED'
   AND EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes m WHERE m.category_id=c.id
    AND m.execution_scope IN('ON_SITE','REMOTE') AND (v_scope='ALL' OR m.execution_scope=v_scope));
  v_items:='[]'::jsonb;v_count:=0;
 ELSE
  WITH RECURSIVE ancestry(id,parent_id,visited,distance) AS (
   SELECT c.id,c.parent_id,ARRAY[c.id],0 FROM private.work_taxonomy_categories c WHERE c.id=v_anchor AND c.state='ESTABLISHED'
   UNION ALL SELECT c.id,c.parent_id,a.visited||c.id,a.distance+1 FROM ancestry a
    JOIN private.work_taxonomy_categories c ON c.id=a.parent_id AND c.state='ESTABLISHED' WHERE NOT c.id=ANY(a.visited)
  ), candidates AS (
   SELECT c.id,c.label,c.canonical_key,c.parent_id,
    CASE WHEN v_operation='ANCESTORS' THEN (SELECT a.distance FROM ancestry a WHERE a.id=c.id)
     WHEN v_operation='SEARCH' THEN CASE
      WHEN private.taxonomy_normalize_v1(c.label)=v_text OR c.canonical_key=v_text THEN 0
      WHEN EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a WHERE a.category_id=c.id AND a.normalized_key=v_text) THEN 1
      WHEN starts_with(private.taxonomy_normalize_v1(c.label),v_text) THEN 2
      WHEN EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a WHERE a.category_id=c.id AND starts_with(a.normalized_key,v_text)) THEN 3
      ELSE 4 END ELSE 0 END sort_rank
   FROM private.work_taxonomy_categories c
   WHERE c.state='ESTABLISHED' AND EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes m
    WHERE m.category_id=c.id AND m.execution_scope IN('ON_SITE','REMOTE') AND (v_scope='ALL' OR m.execution_scope=v_scope))
   AND CASE v_operation
    WHEN 'ROOTS' THEN c.parent_id IS NULL
    WHEN 'CHILDREN' THEN c.parent_id=v_anchor
    WHEN 'SIBLINGS' THEN c.id<>v_anchor AND c.parent_id IS NOT DISTINCT FROM (SELECT parent_id FROM private.work_taxonomy_categories WHERE id=v_anchor)
    WHEN 'ANCESTORS' THEN c.id<>v_anchor AND EXISTS(SELECT 1 FROM ancestry a WHERE a.id=c.id)
    WHEN 'RESOLVE' THEN c.id=ANY(v_ids)
    WHEN 'EXACT' THEN private.taxonomy_normalize_v1(c.label)=v_text OR c.canonical_key=v_text
     OR EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a WHERE a.category_id=c.id AND a.normalized_key=v_text)
    WHEN 'SEARCH' THEN strpos(private.taxonomy_normalize_v1(c.label),v_text)>0 OR strpos(c.canonical_key,v_text)>0
     OR EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a WHERE a.category_id=c.id AND strpos(a.normalized_key,v_text)>0)
    ELSE false END
  ), selected AS (
   SELECT * FROM candidates c WHERE v_after_id IS NULL OR
    (c.sort_rank,c.canonical_key COLLATE "C",c.id)>(v_after_rank,v_after_key COLLATE "C",v_after_id)
   ORDER BY c.sort_rank,c.canonical_key COLLATE "C",c.id LIMIT(v_limit+1)
  ), page AS (
   SELECT * FROM selected ORDER BY sort_rank,canonical_key COLLATE "C",id LIMIT v_limit
  ), walk(origin_id,parent_id,labels,path_ids,visited) AS (
   SELECT p.id,p.parent_id,ARRAY[p.label],ARRAY[p.id],ARRAY[p.id] FROM page p
   UNION ALL SELECT w.origin_id,c.parent_id,ARRAY[c.label]||w.labels,ARRAY[c.id]||w.path_ids,w.visited||c.id
    FROM walk w JOIN private.work_taxonomy_categories c ON c.id=w.parent_id AND c.state='ESTABLISHED'
    WHERE NOT c.id=ANY(w.visited)
  ), paths AS (
   -- Ancestry is organization, not permission to perform the leaf's mode.
   -- The selected service still requires its own direct category_modes row.
   SELECT w.* FROM walk w WHERE w.parent_id IS NULL
  )
  SELECT (SELECT count(*) FROM page),(SELECT count(*) FROM paths),(SELECT count(*)>v_limit FROM selected),
   (SELECT sort_rank FROM page ORDER BY sort_rank DESC,canonical_key COLLATE "C" DESC,id DESC LIMIT 1),
   (SELECT canonical_key FROM page ORDER BY sort_rank DESC,canonical_key COLLATE "C" DESC,id DESC LIMIT 1),
   (SELECT id FROM page ORDER BY sort_rank DESC,canonical_key COLLATE "C" DESC,id DESC LIMIT 1),
   (SELECT coalesce(jsonb_agg(jsonb_build_object('categoryId',p.id,'label',p.label,'parentId',p.parent_id,
    'aliases',coalesce((SELECT jsonb_agg(a.label ORDER BY a.label COLLATE "C") FROM
     (SELECT DISTINCT a.label FROM private.work_taxonomy_aliases a WHERE a.category_id=p.id) a),'[]'::jsonb),
    'modes',(SELECT jsonb_agg(m.execution_scope ORDER BY m.execution_scope) FROM private.work_taxonomy_category_modes m
     WHERE m.category_id=p.id AND m.execution_scope IN('ON_SITE','REMOTE')),
    'path',path.labels,'pathIds',path.path_ids,'isLeaf',NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories child
     WHERE child.parent_id=p.id AND child.state='ESTABLISHED' AND EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes cm
      WHERE cm.category_id=child.id AND cm.execution_scope IN('ON_SITE','REMOTE') AND (v_scope='ALL' OR cm.execution_scope=v_scope))))
    ORDER BY p.sort_rank,p.canonical_key COLLATE "C",p.id),'[]'::jsonb) FROM page p JOIN paths path ON path.origin_id=p.id)
   INTO v_count,v_complete,v_more,v_next_rank,v_next_key,v_next_id,v_items;
  IF v_count<>v_complete THEN RAISE EXCEPTION 'TAXONOMY_QUERY_PARENT_OR_MODE_INTEGRITY' USING errcode='55000'; END IF;
  IF v_more THEN
   v_next:=replace(encode(convert_to(jsonb_build_object('schema',1,'query',v_query_digest,'version',v_version,
    'fingerprint',v_fingerprint,'rank',v_next_rank,'key',v_next_key,'id',v_next_id)::text,'UTF8'),'base64'),E'\n','');
  END IF;
 END IF;
 v_result:=jsonb_build_object('schemaVersion','TAXONOMY_CATALOG_QUERY_V1','action','CATALOG_QUERY',
  'operation',v_operation,'scope',v_scope,'catalogVersion',v_version,'catalogFingerprint',v_fingerprint,
  'items',v_items,'count',v_count,'nextCursor',v_next,
  'classificationAuthority','NONE','capabilityAuthority','NONE','notificationAuthority','NONE',
  'requiresRequesterReview',true,'requiresWorkerConfirmation',true);
 IF v_operation='META' THEN v_result:=v_result||jsonb_build_object('totalCategories',v_total); END IF;
 -- A transport resource failure is explicit, never a partial empty catalogue.
 IF octet_length(v_result::text)>1048576 THEN RAISE EXCEPTION 'TAXONOMY_QUERY_PAGE_TOO_LARGE' USING errcode='54000'; END IF;
 RETURN v_result;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_reconcile_reviewed_outbox_service(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_enabled boolean;v_count integer;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'OUTBOX_RECOVERY_LIMIT_INVALID' USING errcode='22023'; END IF;
 SELECT enabled INTO v_enabled FROM private.work_taxonomy_review_outbox_control_v1
 WHERE singleton;
 IF v_enabled IS DISTINCT FROM true THEN RETURN 0; END IF;
 WITH accepted AS (
   SELECT s.account_id,s.client_request_id,s.review_id,
      'WORKER_CAPABILITY'::text AS purpose,
      w.envelope->'classificationCandidates' AS plans,s.created_at
   FROM private.worker_ai_saves s
   JOIN private.worker_ai_reviews w ON w.id=s.review_id AND w.account_id=s.account_id
   WHERE w.envelope->'canAccept'='true'::jsonb
     AND w.envelope->>'classificationCatalogFingerprint' IS NOT NULL
     AND CASE WHEN jsonb_typeof(w.envelope->'classificationCandidates')='array'
       THEN jsonb_array_length(w.envelope->'classificationCandidates') BETWEEN 1 AND 24
       ELSE false END
   UNION ALL
   SELECT c.account_id,c.client_request_id,c.review_id,
      'NEED_SERVICE'::text AS purpose,
      t.envelope->'classificationCandidates' AS plans,c.created_at
   FROM private.ai_task_review_commands c
   JOIN private.ai_task_reviews t ON t.id=c.review_id AND t.account_id=c.account_id
   WHERE c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED')
     AND t.envelope->'canAccept'='true'::jsonb
     AND t.envelope->>'classificationCatalogFingerprint' IS NOT NULL
     AND CASE WHEN jsonb_typeof(t.envelope->'classificationCandidates')='array'
       THEN jsonb_array_length(t.envelope->'classificationCandidates')=1
       ELSE false END
 ),
 missing AS MATERIALIZED (
   SELECT a.* FROM accepted a
   WHERE NOT private.closure_account_restricted(a.account_id) AND NOT EXISTS (SELECT 1 FROM private.work_taxonomy_review_outbox_v1 q
     WHERE q.owner_account_id=a.account_id AND q.request_key=a.client_request_id)
   ORDER BY a.created_at,a.review_id LIMIT p_limit
 ),
 admitted AS MATERIALIZED (SELECT * FROM missing WHERE private.closure_taxonomy_try_owner_v1(account_id)),
 inserted AS (
   INSERT INTO private.work_taxonomy_review_outbox_v1
     (owner_account_id,request_key,source_review_id,purpose,plans)
   SELECT account_id,client_request_id,review_id,purpose,plans FROM admitted
   ON CONFLICT(owner_account_id,request_key) DO NOTHING
   RETURNING id
 )
 SELECT count(*)::integer INTO v_count FROM inserted;
 RETURN v_count;
END $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_store_classification_turn_hint_service(p_conversation_id uuid, p_draft_revision bigint, p_service text, p_mode text, p_ambiguity_prompt text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare v_current bigint;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then
  raise exception 'TAXONOMY_HINT_DENIED' using errcode='42501'; end if;
 if p_conversation_id is null or p_draft_revision is null or p_draft_revision<0
  or p_service is null or char_length(btrim(p_service)) not between 1 and 200
  or p_mode is not null and p_mode not in('ON_SITE','REMOTE')
  or p_ambiguity_prompt is null or char_length(btrim(p_ambiguity_prompt)) not between 8 and 600
  or p_reason is not null and char_length(p_reason)>300
 then raise exception 'TAXONOMY_HINT_INVALID' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('classification-hint:'||p_conversation_id::text,0));
 v_current:=private.classification_conversation_revision_v1(p_conversation_id);
 if v_current is null then return jsonb_build_object('stored',false,'reason','CONVERSATION_NOT_OPEN'); end if;
 if v_current<>p_draft_revision then return jsonb_build_object('stored',false,'reason','STALE_REVISION','currentRevision',v_current); end if;
 delete from private.classification_turn_hints where created_at<clock_timestamp()-interval '7 days';
 delete from private.classification_turn_hints
  where conversation_id=p_conversation_id and consumed_at is null and draft_revision=p_draft_revision;
 insert into private.classification_turn_hints(conversation_id,draft_revision,service,mode,ambiguity_prompt,reason)
 values(p_conversation_id,p_draft_revision,btrim(p_service),p_mode,btrim(p_ambiguity_prompt),nullif(btrim(p_reason),''));
 return jsonb_build_object('stored',true,'draftRevision',p_draft_revision);
end $function$;


CREATE OR REPLACE FUNCTION public.rpc_taxonomy_worker_scoped_preview_service(p_execution_location_mode text, p_skill_label text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT private.taxonomy_worker_scoped_capability_preview_v1(
   p_execution_location_mode,p_skill_label)
$function$;


CREATE OR REPLACE FUNCTION public.rpc_tick_auto_completion()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare candidate record; a public.agreements; x public.agreement_execution; done integer:=0; at_time timestamptz:=statement_timestamp();
begin
 for candidate in select ag.id,ag.need_id from public.agreements ag join public.agreement_execution ex on ex.agreement_id=ag.id
   where ag.status='CONFIRMED' and ex.state='AWAITING_REQUESTER' and ex.problem_opened_at is null
     and ex.requester_deadline_at is not null and ex.requester_deadline_at<=at_time
   order by ag.need_id,ag.id limit 100
 loop
   perform 1 from public.needs where id=candidate.need_id for update skip locked;
   if not found then continue; end if;
   select * into a from public.agreements where id=candidate.id for update skip locked;
   if not found or a.status<>'CONFIRMED' then continue; end if;
   select * into x from public.agreement_execution where agreement_id=a.id for update skip locked;
   if not found or x.state<>'AWAITING_REQUESTER' or x.agreement_version<>a.current_version
     or x.problem_opened_at is not null or x.requester_deadline_at is null or x.requester_deadline_at>at_time
     or exists(select 1 from public.agreement_change_proposals where agreement_id=a.id and status='PENDING') then continue; end if;
   update public.agreement_execution set state='COMPLETED',completed_at=at_time,requester_deadline_at=null,updated_at=at_time where agreement_id=a.id;
   update public.agreements set status='COMPLETED',updated_at=at_time where id=a.id;
   perform private.sync_need_completion(a.need_id);
   -- PKG-029a (deep read 1.2): the worker is told the job closed, exactly as when the requester confirms (same
   -- event, same dedupe key, so the two paths can never both notify).
   perform private.emit_event(a.worker_account_id, 'WORKER', 'EXECUTION_STATE_CHANGED', 'AGREEMENT', a.id, a.current_version,
     'Dogovor je završen', 'Rok za potvrdu je istekao, pa je završetak potvrđen automatski.',
     'completed:worker:' || a.id::text || ':' || a.current_version::text, 'NORMAL',
     jsonb_build_object('completedAt', at_time, 'automatic', true), null);
   done:=done+1;
 end loop;
 return done;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_urgent_activation_preview(p_need_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid := auth.uid();
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;
  return private.urgent_activation_decision(p_need_id, u, statement_timestamp());
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_withdraw_agreement_change(p_proposal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid(); aid uuid; a public.agreements; p public.agreement_change_proposals;
begin
 if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
 select agreement_id into aid from public.agreement_change_proposals where id=p_proposal_id and proposed_by_account_id=actor;
 if not found then raise exception 'CHANGE_PROPOSAL_NOT_FOUND' using errcode='P0002'; end if;
 perform 1 from public.needs where id=(select need_id from public.agreements where id=aid) for update;
 select * into a from public.agreements where id=aid for update;
 if not found or actor not in(a.requester_account_id,a.worker_account_id) then raise exception 'NOT_PARTY' using errcode='42501'; end if;
 select * into p from public.agreement_change_proposals where id=p_proposal_id for update;
 if p.proposed_by_account_id<>actor then raise exception 'NOT_PROPOSER' using errcode='42501'; end if;
 if p.status='WITHDRAWN' then return jsonb_build_object('proposalId',p.id,'status','WITHDRAWN','idempotentReplay',true,'authoritative',true); end if;
 if p.status<>'PENDING' then raise exception 'PROPOSAL_NOT_PENDING' using errcode='P0001'; end if;
 if a.status<>'CONFIRMED' or not exists(select 1 from public.agreement_execution x where x.agreement_id=a.id
   and x.agreement_version=a.current_version and x.state='CONFIRMED' and x.worker_marked_done_at is null) then
   raise exception 'AGREEMENT_CHANGE_AFTER_WORK_DONE' using errcode='P0001'; end if;
 update public.agreement_change_proposals set status='WITHDRAWN',responded_by_account_id=actor,responded_at=statement_timestamp() where id=p.id;
 return jsonb_build_object('proposalId',p.id,'status','WITHDRAWN','idempotentReplay',false,'authoritative',true);
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_withdraw_response(p_response_id uuid, p_need_revision integer, p_response_version integer, p_client_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  v_need_id uuid;
  n public.needs;
  r public.marketplace_responses;
  v_command private.response_withdraw_commands;
  v_request_hash text;
  v_result jsonb;
  old_status text;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;
  if p_client_request_id is null
     or char_length(btrim(p_client_request_id)) not between 8 and 200 then
    raise exception using errcode='22023', message='INVALID_CLIENT_REQUEST_ID';
  end if;

  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'responseId', p_response_id,
    'needRevision', p_need_revision,
    'responseVersion', p_response_version,
    'reason', btrim(coalesce(p_reason, ''))
  )::text, 'UTF8')), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(u::text || ':' || p_client_request_id, 7242)
  );

  select * into v_command
    from private.response_withdraw_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id;
  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  -- Discover the parent without locking, then take locks in canonical order:
  -- Need -> Response. Selection and submission use the same order.
  select x.need_id into v_need_id
    from public.marketplace_responses x
   where x.id = p_response_id;
  if not found then raise exception using errcode='P0002', message='RESPONSE_NOT_FOUND'; end if;

  select * into n from public.needs where id = v_need_id for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;

  select * into r from public.marketplace_responses x
   where x.id = p_response_id for update;
  if not found then raise exception using errcode='P0002', message='RESPONSE_NOT_FOUND'; end if;
  if r.need_id <> n.id then
    raise exception using errcode='P0001', message='RESPONSE_NEED_MISMATCH';
  end if;
  if r.worker_account_id <> u then
    raise exception using errcode='42501', message='FORBIDDEN';
  end if;
  if not exists (
    select 1 from public.app_profiles p
     where p.id = r.worker_profile_id
       and p.account_id = u
       and p.kind = 'WORKER'
  ) then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if r.status = 'WITHDRAWN' then
    return jsonb_build_object(
      'responseId', r.id,
      'needId', n.id,
      'needRevision', n.revision,
      'submittedNeedRevision', r.submitted_against_need_revision,
      'version', r.current_version,
      'status', r.status,
      'withdrawnAt', r.withdrawn_at,
      'idempotentReplay', true,
      'authoritative', true
    );
  end if;

  if r.current_version is distinct from p_response_version then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  if not exists (
    select 1
      from public.marketplace_response_versions v
     where v.response_id = r.id
       and v.version = r.current_version
       and v.need_revision = r.submitted_against_need_revision
  ) then
    raise exception using errcode='P0002', message='RESPONSE_VERSION_NOT_FOUND';
  end if;

  -- C12.12: every withdrawal decision binds the latest Need revision reviewed
  -- by the Worker. A live Application must also have been submitted against it;
  -- a STALE Application deliberately retains its older immutable binding.
  if n.revision is distinct from p_need_revision
     or (r.status <> 'STALE'
         and r.submitted_against_need_revision is distinct from p_need_revision) then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  if r.status = 'SELECTED'
     or exists (
       select 1 from public.agreements a
        where a.selected_response_id = r.id
          and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
     ) then
    raise exception using errcode='P0001', message='RESPONSE_ALREADY_SELECTED';
  end if;

  if r.status not in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE') then
    raise exception using errcode='22023', message='RESPONSE_NOT_WITHDRAWABLE';
  end if;

  old_status := r.status;

  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and e.entity_type = 'RESPONSE'
     and e.entity_id = r.id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');

  update public.marketplace_responses
     set status = 'WITHDRAWN',
         withdrawn_at = statement_timestamp(),
         selected_at = null
   where id = r.id
   returning * into r;

  -- A DRAFT was never visible to the requester, so withdrawing it emits no
  -- cross-party event. Submitted history remains visible and versioned.
  if old_status <> 'DRAFT' then
    perform private.emit_event(
      n.requester_account_id,
      'REQUESTER',
      'RESPONSE_WITHDRAWN',
      'RESPONSE',
      r.id,
      r.current_version,
      'Prijava je povucena',
      'Uskocer je povukao prijavu za Vasu Potrebu.',
      'response-withdrawn:' || r.id::text || ':' || r.current_version::text,
      'NORMAL',
      jsonb_build_object('needId', n.id, 'needRevision', n.revision),
      null
    );
  end if;

  -- Withdrawal can reopen capacity. Wake dispatch only while the Need can still
  -- accept a replacement; an elapsed deadline must never schedule new work.
  if n.status in ('PUBLISHED','SELECTION')
     and (n.response_deadline is null
          or n.response_deadline > statement_timestamp())
     and public.fn_need_covered_slots(n.id) < n.required_slots then
    perform private.enqueue_dispatch(n.id, statement_timestamp());
  end if;

  perform private.audit_marketplace(
    u,
    'RESPONSE_WITHDRAWN',
    'RESPONSE',
    r.id,
    r.current_version,
    jsonb_build_object(
      'needId', n.id,
      'needRevision', n.revision,
      'submittedNeedRevision', r.submitted_against_need_revision,
      'clientRequestId', p_client_request_id,
      'reason', left(btrim(coalesce(p_reason, '')), 300)
    )
  );

  v_result := jsonb_build_object(
    'responseId', r.id,
    'needId', n.id,
    'needRevision', n.revision,
    'submittedNeedRevision', r.submitted_against_need_revision,
    'version', r.current_version,
    'status', r.status,
    'withdrawnAt', r.withdrawn_at,
    'idempotentReplay', false,
    'authoritative', true
  );

  insert into private.response_withdraw_commands (
    worker_account_id, client_request_id, request_hash,
    response_id, response_version, result
  ) values (
    u, p_client_request_id, v_request_hash,
    r.id, r.current_version, v_result
  );

  return v_result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_write_agreement_current_location(p_expected_user_id uuid, p_agreement_id uuid, p_agreement_version integer, p_client_request_id uuid, p_kind text, p_input_sha256 text, p_point jsonb, p_cancel boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid(); a public.agreements; e public.agreement_execution; c private.agreement_location_commands;
 h text; lat double precision; lon double precision; accuracy double precision; captured timestamptz;
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_expected_user_id is distinct from u then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='42501'; end if;
 if p_agreement_id is null or p_agreement_version is null or p_agreement_version<1 or p_client_request_id is null
 or p_kind is null or p_kind not in('REQUEST','SHARE') or p_input_sha256 is null or p_input_sha256 !~ '^[0-9a-f]{64}$' or p_cancel is null
 then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
 select * into a from public.agreements where id=p_agreement_id and u in(requester_account_id,worker_account_id);
 if not found then raise exception 'AGREEMENT_NOT_AVAILABLE' using errcode='42501'; end if;
 perform private.closure_assert_open(a.requester_account_id,a.worker_account_id);
 perform pg_advisory_xact_lock(hashtextextended('uskoci:location-command:'||u::text||':'||p_client_request_id::text,138));
 select * into c from private.agreement_location_commands where actor_account_id=u and client_request_id=p_client_request_id;
 if found then
  if c.agreement_id<>a.id or c.agreement_version<>p_agreement_version or c.kind<>p_kind or c.input_hash<>p_input_sha256
  then raise exception 'LOCATION_KEY_REUSED' using errcode='22023'; end if;
  if p_cancel or c.state='CANCELLED' then return private.agreement_location_receipt(c); end if;
 end if;
 if p_cancel then
  insert into private.agreement_location_commands(actor_account_id,client_request_id,agreement_id,agreement_version,kind,state,input_hash)
  values(u,p_client_request_id,a.id,p_agreement_version,p_kind,'CANCELLED',p_input_sha256) returning * into c;
  return private.agreement_location_receipt(c);
 end if;
 if p_kind='REQUEST' then
  if p_point is not null then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
 else
  if p_point is null or jsonb_typeof(p_point)<>'object' or (select count(*) from jsonb_object_keys(p_point))<>4
  or not p_point ?& array['latitude','longitude','accuracyMeters','capturedAt']
  or jsonb_typeof(p_point->'latitude')<>'number' or jsonb_typeof(p_point->'longitude')<>'number'
  or jsonb_typeof(p_point->'accuracyMeters')<>'number' or jsonb_typeof(p_point->'capturedAt')<>'string'
  then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
  begin
   lat:=(p_point->>'latitude')::double precision;lon:=(p_point->>'longitude')::double precision;
   accuracy:=(p_point->>'accuracyMeters')::double precision;captured:=(p_point->>'capturedAt')::timestamptz;
  exception when others then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end;
  if not(lat between -90 and 90) or not(lon between -180 and 180) or not(accuracy>=0 and accuracy<'Infinity'::float8) or not isfinite(captured)
  then raise exception 'LOCATION_INPUT_INVALID' using errcode='22023'; end if;
 end if;
 h:=encode(extensions.digest(jsonb_build_object('agreement',a.id,'version',p_agreement_version,'kind',p_kind,'point',p_point)::text,'sha256'),'hex');
 if c.actor_account_id is not null then
  if c.semantic_hash<>h then raise exception 'LOCATION_KEY_REUSED' using errcode='22023'; end if;
  return private.agreement_location_receipt(c);
 end if;
 select * into a from public.agreements where id=a.id for update;
 select * into e from public.agreement_execution where agreement_id=a.id for update;
 perform private.safety_assert_pair(a.requester_account_id,a.worker_account_id);
 if a.current_version<>p_agreement_version then raise exception 'VERSION_CONFLICT' using errcode='PT409'; end if;
 if a.status<>'CONFIRMED' or e.agreement_id is null or e.agreement_version<>a.current_version
 or e.state not in('CONFIRMED','AWAITING_REQUESTER') or e.mode not in('PHYSICAL','PICKUP_DELIVERY')
 then raise exception 'LOCATION_NOT_AVAILABLE' using errcode='42501'; end if;
 if (p_kind='SHARE' and u<>a.worker_account_id) or (p_kind='REQUEST' and u<>a.requester_account_id)
 then raise exception 'LOCATION_NOT_AVAILABLE' using errcode='42501'; end if;
 insert into private.agreement_location_commands(actor_account_id,client_request_id,agreement_id,agreement_version,kind,state,input_hash,semantic_hash)
 values(u,p_client_request_id,a.id,a.current_version,p_kind,'COMMITTED',p_input_sha256,h) returning * into c;
 if p_kind='SHARE' then
  insert into private.agreement_location_points(actor_account_id,client_request_id,latitude,longitude,accuracy_meters,captured_at)
  values(u,p_client_request_id,lat,lon,accuracy,captured);
 end if;
 return private.agreement_location_receipt(c);
end; $function$;


CREATE OR REPLACE FUNCTION public.selectable_application_count(n public.needs)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor uuid:=auth.uid(); actual public.needs; result integer;
begin
  if actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if not public.rpc_storage_account_open() then raise exception 'ACCOUNT_NOT_OPEN' using errcode='42501'; end if;
  -- Only the ID is input. Never trust owner/status/price fields in a caller-supplied composite.
  select * into actual from public.needs t where t.id=n.id and t.requester_account_id=actor;
  if not found then return null; end if;
  select count(*)::integer into result from private.need_candidate_states_v5(actual.id) c
    where c.candidate_state='SELECTABLE';
  return result;
end;
$function$;


CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;


CREATE OR REPLACE FUNCTION rls_private.need_participant_can_read(p_need_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select auth.uid() is not null
     and (
       exists (
         select 1
           from public.agreements a
          where a.need_id = p_need_id
            and a.worker_account_id = auth.uid()
            and a.status in ('CONFIRMED', 'COMPLETED')
       )
       or exists (
         select 1
           from public.need_selections s
          where s.need_id = p_need_id
            and s.worker_account_id = auth.uid()
            and s.status = 'SELECTED'
       )
     );
$function$;


CREATE OR REPLACE FUNCTION rls_private.p6_discovery_test_world_accounts()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
  select coalesce(array_agg(l.account_id order by l.account_id),array[]::uuid[])
  from private.account_lineage_v5 l
  where private.account_visibility_world(l.account_id)='TEST'
$function$;


