ALTER TABLE "public"."notification_push_attempts" ADD CONSTRAINT "push_single_target_authorization_shape_v1" CHECK (single_target_admission IS NULL AND single_target_authorization_id IS NULL OR single_target_admission IS NOT NULL AND single_target_authorization_id IS NOT NULL AND single_target_authorization_id::text = (single_target_admission ->> 'authorizationId'::text));

ALTER TABLE "public"."notification_push_attempts" ADD CONSTRAINT "push_single_target_claim_shape_v1" CHECK (single_target_claimed_at IS NULL OR single_target_admission IS NOT NULL);

ALTER TABLE "public"."notification_push_attempts" ADD CONSTRAINT "push_single_target_shape_v1" CHECK (single_target_admission IS NULL OR COALESCE(jsonb_typeof(single_target_admission) = 'object'::text AND single_target_admission ?& ARRAY['schema'::text, 'authorizationId'::text, 'recipientAccountId'::text, 'recipientRole'::text, 'eventId'::text, 'eventType'::text, 'deviceId'::text, 'deviceRevision'::text, 'boundSessionId'::text, 'expiresAt'::text, 'receiptDeadline'::text] AND (single_target_admission - ARRAY['schema'::text, 'authorizationId'::text, 'recipientAccountId'::text, 'recipientRole'::text, 'eventId'::text, 'eventType'::text, 'deviceId'::text, 'deviceRevision'::text, 'boundSessionId'::text, 'expiresAt'::text, 'receiptDeadline'::text]) = '{}'::jsonb AND (single_target_admission ->> 'schema'::text) = 'PUSH_SINGLE_TARGET_V1'::text AND (single_target_admission ->> 'eventType'::text) = 'MESSAGE_RECEIVED'::text AND ((single_target_admission ->> 'recipientRole'::text) = ANY (ARRAY['REQUESTER'::text, 'WORKER'::text])) AND jsonb_typeof(single_target_admission -> 'authorizationId'::text) = 'string'::text AND (single_target_admission ->> 'authorizationId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text AND jsonb_typeof(single_target_admission -> 'recipientAccountId'::text) = 'string'::text AND (single_target_admission ->> 'recipientAccountId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text AND jsonb_typeof(single_target_admission -> 'eventId'::text) = 'string'::text AND (single_target_admission ->> 'eventId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text AND jsonb_typeof(single_target_admission -> 'deviceId'::text) = 'string'::text AND (single_target_admission ->> 'deviceId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text AND jsonb_typeof(single_target_admission -> 'boundSessionId'::text) = 'string'::text AND (single_target_admission ->> 'boundSessionId'::text) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text AND jsonb_typeof(single_target_admission -> 'deviceRevision'::text) = 'number'::text AND (single_target_admission ->> 'deviceRevision'::text) ~ '^[0-9]+$'::text AND jsonb_typeof(single_target_admission -> 'expiresAt'::text) = 'string'::text AND isfinite((single_target_admission ->> 'expiresAt'::text)::timestamp with time zone) AND jsonb_typeof(single_target_admission -> 'receiptDeadline'::text) = 'string'::text AND isfinite((single_target_admission ->> 'receiptDeadline'::text)::timestamp with time zone), false));

